export enum ViewState {
  LOGIN,
  DRIVER_HOME,
  DRIVER_CHECKIN,
  DRIVER_CHECKOUT,
  DRIVER_REPORT,
  TENKO_DASHBOARD,
  TENKO_QUEUE_CHECKIN,
  TENKO_QUEUE_CHECKOUT,
