  TENKO_APPROVAL_CHECKOUT
}

import { TenkoRecord } from '../types';

const STORAGE_KEY = 'tenko_ttt_data';

export const StorageService = {
  getAll: (): TenkoRecord[] => {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error("Failed to load data", e);
      return [];
    }
  },

  save: (records: TenkoRecord[]) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
    } catch (e) {
      console.error("Failed to save data", e);
    }
  },

  create: (record: Partial<TenkoRecord>): { isOk: boolean, data?: TenkoRecord } => {
    const records = StorageService.getAll();
    const newRecord: TenkoRecord = {
      ...record,
      __backendId: Date.now().toString() + Math.random().toString(36).substring(2),
    } as TenkoRecord;

    records.push(newRecord);
    StorageService.save(records);
    return { isOk: true, data: newRecord };
  },

  update: (record: TenkoRecord): { isOk: boolean } => {
    const records = StorageService.getAll();
    const index = records.findIndex(r => r.__backendId === record.__backendId);
    if (index !== -1) {
      records[index] = record;
      StorageService.save(records);
      return { isOk: true };
    }
    return { isOk: false };
  },

  delete: (recordId: string): { isOk: boolean } => {
    let records = StorageService.getAll();
    const initialLength = records.length;
    records = records.filter(r => r.__backendId !== recordId);
    if (records.length !== initialLength) {
      StorageService.save(records);
      return { isOk: true };
    }
    return { isOk: false };
  }
};

import React from 'react';

// --- Card ---
export const Card: React.FC<{ children: React.ReactNode; className?: string; onClick?: () => void }> = ({ children, className = '', onClick }) => (
  <div 
    className={`bg-white rounded-xl shadow-sm p-6 border border-slate-100 ${onClick ? 'cursor-pointer hover:shadow-md transition-shadow' : ''} ${className}`}
    onClick={onClick}
  >
    {children}
  </div>
);

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', isLoading, className = '', ...props }) => {
  const baseStyle = "px-6 py-2.5 rounded-lg font-semibold transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 hover:shadow-lg shadow-blue-200",
    secondary: "bg-white text-blue-600 border-2 border-blue-600 hover:bg-blue-50",
    danger: "bg-red-500 text-white hover:bg-red-600",
    ghost: "bg-transparent text-slate-600 hover:bg-slate-100"
  };

  return (
    <button 
      className={`${baseStyle} ${variants[variant]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading && <i className="fas fa-circle-notch fa-spin"></i>}
      {children}
    </button>
  );
};

// --- Input ---
interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: boolean;
}

export const Input: React.FC<InputProps> = ({ label, error, className = '', ...props }) => (
  <div className="w-full">
    {label && <label className="block text-sm font-semibold mb-2 text-slate-700">{label}</label>}
    <input 
      className={`w-full px-4 py-2.5 rounded-lg border-2 text-slate-700 transition-colors focus:outline-none focus:ring-2 focus:ring-blue-100 ${error ? 'border-red-400 bg-red-50' : 'border-slate-200 focus:border-blue-500'} ${className}`}
      {...props}
    />
  </div>
);

// --- Badge ---
export const Badge: React.FC<{ children: React.ReactNode; type?: 'pending' | 'approved' | 'danger' | 'neutral' }> = ({ children, type = 'neutral' }) => {
  const styles = {
    pending: "bg-amber-100 text-amber-800",
    approved: "bg-emerald-100 text-emerald-800",
    danger: "bg-red-100 text-red-800",
    neutral: "bg-slate-100 text-slate-600"
  };

  return (
    <span className={`px-3 py-1 rounded-full text-xs font-bold ${styles[type]}`}>
      {children}
    </span>
  );
};

// --- Option Button ---
export const OptionButton: React.FC<{ selected: boolean; onClick: () => void; children: React.ReactNode }> = ({ selected, onClick, children }) => (
  <button
    onClick={onClick}
    className={`px-4 py-2 rounded-lg border-2 font-medium transition-all ${
      selected 
        ? 'border-blue-500 bg-blue-500 text-white shadow-md' 
        : 'border-slate-200 bg-white text-slate-600 hover:border-blue-400 hover:bg-slate-50'
    }`}
  >
    {children}
  </button>
);

import React, { useState } from 'react';
import { Button, Card, Input } from '../components/UI';
import { DRIVERS, TENKO_USERS, SYSTEM_VERSION } from '../constants';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
}

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = () => {
    setError('');
    const driver = DRIVERS.find(d => d.id === username);
    const tenko = TENKO_USERS.find(t => t.id === username);

    if (driver && password === 'driver123') {
      onLogin({ ...driver, role: 'driver' });
    } else if (tenko && password === 'tenko123') {
      onLogin({ ...tenko, role: 'tenko' });
    } else {
      setError('รหัสพนักงานหรือรหัสผ่านไม่ถูกต้อง');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
      <Card className="w-full max-w-md shadow-xl border-t-4 border-blue-600">
        <div className="text-center mb-8">
          <div className="w-20 h-20 bg-blue-600 rounded-full mx-auto mb-4 flex items-center justify-center shadow-lg shadow-blue-200">
            <i className="fas fa-clipboard-check text-white text-3xl"></i>
          </div>
          <h1 className="text-3xl font-bold text-slate-800 mb-1">Tenko TTT</h1>
          <p className="text-slate-500">ACT Transport System</p>
        </div>

        <div className="space-y-5">
          <Input 
            label="รหัสพนักงาน" 
            placeholder="กรอกรหัสพนักงาน" 
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            className="text-lg"
          />

          <div className="relative">
            <Input 
              label="รหัสผ่าน" 
              type={showPassword ? "text" : "password"} 
              placeholder="กรอกรหัสผ่าน"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="pr-10 text-lg"
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
            />
            <button 
              className="absolute right-3 top-[38px] text-slate-400 hover:text-blue-600 transition-colors"
              onClick={() => setShowPassword(!showPassword)}
            >
              <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
            </button>
