import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import { CheckinForm } from './CheckinForm';
import { CheckoutForm } from './CheckoutForm';
import { DriverHistory } from './DriverHistory';

interface DriverAppProps {
  user: User;
  onLogout: () => void;
}

export const DriverApp: React.FC<DriverAppProps> = ({ user, onLogout }) => {
  const [view, setView] = useState<'home' | 'checkin' | 'checkout' | 'history'>('home');
  const [records, setRecords] = useState<TenkoRecord[]>([]);

  useEffect(() => {
    setRecords(StorageService.getAll());
    const interval = setInterval(() => {
        setRecords(StorageService.getAll());
    }, 5000); // Simple polling for updates
    return () => clearInterval(interval);
  }, []);

  const today = new Date().toISOString().split('T')[0];
  const todayRecord = records.find(r => r.driver_id === user.id && r.date === today);

  const getLatestCheckoutTime = () => {
    const driverRecords = records
      .filter(r => r.driver_id === user.id && r.checkout_timestamp)
      .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());

    return driverRecords.length > 0 ? new Date(driverRecords[0].checkout_timestamp!) : null;
  };

  const checkFixStartTime = () => {
    const driverRecords = records
      .filter(r => r.driver_id === user.id && r.checkin_timestamp && r.checkin_status === 'approved')
      .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    if (driverRecords.length === 0) return 'OK';

    const mondayRecords = driverRecords.filter(r => new Date(r.checkin_timestamp!).getDay() === 1);
    if (mondayRecords.length === 0) return 'OK';

    const firstMonday = new Date(mondayRecords[0].checkin_timestamp!);
    const firstMondayTime = firstMonday.getHours() * 60 + firstMonday.getMinutes();

    for (let record of driverRecords) {
      const checkDate = new Date(record.checkin_timestamp!);
      const checkTime = checkDate.getHours() * 60 + checkDate.getMinutes();
      const diff = Math.abs(checkTime - firstMondayTime);
      if (diff > 120) return 'NG';
    }
    return 'OK';
  };

  const canStartCheckin = () => {
     // Rule: 8 hours after last checkout
     const latestCheckout = getLatestCheckoutTime();
     if (!latestCheckout) return { allowed: true };

     const diffHours = (new Date().getTime() - latestCheckout.getTime()) / (1000 * 60 * 60);
     if (diffHours < 8) {
         return { 
             allowed: false, 
             message: `ต้องรอพักผ่อนให้ครบ 8 ชั่วโมง (อีก ${(8 - diffHours).toFixed(1)} ชม.)` 
         };
     }

     if (todayRecord) {
         if (todayRecord.checkin_status === 'approved' && todayRecord.checkout_status === 'approved') {
             return { allowed: true, message: "เริ่มรอบใหม่ได้" };
         }
         return { allowed: false, message: "คุณทำรายการวันนี้ไปแล้ว" };
     }

     return { allowed: true };
  };

  const checkinStatus = canStartCheckin();
  const fixStartTime = checkFixStartTime();

  const handleDataUpdate = () => {
      setRecords(StorageService.getAll());
      setView('home');
  };

  if (view === 'checkin') return <CheckinForm user={user} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'checkout') return <CheckoutForm user={user} record={todayRecord!} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'history') return <DriverHistory user={user} records={records} onBack={() => setView('home')} fixStartTime={fixStartTime} />;

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <header className="bg-gradient-to-r from-blue-700 to-blue-500 text-white p-6 shadow-lg">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <i className="fas fa-user-circle"></i> {user.name}
            </h1>
            <p className="opacity-80">รหัส: {user.id}</p>
            <div className="mt-2 flex gap-2">
                <Badge type={fixStartTime === 'OK' ? 'approved' : 'danger'}>Fix Start Time: {fixStartTime}</Badge>
            </div>
          </div>
          <Button variant="secondary" onClick={onLogout} className="border-white text-white hover:bg-white/20 hover:text-white">
            <i className="fas fa-sign-out-alt"></i> ออก
          </Button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-6 space-y-6">
        {todayRecord && todayRecord.checkin_status !== 'approved' && todayRecord.checkin_status !== null && (
            <Card className="bg-amber-50 border-amber-200">
                <div className="flex items-center gap-4 text-amber-800">
                    <i className="fas fa-clock text-2xl"></i>
                    <div>
                        <h3 className="font-bold">รอตรวจสอบเท็งโกะก่อนเริ่มงาน</h3>
                        <p className="text-sm opacity-80">กรุณารอเจ้าหน้าที่ตรวจสอบข้อมูล</p>
                    </div>
                </div>
            </Card>
        )}

        {todayRecord && todayRecord.checkin_status === 'approved' && todayRecord.checkout_status === null && (
             <Card className="bg-emerald-50 border-emerald-200">
                <div className="flex items-center gap-4 text-emerald-800">
                    <i className="fas fa-check-circle text-2xl"></i>
                    <div>
                        <h3 className="font-bold">พร้อมปฏิบัติงาน</h3>
                        <p className="text-sm opacity-80">อย่าลืมทำรายการหลังเลิกงานเมื่อเสร็จสิ้นภารกิจ</p>
                    </div>
                </div>
            </Card>
        )}

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <Card 
                onClick={() => {
                    if (checkinStatus.allowed) setView('checkin');
                    else alert(checkinStatus.message);
                }} 
                className={`hover:border-blue-300 relative overflow-hidden group ${!checkinStatus.allowed ? 'opacity-60 grayscale' : ''}`}
            >
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
                    <i className="fas fa-clipboard-check text-9xl text-blue-500"></i>
                </div>
                <div className="relative z-10">
                    <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-4 text-2xl">
                        <i className="fas fa-clipboard-check"></i>
                    </div>
                    <h3 className="text-xl font-bold text-slate-800">เท็งโกะก่อนเริ่มงาน</h3>
                    <p className="text-slate-500 text-sm mt-1">ตรวจสอบสุขภาพก่อนขับขี่</p>
                    {!checkinStatus.allowed && <p className="text-red-500 text-xs mt-2 font-bold">{checkinStatus.message}</p>}
                </div>
            </Card>

            <Card 
                onClick={() => {
                    if (todayRecord && todayRecord.checkin_status === 'approved' && !todayRecord.checkout_status) setView('checkout');
                    else if (!todayRecord) alert('กรุณาทำเท็งโกะก่อนเริ่มงานก่อน');
                    else if (todayRecord.checkout_status) alert('ทำรายการเสร็จสิ้นแล้วสำหรับรอบนี้');
                    else alert('รอการอนุมัติเท็งโกะก่อนเริ่มงาน');
                }}
                className={`hover:border-emerald-300 relative overflow-hidden group ${!todayRecord || todayRecord.checkin_status !== 'approved' || todayRecord.checkout_status ? 'opacity-60 grayscale' : ''}`}
            >
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
                    <i className="fas fa-flag-checkered text-9xl text-emerald-500"></i>
                </div>
                <div className="relative z-10">
                    <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-4 text-2xl">
                        <i className="fas fa-flag-checkered"></i>
                    </div>
                    <h3 className="text-xl font-bold text-slate-800">เท็งโกะหลังเลิกงาน</h3>
                    <p className="text-slate-500 text-sm mt-1">รายงานผลหลังปฏิบัติงาน</p>
                </div>
            </Card>

            <Card 
                onClick={() => setView('history')}
                className="hover:border-purple-300 relative overflow-hidden group"
            >
                <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
                    <i className="fas fa-history text-9xl text-purple-500"></i>
                </div>
                <div className="relative z-10">
                    <div className="w-16 h-16 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mb-4 text-2xl">
                        <i className="fas fa-history"></i>
                    </div>
                    <h3 className="text-xl font-bold text-slate-800">ประวัติการทำงาน</h3>
                    <p className="text-slate-500 text-sm mt-1">ตรวจสอบสถิติย้อนหลัง</p>
                </div>
            </Card>
        </div>
      </main>
    </div>
  );
};

import React, { useState } from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, OptionButton, Input } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  user: User;
  onBack: () => void;
  onSubmitSuccess: () => void;
}

export const CheckinForm: React.FC<Props> = ({ user, onBack, onSubmitSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({});
  const [submitting, setSubmitting] = useState(false);

  const updateForm = (key: keyof TenkoRecord, value: any) => {
    setForm(prev => ({ ...prev, [key]: value }));
  };

  const calculateSleep = (start?: string, end?: string) => {
    if (!start || !end) return 0;
    const s = new Date(`2000-01-01T${start}`);
    let e = new Date(`2000-01-01T${end}`);
    if (e < s) e.setDate(e.getDate() + 1);
    return (e.getTime() - s.getTime()) / (1000 * 60 * 60);
  };

  const handleSleepChange = (type: 'start' | 'end', val: string) => {
    const start = type === 'start' ? val : form.sleep_start;
    const end = type === 'end' ? val : form.sleep_end;
    updateForm(type === 'start' ? 'sleep_start' : 'sleep_end', val);

    if (start && end) {
      updateForm('sleep_hours', calculateSleep(start, end));
    }
  };

  const handleSubmit = () => {
    // Basic validation
    if (!form.tired || !form.sick || !form.drowsy || !form.sleep_hours) {
      alert('กรุณากรอกข้อมูลให้ครบถ้วน');
      return;
    }

    setSubmitting(true);
    setTimeout(() => {
      StorageService.create({
        driver_id: user.id,
        driver_name: user.name,
        date: new Date().toISOString().split('T')[0],
        checkin_timestamp: new Date().toISOString(),
        checkin_status: 'pending',
        checkout_status: null, // Explicitly null for clarity
        ...form
      });
      setSubmitting(false);
      onSubmitSuccess();
    }, 800);
  };

  const renderQuestion = (
    label: string, 
    field: keyof TenkoRecord, 
    detailField?: keyof TenkoRecord, 
    triggerValue: string = 'มี'
  ) => (
    <Card className="mb-4">
      <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
        <i className="fas fa-question-circle text-blue-500"></i> {label}
      </h3>
      <div className="flex gap-3 mb-3">
        {['มี', 'ไม่มี'].map(opt => (
          <OptionButton 
            key={opt}
            selected={form[field] === opt} 
            onClick={() => updateForm(field, opt)}
          >
            {opt}
          </OptionButton>
        ))}
      </div>
      {form[field] === triggerValue && detailField && (
        <Input 
          placeholder="ระบุรายละเอียด" 
          value={(form[detailField] as string) || ''}
          onChange={e => updateForm(detailField, e.target.value)}
        />
      )}
    </Card>
  );

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <div className="bg-white sticky top-0 z-20 px-6 py-4 shadow-sm flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">เท็งโกะก่อนเริ่มงาน</h2>
        <Button variant="secondary" onClick={onBack} size="sm">ย้อนกลับ</Button>
      </div>

      <div className="max-w-3xl mx-auto p-6 space-y-6 pb-24">
        {renderQuestion('มีอาการเหนื่อยล้า?', 'tired', 'tired_detail')}
        {renderQuestion('มีอาการเจ็บป่วย?', 'sick', 'sick_detail')}
        {renderQuestion('มีอาการง่วงนอน?', 'drowsy', 'drowsy_detail')}
        {renderQuestion('มีอาการบาดเจ็บ?', 'injury', 'injury_detail')}

        <Card>
            <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                <i className="fas fa-bed text-blue-500"></i> การนอนหลับ
            </h3>
            <div className="grid grid-cols-2 gap-4 mb-4">
                <Input type="time" label="เวลาเริ่มนอน" value={form.sleep_start || ''} onChange={e => handleSleepChange('start', e.target.value)} />
                <Input type="time" label="เวลาตื่น" value={form.sleep_end || ''} onChange={e => handleSleepChange('end', e.target.value)} />
            </div>
            <div className={`p-3 rounded-lg text-center font-bold text-lg mb-4 ${
                (form.sleep_hours || 0) < 6 ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
            }`}>
                รวม {form.sleep_hours?.toFixed(1) || 0} ชั่วโมง
            </div>
             <h4 className="text-sm font-medium mb-2 text-slate-600">คุณภาพการนอน</h4>
             <div className="flex gap-3">
                 <OptionButton selected={form.sleep_quality === 'หลับสนิท'} onClick={() => updateForm('sleep_quality', 'หลับสนิท')}>หลับสนิท</OptionButton>
                 <OptionButton selected={form.sleep_quality === 'ไม่สนิท'} onClick={() => updateForm('sleep_quality', 'ไม่สนิท')}>ไม่สนิท</OptionButton>
             </div>
        </Card>

        {renderQuestion('สภาพร่างกายผิดปกติ?', 'body_condition', 'body_condition_detail', 'ผิดปกติ')}

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t flex justify-center z-20">
            <Button onClick={handleSubmit} isLoading={submitting} className="w-full max-w-md py-3 text-lg">
                <i className="fas fa-paper-plane"></i> ส่งข้อมูล
            </Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, OptionButton, Input } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  user: User;
  record: TenkoRecord;
  onBack: () => void;
  onSubmitSuccess: () => void;
}

export const CheckoutForm: React.FC<Props> = ({ record, onBack, onSubmitSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({});
  const [submitting, setSubmitting] = useState(false);

  const updateForm = (key: keyof TenkoRecord, value: any) => {
    setForm(prev => ({ ...prev, [key]: value }));
  };

  const handleSubmit = () => {
    if (!form.vehicle_handover || !form.body_condition_checkout || !form.route_risk) {
      alert('กรุณากรอกข้อมูลให้ครบถ้วน');
      return;
    }

    setSubmitting(true);
    setTimeout(() => {
      StorageService.update({
        ...record,
        ...form,
        checkout_timestamp: new Date().toISOString(),
        checkout_status: 'pending'
      });
      setSubmitting(false);
      onSubmitSuccess();
    }, 800);
  };

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <div className="bg-white sticky top-0 z-20 px-6 py-4 shadow-sm flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">เท็งโกะหลังเลิกงาน</h2>
        <Button variant="secondary" onClick={onBack}>ย้อนกลับ</Button>
      </div>

      <div className="max-w-3xl mx-auto p-6 space-y-6 pb-24">
        <Card>
            <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                <i className="fas fa-truck text-blue-500"></i> การส่งมอบรถสินค้า
            </h3>
            <div className="flex gap-3 mb-3">
                <OptionButton selected={form.vehicle_handover === 'ปกติ'} onClick={() => updateForm('vehicle_handover', 'ปกติ')}>ปกติ</OptionButton>
                <OptionButton selected={form.vehicle_handover === 'ไม่ปกติ'} onClick={() => updateForm('vehicle_handover', 'ไม่ปกติ')}>ไม่ปกติ</OptionButton>
            </div>
            {form.vehicle_handover === 'ไม่ปกติ' && (
                <Input 
                  placeholder="ระบุรายละเอียดความผิดปกติ" 
                  value={form.vehicle_detail || ''}
                  onChange={e => updateForm('vehicle_detail', e.target.value)}
                />
            )}
        </Card>

        <Card>
            <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                <i className="fas fa-heartbeat text-red-500"></i> สภาพร่างกาย
            </h3>
            <div className="flex gap-3 mb-3">
                <OptionButton selected={form.body_condition_checkout === 'ปกติ'} onClick={() => updateForm('body_condition_checkout', 'ปกติ')}>ปกติ</OptionButton>
                <OptionButton selected={form.body_condition_checkout === 'ไม่ปกติ'} onClick={() => updateForm('body_condition_checkout', 'ไม่ปกติ')}>ไม่ปกติ</OptionButton>
            </div>
            {form.body_condition_checkout === 'ไม่ปกติ' && (
                <Input 
                  placeholder="ระบุอาการ" 
                  value={form.body_detail_checkout || ''}
                  onChange={e => updateForm('body_detail_checkout', e.target.value)}
                />
            )}
        </Card>

        <Card>
            <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                <i className="fas fa-route text-orange-500"></i> จุดเสี่ยงระหว่างเส้นทาง
            </h3>
            <div className="flex gap-3 mb-3">
                <OptionButton selected={form.route_risk === 'ปกติ'} onClick={() => updateForm('route_risk', 'ปกติ')}>ปกติ</OptionButton>
                <OptionButton selected={form.route_risk === 'พบจุดเสี่ยง'} onClick={() => updateForm('route_risk', 'พบจุดเสี่ยง')}>พบจุดเสี่ยง</OptionButton>
            </div>
            {form.route_risk === 'พบจุดเสี่ยง' && (
                <Input 
                  placeholder="ระบุจุดเสี่ยงและรายละเอียด" 
                  value={form.route_detail || ''}
                  onChange={e => updateForm('route_detail', e.target.value)}
                />
            )}
        </Card>

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t flex justify-center z-20">
            <Button onClick={handleSubmit} isLoading={submitting} className="w-full max-w-md py-3 text-lg bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200">
                <i className="fas fa-check-double"></i> ส่งรายงาน
            </Button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, Badge } from '../../components/UI';

interface Props {
  user: User;
  records: TenkoRecord[];
  onBack: () => void;
  fixStartTime: string;
}

export const DriverHistory: React.FC<Props> = ({ user, records, onBack, fixStartTime }) => {
  const myRecords = records
    .filter(r => r.driver_id === user.id && r.checkin_status === 'approved' && r.checkout_status === 'approved')
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const currentMonth = new Date();
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  const getDayStatus = (day: number) => {
    const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const record = myRecords.find(r => r.date === dateStr);
    if (record) return 'complete';
    if (dateStr === new Date().toISOString().split('T')[0]) return 'today';
    return 'none';
  };

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <div className="bg-purple-600 text-white px-6 py-6 shadow-md">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
            <div>
                <h2 className="text-2xl font-bold">รายงานของฉัน</h2>
                <p className="opacity-80">ประวัติการปฏิบัติงานและการตรวจสอบ</p>
            </div>
            <Button onClick={onBack} variant="secondary" className="border-white text-white hover:bg-white/20">ย้อนกลับ</Button>
        </div>
      </div>

      <div className="max-w-4xl mx-auto p-6 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
             <Card className="bg-white border-l-4 border-blue-500">
                 <p className="text-sm text-slate-500">เดือนนี้</p>
                 <p className="text-3xl font-bold text-blue-600">{myRecords.filter(r => new Date(r.date).getMonth() === currentMonth.getMonth()).length}</p>
                 <p className="text-xs text-slate-400">ครั้ง</p>
             </Card>
             <Card className="bg-white border-l-4 border-purple-500">
                 <p className="text-sm text-slate-500">ทั้งหมด</p>
                 <p className="text-3xl font-bold text-purple-600">{myRecords.length}</p>
                 <p className="text-xs text-slate-400">ครั้ง</p>
             </Card>
             <Card className={`bg-white border-l-4 ${fixStartTime === 'OK' ? 'border-emerald-500' : 'border-red-500'}`}>
                 <p className="text-sm text-slate-500">Fix Start Time</p>
                 <p className={`text-3xl font-bold ${fixStartTime === 'OK' ? 'text-emerald-600' : 'text-red-600'}`}>{fixStartTime}</p>
                 <p className="text-xs text-slate-400">{fixStartTime === 'OK' ? 'ปกติ' : 'ผิดปกติ'}</p>
             </Card>
        </div>

        <Card>
            <h3 className="font-bold mb-4 text-slate-700">ปฏิทิน {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</h3>
            <div className="grid grid-cols-7 gap-1">
                {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                {Array.from({length: daysInMonth}).map((_, i) => {
                    const status = getDayStatus(i+1);
                    return (
                        <div key={i} className={`
                            h-10 flex items-center justify-center rounded-lg text-sm font-medium
                            ${status === 'complete' ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 
                              status === 'today' ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-slate-50 text-slate-400'}
                        `}>
                            {i+1}
                        </div>
                    );
                })}
            </div>
        </Card>

        <div className="space-y-4">
            <h3 className="font-bold text-slate-700">รายการล่าสุด</h3>
            {myRecords.slice(0, 10).map(record => (
                <Card key={record.__backendId} className="hover:bg-slate-50 transition-colors">
                    <div className="flex justify-between items-start mb-3">
                        <div>
                            <p className="font-bold text-slate-800">
                                {new Date(record.date).toLocaleDateString('th-TH', { dateStyle: 'long' })}
                            </p>
                            <p className="text-xs text-slate-500">ID: {record.__backendId.substring(0, 8)}</p>
                        </div>
                        <Badge type="approved">สมบูรณ์</Badge>
                    </div>
                    <div className="grid grid-cols-2 gap-4 text-sm">
                        <div className="p-2 bg-blue-50 rounded">
                            <p className="font-semibold text-blue-800 mb-1">ก่อนเริ่มงาน</p>
                            <p>เวลา: {new Date(record.checkin_approved_time || '').toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'})}</p>
                            <p>ผู้ตรวจ: {record.checkin_tenko_name}</p>
                            <p>แอลกอฮอล์: {record.alcohol_checkin}</p>
                        </div>
                        <div className="p-2 bg-emerald-50 rounded">
                            <p className="font-semibold text-emerald-800 mb-1">หลังเลิกงาน</p>
                            <p>เวลา: {new Date(record.checkout_approved_time || '').toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'})}</p>
                            <p>ผู้ตรวจ: {record.checkout_tenko_name}</p>
                            <p>แอลกอฮอล์: {record.alcohol_checkout}</p>
                        </div>
                    </div>
                </Card>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import { TenkoDashboard } from './TenkoDashboard';
import { ApprovalView } from './ApprovalView';
import { StaffManagement } from './StaffManagement';

interface Props {
  user: User;
  onLogout: () => void;
}

type View = 'dashboard' | 'queue-checkin' | 'queue-checkout' | 'completed' | 'manage';

export const TenkoApp: React.FC<Props> = ({ user, onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [selectedRecordId, setSelectedRecordId] = useState<string | null>(null);

  useEffect(() => {
    const load = () => setRecords(StorageService.getAll());
    load();
    const interval = setInterval(load, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleUpdate = () => {
    setRecords(StorageService.getAll());
    setSelectedRecordId(null);
  };

  const SidebarItem = ({ view, icon, label }: { view: View; icon: string; label: string }) => (
    <div 
      onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
      className={`px-4 py-3 cursor-pointer flex items-center gap-3 transition-colors ${currentView === view ? 'bg-white/20 border-r-4 border-white' : 'hover:bg-white/10 border-r-4 border-transparent'}`}
    >
      <i className={`fas ${icon} w-6`}></i>
      <span className="font-medium">{label}</span>
      {view.includes('queue') && (
        <span className="ml-auto bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
            {records.filter(r => view === 'queue-checkin' ? r.checkin_status === 'pending' : r.checkout_status === 'pending').length}
        </span>
      )}
    </div>
  );

  const renderContent = () => {
    if (selectedRecordId) {
       const record = records.find(r => r.__backendId === selectedRecordId);
       if (!record) return <div>Record not found</div>;
       return (
         <ApprovalView 
            record={record} 
            user={user}
            type={currentView === 'queue-checkin' ? 'checkin' : currentView === 'queue-checkout' ? 'checkout' : 'view'}
            onBack={() => setSelectedRecordId(null)}
            onSuccess={handleUpdate}
         />
       );
    }

    if (currentView === 'manage') return <StaffManagement />;

    return (
      <TenkoDashboard 
        view={currentView} 
        records={records} 
        onSelectRecord={(id) => setSelectedRecordId(id)} 
      />
    );
  };

  return (
    <div className="flex h-full bg-slate-50 overflow-hidden">
      <aside className="w-64 bg-gradient-to-b from-blue-800 to-blue-600 text-white flex flex-col shadow-xl z-20">
        <div className="p-6 border-b border-blue-500/30">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                    <i className="fas fa-user-shield"></i>
                </div>
                <div>
                    <h3 className="font-bold leading-tight">{user.name}</h3>
                    <p className="text-xs text-blue-200">เจ้าหน้าที่ Tenko</p>
                </div>
            </div>
        </div>
        <nav className="flex-1 py-4 space-y-1">
            <SidebarItem view="dashboard" icon="fa-chart-pie" label="ภาพรวม" />
            <SidebarItem view="queue-checkin" icon="fa-clipboard-check" label="คิวตรวจ (ก่อนงาน)" />
            <SidebarItem view="queue-checkout" icon="fa-flag-checkered" label="คิวตรวจ (หลังงาน)" />
            <SidebarItem view="completed" icon="fa-history" label="ประวัติรายการ" />
            <SidebarItem view="manage" icon="fa-users-cog" label="จัดการพนักงาน" />
        </nav>
        <div className="p-4 border-t border-blue-500/30">
            <button onClick={onLogout} className="w-full py-2 bg-blue-900/50 hover:bg-blue-900 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm">
                <i className="fas fa-sign-out-alt"></i> ออกจากระบบ
            </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-8">
        {renderContent()}
      </main>
    </div>
  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  const exportExcel = () => {
    const data = records.map(r => ({
        Date: r.date,
        Driver: r.driver_name,
        CheckInTime: r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString() : '-',
        CheckInStatus: r.checkin_status,
        CheckOutTime: r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString() : '-',
        CheckOutStatus: r.checkout_status,
        AlcoholIn: r.alcohol_checkin || 0,
        AlcoholOut: r.alcohol_checkout || 0
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `tenko_export_${today}.xlsx`);
  };

  const renderStats = () => (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1">รอตรวจก่อนงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1">รอตรวจหลังงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1">เสร็จสิ้นแล้ว</h3>
            <div className="text-4xl font-bold">{completed.length}</div>
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1">รายการวันนี้</h3>
            <div className="text-4xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => (
                    <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                        <div className="flex justify-between items-start mb-3">
                            <div>
                                <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{record.driver_name}</h4>
                                <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                            </div>
                            {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                            {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                        </div>
                        <div className="text-sm text-slate-600 space-y-1">
                            <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                            <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {new Date(type === 'checkout' ? record.checkout_timestamp! : record.checkin_timestamp!).toLocaleTimeString('th-TH')}</p>
                        </div>
                    </Card>
                ))}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <>
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <Card>
                <h3 className="font-bold mb-4 text-amber-600">ล่าสุด (รอตรวจก่อนงาน)</h3>
                {pendingCheckin.slice(0, 5).map(r => (
                    <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded cursor-pointer border-b last:border-0 border-slate-100">
                        <span>{r.driver_name}</span>
                        <span className="text-slate-400 text-sm">{new Date(r.checkin_timestamp!).toLocaleTimeString('th-TH')}</span>
                    </div>
                ))}
                 {pendingCheckin.length === 0 && <p className="text-slate-400 text-sm text-center py-4">ว่าง</p>}
            </Card>
            <Card>
                <h3 className="font-bold mb-4 text-purple-600">ล่าสุด (รอตรวจหลังงาน)</h3>
                {pendingCheckout.slice(0, 5).map(r => (
                    <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded cursor-pointer border-b last:border-0 border-slate-100">
                        <span>{r.driver_name}</span>
                        <span className="text-slate-400 text-sm">{new Date(r.checkout_timestamp!).toLocaleTimeString('th-TH')}</span>
                    </div>
                ))}
                {pendingCheckout.length === 0 && <p className="text-slate-400 text-sm text-center py-4">ว่าง</p>}
            </Card>
        </div>
      </>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

