import React, { useState } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  records: TenkoRecord[];
}

export const TenkoAnalytics: React.FC<Props> = ({ records }) => {
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(today);

  // Stats
  const thisMonthRecords = records.filter(r => {
      const d = new Date(r.checkin_timestamp || r.date);
      return d.getMonth() === currentMonth.getMonth() && d.getFullYear() === currentMonth.getFullYear();
  });
  const todayRecords = records.filter(r => new Date(r.checkin_timestamp || r.date).getDate() === today.getDate() && new Date(r.checkin_timestamp || r.date).getMonth() === today.getMonth());

  // Export Logic
  const exportExcel = () => {
    const data = records.map(r => ({
        Date: r.date,
        Driver: r.driver_name,
        CheckIn_Time: r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleString('th-TH') : '-',
        CheckIn_By: r.checkin_tenko_name,
        CheckOut_Time: r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleString('th-TH') : '-',
        CheckOut_By: r.checkout_tenko_name,
        Temp: r.temperature,
        BP_High: r.blood_pressure_high,
        BP_Low: r.blood_pressure_low,
        Alcohol_In: r.alcohol_checkin,
        Alcohol_Out: r.alcohol_checkout,
        Sleep_Hours: r.sleep_hours,
        Status: (r.checkin_status === 'approved' && r.checkout_status === 'approved') ? 'Completed' : 'Pending'
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "TenkoReport");
    XLSX.writeFile(wb, `Tenko_Export_${today.toISOString().split('T')[0]}.xlsx`);
  };

  // Calendar Logic
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  const getDayCount = (day: number) => {
    return thisMonthRecords.filter(r => new Date(r.checkin_timestamp || r.date).getDate() === day).length;
  };

  return (
    <div className="space-y-6">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">แดชบอร์ดและการส่งออก</h2>
            <Button onClick={exportExcel} className="bg-green-600 hover:bg-green-700">
                <i className="fas fa-file-excel"></i> Export Excel
            </Button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Card className="bg-gradient-to-r from-blue-500 to-blue-600 text-white border-none">
                <h3 className="text-blue-100 text-lg">รายการเดือนนี้</h3>
                <p className="text-5xl font-bold mt-2">{thisMonthRecords.length}</p>
                <p className="text-sm opacity-80 mt-1">{currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</p>
            </Card>
            <Card className="bg-gradient-to-r from-orange-500 to-orange-600 text-white border-none">
                <h3 className="text-orange-100 text-lg">รายการวันนี้</h3>
                <p className="text-5xl font-bold mt-2">{todayRecords.length}</p>
                <p className="text-sm opacity-80 mt-1">{today.toLocaleDateString('th-TH')}</p>
            </Card>
        </div>

        <Card>
            <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg text-slate-700">ปฏิทินงาน</h3>
                <div className="flex gap-2">
                    <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-2 hover:bg-slate-100 rounded"><i className="fas fa-chevron-left"></i></button>
                    <span className="font-bold px-2">{currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</span>
                    <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-2 hover:bg-slate-100 rounded"><i className="fas fa-chevron-right"></i></button>
                </div>
            </div>

            <div className="grid grid-cols-7 gap-1">
                {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-sm font-bold text-slate-400 py-2">{d}</div>)}
                {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                {Array.from({length: daysInMonth}).map((_, i) => {
                    const count = getDayCount(i+1);
                    return (
                        <div key={i} className={`
                            h-16 flex flex-col items-center justify-center rounded-lg border text-sm font-medium transition-colors
                            ${count > 0 ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-100 text-slate-400'}
                        `}>
                            <span>{i+1}</span>
                            {count > 0 && <span className="bg-blue-600 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center mt-1">{count}</span>}
                        </div>
                    );
                })}
            </div>
        </Card>
    </div>
  );
};

import React from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, Badge } from '../../components/UI';

interface Props {
  user: User;
  records: TenkoRecord[];
  onBack: () => void;
  fixStartTime: string;
}

export const DriverHistory: React.FC<Props> = ({ user, records, onBack, fixStartTime }) => {
  const myRecords = records
    .filter(r => r.driver_id === user.id && r.checkin_status === 'approved' && r.checkout_status === 'approved')
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const currentMonth = new Date();
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  const getDayStatus = (day: number) => {
    const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const record = myRecords.find(r => r.date === dateStr);
    if (record) return 'complete';
    if (dateStr === new Date().toISOString().split('T')[0]) return 'today';
    return 'none';
  };

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <div className="bg-purple-600 text-white px-6 py-6 shadow-md">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
            <div>
                <h2 className="text-2xl font-bold">รายงานของฉัน</h2>
                <p className="opacity-80">ประวัติการปฏิบัติงานและการตรวจสอบ</p>
            </div>
            <Button onClick={onBack} variant="secondary" className="border-white text-white hover:bg-white/20">ย้อนกลับ</Button>
        </div>
      </div>

      <div className="max-w-4xl mx-auto p-6 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
             <Card className="bg-white border-l-4 border-blue-500">
                 <p className="text-sm text-slate-500">เดือนนี้</p>
                 <p className="text-3xl font-bold text-blue-600">{myRecords.filter(r => new Date(r.date).getMonth() === currentMonth.getMonth()).length}</p>
                 <p className="text-xs text-slate-400">ครั้ง</p>
             </Card>
             <Card className="bg-white border-l-4 border-purple-500">
                 <p className="text-sm text-slate-500">ทั้งหมด</p>
                 <p className="text-3xl font-bold text-purple-600">{myRecords.length}</p>
                 <p className="text-xs text-slate-400">ครั้ง</p>
             </Card>
             <Card className={`bg-white border-l-4 ${fixStartTime === 'OK' ? 'border-emerald-500' : 'border-red-500'}`}>
                 <p className="text-sm text-slate-500">Fix Start Time</p>
                 <p className={`text-3xl font-bold ${fixStartTime === 'OK' ? 'text-emerald-600' : 'text-red-600'}`}>{fixStartTime}</p>
                 <p className="text-xs text-slate-400">{fixStartTime === 'OK' ? 'ปกติ' : 'ผิดปกติ'}</p>
             </Card>
        </div>

        <Card>
            <h3 className="font-bold mb-4 text-slate-700">ปฏิทิน {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</h3>
            <div className="grid grid-cols-7 gap-1">
                {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                {Array.from({length: daysInMonth}).map((_, i) => {
                    const status = getDayStatus(i+1);
                    return (
                        <div key={i} className={`
                            h-10 flex items-center justify-center rounded-lg text-sm font-medium
                            ${status === 'complete' ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 
                              status === 'today' ? 'bg-blue-100 text-blue-700 border border-blue-200' : 'bg-slate-50 text-slate-400'}
                        `}>
                            {i+1}
                        </div>
                    );
                })}
            </div>
        </Card>

        <div className="space-y-4">
            <h3 className="font-bold text-slate-700">รายการล่าสุด</h3>
            {myRecords.slice(0, 10).map(record => (
                <Card key={record.__backendId} className="hover:bg-slate-50 transition-colors">
                    <div className="flex justify-between items-start mb-3">
                        <div>
                            <p className="font-bold text-slate-800">
                                {new Date(record.date).toLocaleDateString('th-TH', { dateStyle: 'long' })}
                            </p>
                            <p className="text-xs text-slate-500">ID: {record.__backendId.substring(0, 8)}</p>
                        </div>
                        <Badge type="approved">สมบูรณ์</Badge>
                    </div>
                    <div className="grid grid-cols-2 gap-4 text-sm">
                        <div className="p-2 bg-blue-50 rounded">
                            <p className="font-semibold text-blue-800 mb-1">ก่อนเริ่มงาน</p>
                            <p>เวลา: {record.checkin_timestamp ? new Date(record.checkin_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'}</p>
                            <p>ผู้ตรวจ: {record.checkin_tenko_name}</p>
                            <p>แอลกอฮอล์: {record.alcohol_checkin}</p>
                        </div>
                        <div className="p-2 bg-emerald-50 rounded">
                            <p className="font-semibold text-emerald-800 mb-1">หลังเลิกงาน</p>
                            <p>เวลา: {record.checkout_timestamp ? new Date(record.checkout_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'}</p>
                            <p>ผู้ตรวจ: {record.checkout_tenko_name}</p>
                            <p>แอลกอฮอล์: {record.alcohol_checkout}</p>
                        </div>
                    </div>
                </Card>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, OptionButton, Input } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  user: User;
  onBack: () => void;
  onSubmitSuccess: () => void;
}

export const CheckinForm: React.FC<Props> = ({ user, onBack, onSubmitSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    tired: 'ไม่มี',
    sick: 'ไม่มี',
    drowsy: 'ไม่มี',
    injury: 'ไม่มี',
    medication: 'ไม่ทาน',
    body_condition: 'ปกติ',
    sleep_quality: 'หลับสนิท',
    extra_sleep: 'ไม่นอนเพิ่ม',
    worry_detail: 'ไม่มี',
    rest_location: 'บ้าน',
    vision_problem: 'ไม่มี',
    glasses: 'ไม่มี',
    hearing_problem: 'ไม่มี',
    hearing_aid: 'ไม่มี'
  });
  const [submitting, setSubmitting] = useState(false);
  const [lastCheckout, setLastCheckout] = useState<string | null>(null);

  useEffect(() => {
    // Find last checkout time
    const records = StorageService.getAll();
    const myRecords = records
        .filter(r => r.driver_id === user.id && r.checkout_timestamp)
        .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());

    if (myRecords.length > 0) {
        setLastCheckout(new Date(myRecords[0].checkout_timestamp!).toLocaleString('th-TH'));
    }
  }, [user.id]);

  const updateForm = (key: keyof TenkoRecord, value: any) => {
    setForm(prev => ({ ...prev, [key]: value }));
  };

  const calculateHours = (start?: string, end?: string) => {
    if (!start || !end) return 0;
    const s = new Date(`2000-01-01T${start}`);
    let e = new Date(`2000-01-01T${end}`);
    if (e < s) e.setDate(e.getDate() + 1);
    return (e.getTime() - s.getTime()) / (1000 * 60 * 60);
  };

  const handleSleepChange = (field: 'sleep' | 'extra_sleep', type: 'start' | 'end', val: string) => {
    if (field === 'sleep') {
        const start = type === 'start' ? val : form.sleep_start;
        const end = type === 'end' ? val : form.sleep_end;
        updateForm(type === 'start' ? 'sleep_start' : 'sleep_end', val);
        if (start && end) updateForm('sleep_hours', calculateHours(start, end));
    } else {
        const start = type === 'start' ? val : form.extra_sleep_start;
        const end = type === 'end' ? val : form.extra_sleep_end;
        updateForm(type === 'start' ? 'extra_sleep_start' : 'extra_sleep_end', val);
        if (start && end) updateForm('extra_sleep_hours', calculateHours(start, end));
    }
  };

  const handleSubmit = () => {
    if (!form.sleep_hours) {
      alert('กรุณากรอกเวลาการนอนหลับ');
      return;
    }

    setSubmitting(true);
    setTimeout(() => {
      StorageService.create({
        driver_id: user.id,
        driver_name: user.name,
        date: new Date().toISOString().split('T')[0],
        checkin_real_timestamp: new Date().toISOString(),
        checkin_status: 'pending',
        checkout_status: null,
        ...form
      });
      setSubmitting(false);
      onSubmitSuccess();
    }, 800);
  };

  const renderSection = (title: string, icon: string, children: React.ReactNode) => (
    <Card className="mb-4">
        <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2 text-lg border-b pb-2">
            <i className={`fas ${icon} text-blue-500`}></i> {title}
        </h3>
        {children}
    </Card>
  );

  const renderQuestion = (
    label: string, 
    field: keyof TenkoRecord, 
    detailField?: keyof TenkoRecord, 
    triggerValue: string = 'มี',
    choices: string[] = ['มี', 'ไม่มี']
  ) => (
    <div className="mb-4 last:mb-0">
      <label className="block text-slate-700 font-medium mb-2">{label}</label>
      <div className="flex gap-2 mb-2 flex-wrap">
        {choices.map(opt => (
          <OptionButton 
            key={opt}
            selected={form[field] === opt} 
            onClick={() => updateForm(field, opt)}
          >
            {opt}
          </OptionButton>
        ))}
      </div>
      {form[field] === triggerValue && detailField && (
        <Input 
          placeholder="ระบุรายละเอียด" 
          value={(form[detailField] as string) || ''}
          onChange={e => updateForm(detailField, e.target.value)}
        />
      )}
    </div>
  );

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <div className="bg-white sticky top-0 z-20 px-6 py-4 shadow-sm flex justify-between items-center">
        <div>
            <h2 className="text-xl font-bold text-slate-800">เท็งโกะก่อนเริ่มงาน</h2>
        </div>
        <Button variant="secondary" onClick={onBack} size="sm">ย้อนกลับ</Button>
      </div>

      <div className="max-w-3xl mx-auto p-6 pb-24">
        <Card className="mb-4 bg-slate-100 border-slate-200">
            <h3 className="font-semibold text-slate-700 mb-1 flex items-center gap-2">
                <i className="fas fa-clock text-slate-500"></i> เวลาเลิกงานล่าสุด
            </h3>
            <p className="text-2xl font-bold text-slate-800">{lastCheckout || 'ไม่มีประวัติ'}</p>
        </Card>

        {renderSection('อาการทั่วไป', 'fa-heartbeat', (
            <>
                {renderQuestion('1. มีอาการเหนื่อยล้า?', 'tired', 'tired_detail')}
                {renderQuestion('2. มีอาการเจ็บป่วย?', 'sick', 'sick_detail', 'มี')}
                {form.sick === 'มี' && (
                    <div className="pl-4 border-l-2 border-slate-200 mb-4 space-y-3">
                         {renderQuestion('ไปพบแพทย์หรือไม่?', 'seen_doctor', 'seen_doctor_detail', 'มี')}
                    </div>
                )}
                {renderQuestion('3. มีอาการง่วงนอน?', 'drowsy', 'drowsy_detail')}
                {renderQuestion('4. มีอาการบาดเจ็บ?', 'injury', 'injury_detail')}
                {renderQuestion('5. ทานยาที่ส่งผลต่อการขับขี่?', 'medication', 'medication_name', 'ทาน', ['ทาน', 'ไม่ทาน'])}
                {renderQuestion('6. สภาพร่างกาย?', 'body_condition', 'body_condition_detail', 'ไม่ปกติ', ['ปกติ', 'ไม่ปกติ'])}
            </>
        ))}

        {renderSection('การนอนหลับ', 'fa-bed', (
            <>
                <h4 className="font-bold text-slate-700 mb-2">7. การนอนปกติ</h4>
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <Input type="time" label="เริ่มนอน" value={form.sleep_start || ''} onChange={e => handleSleepChange('sleep', 'start', e.target.value)} />
                    <Input type="time" label="ตื่น" value={form.sleep_end || ''} onChange={e => handleSleepChange('sleep', 'end', e.target.value)} />
                </div>
                <div className={`p-3 rounded-lg text-center font-bold text-lg mb-4 border-2 ${
                    (form.sleep_hours || 0) < 6 ? 'bg-red-50 border-red-200 text-red-700' : 'bg-green-50 border-green-200 text-green-700'
                }`}>
                    รวม {form.sleep_hours?.toFixed(1) || 0} ชั่วโมง
                </div>
                {renderQuestion('คุณภาพการนอน', 'sleep_quality', 'sleep_quality_detail', 'ไม่สนิท', ['หลับสนิท', 'ไม่สนิท'])}

                <hr className="my-4"/>

                <h4 className="font-bold text-slate-700 mb-2">8. การนอนเพิ่ม</h4>
                {renderQuestion('มีการนอนเพิ่มหรือไม่?', 'extra_sleep', undefined, 'นอนเพิ่ม', ['นอนเพิ่ม', 'ไม่นอนเพิ่ม'])}

                {form.extra_sleep === 'นอนเพิ่ม' && (
                    <div className="bg-blue-50 p-4 rounded-lg">
                        <p className="text-sm text-blue-800 mb-2 font-bold"><i className="fas fa-info-circle"></i> การนอนเพิ่มควรมากกว่า 4.5 ชั่วโมง</p>
                        <div className="grid grid-cols-2 gap-4 mb-4">
                            <Input type="time" label="เริ่มนอนเพิ่ม" value={form.extra_sleep_start || ''} onChange={e => handleSleepChange('extra_sleep', 'start', e.target.value)} />
                            <Input type="time" label="ตื่นมาเพิ่ม" value={form.extra_sleep_end || ''} onChange={e => handleSleepChange('extra_sleep', 'end', e.target.value)} />
                        </div>
                        <div className={`p-3 rounded-lg text-center font-bold text-lg mb-4 border-2 ${
                            (form.extra_sleep_hours || 0) < 4.5 ? 'bg-red-50 border-red-200 text-red-700' : 'bg-green-50 border-green-200 text-green-700'
                        }`}>
                            รวม {form.extra_sleep_hours?.toFixed(1) || 0} ชั่วโมง
                        </div>
                        {renderQuestion('คุณภาพการนอนเพิ่ม', 'extra_sleep_quality', 'extra_sleep_quality_detail', 'ไม่สนิท', ['หลับสนิท', 'ไม่สนิท'])}
                    </div>
                )}
            </>
        ))}

        {renderSection('สภาพแวดล้อมและประสาทสัมผัส', 'fa-eye', (
             <>
                {renderQuestion('เรื่องกังวลใจ?', 'worry_detail', 'worry_text')}
                {renderQuestion('สถานที่พักผ่อน?', 'rest_location', 'rest_location_detail', 'นอกบ้าน', ['บ้าน', 'นอกบ้าน'])}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        {renderQuestion('ปัญหาสายตา?', 'vision_problem', 'vision_detail')}
                        {renderQuestion('สวมแว่นตา?', 'glasses', 'glasses_detail')}
                    </div>
                    <div>
                        {renderQuestion('ปัญหาการได้ยิน?', 'hearing_problem', 'hearing_detail')}
                        {renderQuestion('เครื่องช่วยฟัง?', 'hearing_aid', 'hearing_aid_detail')}
                    </div>
                </div>
             </>
        ))}

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t flex justify-center z-20">
            <Button onClick={handleSubmit} isLoading={submitting} className="w-full max-w-md py-3 text-lg">
                <i className="fas fa-paper-plane"></i> ส่งข้อมูลให้ Tenko
            </Button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  const exportExcel = () => {
    const data = records.map(r => ({
        Date: r.date,
        Driver: r.driver_name,
        CheckInTime: r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString() : '-',
        CheckInStatus: r.checkin_status,
        CheckOutTime: r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString() : '-',
        CheckOutStatus: r.checkout_status,
        AlcoholIn: r.alcohol_checkin || 0,
        AlcoholOut: r.alcohol_checkout || 0
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `tenko_export_${today}.xlsx`);
  };

  const renderStats = () => (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1">รอตรวจก่อนงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1">รอตรวจหลังงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1">เสร็จสิ้นแล้ว</h3>
            <div className="text-4xl font-bold">{completed.length}</div>
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1">รายการวันนี้</h3>
            <div className="text-4xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => (
                    <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                        <div className="flex justify-between items-start mb-3">
                            <div>
                                <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{record.driver_name}</h4>
                                <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                            </div>
                            {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                            {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                        </div>
                        <div className="text-sm text-slate-600 space-y-1">
                            <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                            <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {new Date(type === 'checkout' ? record.checkout_timestamp! : record.checkin_timestamp!).toLocaleTimeString('th-TH')}</p>
                        </div>
                    </Card>
                ))}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-[500px]">
            <Card className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-600 text-lg">
                        <i className="fas fa-clock"></i> ล่าสุด (รอตรวจก่อนงาน)
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length} รายการ</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{new Date(r.checkin_timestamp!).toLocaleTimeString('th-TH')}</p>
                                <p className="text-xs text-slate-400">น.</p>
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการค้าง</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-600 text-lg">
                        <i className="fas fa-flag-checkered"></i> ล่าสุด (รอตรวจหลังงาน)
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length} รายการ</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{new Date(r.checkout_timestamp!).toLocaleTimeString('th-TH')}</p>
                                <p className="text-xs text-slate-400">น.</p>
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการค้าง</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

