  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  const exportExcel = () => {
    const data = records.map(r => ({
        Date: r.date,
        Driver: r.driver_name,
        CheckInTime: r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString() : '-',
        CheckInStatus: r.checkin_status,
        CheckOutTime: r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString() : '-',
        CheckOutStatus: r.checkout_status,
        AlcoholIn: r.alcohol_checkin || 0,
        AlcoholOut: r.alcohol_checkout || 0
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `tenko_export_${today}.xlsx`);
  };

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleTimeString('th-TH');
    } catch (e) {
        return '-';
    }
  };

  const renderStats = () => (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1">รอตรวจก่อนงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1">รอตรวจหลังงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1">เสร็จสิ้นแล้ว</h3>
            <div className="text-4xl font-bold">{completed.length}</div>
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1">รายการวันนี้</h3>
            <div className="text-4xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors">{record.driver_name}</h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-[500px]">
            <Card className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-600 text-lg">
                        <i className="fas fa-clock"></i> ล่าสุด (รอตรวจก่อนงาน)
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length} รายการ</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                                <p className="text-xs text-slate-400">น.</p>
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการค้าง</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-600 text-lg">
                        <i className="fas fa-flag-checkered"></i> ล่าสุด (รอตรวจหลังงาน)
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length} รายการ</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkout_timestamp || r.checkout_real_timestamp)}</p>
                                <p className="text-xs text-slate-400">น.</p>
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการค้าง</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

import React, { useState, useMemo } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import * as XLSX from 'xlsx';

interface Props {
  records: TenkoRecord[];
}

export const TenkoAnalytics: React.FC<Props> = ({ records }) => {
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(today);
  const [selectedDriverId, setSelectedDriverId] = useState<string>(''); // Filter state

  const drivers = StorageService.getUsers().filter(u => u.role === 'driver');

  // --- Filtering Logic ---
  const filteredRecords = useMemo(() => {
    let res = records;
    if (selectedDriverId) {
        res = res.filter(r => r.driver_id === selectedDriverId);
    }
    return res;
  }, [records, selectedDriverId]);

  const monthRecords = useMemo(() => {
    return filteredRecords.filter(r => {
        const d = new Date(r.checkin_timestamp || r.date);
        return d.getMonth() === currentMonth.getMonth() && d.getFullYear() === currentMonth.getFullYear();
    });
  }, [filteredRecords, currentMonth]);

  // --- Graph Data (Last 5 days for selected driver or aggregate) ---
  const graphData = useMemo(() => {
    // Sort by date ascending
    const sorted = [...monthRecords]
        .filter(r => r.blood_pressure_high && r.blood_pressure_low)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Take last 5
    return sorted.slice(-5);
  }, [monthRecords]);


  // --- Export Logic ---
  const exportExcel = () => {
    const data = monthRecords.map(r => ({
        Date: r.date,
        Driver: r.driver_name,
        CheckIn_Time: r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleString('th-TH') : '-',
        CheckIn_By: r.checkin_tenko_name,
        Temp: r.temperature,
        BP_High: r.blood_pressure_high,
        BP_Low: r.blood_pressure_low,
        Alcohol: r.alcohol_checkin,
        Status: (r.checkin_status === 'approved' && r.checkout_status === 'approved') ? 'Completed' : 'Pending'
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "TenkoReport");
    XLSX.writeFile(wb, `Tenko_Export_${selectedDriverId || 'ALL'}_${currentMonth.toISOString().slice(0,7)}.xlsx`);
  };

  // --- Calendar Helpers ---
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  const getDayCount = (day: number) => {
    const target = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
    return filteredRecords.filter(r => r.date === target).length;
  };

  // --- SVG Graph Render ---
  const renderBPGraph = () => {
    if (graphData.length < 2) return <div className="h-64 flex items-center justify-center text-slate-400 bg-slate-50 rounded-lg border border-dashed">ข้อมูลไม่เพียงพอสำหรับกราฟ (ต้องมีอย่างน้อย 2 วัน)</div>;

    // Canvas Configuration
    const svgHeight = 300;
    const svgWidth = 800; // Internal coordinate system width
    const paddingX = 80;
    const paddingY = 40;

    // Y-Axis Scale
    const maxVal = 180;
    const minVal = 50;
    const range = maxVal - minVal;
    const drawingHeight = svgHeight - (paddingY * 2);
    const drawingWidth = svgWidth - (paddingX * 2);

    const getX = (i: number) => paddingX + (i / (graphData.length - 1)) * drawingWidth;
    const getY = (val: number) => (svgHeight - paddingY) - ((val - minVal) / range) * drawingHeight;

    // Generate Points
    const pointsHigh = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_high || 0)}`).join(' ');
    const pointsLow = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_low || 0)}`).join(' ');

    // Generate Areas (for gradient fill)
    const areaHigh = `${pointsHigh} ${getX(graphData.length-1)},${svgHeight-paddingY} ${getX(0)},${svgHeight-paddingY}`;
    const areaLow = `${pointsLow} ${getX(graphData.length-1)},${svgHeight-paddingY} ${getX(0)},${svgHeight-paddingY}`;

    return (
        <div className="relative h-[320px] w-full p-2">
            <svg viewBox={`0 0 ${svgWidth} ${svgHeight}`} className="w-full h-full overflow-visible drop-shadow-sm">
                <defs>
                    <linearGradient id="gradHigh" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stopColor="#ef4444" stopOpacity="0.2" />
                        <stop offset="100%" stopColor="#ef4444" stopOpacity="0" />
                    </linearGradient>
                    <linearGradient id="gradLow" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.2" />
                        <stop offset="100%" stopColor="#3b82f6" stopOpacity="0" />
                    </linearGradient>
                </defs>

                {/* Grid Lines & Y-Axis Labels */}
                {[60, 90, 120, 150].map((val) => (
                    <g key={val}>
                        <line 
                            x1={paddingX - 10} y1={getY(val)} 
                            x2={svgWidth - paddingX + 10} y2={getY(val)} 
                            stroke="#e2e8f0" strokeWidth="1" strokeDasharray={val === 90 || val === 140 ? "5,5" : ""} 
                        />
                        <text x={paddingX - 20} y={getY(val) + 4} fontSize="12" fill="#94a3b8" textAnchor="end">{val}</text>
                    </g>
                ))}

                {/* Area Fills */}
                <polygon points={areaHigh} fill="url(#gradHigh)" />
                <polygon points={areaLow} fill="url(#gradLow)" />

                {/* Lines */}
                <polyline points={pointsHigh} fill="none" stroke="#ef4444" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                <polyline points={pointsLow} fill="none" stroke="#3b82f6" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

                {/* Data Points */}
                {graphData.map((d, i) => (
                    <g key={i} className="group cursor-pointer">
                        {/* High Point */}
                        <circle cx={getX(i)} cy={getY(d.blood_pressure_high!)} r="5" fill="#fff" stroke="#ef4444" strokeWidth="2.5" className="transition-all duration-300 group-hover:r-7" />
                        <text x={getX(i)} y={getY(d.blood_pressure_high!) - 15} fontSize="14" fontWeight="bold" fill="#ef4444" textAnchor="middle" className="opacity-0 group-hover:opacity-100 transition-opacity select-none">{d.blood_pressure_high}</text>

                        {/* Low Point */}
                        <circle cx={getX(i)} cy={getY(d.blood_pressure_low!)} r="5" fill="#fff" stroke="#3b82f6" strokeWidth="2.5" className="transition-all duration-300 group-hover:r-7" />
                        <text x={getX(i)} y={getY(d.blood_pressure_low!) + 25} fontSize="14" fontWeight="bold" fill="#3b82f6" textAnchor="middle" className="opacity-0 group-hover:opacity-100 transition-opacity select-none">{d.blood_pressure_low}</text>

                        {/* X-Axis Date Label */}
                        <text x={getX(i)} y={svgHeight - 10} fontSize="12" fill="#64748b" textAnchor="middle">{new Date(d.date).toLocaleDateString('th-TH', {day: 'numeric', month: 'short'})}</text>

                        {/* Vertical Guide Line on Hover */}
                        <line x1={getX(i)} y1={paddingY} x2={getX(i)} y2={svgHeight - paddingY} stroke="#94a3b8" strokeWidth="1" strokeDasharray="4" className="opacity-0 group-hover:opacity-20" />
                    </g>
                ))}
            </svg>
            <div className="absolute top-2 right-4 flex gap-4 text-xs bg-white/80 p-2 rounded-lg backdrop-blur-sm shadow-sm border border-slate-100">
                <div className="flex items-center gap-2"><div className="w-3 h-3 bg-red-500 rounded-full border-2 border-white shadow-sm"></div> ความดันบน (SYS)</div>
                <div className="flex items-center gap-2"><div className="w-3 h-3 bg-blue-500 rounded-full border-2 border-white shadow-sm"></div> ความดันล่าง (DIA)</div>
            </div>
        </div>
    );
  };

  return (
    <div className="space-y-6">
        {/* Header & Controls */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <div>
                <h2 className="text-2xl font-bold text-slate-800">แดชบอร์ด & สถิติ</h2>
                <p className="text-slate-500 text-sm">ข้อมูลเดือน: {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</p>
            </div>
            <div className="flex gap-3 w-full md:w-auto">
                <select 
                    className="p-2.5 border rounded-lg bg-slate-50 min-w-[200px]"
                    value={selectedDriverId}
                    onChange={(e) => setSelectedDriverId(e.target.value)}
                >
                    <option value="">-- พนักงานทั้งหมด --</option>
                    {drivers.map(d => (
                        <option key={d.id} value={d.id}>{d.name} ({d.id})</option>
                    ))}
                </select>
                <Button onClick={exportExcel} className="bg-green-600 hover:bg-green-700 whitespace-nowrap">
                    <i className="fas fa-file-excel"></i> Export
                </Button>
            </div>
        </div>

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Left: Calendar */}
            <Card className="h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg text-slate-700">ปฏิทินการทำงาน</h3>
                    <div className="flex gap-2">
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-1 hover:bg-slate-100 rounded"><i className="fas fa-chevron-left"></i></button>
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-1 hover:bg-slate-100 rounded"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>

                <div className="grid grid-cols-7 gap-1">
                    {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                    {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                    {Array.from({length: daysInMonth}).map((_, i) => {
                        const count = getDayCount(i+1);
                        return (
                            <div key={i} className={`
                                h-14 flex flex-col items-center justify-center rounded-lg border text-sm font-medium transition-colors relative
                                ${count > 0 ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-100 text-slate-400'}
                                ${selectedDriverId && count > 0 ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : ''}
                            `}>
                                <span>{i+1}</span>
                                {count > 0 && (
                                    <span className={`text-xs rounded-full w-5 h-5 flex items-center justify-center mt-1 text-white font-bold
                                        ${selectedDriverId ? 'bg-emerald-500' : 'bg-blue-600'}
                                    `}>
                                        {selectedDriverId ? <i className="fas fa-check text-[10px]"></i> : count}
                                    </span>
                                )}
                            </div>
                        );
                    })}
                </div>
            </Card>

            {/* Right: BP Graph */}
            <Card className="h-full flex flex-col">
                <div className="mb-4">
                    <h3 className="font-bold text-lg text-slate-700 flex items-center gap-2">
                        <i className="fas fa-heartbeat text-red-500"></i> แนวโน้มความดันโลหิต
                    </h3>
                    <p className="text-xs text-slate-500">5 วันล่าสุดที่มีข้อมูล {selectedDriverId ? '(รายบุคคล)' : '(รวม)'}</p>
                </div>
                <div className="flex-1 bg-white rounded-lg border border-slate-100 overflow-hidden shadow-inner">
                    {renderBPGraph()}
                </div>
                <div className="mt-4 grid grid-cols-2 gap-4 text-center">
                    <div className="bg-red-50 p-3 rounded-lg border border-red-100">
                        <span className="text-xs text-slate-500 block uppercase tracking-wide">Avg ความดันบน</span>
                        <span className="font-bold text-red-600 text-xl">
                            {graphData.length > 0 ? Math.round(graphData.reduce((a,b) => a + (b.blood_pressure_high||0), 0) / graphData.length) : '-'}
                        </span>
                        <span className="text-xs text-red-400 ml-1">mmHg</span>
                    </div>
                    <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                        <span className="text-xs text-slate-500 block uppercase tracking-wide">Avg ความดันล่าง</span>
                        <span className="font-bold text-blue-600 text-xl">
                            {graphData.length > 0 ? Math.round(graphData.reduce((a,b) => a + (b.blood_pressure_low||0), 0) / graphData.length) : '-'}
                        </span>
                        <span className="text-xs text-blue-400 ml-1">mmHg</span>
                    </div>
                </div>
            </Card>
        </div>

        {/* Bottom: Detailed List */}
        <Card>
            <h3 className="font-bold text-lg text-slate-700 mb-4 flex items-center gap-2">
                <i className="fas fa-list"></i> รายละเอียดการตรวจ ({monthRecords.length} รายการ)
            </h3>
            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-100 text-slate-600 font-semibold uppercase">
                        <tr>
                            <th className="p-3 rounded-tl-lg">วันที่</th>
                            <th className="p-3">พนักงาน</th>
                            <th className="p-3 text-center">เวลาเข้า</th>
                            <th className="p-3 text-center">BP (บน/ล่าง)</th>
                            <th className="p-3 text-center">Temp</th>
                            <th className="p-3 text-center">Alcohol</th>
                            <th className="p-3 text-right rounded-tr-lg">สถานะ</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {monthRecords.map(r => (
                            <tr key={r.__backendId} className="hover:bg-slate-50 transition-colors">
                                <td className="p-3 font-medium text-slate-700">{new Date(r.date).toLocaleDateString('th-TH')}</td>
                                <td className="p-3">
                                    <div className="font-bold text-slate-700">{r.driver_name}</div>
                                    <div className="text-xs text-slate-400">{r.driver_id}</div>
                                </td>
                                <td className="p-3 text-center text-slate-600">
                                    {r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'}
                                </td>
                                <td className="p-3 text-center">
                                    <span className={`font-bold ${r.blood_pressure_high! > 140 ? 'text-red-600' : 'text-slate-700'}`}>
                                        {r.blood_pressure_high}
                                    </span> / {r.blood_pressure_low}
                                </td>
                                <td className="p-3 text-center">{r.temperature}</td>
                                <td className="p-3 text-center text-emerald-600 font-bold">{r.alcohol_checkin}</td>
                                <td className="p-3 text-right">
                                    <Badge type={r.checkin_status === 'approved' ? 'approved' : 'pending'}>
                                        {r.checkin_status === 'approved' ? 'อนุมัติแล้ว' : 'รอตรวจ'}
                                    </Badge>
                                </td>
                            </tr>
                        ))}
                        {monthRecords.length === 0 && (
                            <tr>
                                <td colSpan={7} className="p-8 text-center text-slate-400">ไม่พบข้อมูล</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </Card>
    </div>
  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  const exportExcel = () => {
    const data = records.map(r => ({
        Date: r.date,
        Driver: r.driver_name,
        CheckInTime: r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString() : '-',
        CheckInStatus: r.checkin_status,
        CheckOutTime: r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString() : '-',
        CheckOutStatus: r.checkout_status,
        AlcoholIn: r.alcohol_checkin || 0,
        AlcoholOut: r.alcohol_checkout || 0
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `tenko_export_${today}.xlsx`);
  };

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
        return '-';
    }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    // Logic to find first Monday approved checkin
    const history = records.filter(r => 
        r.driver_id === record.driver_id && 
        r.checkin_status === 'approved' && 
        r.checkin_timestamp
    ).sort((a,b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const mondayRecord = history.find(r => new Date(r.checkin_timestamp!).getDay() === 1);

    let status = 'New';

    if (mondayRecord) {
        const currentStr = record.checkin_timestamp || record.checkin_real_timestamp;
        if (currentStr) {
             const baseDate = new Date(mondayRecord.checkin_timestamp!);
             const targetDate = new Date(currentStr);
             const baseMinutes = baseDate.getHours() * 60 + baseDate.getMinutes();
             const targetMinutes = targetDate.getHours() * 60 + targetDate.getMinutes();

             if (Math.abs(targetMinutes - baseMinutes) > 120) {
                 status = 'NG';
             } else {
                 status = 'OK';
             }
        }
    }

    if (status === 'NG') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-600 border border-red-200 whitespace-nowrap">Fix Start: NG</span>;
    if (status === 'OK') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-600 border border-emerald-200 whitespace-nowrap">Fix Start: OK</span>;
    return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 border border-slate-200 whitespace-nowrap">First Time</span>;
  };

  const renderStats = () => (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1">รอตรวจก่อนงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1">รอตรวจหลังงาน</h3>
            <div className="text-4xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1">เสร็จสิ้นแล้ว</h3>
            <div className="text-4xl font-bold">{completed.length}</div>
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1">รายการวันนี้</h3>
            <div className="text-4xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors flex items-center flex-wrap gap-1">
                                        {record.driver_name}
                                        {type === 'checkin' && getFixStartBadge(record)}
                                    </h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-[500px]">
            <Card className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-600 text-lg">
                        <i className="fas fa-clock"></i> ล่าสุด (รอตรวจก่อนงาน)
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length} รายการ</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700 flex items-center gap-1">
                                    {r.driver_name}
                                    {getFixStartBadge(r)}
                                </p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                                <p className="text-xs text-slate-400">น.</p>
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการค้าง</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-600 text-lg">
                        <i className="fas fa-flag-checkered"></i> ล่าสุด (รอตรวจหลังงาน)
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length} รายการ</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkout_timestamp || r.checkout_real_timestamp)}</p>
                                <p className="text-xs text-slate-400">น.</p>
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการค้าง</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

import React, { useState, useEffect } from 'react';
import { TenkoRecord, User } from '../../types';
import { Button, Card, Input, OptionButton, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  record: TenkoRecord;
  user: User;
  type: 'checkin' | 'checkout' | 'view';
  onBack: () => void;
  onSuccess: () => void;
}

export const ApprovalView: React.FC<Props> = ({ record, user, type, onBack, onSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    temperature: record.temperature,
    blood_pressure_high: record.blood_pressure_high,
    blood_pressure_low: record.blood_pressure_low,
    alcohol_checkin: record.alcohol_checkin ?? 0,
    alcohol_checkout: record.alcohol_checkout ?? 0,
    phone_usage_compliant: record.phone_usage_compliant || 'ตรงตามที่แจ้ง',
    can_work: record.can_work || 'ได้',
    driving_violation: record.driving_violation || 'ไม่มี',

    // Default approval timestamp to now if not set
    checkin_timestamp: record.checkin_timestamp || new Date().toISOString(),
    checkout_timestamp: record.checkout_timestamp || new Date().toISOString()
  });

  const [fixStartStatus, setFixStartStatus] = useState<string>('N/A');
  const [lastCheckout, setLastCheckout] = useState<string>('-');

  // --- Logic for Fix Start Time & Last Checkout ---
  useEffect(() => {
    const allRecords = StorageService.getAll();

    // 1. Last Checkout
    const previousRecords = allRecords
        .filter(r => r.driver_id === record.driver_id && r.checkout_timestamp && r.__backendId !== record.__backendId)
        .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());
    if (previousRecords.length > 0) {
        setLastCheckout(new Date(previousRecords[0].checkout_timestamp!).toLocaleString('th-TH'));
    }

    // 2. Fix Start Time Logic
    const driverRecords = allRecords
      .filter(r => r.driver_id === record.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
      .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    if (driverRecords.length > 0) {
        const mondayRecords = driverRecords.filter(r => new Date(r.checkin_timestamp!).getDay() === 1);
        if (mondayRecords.length > 0) {
            const firstMonday = new Date(mondayRecords[0].checkin_timestamp!);
            const firstMondayTime = firstMonday.getHours() * 60 + firstMonday.getMinutes();

            // Compare current record with first Monday
            const currentRecTime = new Date(form.checkin_timestamp!).getHours() * 60 + new Date(form.checkin_timestamp!).getMinutes();
            const diff = Math.abs(currentRecTime - firstMondayTime);
            setFixStartStatus(diff > 120 ? 'NG' : 'OK');
        } else {
             setFixStartStatus('OK (No Monday Record)');
        }
    } else {
        setFixStartStatus('OK (First Record)');
    }
  }, [record.driver_id, form.checkin_timestamp]);


  const updateForm = (k: keyof TenkoRecord, v: any) => setForm(p => ({ ...p, [k]: v }));

  // --- Validation Helpers ---
  const isTempBad = (t?: number) => t && t > 37.5;
  const isBPHighBad = (bp?: number) => bp && (bp < 90 || bp > 160);
  const isBPLowBad = (bp?: number) => bp && (bp < 60 || bp > 100);
  const isAlcoholBad = (a?: number) => a !== undefined && a !== 0;

  const handleApprove = () => {
    // Basic validation for reasons
    if (isAlcoholBad(form.alcohol_checkin) && !form.alcohol_checkin_reason) return alert('กรุณาระบุเหตุผลค่าแอลกอฮอล์');
    if (form.can_work === 'ไม่ได้' && !form.cannot_work_reason) return alert('กรุณาระบุสาเหตุที่วิ่งงานไม่ได้');

    const updateData: Partial<TenkoRecord> = { ...form };

    if (type === 'checkin') {
      updateData.checkin_status = 'approved';
      updateData.checkin_tenko_id = user.id;
      updateData.checkin_tenko_name = user.name;
    } else if (type === 'checkout') {
      updateData.checkout_status = 'approved';
      updateData.checkout_tenko_id = user.id;
      updateData.checkout_tenko_name = user.name;
    }

    StorageService.update({ ...record, ...updateData });
    onSuccess();
  };

  const handleDelete = () => {
      if(confirm('ยืนยันการลบข้อมูลนี้?')) {
          StorageService.delete(record.__backendId);
          onSuccess();
      }
  }

  // Helper to format Date ISO string (UTC) to Local datetime-local input format (YYYY-MM-DDTHH:mm)
  const formatDateForInput = (isoString?: string) => {
      if (!isoString) return '';
      const date = new Date(isoString);
      if (isNaN(date.getTime())) return '';

      // We need to shift the time by the timezone offset so that toISOString() outputs the local time values
      const tzOffset = date.getTimezoneOffset() * 60000; 
      const localDate = new Date(date.getTime() - tzOffset);
      return localDate.toISOString().slice(0, 16);
  };

  const handleDateChange = (val: string, field: 'checkin_timestamp' | 'checkout_timestamp') => {
      if (!val) return;
      // val is YYYY-MM-DDTHH:mm in Local time.
      // new Date(val) creates a date object representing that local time.
      // .toISOString() converts it back to UTC for storage.
      const date = new Date(val);
      if (!isNaN(date.getTime())) {
          updateForm(field, date.toISOString());
      }
  };

  // --- Render Sections ---
  const renderDriverDataSection = () => (
    <Card className="h-full">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex justify-between">
            <span><i className="fas fa-user-circle"></i> ข้อมูลพนักงาน</span>
            <span className="text-sm font-normal text-slate-500">{record.driver_name} ({record.driver_id})</span>
        </h3>

        <div className="space-y-4 text-sm overflow-y-auto max-h-[600px] pr-2">
            <div className="bg-slate-50 p-3 rounded border">
                <p><strong>เลิกงานล่าสุด:</strong> {lastCheckout}</p>
                <p><strong>Fix Start Time:</strong> <Badge type={fixStartStatus.includes('OK') ? 'approved' : 'danger'}>{fixStartStatus}</Badge></p>
            </div>

            <div className="grid grid-cols-2 gap-2">
                <p><strong>เหนื่อยล้า:</strong> {record.tired} {record.tired_detail && `(${record.tired_detail})`}</p>
                <p><strong>เจ็บป่วย:</strong> {record.sick} {record.sick === 'มี' && `(หาหมอ: ${record.seen_doctor})`}</p>
                <p><strong>ง่วงนอน:</strong> {record.drowsy}</p>
                <p><strong>บาดเจ็บ:</strong> {record.injury}</p>
                <p><strong>ยา:</strong> {record.medication} {record.medication_name}</p>
                <p><strong>สายตา/การได้ยิน:</strong> {record.vision_problem}/{record.hearing_problem}</p>
            </div>

            <div className="p-3 bg-blue-50 rounded border border-blue-100">
                <h4 className="font-bold mb-1">การนอน</h4>
                <p>ปกติ: {record.sleep_start} - {record.sleep_end} ({record.sleep_hours} ชม.) - <span className={record.sleep_hours! < 6 ? 'text-red-600 font-bold' : 'text-green-600'}>{record.sleep_quality}</span></p>
                {record.extra_sleep === 'นอนเพิ่ม' && (
                    <p>เพิ่ม: {record.extra_sleep_start} - {record.extra_sleep_end} ({record.extra_sleep_hours} ชม.) - <span className={record.extra_sleep_hours! < 4.5 ? 'text-red-600 font-bold' : 'text-green-600'}>{record.extra_sleep_quality}</span></p>
                )}
            </div>
        </div>
    </Card>
  );

  const renderTenkoInputSection = () => (
    <Card className="h-full border-l-4 border-blue-500">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex items-center gap-2">
            <i className="fas fa-user-shield"></i> ส่วนบันทึกของ Tenko
        </h3>

        {/* Pre-work Inputs - Grouped for Continuous Entry */}
        {(type === 'checkin' || type === 'view') && (
            <div className="space-y-4">
                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <h4 className="font-bold text-blue-800 mb-3"><i className="fas fa-stethoscope"></i> ข้อมูลสัญญาณชีพ (กรอกต่อเนื่อง)</h4>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-4">
                            <Input 
                                label="1. อุณหภูมิ (°C)" 
                                type="number" step="0.1"
                                placeholder="36.5"
                                autoFocus
                                value={form.temperature || ''} 
                                onChange={e => updateForm('temperature', parseFloat(e.target.value))}
                                className={isTempBad(form.temperature) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="3. ความดันตัวบน (Sys)" 
                                type="number" 
                                placeholder="120"
                                value={form.blood_pressure_high || ''} 
                                onChange={e => updateForm('blood_pressure_high', parseFloat(e.target.value))} 
                                className={isBPHighBad(form.blood_pressure_high) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                        <div className="space-y-4">
                            <Input 
                                label="2. แอลกอฮอล์ (mg%)" 
                                type="number" 
                                placeholder="0"
                                value={form.alcohol_checkin} 
                                onChange={e => updateForm('alcohol_checkin', parseFloat(e.target.value))}
                                className={isAlcoholBad(form.alcohol_checkin) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="4. ความดันตัวล่าง (Dia)" 
                                type="number" 
                                placeholder="80"
                                value={form.blood_pressure_low || ''} 
                                onChange={e => updateForm('blood_pressure_low', parseFloat(e.target.value))} 
                                className={isBPLowBad(form.blood_pressure_low) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                    </div>
                    {isAlcoholBad(form.alcohol_checkin) && (
                         <Input className="mt-3" placeholder="ระบุเหตุผลค่าแอลกอฮอล์" value={form.alcohol_checkin_reason || ''} onChange={e => updateForm('alcohol_checkin_reason', e.target.value)} />
                    )}
                </div>

                <div className="p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold block mb-2 text-sm text-slate-700">การใช้โทรศัพท์</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.phone_usage_compliant === 'ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ตรงตามที่แจ้ง')}>ตรงตามที่แจ้ง</OptionButton>
                        <OptionButton selected={form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ไม่ตรงตามที่แจ้ง')}>ไม่ตรงตามที่แจ้ง</OptionButton>
                    </div>
                    {form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง' && (
                        <div className="space-y-2 mt-2">
                             <Input placeholder="ระบุสาเหตุ" value={form.phone_usage_reason || ''} onChange={e => updateForm('phone_usage_reason', e.target.value)} />
                        </div>
                    )}
                </div>

                <div className="flex items-center justify-between p-3 border rounded-lg bg-slate-50">
