        <div className="mt-6 flex flex-col gap-3">
            <Button onClick={handleApprove} className="w-full bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 py-3 text-lg">
                <i className="fas fa-save"></i> บันทึกข้อมูล (Save)
            </Button>
            {type === 'view' && (
