            {fixStartNGCount === 0 && <div className="text-[10px] text-green-300 mt-1"><i className="fas fa-check-circle"></i> ปกติทุกท่าน</div>}
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
            <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors flex items-center flex-wrap gap-1">
                                        {record.driver_name}
                                        {type === 'checkin' && getFixStartBadge(record)}
                                    </h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
            {/* Column 1: Pending Check-in */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-amber-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-700 text-lg">
                        <i className="fas fa-clock"></i> รอตรวจก่อนงาน
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700 flex items-center gap-1">
                                    {r.driver_name}
                                    {getFixStartBadge(r)}
                                </p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>

            {/* Column 2: Active / Not Checkout Yet */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-blue-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-blue-700 text-lg">
                        <i className="fas fa-truck-moving"></i> กำลังปฏิบัติงาน (ยังไม่ส่งเลิก)
                    </h3>
                    <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full">{activeDrivers.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {activeDrivers.map(r => (
                        <div key={r.__backendId} className="flex justify-between p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-500">เริ่มงานเมื่อ: {getSafeDateTime(r.checkin_timestamp)}</p>
                            </div>
                            <div className="text-right">
                                <Badge type="approved">On Duty</Badge>
                            </div>
                        </div>
                    ))}
                    {activeDrivers.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-road text-4xl mb-2"></i>
                            <p>ไม่มีรถวิ่งงาน</p>
                        </div>
                    )}
                </div>
            </Card>

            {/* Column 3: Pending Check-out */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-purple-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-700 text-lg">
                        <i className="fas fa-flag-checkered"></i> รอตรวจหลังงาน
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeDateTime(r.checkout_timestamp || r.checkout_real_timestamp)}</p>
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

import React, { useState, useEffect } from 'react';
import { TenkoRecord, User } from '../../types';
import { Button, Card, Input, OptionButton, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  record: TenkoRecord;
  user: User;
  type: 'checkin' | 'checkout' | 'view';
  onBack: () => void;
  onSuccess: () => void;
}

export const ApprovalView: React.FC<Props> = ({ record, user, type, onBack, onSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    temperature: record.temperature,
    blood_pressure_high: record.blood_pressure_high,
    blood_pressure_low: record.blood_pressure_low,
    alcohol_checkin: record.alcohol_checkin ?? 0,
    alcohol_checkout: record.alcohol_checkout ?? 0,
    phone_usage_compliant: record.phone_usage_compliant || 'ตรงตามที่แจ้ง',
    can_work: record.can_work || 'ได้',
    driving_violation: record.driving_violation || 'ไม่มี',

    // Default approval timestamp to now if not set
    checkin_timestamp: record.checkin_timestamp || new Date().toISOString(),
    checkout_timestamp: record.checkout_timestamp || new Date().toISOString()
  });

  const [fixStartStatus, setFixStartStatus] = useState<string>('N/A');
  const [lastCheckout, setLastCheckout] = useState<string>('-');

  // --- Logic for Fix Start Time & Last Checkout ---
  useEffect(() => {
    const allRecords = StorageService.getAll();

    // 1. Last Checkout
    const previousRecords = allRecords
        .filter(r => r.driver_id === record.driver_id && r.checkout_timestamp && r.__backendId !== record.__backendId)
        .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());
    if (previousRecords.length > 0) {
        setLastCheckout(new Date(previousRecords[0].checkout_timestamp!).toLocaleString('th-TH'));
    }

    // 2. Fix Start Time Logic
    const driverRecords = allRecords
      .filter(r => r.driver_id === record.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
      .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    if (driverRecords.length > 0) {
        const mondayRecords = driverRecords.filter(r => new Date(r.checkin_timestamp!).getDay() === 1);
        if (mondayRecords.length > 0) {
            const firstMonday = new Date(mondayRecords[0].checkin_timestamp!);
            const firstMondayTime = firstMonday.getHours() * 60 + firstMonday.getMinutes();

            // Compare current record with first Monday
            const currentRecTime = new Date(form.checkin_timestamp!).getHours() * 60 + new Date(form.checkin_timestamp!).getMinutes();
            const diff = Math.abs(currentRecTime - firstMondayTime);
            setFixStartStatus(diff > 120 ? 'NG' : 'OK');
        } else {
             setFixStartStatus('OK (No Monday Record)');
        }
    } else {
        setFixStartStatus('OK (First Record)');
    }
  }, [record.driver_id, form.checkin_timestamp]);


  const updateForm = (k: keyof TenkoRecord, v: any) => setForm(p => ({ ...p, [k]: v }));

  // --- Validation Helpers ---
  const isTempBad = (t?: number) => t && t > 37.5;
  const isBPHighBad = (bp?: number) => bp && (bp < 90 || bp > 160);
  const isBPLowBad = (bp?: number) => bp && (bp < 60 || bp > 100);
  const isAlcoholBad = (a?: number) => a !== undefined && a !== 0;

  const handleApprove = () => {
    // Basic validation for reasons
    if (isAlcoholBad(form.alcohol_checkin) && !form.alcohol_checkin_reason) return alert('กรุณาระบุเหตุผลค่าแอลกอฮอล์');
    if (form.can_work === 'ไม่ได้' && !form.cannot_work_reason) return alert('กรุณาระบุสาเหตุที่วิ่งงานไม่ได้');

    const updateData: Partial<TenkoRecord> = { ...form };

    if (type === 'checkin') {
      updateData.checkin_status = 'approved';
      updateData.checkin_tenko_id = user.id;
      updateData.checkin_tenko_name = user.name;
    } else if (type === 'checkout') {
      updateData.checkout_status = 'approved';
      updateData.checkout_tenko_id = user.id;
      updateData.checkout_tenko_name = user.name;
    }

    StorageService.update({ ...record, ...updateData });
    onSuccess();
  };

  const handleDelete = () => {
      if(confirm('ยืนยันการลบข้อมูลนี้?')) {
          StorageService.delete(record.__backendId);
          onSuccess();
      }
  }

  // Helper to format Date ISO string (UTC) to Local datetime-local input format (YYYY-MM-DDTHH:mm)
  const formatDateForInput = (isoString?: string) => {
      if (!isoString) return '';
      const date = new Date(isoString);
      if (isNaN(date.getTime())) return '';

      // We need to shift the time by the timezone offset so that toISOString() outputs the local time values
      const tzOffset = date.getTimezoneOffset() * 60000; 
      const localDate = new Date(date.getTime() - tzOffset);
      return localDate.toISOString().slice(0, 16);
  };

  const handleDateChange = (val: string, field: 'checkin_timestamp' | 'checkout_timestamp') => {
      if (!val) return;
      // val is YYYY-MM-DDTHH:mm in Local time.
      // new Date(val) creates a date object representing that local time.
      // .toISOString() converts it back to UTC for storage.
      const date = new Date(val);
      if (!isNaN(date.getTime())) {
          updateForm(field, date.toISOString());
      }
  };

  // --- Render Sections ---
  const renderDriverDataSection = () => (
    <Card className="h-fit">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex justify-between">
            <span><i className="fas fa-user-circle"></i> ข้อมูลพนักงาน</span>
            <span className="text-sm font-normal text-slate-500">{record.driver_name} ({record.driver_id})</span>
        </h3>

        <div className="space-y-4 text-sm pr-2">
            <div className="bg-slate-50 p-3 rounded border space-y-2">
                <p><strong>เลิกงานล่าสุด:</strong> {lastCheckout}</p>
                <p><strong>Fix Start Time:</strong> <Badge type={fixStartStatus.includes('OK') ? 'approved' : 'danger'}>{fixStartStatus}</Badge></p>

                <div className="border-t border-slate-200 pt-2 mt-2">
                    <p className="flex justify-between items-center">
                        <span className="font-bold text-blue-700">เข้างาน:</span>
                        <span>{record.checkin_timestamp ? new Date(record.checkin_timestamp).toLocaleString('th-TH', { dateStyle: 'short', timeStyle: 'short' }) : '-'}</span>
                    </p>
                    {(type === 'checkout' || type === 'view') && (
                        <p className="flex justify-between items-center mt-1">
                            <span className="font-bold text-purple-700">เลิกงาน:</span>
                            <span>{record.checkout_timestamp ? new Date(record.checkout_timestamp).toLocaleString('th-TH', { dateStyle: 'short', timeStyle: 'short' }) : '-'}</span>
                        </p>
                    )}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-2">
                <p><strong>เหนื่อยล้า:</strong> {record.tired} {record.tired_detail && `(${record.tired_detail})`}</p>
                <p><strong>เจ็บป่วย:</strong> {record.sick} {record.sick === 'มี' && `(หาหมอ: ${record.seen_doctor})`}</p>
                <p><strong>ง่วงนอน:</strong> {record.drowsy}</p>
                <p><strong>บาดเจ็บ:</strong> {record.injury}</p>
                <p><strong>ยา:</strong> {record.medication} {record.medication_name}</p>
                <p><strong>สายตา/การได้ยิน:</strong> {record.vision_problem}/{record.hearing_problem}</p>
            </div>

            <div className="p-3 bg-blue-50 rounded border border-blue-100">
                <h4 className="font-bold mb-1">การนอน</h4>
                <p>ปกติ: {record.sleep_start} - {record.sleep_end} ({record.sleep_hours} ชม.) - <span className={record.sleep_hours! < 6 ? 'text-red-600 font-bold' : 'text-green-600'}>{record.sleep_quality}</span></p>
                {record.extra_sleep === 'นอนเพิ่ม' && (
                    <p>เพิ่ม: {record.extra_sleep_start} - {record.extra_sleep_end} ({record.extra_sleep_hours} ชม.) - <span className={record.extra_sleep_hours! < 4.5 ? 'text-red-600 font-bold' : 'text-green-600'}>{record.extra_sleep_quality}</span></p>
                )}
            </div>

            {/* Post-Work Driver Report Section */}
            {(type === 'checkout' || type === 'view') && (
                <div className="p-3 bg-purple-50 rounded border border-purple-100 mt-2">
                    <h4 className="font-bold text-purple-800 mb-2 border-b border-purple-200 pb-1 flex items-center gap-2">
                        <i className="fas fa-clipboard-list"></i> รายงานหลังเลิกงาน
                    </h4>
                    <div className="space-y-3">
                        <div className="flex flex-col">
                            <div className="flex justify-between">
                                <span className="font-semibold text-slate-700">การส่งมอบรถ:</span>
                                <span className={record.vehicle_handover === 'ปกติ' ? 'text-green-600 font-bold' : 'text-red-600 font-bold'}>
                                    {record.vehicle_handover || '-'}
                                </span>
                            </div>
                            {record.vehicle_detail && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-exclamation-circle text-red-400"></i> {record.vehicle_detail}</div>}
                        </div>

                        <div className="flex flex-col">
                            <div className="flex justify-between">
                                <span className="font-semibold text-slate-700">สภาพร่างกาย:</span>
                                <span className={record.body_condition_checkout === 'ปกติ' ? 'text-green-600 font-bold' : 'text-red-600 font-bold'}>
                                    {record.body_condition_checkout || '-'}
                                </span>
                            </div>
                            {record.body_detail_checkout && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-exclamation-circle text-red-400"></i> {record.body_detail_checkout}</div>}
                        </div>

                        <div className="flex flex-col">
                            <div className="flex justify-between">
                                <span className="font-semibold text-slate-700">จุดเสี่ยง:</span>
                                <span className={record.route_risk === 'ปกติ' ? 'text-green-600 font-bold' : 'text-orange-600 font-bold'}>
                                    {record.route_risk || '-'}
                                </span>
                            </div>
                            {record.route_detail && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-map-marker-alt text-orange-400"></i> {record.route_detail}</div>}
                        </div>
                    </div>
                </div>
            )}
        </div>
    </Card>
  );

  const renderTenkoInputSection = () => (
    <Card className="h-fit border-l-4 border-blue-500">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex items-center gap-2">
            <i className="fas fa-user-shield"></i> ส่วนบันทึกของ Tenko
        </h3>

        {/* Pre-work Inputs - Grouped for Continuous Entry */}
        {(type === 'checkin' || type === 'view') && (
            <div className="space-y-4">
                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <h4 className="font-bold text-blue-800 mb-3"><i className="fas fa-stethoscope"></i> ข้อมูลสัญญาณชีพ (กรอกต่อเนื่อง)</h4>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-4">
                            <Input 
                                label="1. อุณหภูมิ (°C)" 
                                type="number" step="0.1"
                                placeholder="36.5"
                                autoFocus
                                value={form.temperature || ''} 
                                onChange={e => updateForm('temperature', parseFloat(e.target.value))}
                                className={isTempBad(form.temperature) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="3. ความดันตัวบน (Sys)" 
                                type="number" 
                                placeholder="120"
                                value={form.blood_pressure_high || ''} 
                                onChange={e => updateForm('blood_pressure_high', parseFloat(e.target.value))} 
                                className={isBPHighBad(form.blood_pressure_high) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                        <div className="space-y-4">
                            <Input 
                                label="2. แอลกอฮอล์ (mg%)" 
                                type="number" 
                                placeholder="0"
                                value={form.alcohol_checkin} 
                                onChange={e => updateForm('alcohol_checkin', parseFloat(e.target.value))}
                                className={isAlcoholBad(form.alcohol_checkin) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="4. ความดันตัวล่าง (Dia)" 
                                type="number" 
                                placeholder="80"
                                value={form.blood_pressure_low || ''} 
                                onChange={e => updateForm('blood_pressure_low', parseFloat(e.target.value))} 
                                className={isBPLowBad(form.blood_pressure_low) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                    </div>
                    {isAlcoholBad(form.alcohol_checkin) && (
                         <Input className="mt-3" placeholder="ระบุเหตุผลค่าแอลกอฮอล์" value={form.alcohol_checkin_reason || ''} onChange={e => updateForm('alcohol_checkin_reason', e.target.value)} />
                    )}
                </div>

                <div className="p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold block mb-2 text-sm text-slate-700">การใช้โทรศัพท์</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.phone_usage_compliant === 'ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ตรงตามที่แจ้ง')}>ตรงตามที่แจ้ง</OptionButton>
                        <OptionButton selected={form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ไม่ตรงตามที่แจ้ง')}>ไม่ตรงตามที่แจ้ง</OptionButton>
                    </div>
                    {form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง' && (
                        <div className="space-y-2 mt-2">
                             <Input placeholder="ระบุสาเหตุ" value={form.phone_usage_reason || ''} onChange={e => updateForm('phone_usage_reason', e.target.value)} />
                        </div>
                    )}
                </div>

                <div className="flex items-center justify-between p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold text-slate-700">อนุญาตให้ปฏิบัติงาน?</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.can_work === 'ได้'} onClick={() => updateForm('can_work', 'ได้')}>ได้</OptionButton>
                        <OptionButton selected={form.can_work === 'ไม่ได้'} onClick={() => updateForm('can_work', 'ไม่ได้')}>ไม่ได้</OptionButton>
                    </div>
                </div>
                {form.can_work === 'ไม่ได้' && (
                        <Input placeholder="ระบุสาเหตุที่ไม่อนุญาต" value={form.cannot_work_reason || ''} onChange={e => updateForm('cannot_work_reason', e.target.value)} />
                )}
            </div>
        )}

        {/* Post-work Inputs */}
        {(type === 'checkout' || type === 'view') && (
            <div className="space-y-4 mt-6 border-t pt-4">
                <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                    <h4 className="font-bold text-purple-800 mb-3">ตรวจสอบหลังเลิกงาน</h4>
                    <div className="grid grid-cols-2 gap-4">
                         <Input 
                            label="แอลกอฮอล์ (ต้อง 0)" 
                            type="number" 
                            autoFocus
                            value={form.alcohol_checkout} 
                            onChange={e => updateForm('alcohol_checkout', parseFloat(e.target.value))}
                            className={isAlcoholBad(form.alcohol_checkout) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                         />
                         {isAlcoholBad(form.alcohol_checkout) && (
                             <Input label="เหตุผล" placeholder="ระบุเหตุผล" value={form.alcohol_checkout_reason || ''} onChange={e => updateForm('alcohol_checkout_reason', e.target.value)} />
                         )}
                    </div>

                     <div className="mt-4">
                        <label className="block text-sm font-semibold mb-2">ข้อละเมิดการขับขี่?</label>
                        <div className="flex gap-2">
                            <OptionButton selected={form.driving_violation === 'ไม่มี'} onClick={() => updateForm('driving_violation', 'ไม่มี')}>ไม่มี</OptionButton>
                            <OptionButton selected={form.driving_violation === 'มี'} onClick={() => updateForm('driving_violation', 'มี')}>มี</OptionButton>
                        </div>
                        {form.driving_violation === 'มี' && <Input className="mt-2" placeholder="ระบุรายละเอียด" value={form.violation_detail || ''} onChange={e => updateForm('violation_detail', e.target.value)} />}
                    </div>
                </div>
            </div>
        )}

        <div className="bg-yellow-50 p-3 rounded border border-yellow-200 mt-4">
            <label className="block text-sm font-bold mb-1 text-yellow-800">
                <i className="fas fa-clock"></i> เวลาที่บันทึก
            </label>
            <input 
                type="datetime-local" 
                className="w-full p-2 border rounded bg-white text-sm"
                value={formatDateForInput(type === 'checkout' ? form.checkout_timestamp : form.checkin_timestamp)}
                onChange={e => handleDateChange(e.target.value, type === 'checkout' ? 'checkout_timestamp' : 'checkin_timestamp')}
            />
        </div>

        <div className="mt-6 flex flex-col gap-3">
            <Button onClick={handleApprove} className="w-full bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 py-3 text-lg">
                <i className="fas fa-save"></i> บันทึกข้อมูล (Save)
            </Button>
            {type === 'view' && (
                <Button onClick={handleDelete} variant="danger" className="w-full">
                    <i className="fas fa-trash-alt"></i> ลบข้อมูล
                </Button>
            )}
        </div>
    </Card>
  );

  return (
    <div className="space-y-4 max-w-6xl mx-auto pb-10 flex flex-col">
      <div className="flex justify-between items-center shrink-0">
        <h2 className="text-2xl font-bold text-slate-800">
          {type === 'checkin' ? 'คิวตรวจสอบ (ก่อนงาน)' : type === 'checkout' ? 'คิวตรวจสอบ (หลังงาน)' : 'แก้ไขข้อมูล'}
        </h2>
        <Button variant="secondary" onClick={onBack}>ย้อนกลับ</Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {renderDriverDataSection()}
        {renderTenkoInputSection()}
      </div>
    </div>
  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  // Drivers who are working (approved checkin) but haven't submitted checkout yet
  const activeDrivers = records.filter(r => r.checkin_status === 'approved' && !r.checkout_status);
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  const exportExcel = () => {
    const data = records.map(r => {
        // Format details for columns
        const vehicleStatus = r.vehicle_handover === 'ไม่ปกติ' && r.vehicle_detail 
            ? `ไม่ปกติ (${r.vehicle_detail})` 
            : (r.vehicle_handover || '-');

        const bodyCheckoutStatus = r.body_condition_checkout === 'ไม่ปกติ' && r.body_detail_checkout
            ? `ไม่ปกติ (${r.body_detail_checkout})`
            : (r.body_condition_checkout || '-');

        const routeRiskStatus = r.route_risk === 'พบจุดเสี่ยง' && r.route_detail
            ? `พบจุดเสี่ยง (${r.route_detail})`
            : (r.route_risk || '-');

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,

            // Check-in Info
            "เวลาเข้างาน": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "สถานะเข้างาน": r.checkin_status === 'approved' ? 'อนุมัติ' : r.checkin_status === 'pending' ? 'รอตรวจ' : '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน (บน/ล่าง)": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "ชั่วโมงนอน": r.sleep_hours || 0,
            "ความเหนื่อยล้า": r.tired || '-',
            "เจ็บป่วย": r.sick || '-',
            "ง่วงนอน": r.drowsy || '-',
            "การใช้ยา": r.medication || '-',
            "อนุญาตให้ขับ": r.can_work || '-',

            // Check-out Info
            "เวลาเลิกงาน": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "สถานะเลิกงาน": r.checkout_status === 'approved' ? 'อนุมัติ' : r.checkout_status === 'pending' ? 'รอตรวจ' : '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "การส่งมอบรถสินค้า": vehicleStatus,
            "สภาพร่างกาย (หลังงาน)": bodyCheckoutStatus,
            "จุดเสี่ยงระหว่างทาง": routeRiskStatus
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);

    // Auto-width for better visibility (Approximation)
    const wscols = [
        {wch: 12}, {wch: 20}, {wch: 10}, // Date, Name, ID
        {wch: 10}, {wch: 10}, {wch: 8}, {wch: 10}, {wch: 12}, {wch: 8}, // Checkin stats
        {wch: 10}, {wch: 10}, {wch: 10}, {wch: 10}, {wch: 10}, // Health stats
        {wch: 10}, {wch: 10}, {wch: 12}, // Checkout stats
        {wch: 20}, {wch: 20}, {wch: 20} // Details
    ];
    ws['!cols'] = wscols;

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `Tenko_Report_${today}.xlsx`);
  };

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
        return '-';
    }
  };

  const getSafeDateTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleString('th-TH', { 
            day: '2-digit', 
            month: '2-digit', 
            hour: '2-digit', 
            minute: '2-digit' 
        });
    } catch (e) {
        return '-';
    }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    // Logic to find first Monday approved checkin
    const history = records.filter(r => 
        r.driver_id === record.driver_id && 
        r.checkin_status === 'approved' && 
        r.checkin_timestamp
    ).sort((a,b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const mondayRecord = history.find(r => new Date(r.checkin_timestamp!).getDay() === 1);

    let status = 'New';

    if (mondayRecord) {
        const currentStr = record.checkin_timestamp || record.checkin_real_timestamp;
        if (currentStr) {
             const baseDate = new Date(mondayRecord.checkin_timestamp!);
             const targetDate = new Date(currentStr);
             const baseMinutes = baseDate.getHours() * 60 + baseDate.getMinutes();
             const targetMinutes = targetDate.getHours() * 60 + targetDate.getMinutes();

             if (Math.abs(targetMinutes - baseMinutes) > 120) {
                 status = 'NG';
             } else {
                 status = 'OK';
             }
        }
    }

    if (status === 'NG') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-600 border border-red-200 whitespace-nowrap">Fix Start: NG</span>;
    if (status === 'OK') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-600 border border-emerald-200 whitespace-nowrap">Fix Start: OK</span>;
    return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 border border-slate-200 whitespace-nowrap">First Time</span>;
  };

  const calculateFixStartNGMonth = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    let ngCount = 0;

    // Group approved records by driver for current month
    const driverGroups: Record<string, TenkoRecord[]> = {};
    records.filter(r => {
         if (!r.checkin_timestamp || r.checkin_status !== 'approved') return false;
         const d = new Date(r.checkin_timestamp);
         return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    }).forEach(r => {
        if (!driverGroups[r.driver_id]) driverGroups[r.driver_id] = [];
        driverGroups[r.driver_id].push(r);
    });

    // Check logic
    Object.values(driverGroups).forEach(list => {
        // Sort by time ascending
        list.sort((a,b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

        // Find Monday base
        const monday = list.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
        if (monday) {
             const baseTime = new Date(monday.checkin_timestamp!);
             const baseMins = baseTime.getHours() * 60 + baseTime.getMinutes();

             list.forEach(item => {
                 const curTime = new Date(item.checkin_timestamp!);
                 const curMins = curTime.getHours() * 60 + curTime.getMinutes();
                 if (Math.abs(curMins - baseMins) > 120) {
                     ngCount++;
                 }
             });
        }
    });
    return ngCount;
  };

  const fixStartNGCount = calculateFixStartNGMonth();

  const renderStats = () => (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1 text-sm">รอตรวจก่อนงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-blue-500 to-cyan-600 text-white border-none">
            <h3 className="text-blue-100 mb-1 text-sm">กำลังปฏิบัติงาน</h3>
            <div className="text-3xl font-bold">{activeDrivers.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1 text-sm">รอตรวจหลังงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1 text-sm">เสร็จสิ้นแล้ว</h3>
            <div className="text-3xl font-bold">{completed.length}</div>
        </Card>
        <Card className={`${fixStartNGCount > 0 ? 'bg-red-600' : 'bg-blue-900'} text-white border-none`}>
            <h3 className="text-white/80 mb-1 text-sm">Fix Start (เดือนนี้)</h3>
            <div className="text-3xl font-bold flex items-baseline gap-2">
                {fixStartNGCount} <span className="text-sm font-normal">NG</span>
            </div>
            {fixStartNGCount === 0 && <div className="text-[10px] text-green-300 mt-1"><i className="fas fa-check-circle"></i> ปกติทุกท่าน</div>}
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
            <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors flex items-center flex-wrap gap-1">
                                        {record.driver_name}
                                        {type === 'checkin' && getFixStartBadge(record)}
                                    </h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
            {/* Column 1: Pending Check-in */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-amber-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-700 text-lg">
                        <i className="fas fa-clock"></i> รอตรวจก่อนงาน
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700 flex items-center gap-1">
                                    {r.driver_name}
                                    {getFixStartBadge(r)}
                                </p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>

            {/* Column 2: Active / Not Checkout Yet */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-blue-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-blue-700 text-lg">
                        <i className="fas fa-truck-moving"></i> กำลังปฏิบัติงาน (ยังไม่ส่งเลิก)
                    </h3>
                    <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full">{activeDrivers.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {activeDrivers.map(r => (
                        <div key={r.__backendId} className="flex justify-between p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-500">เริ่มงานเมื่อ: {getSafeDateTime(r.checkin_timestamp)}</p>
                            </div>
                            <div className="text-right">
                                <Badge type="approved">On Duty</Badge>
                            </div>
                        </div>
                    ))}
                    {activeDrivers.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-road text-4xl mb-2"></i>
                            <p>ไม่มีรถวิ่งงาน</p>
                        </div>
                    )}
                </div>
            </Card>

            {/* Column 3: Pending Check-out */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-purple-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-700 text-lg">
                        <i className="fas fa-flag-checkered"></i> รอตรวจหลังงาน
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeDateTime(r.checkout_timestamp || r.checkout_real_timestamp)}</p>
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

import React, { useState, useMemo } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import * as XLSX from 'xlsx';

interface Props {
  records: TenkoRecord[];
}

export const TenkoAnalytics: React.FC<Props> = ({ records }) => {
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(today);
  const [selectedDriverId, setSelectedDriverId] = useState<string>(''); // Filter state

  const drivers = StorageService.getUsers().filter(u => u.role === 'driver');

  // --- Filtering Logic ---
  const filteredRecords = useMemo(() => {
    let res = records;
    if (selectedDriverId) {
        res = res.filter(r => r.driver_id === selectedDriverId);
    }
    return res;
  }, [records, selectedDriverId]);

  const monthRecords = useMemo(() => {
    return filteredRecords.filter(r => {
        const d = new Date(r.checkin_timestamp || r.date);
        return d.getMonth() === currentMonth.getMonth() && d.getFullYear() === currentMonth.getFullYear();
    });
  }, [filteredRecords, currentMonth]);

  // --- Graph Data (Last 5 days for selected driver or aggregate) ---
  const graphData = useMemo(() => {
    // Sort by date ascending
    const sorted = [...monthRecords]
        .filter(r => r.blood_pressure_high && r.blood_pressure_low)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Take last 5
    return sorted.slice(-5);
  }, [monthRecords]);


  // --- Export Logic ---
  const exportExcel = () => {
    const data = monthRecords.map(r => {
        // Format details for columns
        const vehicleStatus = r.vehicle_handover === 'ไม่ปกติ' && r.vehicle_detail 
            ? `ไม่ปกติ (${r.vehicle_detail})` 
            : (r.vehicle_handover || '-');

        const bodyCheckoutStatus = r.body_condition_checkout === 'ไม่ปกติ' && r.body_detail_checkout
            ? `ไม่ปกติ (${r.body_detail_checkout})`
            : (r.body_condition_checkout || '-');

        const routeRiskStatus = r.route_risk === 'พบจุดเสี่ยง' && r.route_detail
            ? `พบจุดเสี่ยง (${r.route_detail})`
            : (r.route_risk || '-');

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,

            // Check-in Info
            "เวลาเข้างาน": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "สถานะเข้างาน": r.checkin_status === 'approved' ? 'อนุมัติ' : r.checkin_status === 'pending' ? 'รอตรวจ' : '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน (บน/ล่าง)": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "ชั่วโมงนอน": r.sleep_hours || 0,
            "ความเหนื่อยล้า": r.tired || '-',
            "เจ็บป่วย": r.sick || '-',
            "ง่วงนอน": r.drowsy || '-',
            "การใช้ยา": r.medication || '-',
            "อนุญาตให้ขับ": r.can_work || '-',

            // Check-out Info
            "เวลาเลิกงาน": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "สถานะเลิกงาน": r.checkout_status === 'approved' ? 'อนุมัติ' : r.checkout_status === 'pending' ? 'รอตรวจ' : '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "การส่งมอบรถสินค้า": vehicleStatus,
            "สภาพร่างกาย (หลังงาน)": bodyCheckoutStatus,
            "จุดเสี่ยงระหว่างทาง": routeRiskStatus
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);

    // Auto-width
    const wscols = [
        {wch: 12}, {wch: 20}, {wch: 10}, 
        {wch: 10}, {wch: 10}, {wch: 8}, {wch: 10}, {wch: 12}, {wch: 8}, 
        {wch: 10}, {wch: 10}, {wch: 10}, {wch: 10}, {wch: 10},
        {wch: 10}, {wch: 10}, {wch: 12},
        {wch: 20}, {wch: 20}, {wch: 20}
    ];
    ws['!cols'] = wscols;

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "TenkoReport");
    XLSX.writeFile(wb, `Tenko_Export_${selectedDriverId || 'ALL'}_${currentMonth.toISOString().slice(0,7)}.xlsx`);
  };

  // --- Calendar Helpers ---
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  const getDayCount = (day: number) => {
    const target = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
    return filteredRecords.filter(r => r.date === target).length;
  };

  // --- SVG Graph Render ---
  const renderBPGraph = () => {
    if (graphData.length < 2) return <div className="h-64 flex items-center justify-center text-slate-400 bg-slate-50 rounded-lg border border-dashed">ข้อมูลไม่เพียงพอสำหรับกราฟ (ต้องมีอย่างน้อย 2 วัน)</div>;

    // Canvas Configuration
    const svgHeight = 300;
    const svgWidth = 800; // Internal coordinate system width
    const paddingX = 80;
    const paddingY = 40;

    // Y-Axis Scale
    const maxVal = 180;
    const minVal = 50;
    const range = maxVal - minVal;
    const drawingHeight = svgHeight - (paddingY * 2);
    const drawingWidth = svgWidth - (paddingX * 2);

    const getX = (i: number) => paddingX + (i / (graphData.length - 1)) * drawingWidth;
    const getY = (val: number) => (svgHeight - paddingY) - ((val - minVal) / range) * drawingHeight;

    // Generate Points
    const pointsHigh = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_high || 0)}`).join(' ');
    const pointsLow = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_low || 0)}`).join(' ');

    // Generate Areas (for gradient fill)
    const areaHigh = `${pointsHigh} ${getX(graphData.length-1)},${svgHeight-paddingY} ${getX(0)},${svgHeight-paddingY}`;
    const areaLow = `${pointsLow} ${getX(graphData.length-1)},${svgHeight-paddingY} ${getX(0)},${svgHeight-paddingY}`;

    return (
        <div className="relative h-[320px] w-full p-2">
            <svg viewBox={`0 0 ${svgWidth} ${svgHeight}`} className="w-full h-full overflow-visible drop-shadow-sm">
                <defs>
                    <linearGradient id="gradHigh" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stopColor="#ef4444" stopOpacity="0.2" />
                        <stop offset="100%" stopColor="#ef4444" stopOpacity="0" />
                    </linearGradient>
                    <linearGradient id="gradLow" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.2" />
                        <stop offset="100%" stopColor="#3b82f6" stopOpacity="0" />
                    </linearGradient>
                </defs>

                {/* Grid Lines & Y-Axis Labels */}
                {[60, 90, 120, 150].map((val) => (
                    <g key={val}>
                        <line 
                            x1={paddingX - 10} y1={getY(val)} 
                            x2={svgWidth - paddingX + 10} y2={getY(val)} 
                            stroke="#e2e8f0" strokeWidth="1" strokeDasharray={val === 90 || val === 140 ? "5,5" : ""} 
                        />
                        <text x={paddingX - 20} y={getY(val) + 4} fontSize="12" fill="#94a3b8" textAnchor="end">{val}</text>
                    </g>
                ))}

                {/* Area Fills */}
                <polygon points={areaHigh} fill="url(#gradHigh)" />
                <polygon points={areaLow} fill="url(#gradLow)" />

                {/* Lines */}
                <polyline points={pointsHigh} fill="none" stroke="#ef4444" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                <polyline points={pointsLow} fill="none" stroke="#3b82f6" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

                {/* Data Points */}
                {graphData.map((d, i) => (
                    <g key={i} className="group cursor-pointer">
                        {/* High Point */}
                        <circle cx={getX(i)} cy={getY(d.blood_pressure_high!)} r="5" fill="#fff" stroke="#ef4444" strokeWidth="2.5" className="transition-all duration-300 group-hover:r-7" />
                        <text x={getX(i)} y={getY(d.blood_pressure_high!) - 15} fontSize="14" fontWeight="bold" fill="#ef4444" textAnchor="middle" className="opacity-0 group-hover:opacity-100 transition-opacity select-none">{d.blood_pressure_high}</text>

                        {/* Low Point */}
                        <circle cx={getX(i)} cy={getY(d.blood_pressure_low!)} r="5" fill="#fff" stroke="#3b82f6" strokeWidth="2.5" className="transition-all duration-300 group-hover:r-7" />
                        <text x={getX(i)} y={getY(d.blood_pressure_low!) + 25} fontSize="14" fontWeight="bold" fill="#3b82f6" textAnchor="middle" className="opacity-0 group-hover:opacity-100 transition-opacity select-none">{d.blood_pressure_low}</text>

                        {/* X-Axis Date Label */}
                        <text x={getX(i)} y={svgHeight - 10} fontSize="12" fill="#64748b" textAnchor="middle">{new Date(d.date).toLocaleDateString('th-TH', {day: 'numeric', month: 'short'})}</text>

                        {/* Vertical Guide Line on Hover */}
                        <line x1={getX(i)} y1={paddingY} x2={getX(i)} y2={svgHeight - paddingY} stroke="#94a3b8" strokeWidth="1" strokeDasharray="4" className="opacity-0 group-hover:opacity-20" />
                    </g>
                ))}
            </svg>
            <div className="absolute top-2 right-4 flex gap-4 text-xs bg-white/80 p-2 rounded-lg backdrop-blur-sm shadow-sm border border-slate-100">
                <div className="flex items-center gap-2"><div className="w-3 h-3 bg-red-500 rounded-full border-2 border-white shadow-sm"></div> ความดันบน (SYS)</div>
                <div className="flex items-center gap-2"><div className="w-3 h-3 bg-blue-500 rounded-full border-2 border-white shadow-sm"></div> ความดันล่าง (DIA)</div>
            </div>
        </div>
    );
  };

  return (
    <div className="space-y-6">
        {/* Header & Controls */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <div>
                <h2 className="text-2xl font-bold text-slate-800">แดชบอร์ด & สถิติ</h2>
                <p className="text-slate-500 text-sm">ข้อมูลเดือน: {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</p>
            </div>
            <div className="flex gap-3 w-full md:w-auto">
                <select 
                    className="p-2.5 border rounded-lg bg-slate-50 min-w-[200px]"
                    value={selectedDriverId}
                    onChange={(e) => setSelectedDriverId(e.target.value)}
                >
                    <option value="">-- พนักงานทั้งหมด --</option>
                    {drivers.map(d => (
                        <option key={d.id} value={d.id}>{d.name} ({d.id})</option>
                    ))}
                </select>
                <Button onClick={exportExcel} className="bg-green-600 hover:bg-green-700 whitespace-nowrap">
                    <i className="fas fa-file-excel"></i> Export
                </Button>
            </div>
        </div>

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Left: Calendar */}
            <Card className="h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg text-slate-700">ปฏิทินการทำงาน</h3>
                    <div className="flex gap-2">
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-1 hover:bg-slate-100 rounded"><i className="fas fa-chevron-left"></i></button>
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-1 hover:bg-slate-100 rounded"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>

                <div className="grid grid-cols-7 gap-1">
                    {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                    {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                    {Array.from({length: daysInMonth}).map((_, i) => {
                        const count = getDayCount(i+1);
                        return (
                            <div key={i} className={`
                                h-14 flex flex-col items-center justify-center rounded-lg border text-sm font-medium transition-colors relative
                                ${count > 0 ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-100 text-slate-400'}
                                ${selectedDriverId && count > 0 ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : ''}
                            `}>
                                <span>{i+1}</span>
                                {count > 0 && (
                                    <span className={`text-xs rounded-full w-5 h-5 flex items-center justify-center mt-1 text-white font-bold
                                        ${selectedDriverId ? 'bg-emerald-500' : 'bg-blue-600'}
                                    `}>
                                        {selectedDriverId ? <i className="fas fa-check text-[10px]"></i> : count}
                                    </span>
                                )}
                            </div>
                        );
                    })}
                </div>
            </Card>

            {/* Right: BP Graph */}
            <Card className="h-full flex flex-col">
                <div className="mb-4">
                    <h3 className="font-bold text-lg text-slate-700 flex items-center gap-2">
                        <i className="fas fa-heartbeat text-red-500"></i> แนวโน้มความดันโลหิต
                    </h3>
                    <p className="text-xs text-slate-500">5 วันล่าสุดที่มีข้อมูล {selectedDriverId ? '(รายบุคคล)' : '(รวม)'}</p>
                </div>
                <div className="flex-1 bg-white rounded-lg border border-slate-100 overflow-hidden shadow-inner">
                    {renderBPGraph()}
                </div>
                <div className="mt-4 grid grid-cols-2 gap-4 text-center">
                    <div className="bg-red-50 p-3 rounded-lg border border-red-100">
                        <span className="text-xs text-slate-500 block uppercase tracking-wide">Avg ความดันบน</span>
                        <span className="font-bold text-red-600 text-xl">
                            {graphData.length > 0 ? Math.round(graphData.reduce((a,b) => a + (b.blood_pressure_high||0), 0) / graphData.length) : '-'}
                        </span>
                        <span className="text-xs text-red-400 ml-1">mmHg</span>
                    </div>
                    <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                        <span className="text-xs text-slate-500 block uppercase tracking-wide">Avg ความดันล่าง</span>
                        <span className="font-bold text-blue-600 text-xl">
                            {graphData.length > 0 ? Math.round(graphData.reduce((a,b) => a + (b.blood_pressure_low||0), 0) / graphData.length) : '-'}
                        </span>
                        <span className="text-xs text-blue-400 ml-1">mmHg</span>
                    </div>
                </div>
            </Card>
        </div>

        {/* Bottom: Detailed List */}
        <Card>
            <h3 className="font-bold text-lg text-slate-700 mb-4 flex items-center gap-2">
                <i className="fas fa-list"></i> รายละเอียดการตรวจ ({monthRecords.length} รายการ)
            </h3>
            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-100 text-slate-600 font-semibold uppercase">
                        <tr>
                            <th className="p-3 rounded-tl-lg">วันที่</th>
                            <th className="p-3">พนักงาน</th>
                            <th className="p-3 text-center">เวลาเข้า</th>
                            <th className="p-3 text-center">BP (บน/ล่าง)</th>
                            <th className="p-3 text-center">Temp</th>
                            <th className="p-3 text-center">Alcohol</th>
                            <th className="p-3 text-right rounded-tr-lg">สถานะ</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {monthRecords.map(r => (
                            <tr key={r.__backendId} className="hover:bg-slate-50 transition-colors">
                                <td className="p-3 font-medium text-slate-700">{new Date(r.date).toLocaleDateString('th-TH')}</td>
                                <td className="p-3">
                                    <div className="font-bold text-slate-700">{r.driver_name}</div>
                                    <div className="text-xs text-slate-400">{r.driver_id}</div>
                                </td>
                                <td className="p-3 text-center text-slate-600">
                                    {r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'}
                                </td>
                                <td className="p-3 text-center">
                                    <span className={`font-bold ${r.blood_pressure_high! > 140 ? 'text-red-600' : 'text-slate-700'}`}>
                                        {r.blood_pressure_high}
                                    </span> / {r.blood_pressure_low}
                                </td>
                                <td className="p-3 text-center">{r.temperature}</td>
                                <td className="p-3 text-center text-emerald-600 font-bold">{r.alcohol_checkin}</td>
                                <td className="p-3 text-right">
                                    <Badge type={r.checkin_status === 'approved' ? 'approved' : 'pending'}>
                                        {r.checkin_status === 'approved' ? 'อนุมัติแล้ว' : 'รอตรวจ'}
                                    </Badge>
                                </td>
                            </tr>
                        ))}
                        {monthRecords.length === 0 && (
                            <tr>
                                <td colSpan={7} className="p-8 text-center text-slate-400">ไม่พบข้อมูล</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </Card>
    </div>
  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  // Drivers who are working (approved checkin) but haven't submitted checkout yet
  const activeDrivers = records.filter(r => r.checkin_status === 'approved' && !r.checkout_status);
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  const exportExcel = () => {
    const data = records.map(r => {
        // Helper for combining status and detail
        const formatDetail = (status?: string, detail?: string) => {
            if (!status) return '-';
            return detail ? `${status} (${detail})` : status;
        };

        const sleepInfo = r.sleep_hours 
            ? `${r.sleep_hours} ชม. (${r.sleep_start || '-'} - ${r.sleep_end || '-'}) ${r.sleep_quality || ''}`
            : '-';

        const extraSleepInfo = r.extra_sleep === 'นอนเพิ่ม'
            ? `${r.extra_sleep_hours} ชม. (${r.extra_sleep_start || '-'} - ${r.extra_sleep_end || '-'}) ${r.extra_sleep_quality || ''}`
            : 'ไม่นอนเพิ่ม';

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,

            // --- 1. สุขภาพก่อนงาน (Driver Self Check) ---
            "ความเหนื่อยล้า": formatDetail(r.tired, r.tired_detail),
            "การเจ็บป่วย": r.sick === 'มี' ? `มี (${r.sick_detail || '-'}) หาหมอ: ${r.seen_doctor || '-'}` : 'ไม่มี',
            "ความง่วง": formatDetail(r.drowsy, r.drowsy_detail),
            "การบาดเจ็บ": formatDetail(r.injury, r.injury_detail),
            "การใช้ยา": r.medication === 'ทาน' ? `ทาน (${r.medication_name || '-'})` : 'ไม่ทาน',
            "สภาพร่างกาย(ก่อน)": formatDetail(r.body_condition, r.body_condition_detail),
            "การนอนหลับ": sleepInfo,
            "การนอนเพิ่ม": extraSleepInfo,
            "เรื่องกังวลใจ": formatDetail(r.worry_detail, r.worry_text),
            "สถานที่พักผ่อน": formatDetail(r.rest_location, r.rest_location_detail),
            "ปัญหาสายตา": `${r.vision_problem || '-'} (แว่น: ${r.glasses || '-'})`,
            "การได้ยิน": `${r.hearing_problem || '-'} (เครื่องช่วย: ${r.hearing_aid || '-'})`,

            // --- 2. การตรวจสอบก่อนงาน (Tenko Check) ---
            "เวลาเข้างาน (อนุมัติ)": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เข้างาน)": r.checkin_tenko_name || '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "เหตุผลแอลกอฮอล์(เข้า)": r.alcohol_checkin_reason || '-',
            "การใช้โทรศัพท์": formatDetail(r.phone_usage_compliant, r.phone_usage_reason),
            "ผลประเมิน": formatDetail(r.can_work, r.cannot_work_reason),

            // --- 3. รายงานหลังงาน (Driver Post-work) ---
            "การส่งมอบรถ": formatDetail(r.vehicle_handover, r.vehicle_detail),
            "สภาพร่างกาย(หลัง)": formatDetail(r.body_condition_checkout, r.body_detail_checkout),
            "จุดเสี่ยง": formatDetail(r.route_risk, r.route_detail),

            // --- 4. การตรวจสอบหลังงาน (Tenko Check) ---
            "เวลาเลิกงาน (อนุมัติ)": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เลิกงาน)": r.checkout_tenko_name || '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "เหตุผลแอลกอฮอล์(ออก)": r.alcohol_checkout_reason || '-',
            "ข้อละเมิดการขับขี่": formatDetail(r.driving_violation, r.violation_detail)
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);

    // Auto-width for key columns
    const wscols = [
        {wch: 12}, {wch: 20}, {wch: 10}, // Date, Name, ID
        {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, // Health
        {wch: 25}, {wch: 25}, // Sleep
        {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, // Env
        {wch: 15}, {wch: 20}, {wch: 10}, {wch: 10}, {wch: 10}, {wch: 15}, // Tenko Checkin
        {wch: 20}, {wch: 20}, {wch: 20}, // Post-work Driver
        {wch: 15}, {wch: 20}, {wch: 10}, {wch: 15}, {wch: 20} // Tenko Checkout
    ];
    ws['!cols'] = wscols;

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `Tenko_Full_Report_${today}.xlsx`);
  };

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' });
    } catch (e) {
        return '-';
    }
  };

  const getSafeDateTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleString('th-TH', { 
            day: '2-digit', 
            month: '2-digit', 
            hour: '2-digit', 
            minute: '2-digit' 
        });
    } catch (e) {
        return '-';
    }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    // Logic to find first Monday approved checkin
    const history = records.filter(r => 
        r.driver_id === record.driver_id && 
        r.checkin_status === 'approved' && 
        r.checkin_timestamp
    ).sort((a,b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const mondayRecord = history.find(r => new Date(r.checkin_timestamp!).getDay() === 1);

    let status = 'New';

    if (mondayRecord) {
        const currentStr = record.checkin_timestamp || record.checkin_real_timestamp;
        if (currentStr) {
             const baseDate = new Date(mondayRecord.checkin_timestamp!);
             const targetDate = new Date(currentStr);
             const baseMinutes = baseDate.getHours() * 60 + baseDate.getMinutes();
             const targetMinutes = targetDate.getHours() * 60 + targetDate.getMinutes();

             if (Math.abs(targetMinutes - baseMinutes) > 120) {
                 status = 'NG';
             } else {
                 status = 'OK';
             }
        }
    }

    if (status === 'NG') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-600 border border-red-200 whitespace-nowrap">Fix Start: NG</span>;
    if (status === 'OK') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-600 border border-emerald-200 whitespace-nowrap">Fix Start: OK</span>;
    return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 border border-slate-200 whitespace-nowrap">First Time</span>;
  };

  const calculateFixStartNGMonth = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    let ngCount = 0;

    // Group approved records by driver for current month
    const driverGroups: Record<string, TenkoRecord[]> = {};
    records.filter(r => {
         if (!r.checkin_timestamp || r.checkin_status !== 'approved') return false;
         const d = new Date(r.checkin_timestamp);
         return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    }).forEach(r => {
        if (!driverGroups[r.driver_id]) driverGroups[r.driver_id] = [];
        driverGroups[r.driver_id].push(r);
    });

    // Check logic
    Object.values(driverGroups).forEach(list => {
        // Sort by time ascending
        list.sort((a,b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

        // Find Monday base
        const monday = list.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
        if (monday) {
             const baseTime = new Date(monday.checkin_timestamp!);
             const baseMins = baseTime.getHours() * 60 + baseTime.getMinutes();

             list.forEach(item => {
                 const curTime = new Date(item.checkin_timestamp!);
                 const curMins = curTime.getHours() * 60 + curTime.getMinutes();
                 if (Math.abs(curMins - baseMins) > 120) {
                     ngCount++;
                 }
             });
        }
    });
    return ngCount;
  };

  const fixStartNGCount = calculateFixStartNGMonth();

  const renderStats = () => (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1 text-sm">รอตรวจก่อนงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-blue-500 to-cyan-600 text-white border-none">
            <h3 className="text-blue-100 mb-1 text-sm">กำลังปฏิบัติงาน</h3>
            <div className="text-3xl font-bold">{activeDrivers.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1 text-sm">รอตรวจหลังงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1 text-sm">เสร็จสิ้นแล้ว</h3>
            <div className="text-3xl font-bold">{completed.length}</div>
        </Card>
        <Card className={`${fixStartNGCount > 0 ? 'bg-red-600' : 'bg-blue-900'} text-white border-none`}>
            <h3 className="text-white/80 mb-1 text-sm">Fix Start (เดือนนี้)</h3>
            <div className="text-3xl font-bold flex items-baseline gap-2">
                {fixStartNGCount} <span className="text-sm font-normal">NG</span>
            </div>
            {fixStartNGCount === 0 && <div className="text-[10px] text-green-300 mt-1"><i className="fas fa-check-circle"></i> ปกติทุกท่าน</div>}
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
            <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors flex items-center flex-wrap gap-1">
                                        {record.driver_name}
                                        {type === 'checkin' && getFixStartBadge(record)}
                                    </h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
            {/* Column 1: Pending Check-in */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-amber-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-700 text-lg">
                        <i className="fas fa-clock"></i> รอตรวจก่อนงาน
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700 flex items-center gap-1">
                                    {r.driver_name}
                                    {getFixStartBadge(r)}
                                </p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>

            {/* Column 2: Active / Not Checkout Yet */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-blue-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-blue-700 text-lg">
                        <i className="fas fa-truck-moving"></i> กำลังปฏิบัติงาน (ยังไม่ส่งเลิก)
                    </h3>
                    <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full">{activeDrivers.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {activeDrivers.map(r => (
                        <div key={r.__backendId} className="flex justify-between p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-500">เริ่มงานเมื่อ: {getSafeDateTime(r.checkin_timestamp)}</p>
                            </div>
                            <div className="text-right">
                                <Badge type="approved">On Duty</Badge>
                            </div>
                        </div>
                    ))}
                    {activeDrivers.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-road text-4xl mb-2"></i>
                            <p>ไม่มีรถวิ่งงาน</p>
                        </div>
                    )}
                </div>
            </Card>

            {/* Column 3: Pending Check-out */}
            <Card className="flex flex-col h-full bg-white border-t-4 border-purple-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-700 text-lg">
                        <i className="fas fa-flag-checkered"></i> รอตรวจหลังงาน
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-sm font-bold text-slate-600">{getSafeDateTime(r.checkout_timestamp || r.checkout_real_timestamp)}</p>
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

import React, { useState, useMemo } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import * as XLSX from 'xlsx';

interface Props {
  records: TenkoRecord[];
}

export const TenkoAnalytics: React.FC<Props> = ({ records }) => {
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(today);
  const [selectedDriverId, setSelectedDriverId] = useState<string>(''); // Filter state

  const drivers = StorageService.getUsers().filter(u => u.role === 'driver');

  // --- Filtering Logic ---
  const filteredRecords = useMemo(() => {
    let res = records;
    if (selectedDriverId) {
        res = res.filter(r => r.driver_id === selectedDriverId);
    }
    return res;
  }, [records, selectedDriverId]);

  const monthRecords = useMemo(() => {
    return filteredRecords.filter(r => {
        const d = new Date(r.checkin_timestamp || r.date);
        return d.getMonth() === currentMonth.getMonth() && d.getFullYear() === currentMonth.getFullYear();
    });
  }, [filteredRecords, currentMonth]);

  // --- Graph Data (Last 5 days for selected driver or aggregate) ---
  const graphData = useMemo(() => {
    // Sort by date ascending
    const sorted = [...monthRecords]
        .filter(r => r.blood_pressure_high && r.blood_pressure_low)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    // Take last 5
    return sorted.slice(-5);
  }, [monthRecords]);


  // --- Export Logic ---
  const exportExcel = () => {
    const data = monthRecords.map(r => {
        // Helper for combining status and detail
        const formatDetail = (status?: string, detail?: string) => {
            if (!status) return '-';
            return detail ? `${status} (${detail})` : status;
        };

        const sleepInfo = r.sleep_hours 
            ? `${r.sleep_hours} ชม. (${r.sleep_start || '-'} - ${r.sleep_end || '-'}) ${r.sleep_quality || ''}`
            : '-';

        const extraSleepInfo = r.extra_sleep === 'นอนเพิ่ม'
            ? `${r.extra_sleep_hours} ชม. (${r.extra_sleep_start || '-'} - ${r.extra_sleep_end || '-'}) ${r.extra_sleep_quality || ''}`
            : 'ไม่นอนเพิ่ม';

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,

            // --- 1. สุขภาพก่อนงาน (Driver Self Check) ---
            "ความเหนื่อยล้า": formatDetail(r.tired, r.tired_detail),
            "การเจ็บป่วย": r.sick === 'มี' ? `มี (${r.sick_detail || '-'}) หาหมอ: ${r.seen_doctor || '-'}` : 'ไม่มี',
            "ความง่วง": formatDetail(r.drowsy, r.drowsy_detail),
            "การบาดเจ็บ": formatDetail(r.injury, r.injury_detail),
            "การใช้ยา": r.medication === 'ทาน' ? `ทาน (${r.medication_name || '-'})` : 'ไม่ทาน',
            "สภาพร่างกาย(ก่อน)": formatDetail(r.body_condition, r.body_condition_detail),
            "การนอนหลับ": sleepInfo,
            "การนอนเพิ่ม": extraSleepInfo,
            "เรื่องกังวลใจ": formatDetail(r.worry_detail, r.worry_text),
            "สถานที่พักผ่อน": formatDetail(r.rest_location, r.rest_location_detail),
            "ปัญหาสายตา": `${r.vision_problem || '-'} (แว่น: ${r.glasses || '-'})`,
            "การได้ยิน": `${r.hearing_problem || '-'} (เครื่องช่วย: ${r.hearing_aid || '-'})`,

            // --- 2. การตรวจสอบก่อนงาน (Tenko Check) ---
            "เวลาเข้างาน (อนุมัติ)": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เข้างาน)": r.checkin_tenko_name || '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "เหตุผลแอลกอฮอล์(เข้า)": r.alcohol_checkin_reason || '-',
            "การใช้โทรศัพท์": formatDetail(r.phone_usage_compliant, r.phone_usage_reason),
            "ผลประเมิน": formatDetail(r.can_work, r.cannot_work_reason),

            // --- 3. รายงานหลังงาน (Driver Post-work) ---
            "การส่งมอบรถ": formatDetail(r.vehicle_handover, r.vehicle_detail),
            "สภาพร่างกาย(หลัง)": formatDetail(r.body_condition_checkout, r.body_detail_checkout),
            "จุดเสี่ยง": formatDetail(r.route_risk, r.route_detail),

            // --- 4. การตรวจสอบหลังงาน (Tenko Check) ---
            "เวลาเลิกงาน (อนุมัติ)": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เลิกงาน)": r.checkout_tenko_name || '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "เหตุผลแอลกอฮอล์(ออก)": r.alcohol_checkout_reason || '-',
            "ข้อละเมิดการขับขี่": formatDetail(r.driving_violation, r.violation_detail)
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);

    // Auto-width
    const wscols = [
        {wch: 12}, {wch: 20}, {wch: 10}, 
        {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15},
        {wch: 25}, {wch: 25},
        {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15},
        {wch: 15}, {wch: 20}, {wch: 10}, {wch: 10}, {wch: 10}, {wch: 15},
        {wch: 20}, {wch: 20}, {wch: 20},
        {wch: 15}, {wch: 20}, {wch: 10}, {wch: 15}, {wch: 20}
    ];
    ws['!cols'] = wscols;

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "TenkoReport");
    XLSX.writeFile(wb, `Tenko_Full_Export_${selectedDriverId || 'ALL'}_${currentMonth.toISOString().slice(0,7)}.xlsx`);
  };

  // --- Calendar Helpers ---
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  const getDayCount = (day: number) => {
    const target = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day).toISOString().split('T')[0];
    return filteredRecords.filter(r => r.date === target).length;
  };

  // --- SVG Graph Render ---
  const renderBPGraph = () => {
    if (graphData.length < 2) return <div className="h-64 flex items-center justify-center text-slate-400 bg-slate-50 rounded-lg border border-dashed">ข้อมูลไม่เพียงพอสำหรับกราฟ (ต้องมีอย่างน้อย 2 วัน)</div>;

    // Canvas Configuration
    const svgHeight = 300;
    const svgWidth = 800; // Internal coordinate system width
    const paddingX = 80;
    const paddingY = 40;

    // Y-Axis Scale
    const maxVal = 180;
    const minVal = 50;
    const range = maxVal - minVal;
    const drawingHeight = svgHeight - (paddingY * 2);
    const drawingWidth = svgWidth - (paddingX * 2);

    const getX = (i: number) => paddingX + (i / (graphData.length - 1)) * drawingWidth;
    const getY = (val: number) => (svgHeight - paddingY) - ((val - minVal) / range) * drawingHeight;

    // Generate Points
    const pointsHigh = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_high || 0)}`).join(' ');
    const pointsLow = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_low || 0)}`).join(' ');

    // Generate Areas (for gradient fill)
    const areaHigh = `${pointsHigh} ${getX(graphData.length-1)},${svgHeight-paddingY} ${getX(0)},${svgHeight-paddingY}`;
    const areaLow = `${pointsLow} ${getX(graphData.length-1)},${svgHeight-paddingY} ${getX(0)},${svgHeight-paddingY}`;

    return (
        <div className="relative h-[320px] w-full p-2">
            <svg viewBox={`0 0 ${svgWidth} ${svgHeight}`} className="w-full h-full overflow-visible drop-shadow-sm">
                <defs>
                    <linearGradient id="gradHigh" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stopColor="#ef4444" stopOpacity="0.2" />
                        <stop offset="100%" stopColor="#ef4444" stopOpacity="0" />
                    </linearGradient>
                    <linearGradient id="gradLow" x1="0" x2="0" y1="0" y2="1">
                        <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.2" />
                        <stop offset="100%" stopColor="#3b82f6" stopOpacity="0" />
                    </linearGradient>
                </defs>

                {/* Grid Lines & Y-Axis Labels */}
                {[60, 90, 120, 150].map((val) => (
                    <g key={val}>
                        <line 
                            x1={paddingX - 10} y1={getY(val)} 
                            x2={svgWidth - paddingX + 10} y2={getY(val)} 
                            stroke="#e2e8f0" strokeWidth="1" strokeDasharray={val === 90 || val === 140 ? "5,5" : ""} 
                        />
                        <text x={paddingX - 20} y={getY(val) + 4} fontSize="12" fill="#94a3b8" textAnchor="end">{val}</text>
                    </g>
                ))}

                {/* Area Fills */}
                <polygon points={areaHigh} fill="url(#gradHigh)" />
                <polygon points={areaLow} fill="url(#gradLow)" />

                {/* Lines */}
                <polyline points={pointsHigh} fill="none" stroke="#ef4444" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
                <polyline points={pointsLow} fill="none" stroke="#3b82f6" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

                {/* Data Points */}
                {graphData.map((d, i) => (
                    <g key={i} className="group cursor-pointer">
                        {/* High Point */}
                        <circle cx={getX(i)} cy={getY(d.blood_pressure_high!)} r="5" fill="#fff" stroke="#ef4444" strokeWidth="2.5" className="transition-all duration-300 group-hover:r-7" />
                        <text x={getX(i)} y={getY(d.blood_pressure_high!) - 15} fontSize="14" fontWeight="bold" fill="#ef4444" textAnchor="middle" className="opacity-0 group-hover:opacity-100 transition-opacity select-none">{d.blood_pressure_high}</text>

                        {/* Low Point */}
                        <circle cx={getX(i)} cy={getY(d.blood_pressure_low!)} r="5" fill="#fff" stroke="#3b82f6" strokeWidth="2.5" className="transition-all duration-300 group-hover:r-7" />
                        <text x={getX(i)} y={getY(d.blood_pressure_low!) + 25} fontSize="14" fontWeight="bold" fill="#3b82f6" textAnchor="middle" className="opacity-0 group-hover:opacity-100 transition-opacity select-none">{d.blood_pressure_low}</text>

                        {/* X-Axis Date Label */}
                        <text x={getX(i)} y={svgHeight - 10} fontSize="12" fill="#64748b" textAnchor="middle">{new Date(d.date).toLocaleDateString('th-TH', {day: 'numeric', month: 'short'})}</text>

                        {/* Vertical Guide Line on Hover */}
                        <line x1={getX(i)} y1={paddingY} x2={getX(i)} y2={svgHeight - paddingY} stroke="#94a3b8" strokeWidth="1" strokeDasharray="4" className="opacity-0 group-hover:opacity-20" />
                    </g>
                ))}
            </svg>
            <div className="absolute top-2 right-4 flex gap-4 text-xs bg-white/80 p-2 rounded-lg backdrop-blur-sm shadow-sm border border-slate-100">
                <div className="flex items-center gap-2"><div className="w-3 h-3 bg-red-500 rounded-full border-2 border-white shadow-sm"></div> ความดันบน (SYS)</div>
                <div className="flex items-center gap-2"><div className="w-3 h-3 bg-blue-500 rounded-full border-2 border-white shadow-sm"></div> ความดันล่าง (DIA)</div>
            </div>
        </div>
    );
  };

  return (
    <div className="space-y-6">
        {/* Header & Controls */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-100">
            <div>
                <h2 className="text-2xl font-bold text-slate-800">แดชบอร์ด & สถิติ</h2>
                <p className="text-slate-500 text-sm">ข้อมูลเดือน: {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</p>
            </div>
            <div className="flex gap-3 w-full md:w-auto">
                <select 
                    className="p-2.5 border rounded-lg bg-slate-50 min-w-[200px]"
                    value={selectedDriverId}
                    onChange={(e) => setSelectedDriverId(e.target.value)}
                >
                    <option value="">-- พนักงานทั้งหมด --</option>
                    {drivers.map(d => (
                        <option key={d.id} value={d.id}>{d.name} ({d.id})</option>
                    ))}
                </select>
                <Button onClick={exportExcel} className="bg-green-600 hover:bg-green-700 whitespace-nowrap">
                    <i className="fas fa-file-excel"></i> Export
                </Button>
            </div>
        </div>

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Left: Calendar */}
            <Card className="h-full">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg text-slate-700">ปฏิทินการทำงาน</h3>
                    <div className="flex gap-2">
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()-1)))} className="p-1 hover:bg-slate-100 rounded"><i className="fas fa-chevron-left"></i></button>
                        <button onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth()+1)))} className="p-1 hover:bg-slate-100 rounded"><i className="fas fa-chevron-right"></i></button>
                    </div>
                </div>

                <div className="grid grid-cols-7 gap-1">
                    {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                    {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                    {Array.from({length: daysInMonth}).map((_, i) => {
                        const count = getDayCount(i+1);
                        return (
                            <div key={i} className={`
                                h-14 flex flex-col items-center justify-center rounded-lg border text-sm font-medium transition-colors relative
                                ${count > 0 ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-100 text-slate-400'}
                                ${selectedDriverId && count > 0 ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : ''}
                            `}>
                                <span>{i+1}</span>
                                {count > 0 && (
                                    <span className={`text-xs rounded-full w-5 h-5 flex items-center justify-center mt-1 text-white font-bold
                                        ${selectedDriverId ? 'bg-emerald-500' : 'bg-blue-600'}
                                    `}>
                                        {selectedDriverId ? <i className="fas fa-check text-[10px]"></i> : count}
                                    </span>
                                )}
                            </div>
                        );
                    })}
                </div>
            </Card>

            {/* Right: BP Graph */}
            <Card className="h-full flex flex-col">
                <div className="mb-4">
                    <h3 className="font-bold text-lg text-slate-700 flex items-center gap-2">
                        <i className="fas fa-heartbeat text-red-500"></i> แนวโน้มความดันโลหิต
                    </h3>
                    <p className="text-xs text-slate-500">5 วันล่าสุดที่มีข้อมูล {selectedDriverId ? '(รายบุคคล)' : '(รวม)'}</p>
                </div>
                <div className="flex-1 bg-white rounded-lg border border-slate-100 overflow-hidden shadow-inner">
                    {renderBPGraph()}
                </div>
                <div className="mt-4 grid grid-cols-2 gap-4 text-center">
                    <div className="bg-red-50 p-3 rounded-lg border border-red-100">
                        <span className="text-xs text-slate-500 block uppercase tracking-wide">Avg ความดันบน</span>
                        <span className="font-bold text-red-600 text-xl">
                            {graphData.length > 0 ? Math.round(graphData.reduce((a,b) => a + (b.blood_pressure_high||0), 0) / graphData.length) : '-'}
                        </span>
                        <span className="text-xs text-red-400 ml-1">mmHg</span>
                    </div>
                    <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                        <span className="text-xs text-slate-500 block uppercase tracking-wide">Avg ความดันล่าง</span>
                        <span className="font-bold text-blue-600 text-xl">
                            {graphData.length > 0 ? Math.round(graphData.reduce((a,b) => a + (b.blood_pressure_low||0), 0) / graphData.length) : '-'}
                        </span>
                        <span className="text-xs text-blue-400 ml-1">mmHg</span>
                    </div>
                </div>
            </Card>
        </div>

        {/* Bottom: Detailed List */}
        <Card>
            <h3 className="font-bold text-lg text-slate-700 mb-4 flex items-center gap-2">
                <i className="fas fa-list"></i> รายละเอียดการตรวจ ({monthRecords.length} รายการ)
            </h3>
            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-slate-100 text-slate-600 font-semibold uppercase">
                        <tr>
                            <th className="p-3 rounded-tl-lg">วันที่</th>
                            <th className="p-3">พนักงาน</th>
                            <th className="p-3 text-center">เวลาเข้า</th>
                            <th className="p-3 text-center">BP (บน/ล่าง)</th>
                            <th className="p-3 text-center">Temp</th>
                            <th className="p-3 text-center">Alcohol</th>
                            <th className="p-3 text-right rounded-tr-lg">สถานะ</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {monthRecords.map(r => (
                            <tr key={r.__backendId} className="hover:bg-slate-50 transition-colors">
                                <td className="p-3 font-medium text-slate-700">{new Date(r.date).toLocaleDateString('th-TH')}</td>
                                <td className="p-3">
                                    <div className="font-bold text-slate-700">{r.driver_name}</div>
                                    <div className="text-xs text-slate-400">{r.driver_id}</div>
                                </td>
                                <td className="p-3 text-center text-slate-600">
                                    {r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'}
                                </td>
                                <td className="p-3 text-center">
                                    <span className={`font-bold ${r.blood_pressure_high! > 140 ? 'text-red-600' : 'text-slate-700'}`}>
                                        {r.blood_pressure_high}
                                    </span> / {r.blood_pressure_low}
                                </td>
                                <td className="p-3 text-center">{r.temperature}</td>
                                <td className="p-3 text-center text-emerald-600 font-bold">{r.alcohol_checkin}</td>
                                <td className="p-3 text-right">
                                    <Badge type={r.checkin_status === 'approved' ? 'approved' : 'pending'}>
                                        {r.checkin_status === 'approved' ? 'อนุมัติแล้ว' : 'รอตรวจ'}
                                    </Badge>
                                </td>
                            </tr>
                        ))}
                        {monthRecords.length === 0 && (
                            <tr>
                                <td colSpan={7} className="p-8 text-center text-slate-400">ไม่พบข้อมูล</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </Card>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { StorageService } from '../../services/storage';
import { TenkoDashboard } from './TenkoDashboard';
import { ApprovalView } from './ApprovalView';
import { StaffManagement } from './StaffManagement';
import { TenkoHistory } from './TenkoHistory';
import { TenkoAnalytics } from './TenkoAnalytics';
import { TenkoReportPrint } from './TenkoReportPrint';

interface Props {
  user: User;
  onLogout: () => void;
}

type View = 'dashboard' | 'queue-checkin' | 'queue-checkout' | 'completed' | 'analytics' | 'manage' | 'report';

export const TenkoApp: React.FC<Props> = ({ user, onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [selectedRecordId, setSelectedRecordId] = useState<string | null>(null);

  useEffect(() => {
    const load = () => setRecords(StorageService.getAll());
    load();
    const interval = setInterval(load, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleUpdate = () => {
    setRecords(StorageService.getAll());
    setSelectedRecordId(null);
  };

  const SidebarItem = ({ view, icon, label }: { view: View; icon: string; label: string }) => (
    <div 
      onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
      className={`px-4 py-3 cursor-pointer flex items-center gap-3 transition-colors ${currentView === view ? 'bg-white/20 border-r-4 border-white' : 'hover:bg-white/10 border-r-4 border-transparent'}`}
    >
      <i className={`fas ${icon} w-6 text-center`}></i>
      <span className="font-medium">{label}</span>
      {view.includes('queue') && (
        <span className="ml-auto bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
            {records.filter(r => view === 'queue-checkin' ? r.checkin_status === 'pending' : r.checkout_status === 'pending').length}
        </span>
      )}
    </div>
  );

  const renderContent = () => {
    if (selectedRecordId) {
       const record = records.find(r => r.__backendId === selectedRecordId);
       if (!record) return <div>Record not found</div>;
       return (
         <ApprovalView 
            record={record} 
            user={user}
            type={currentView === 'queue-checkin' ? 'checkin' : currentView === 'queue-checkout' ? 'checkout' : 'view'}
            onBack={() => setSelectedRecordId(null)}
            onSuccess={handleUpdate}
         />
       );
    }

    switch (currentView) {
        case 'manage': return <StaffManagement />;
        case 'analytics': return <TenkoAnalytics records={records} />;
        case 'report': return <TenkoReportPrint records={records} />;
        case 'completed': return <TenkoHistory records={records} onSelectRecord={setSelectedRecordId} onDelete={handleUpdate} />;
        case 'queue-checkin': return <TenkoDashboard view="queue-checkin" records={records} onSelectRecord={setSelectedRecordId} />;
        case 'queue-checkout': return <TenkoDashboard view="queue-checkout" records={records} onSelectRecord={setSelectedRecordId} />;
        default: return <TenkoDashboard view="dashboard" records={records} onSelectRecord={setSelectedRecordId} />;
    }
  };

  return (
    <div className="flex h-full bg-slate-50 overflow-hidden">
      {/* Sidebar hidden when printing */}
      <aside className="w-64 bg-gradient-to-b from-blue-900 to-blue-700 text-white flex flex-col shadow-xl z-20 print:hidden">
        <div className="p-6 border-b border-blue-500/30">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                    <i className="fas fa-user-shield"></i>
                </div>
                <div>
                    <h3 className="font-bold leading-tight">{user.name}</h3>
                    <p className="text-xs text-blue-200">เจ้าหน้าที่ Tenko</p>
                </div>
            </div>
        </div>
        <nav className="flex-1 py-4 space-y-1 text-sm">
            <SidebarItem view="dashboard" icon="fa-home" label="หน้าหลัก" />
            <SidebarItem view="queue-checkin" icon="fa-clipboard-check" label="คิว (ก่อนเริ่มงาน)" />
            <SidebarItem view="queue-checkout" icon="fa-flag-checkered" label="คิว (หลังเลิกงาน)" />
            <SidebarItem view="completed" icon="fa-check-double" label="รายการเสร็จสิ้น" />
            <SidebarItem view="analytics" icon="fa-chart-line" label="แดชบอร์ด/ปฏิทิน" />
            <SidebarItem view="report" icon="fa-print" label="พิมพ์รายงาน" />
            <SidebarItem view="manage" icon="fa-users-cog" label="ข้อมูลพนักงาน" />
        </nav>
        <div className="p-4 border-t border-blue-500/30">
            <button onClick={onLogout} className="w-full py-2 bg-blue-900/50 hover:bg-blue-800 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm">
                <i className="fas fa-sign-out-alt"></i> ออกจากระบบ
            </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto p-8 print:p-0 print:overflow-visible">
        {renderContent()}
      </main>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { TenkoRecord, User } from '../../types';
import { StorageService } from '../../services/storage';
import { Button, Card } from '../../components/UI';

interface Props {
  records: TenkoRecord[];
}

export const TenkoReportPrint: React.FC<Props> = ({ records }) => {
  const [selectedDriverId, setSelectedDriverId] = useState('');
  const [selectedDate, setSelectedDate] = useState('');

  const drivers = useMemo(() => StorageService.getUsers().filter(u => u.role === 'driver'), []);

  // Get available dates for the selected driver
  const availableDates = useMemo(() => {
    if (!selectedDriverId) return [];
    return records
        .filter(r => r.driver_id === selectedDriverId)
        .map(r => r.date)
        .sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  }, [records, selectedDriverId]);

  const record = useMemo(() => {
    return records.find(r => r.driver_id === selectedDriverId && r.date === selectedDate);
  }, [records, selectedDriverId, selectedDate]);

  const handlePrint = () => {
    window.print();
  };

  // Helper for checkbox rendering
  const CheckBox = ({ checked, label, detail }: { checked: boolean; label: string; detail?: string }) => (
    <div className="flex items-start gap-2 text-sm mb-1">
      <div className={`w-4 h-4 border border-slate-600 flex items-center justify-center shrink-0 mt-0.5 ${checked ? 'bg-slate-800 text-white' : 'bg-white'}`}>
        {checked && <i className="fas fa-check text-[10px]"></i>}
      </div>
      <div className="leading-tight">
        <span className={checked ? 'font-bold' : ''}>{label}</span>
        {checked && detail && <span className="ml-1 underline decoration-dotted text-slate-700">({detail})</span>}
      </div>
    </div>
  );

  const LabelVal = ({ label, val, unit = '' }: { label: string; val?: string | number; unit?: string }) => (
    <div className="flex justify-between items-end border-b border-slate-300 border-dotted pb-0.5 mb-1">
        <span className="text-sm font-semibold text-slate-600">{label}</span>
        <span className="text-sm font-bold text-slate-900">{val || '-'} {unit}</span>
    </div>
  );

  return (
    <div className="flex flex-col h-full">
      {/* Controls - Hidden on Print */}
      <div className="print:hidden mb-6 space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800"><i className="fas fa-print"></i> พิมพ์รายงาน (A4)</h2>
        </div>

        <Card className="bg-white border-l-4 border-blue-500">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
                <div>
                    <label className="block text-sm font-bold mb-1">เลือกพนักงานขับรถ</label>
                    <select 
                        className="w-full p-2 border rounded"
                        value={selectedDriverId}
                        onChange={e => { setSelectedDriverId(e.target.value); setSelectedDate(''); }}
                    >
                        <option value="">-- กรุณาเลือก --</option>
                        {drivers.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-bold mb-1">เลือกวันที่</label>
                    <select 
                        className="w-full p-2 border rounded"
                        value={selectedDate}
                        onChange={e => setSelectedDate(e.target.value)}
                        disabled={!selectedDriverId}
                    >
                        <option value="">-- กรุณาเลือก --</option>
                        {availableDates.map(d => (
                            <option key={d} value={d}>{new Date(d).toLocaleDateString('th-TH', {dateStyle: 'full'})}</option>
                        ))}
                    </select>
                </div>
                <div>
                    <Button onClick={handlePrint} disabled={!record} className="w-full bg-slate-800 text-white">
                        <i className="fas fa-file-pdf"></i> พิมพ์ / บันทึกเป็น PDF
                    </Button>
                </div>
            </div>
        </Card>
      </div>

      {/* A4 Report Area */}
      <div className="flex-1 flex justify-center bg-slate-200 p-4 print:p-0 print:bg-white overflow-y-auto">
        {record ? (
            <div 
                id="print-section"
                className="bg-white shadow-lg print:shadow-none mx-auto relative box-border"
                style={{ width: '210mm', minHeight: '297mm', padding: '15mm 15mm' }}
            >
                {/* Header */}
                <div className="border-b-2 border-slate-800 pb-4 mb-4 flex justify-between items-start">
                    <div>
                        <h1 className="text-2xl font-bold text-slate-900 uppercase">แบบฟอร์มตรวจสอบความพร้อม (Tenko)</h1>
                        <p className="text-slate-500 text-sm">บริษัท ออโต้แครี่เออร์ จำกัด (ACT)</p>
                    </div>
                    <div className="text-right">
                        <div className="text-sm font-bold text-slate-600">วันที่ปฏิบัติงาน</div>
                        <div className="text-xl font-bold">{new Date(record.date).toLocaleDateString('th-TH', { dateStyle: 'long' })}</div>
                    </div>
                </div>

                {/* Driver Info Row */}
                <div className="bg-slate-100 p-3 rounded mb-4 border border-slate-300 flex justify-between">
                    <div><span className="font-bold">ชื่อพนักงาน:</span> {record.driver_name}</div>
                    <div><span className="font-bold">รหัส:</span> {record.driver_id}</div>
                </div>

                <div className="grid grid-cols-2 gap-6 h-full">
                    {/* LEFT COLUMN: Check-in */}
                    <div className="flex flex-col gap-4">
                        {/* 1. Driver Self Check */}
                        <div className="border border-slate-400 rounded p-3">
                            <h3 className="font-bold bg-slate-200 px-2 py-1 -mx-3 -mt-3 mb-2 text-sm border-b border-slate-400 text-center">1. การประเมินตนเอง (Driver Self-Check)</h3>

                            <div className="space-y-1 mb-3">
                                <CheckBox checked={record.tired === 'มี'} label="มีความเหนื่อยล้าสะสม" detail={record.tired_detail} />
                                <CheckBox checked={record.sick === 'มี'} label="มีอาการเจ็บป่วย / ไม่สบาย" detail={record.sick_detail} />
                                <CheckBox checked={record.drowsy === 'มี'} label="มีอาการง่วงนอน" detail={record.drowsy_detail} />
                                <CheckBox checked={record.injury === 'มี'} label="มีอาการบาดเจ็บทางร่างกาย" detail={record.injury_detail} />
                                <CheckBox checked={record.medication === 'ทาน'} label="ทานยาที่ส่งผลต่อการขับขี่" detail={record.medication_name} />
                            </div>

                            <div className="border-t border-slate-300 pt-2 mb-2">
                                <p className="font-bold text-sm mb-1">การนอนหลับ</p>
                                <LabelVal label="เวลานอน" val={`${record.sleep_start} - ${record.sleep_end}`} />
                                <LabelVal label="รวมชั่วโมง" val={record.sleep_hours} unit="ชม." />
                                <CheckBox checked={record.sleep_quality === 'หลับสนิท'} label="หลับสนิท" />
                                {record.extra_sleep === 'นอนเพิ่ม' && (
                                    <div className="mt-1 text-xs text-slate-600 bg-slate-50 p-1 rounded">
                                        นอนเพิ่ม: {record.extra_sleep_start}-{record.extra_sleep_end} ({record.extra_sleep_hours} ชม.)
