import { Pool } from '@neondatabase/serverless';
import { TenkoRecord, User } from '../types';
import { DRIVERS, TENKO_USERS } from '../constants';

// *** สำคัญ: นำ Connection String จาก Neon Console มาวางตรงนี้ ***
const CONNECTION_STRING = "postgresql://neondb_owner:npg_gS1u2xVdUYJc@ep-odd-silence-a1n4q29c-pooler.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

// Create a connection pool
const pool = new Pool({ connectionString: CONNECTION_STRING });

export const StorageService = {
  // --- Records ---
  getAll: async (): Promise<TenkoRecord[]> => {
    try {
      // Query ข้อมูลทั้งหมดจากตาราง records
      const result = await pool.query('SELECT * FROM records ORDER BY date DESC');

      // แปลงข้อมูลจาก DB กลับมาเป็น Object ที่แอพใช้งาน
      return result.rows.map(row => {
        // row.data คือ JSONB ที่เก็บ field ย่อยๆ
        return {
          ...row.data,
          __backendId: row.id, // ใช้ ID จริงจาก DB
          driver_id: row.driver_id,
          date: row.date
        } as TenkoRecord;
      });
    } catch (e) {
      console.error("Failed to load data from Neon", e);
      return [];
    }
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    try {
      const id = crypto.randomUUID(); // สร้าง ID
      const driver_id = record.driver_id || '';
      const date = record.date || '';

      // สร้าง Object ที่จะเก็บลง JSONB (ตัด field หลักออกเพื่อไม่ให้ซ้ำซ้อน แต่เก็บไว้ใน JSON ด้วยก็ได้เพื่อความง่าย)
      const jsonData = { ...record, __backendId: id };

      await pool.query(
        'INSERT INTO records (id, driver_id, date, data) VALUES ($1, $2, $3, $4)',
        [id, driver_id, date, jsonData]
      );

      return { isOk: true, data: { ...record, __backendId: id } as TenkoRecord };
    } catch (e) {
      console.error("Failed to create record", e);
      return { isOk: false };
    }
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    try {
      // อัปเดต JSON data ใหม่ทั้งหมด
      await pool.query(
        'UPDATE records SET data = $1, checkin_status = $2, checkout_status = $3 WHERE id = $4',
        [record, record.checkin_status, record.checkout_status, record.__backendId]
      );
      return { isOk: true };
    } catch (e) {
        // Fallback query if checkin_status columns don't exist in your specific DB setup yet, 
        // usually just updating 'data' column is enough if we designed schema that way.
        // For this implementation, let's assume we update the whole JSON blob.
        try {
             await pool.query(
                'UPDATE records SET data = $1 WHERE id = $2',
                [record, record.__backendId]
             );
             return { isOk: true };
        } catch (ex) {
             console.error("Failed to update record", ex);
             return { isOk: false };
        }
    }
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    try {
      await pool.query('DELETE FROM records WHERE id = $1', [recordId]);
      return { isOk: true };
    } catch (e) {
      console.error("Failed to delete record", e);
      return { isOk: false };
    }
  },

  // --- Users ---
  getUsers: async (): Promise<User[]> => {
    try {
      const result = await pool.query('SELECT * FROM users');
      if (result.rows.length === 0) {
        // ถ้า DB ว่างเปล่า ให้คืนค่า Default (แต่ไม่ Save ลง DB อัตโนมัติเพื่อความปลอดภัย)
        console.log("No users in DB, using defaults for display only.");
        const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
        ];
        return defaults;
      }
      return result.rows.map(row => ({
        id: row.id,
        name: row.name,
        role: row.role as 'driver' | 'tenko'
      }));
    } catch (e) {
      console.error("Failed to load users", e);
      return [];
    }
  },

  saveUser: async (user: User) => {
    try {
      // Upsert (Insert or Update)
      // Note: ON CONFLICT needs a constraint name or column. Assuming id is PK.
      await pool.query(
        `INSERT INTO users (id, name, role, data) VALUES ($1, $2, $3, $4)
         ON CONFLICT (id) DO UPDATE SET name = $2, role = $3`,
        [user.id, user.name, user.role, user]
      );
    } catch (e) {
      console.error("Failed to save user", e);
    }
  },

  deleteUser: async (userId: string) => {
    try {
      await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    } catch (e) {
      console.error("Failed to delete user", e);
    }
  }
};

