// *** สำคัญ: นำ Connection String จาก Neon Console มาวางตรงนี้ ***
// หมายเหตุ: การใส่ Connection String ใน Client-side code ไม่ปลอดภัยสำหรับการใช้งานจริง
const CONNECTION_STRING = "postgresql://neondb_owner:npg_gS1u2xVdUYJc@ep-odd-silence-a1n4q29c-pooler.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

// Create a connection pool
const pool = new Pool({ connectionString: CONNECTION_STRING });

export const StorageService = {
  // --- Records ---
  getAll: async (): Promise<TenkoRecord[]> => {
    try {
      // Query ข้อมูลทั้งหมดจากตาราง records
      const result = await pool.query('SELECT * FROM records ORDER BY date DESC');

      // แปลงข้อมูลจาก DB กลับมาเป็น Object ที่แอพใช้งาน
      return result.rows.map(row => {
        // row.data คือ JSONB ที่เก็บ field ย่อยๆ
        return {
          ...row.data,
          __backendId: row.id, // ใช้ ID จริงจาก DB
          driver_id: row.driver_id,
          date: row.date
        } as TenkoRecord;
      });
    } catch (e) {
      console.error("Failed to load data from Neon", e);
      return [];
    }
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    try {
      const id = crypto.randomUUID(); // สร้าง ID
      const driver_id = record.driver_id || '';
      const date = record.date || '';

      // สร้าง Object ที่จะเก็บลง JSONB
      const jsonData = { ...record, __backendId: id };

      await pool.query(
        'INSERT INTO records (id, driver_id, date, data) VALUES ($1, $2, $3, $4)',
        [id, driver_id, date, jsonData]
      );

      return { isOk: true, data: { ...record, __backendId: id } as TenkoRecord };
    } catch (e) {
      console.error("Failed to create record", e);
      return { isOk: false };
    }
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    try {
      // อัปเดต JSON data ใหม่ทั้งหมด
      await pool.query(
        'UPDATE records SET data = $1, checkin_status = $2, checkout_status = $3 WHERE id = $4',
        [record, record.checkin_status, record.checkout_status, record.__backendId]
      );
      return { isOk: true };
    } catch (e) {
        try {
             await pool.query(
                'UPDATE records SET data = $1 WHERE id = $2',
                [record, record.__backendId]
             );
             return { isOk: true };
        } catch (ex) {
             console.error("Failed to update record", ex);
             return { isOk: false };
        }
    }
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    try {
      await pool.query('DELETE FROM records WHERE id = $1', [recordId]);
      return { isOk: true };
    } catch (e) {
      console.error("Failed to delete record", e);
      return { isOk: false };
    }
  },

  // --- Users ---
  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];

    try {
      const result = await pool.query('SELECT * FROM users');
      if (result.rows.length === 0) {
        console.log("No users in DB, using defaults.");
        return defaults;
      }
      return result.rows.map(row => ({
        id: row.id,
        name: row.name,
        role: row.role as 'driver' | 'tenko'
      }));
    } catch (e) {
      console.error("Failed to load users from DB (Connection error or Table missing). Using Fallback Defaults.", e);
      // Fallback to static data so Login still works
      return defaults;
    }
  },

  saveUser: async (user: User) => {
    try {
      await pool.query(
        `INSERT INTO users (id, name, role, data) VALUES ($1, $2, $3, $4)
         ON CONFLICT (id) DO UPDATE SET name = $2, role = $3`,
        [user.id, user.name, user.role, user]
      );
    } catch (e) {
      console.error("Failed to save user", e);
    }
  },

  deleteUser: async (userId: string) => {
    try {
      await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    } catch (e) {
      console.error("Failed to delete user", e);
    }
  }
};

import { Pool } from '@neondatabase/serverless';
import { TenkoRecord, User } from '../types';
import { DRIVERS, TENKO_USERS } from '../constants';

// *** สำคัญ: นำ Connection String จาก Neon Console มาวางตรงนี้ ***
const CONNECTION_STRING = "postgresql://neondb_owner:npg_gS1u2xVdUYJc@ep-odd-silence-a1n4q29c-pooler.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

// Create a connection pool
const pool = new Pool({ connectionString: CONNECTION_STRING });
const OFFLINE_KEY = 'tenko_offline_records';

const getOfflineData = (): TenkoRecord[] => {
    try {
        return JSON.parse(localStorage.getItem(OFFLINE_KEY) || '[]');
    } catch {
        return [];
    }
};

const saveOfflineData = (records: TenkoRecord[]) => {
    localStorage.setItem(OFFLINE_KEY, JSON.stringify(records));
};

export const StorageService = {
  // --- Sync Mechanism ---
  syncPendingData: async (): Promise<number> => {
      const offlineRecords = getOfflineData();
      if (offlineRecords.length === 0) return 0;

      console.log(`Syncing ${offlineRecords.length} records...`);
      const remainingRecords: TenkoRecord[] = [];
      let syncedCount = 0;

      for (const record of offlineRecords) {
          try {
              // Try to Upsert (Insert or Update based on ID)
              // We use a strategy to check if exists first or just overwrite data
              const check = await pool.query('SELECT id FROM records WHERE id = $1', [record.__backendId]);

              if (check.rows.length > 0) {
                  // Update
                  await pool.query(
                    'UPDATE records SET data = $1, checkin_status = $2, checkout_status = $3 WHERE id = $4',
                    [record, record.checkin_status, record.checkout_status, record.__backendId]
                  );
              } else {
                  // Insert
                  await pool.query(
                    'INSERT INTO records (id, driver_id, date, data) VALUES ($1, $2, $3, $4)',
                    [record.__backendId, record.driver_id, record.date, record]
                  );
              }
              syncedCount++;
          } catch (e) {
              console.error("Sync failed for record", record.__backendId, e);
              remainingRecords.push(record); // Keep in offline if failed
          }
      }

      saveOfflineData(remainingRecords);
      return syncedCount;
  },

  getPendingCount: (): number => {
      return getOfflineData().length;
  },

  // --- Records ---
  getAll: async (): Promise<TenkoRecord[]> => {
    let dbRecords: TenkoRecord[] = [];
    try {
      const result = await pool.query('SELECT * FROM records ORDER BY date DESC');
      dbRecords = result.rows.map(row => ({
          ...row.data,
          __backendId: row.id,
          driver_id: row.driver_id,
          date: row.date
        } as TenkoRecord));
    } catch (e) {
      console.error("Failed to load data from Neon (Offline mode active)", e);
    }

    // Merge with offline records
    const offlineRecords = getOfflineData();

    // Use a Map to merge, preferring Offline records (most recent edits) over DB records
    const recordMap = new Map<string, TenkoRecord>();

    // 1. Put DB records first
    dbRecords.forEach(r => recordMap.set(r.__backendId, r));

    // 2. Overwrite with Offline records
    offlineRecords.forEach(r => recordMap.set(r.__backendId, r));

    // Convert back to array and sort
    return Array.from(recordMap.values()).sort((a, b) => 
        new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    const id = crypto.randomUUID();
    const fullRecord = { 
        ...record, 
        __backendId: id,
        driver_id: record.driver_id || '',
        date: record.date || ''
    } as TenkoRecord;

    try {
      await pool.query(
        'INSERT INTO records (id, driver_id, date, data) VALUES ($1, $2, $3, $4)',
        [id, fullRecord.driver_id, fullRecord.date, fullRecord]
      );
      return { isOk: true, data: fullRecord };
    } catch (e) {
      console.warn("Neon connection failed. Saving locally.", e);
      // Fallback: Save to LocalStorage
      const offline = getOfflineData();
      offline.push(fullRecord);
      saveOfflineData(offline);
      return { isOk: true, data: fullRecord }; // Return success to UI
    }
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    try {
      await pool.query(
        'UPDATE records SET data = $1, checkin_status = $2, checkout_status = $3 WHERE id = $4',
        [record, record.checkin_status, record.checkout_status, record.__backendId]
      );
      return { isOk: true };
    } catch (e) {
      console.warn("Neon connection failed. Updating locally.", e);
      // Fallback: Update in LocalStorage
      const offline = getOfflineData();
      const index = offline.findIndex(r => r.__backendId === record.__backendId);

      if (index >= 0) {
          offline[index] = record;
      } else {
          offline.push(record);
      }
      saveOfflineData(offline);
      return { isOk: true };
    }
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    try {
      await pool.query('DELETE FROM records WHERE id = $1', [recordId]);

      // Also remove from offline if exists
      const offline = getOfflineData().filter(r => r.__backendId !== recordId);
      saveOfflineData(offline);

      return { isOk: true };
    } catch (e) {
      console.warn("Neon delete failed. Attempting local delete only.", e);
       // If DB fails, we can't easily mark for delete in this simple logic without a 'deleted' flag.
       // For now, we just remove from local queue if it was there.
       const offline = getOfflineData().filter(r => r.__backendId !== recordId);
       saveOfflineData(offline);
       // Note: If record exists in DB but we are offline, it won't be deleted from DB until back online and manual action.
       // A full sync would require a 'deleted_queue', but let's keep it simple for now.
      return { isOk: true };
    }
  },

  // --- Users ---
  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];

    try {
      const result = await pool.query('SELECT * FROM users');
      if (result.rows.length === 0) return defaults;
      return result.rows.map(row => ({
        id: row.id,
        name: row.name,
        role: row.role as 'driver' | 'tenko'
      }));
    } catch (e) {
      // Offline fallback
      return defaults;
    }
  },

  saveUser: async (user: User) => {
    try {
      await pool.query(
        `INSERT INTO users (id, name, role, data) VALUES ($1, $2, $3, $4)
         ON CONFLICT (id) DO UPDATE SET name = $2, role = $3`,
        [user.id, user.name, user.role, user]
      );
    } catch (e) {
      console.error("Failed to save user (Offline)", e);
    }
  },

  deleteUser: async (userId: string) => {
    try {
      await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    } catch (e) {
      console.error("Failed to delete user", e);
    }
  }
};

