};

const saveOfflineData = (records: TenkoRecord[]) => {
    localStorage.setItem(OFFLINE_KEY, JSON.stringify(records));
};

export const StorageService = {
  getConnectionStatus: () => lastConnectionStatus,

  // --- Google Auth & Init ---
  initGoogle: async (): Promise<boolean> => {
      const config = getGoogleConfig();
      if (!config.apiKey || !config.clientId) {
          console.warn("Google API Key or Client ID missing");
          lastConnectionStatus = 'offline';
          return false;
      }

      return new Promise((resolve) => {
          gapi.load('client', async () => {
              try {
                  await gapi.client.init({
                      apiKey: config.apiKey,
                      discoveryDocs: [DISCOVERY_DOC],
                  });
                  gapiInited = true;

                  tokenClient = google.accounts.oauth2.initTokenClient({
                      client_id: config.clientId,
                      scope: SCOPES,
                      callback: (resp: any) => {
                          if (resp.error !== undefined) {
                              throw (resp);
                          }
                          accessToken = resp.access_token;
                          lastConnectionStatus = 'online';
                      },
                  });
                  gisInited = true;
                  resolve(true);
              } catch (err) {
                  console.error("GAPI Init Error:", err);
                  lastConnectionStatus = 'error';
                  resolve(false);
              }
          });
      });
  },

  loginToGoogle: () => {
      return new Promise<void>((resolve, reject) => {
          if (!tokenClient) return reject("Google Token Client not initialized");

          // Override callback to resolve promise
          tokenClient.callback = (resp: any) => {
              if (resp.error) {
                  reject(resp);
              } else {
                  accessToken = resp.access_token;
                  lastConnectionStatus = 'online';
                  resolve();
              }
          };

          // Prompt handling
          if (gapi.client.getToken() === null) {
              tokenClient.requestAccessToken({prompt: 'consent'});
          } else {
              tokenClient.requestAccessToken({prompt: ''});
          }
      });
  },

  isLoggedIn: () => !!accessToken,

  // --- Records Logic (Sheet: 'Records') ---
  // Structure: Col A = ID, Col B = JSON Data

  getAll: async (): Promise<TenkoRecord[]> => {
    if (!accessToken) {
        // Return offline mixed with defaults if available
        return getOfflineData();
    }

    try {
        // Assume sheet 'Records' exists. Range A:B
        const response = await gapi.client.sheets.spreadsheets.values.get({
            spreadsheetId: GOOGLE_SHEET_ID,
            range: 'Records!A:B',
        });

        const rows = response.result.values;
        let dbRecords: TenkoRecord[] = [];

        if (rows && rows.length > 0) {
            // Skip header if exists (check if first row is ID/Data)
            const startIdx = rows[0][0] === 'ID' ? 1 : 0;

            for (let i = startIdx; i < rows.length; i++) {
                try {
                    const jsonStr = rows[i][1];
                    if (jsonStr) {
                        const rec = JSON.parse(jsonStr);
                        // Ensure backend ID matches
                        rec.__backendId = rows[i][0];
                        dbRecords.push(rec);
                    }
                } catch (e) {
                    console.warn("Failed to parse row", i, e);
                }
            }
        }

        lastConnectionStatus = 'online';

        // Merge offline
        const offlineRecords = getOfflineData();
        const recordMap = new Map<string, TenkoRecord>();
        dbRecords.forEach(r => recordMap.set(r.__backendId, r));
        offlineRecords.forEach(r => recordMap.set(r.__backendId, r));

        return Array.from(recordMap.values()).sort((a, b) => 
            new Date(b.date).getTime() - new Date(a.date).getTime()
        );

    } catch (e) {
        console.error("Google Sheet Read Error:", e);
        lastConnectionStatus = 'error';
        return getOfflineData();
    }
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    const id = crypto.randomUUID();
    const fullRecord = { 
        ...record, 
        __backendId: id,
        driver_id: record.driver_id || '',
        date: record.date || ''
    } as TenkoRecord;

    if (accessToken) {
        try {
            const values = [
                [id, JSON.stringify(fullRecord)]
            ];

            await gapi.client.sheets.spreadsheets.values.append({
                spreadsheetId: GOOGLE_SHEET_ID,
                range: 'Records!A:B',
                valueInputOption: 'RAW',
                resource: { values },
            });

            lastConnectionStatus = 'online';
            return { isOk: true, data: fullRecord };
        } catch (e) {
            console.error("Create Record Failed:", e);
            lastConnectionStatus = 'error';
        }
    }

    // Offline Fallback
    const offline = getOfflineData();
    offline.push(fullRecord);
    saveOfflineData(offline);
    return { isOk: true, data: fullRecord };
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    if (accessToken) {
        try {
            // 1. Find the row index
            const response = await gapi.client.sheets.spreadsheets.values.get({
                spreadsheetId: GOOGLE_SHEET_ID,
                range: 'Records!A:A', // Read IDs only
            });

            const rows = response.result.values;
            let rowIndex = -1;

            if (rows) {
                for (let i = 0; i < rows.length; i++) {
                    if (rows[i][0] === record.__backendId) {
                        rowIndex = i + 1; // 1-based index
                        break;
                    }
                }
            }

            if (rowIndex !== -1) {
                // 2. Update the row
                await gapi.client.sheets.spreadsheets.values.update({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: `Records!B${rowIndex}`,
                    valueInputOption: 'RAW',
                    resource: { values: [[JSON.stringify(record)]] }
                });
                lastConnectionStatus = 'online';
                return { isOk: true };
            }
        } catch (e) {
            console.error("Update Record Failed:", e);
            lastConnectionStatus = 'error';
        }
    }

    // Offline Update
    const offline = getOfflineData();
    const index = offline.findIndex(r => r.__backendId === record.__backendId);
    if (index >= 0) {
        offline[index] = record;
    } else {
        offline.push(record);
    }
    saveOfflineData(offline);
    return { isOk: true };
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    // Delete in sheets is hard (requires batchUpdate with deleteDimension). 
    // We will simple "blank out" the data or mark as deleted.
    // For simplicity in this demo, we will just remove from offline.
    // Real implementation: Find row, clear content.

    if (accessToken) {
         try {
            const response = await gapi.client.sheets.spreadsheets.values.get({
                spreadsheetId: GOOGLE_SHEET_ID,
                range: 'Records!A:A',
            });
            const rows = response.result.values;
            let rowIndex = -1;
            if (rows) {
                for (let i = 0; i < rows.length; i++) {
                    if (rows[i][0] === recordId) {
                        rowIndex = i + 1;
                        break;
                    }
                }
            }
            if (rowIndex !== -1) {
                 await gapi.client.sheets.spreadsheets.values.clear({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: `Records!A${rowIndex}:B${rowIndex}`,
                });
            }
            lastConnectionStatus = 'online';
         } catch(e) {
             console.error("Delete failed", e);
             lastConnectionStatus = 'error';
         }
    }

    const offline = getOfflineData().filter(r => r.__backendId !== recordId);
    saveOfflineData(offline);
    return { isOk: true };
  },

  syncPendingData: async (): Promise<number> => {
      if (!accessToken) return 0;

      const offlineRecords = getOfflineData();
      if (offlineRecords.length === 0) return 0;

      console.log(`Syncing ${offlineRecords.length} records to Sheets...`);
      const remainingRecords: TenkoRecord[] = [];
      let syncedCount = 0;

      for (const record of offlineRecords) {
          try {
             // Check if exists
             // Performance note: This is slow loop. In prod, batch get first.
             // For prototype, reusing update logic.
             // Try to update, if fail (not found logic in update isn't returning bool properly), append.

             // Simplification: just try create. If ID exists, we need dedupe logic.
             // Let's rely on Create for now as most offline are new.
             // If it's an update, it should have been updated locally.

             // Correct logic: Try to find ID.
             const response = await gapi.client.sheets.spreadsheets.values.get({
                spreadsheetId: GOOGLE_SHEET_ID,
                range: 'Records!A:A',
            });
            const rows = response.result.values || [];
            const exists = rows.some((r: any[]) => r[0] === record.__backendId);

            if (exists) {
                // Update
                // Find row index logic again
                let rowIndex = rows.findIndex((r: any[]) => r[0] === record.__backendId) + 1;
                 await gapi.client.sheets.spreadsheets.values.update({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: `Records!B${rowIndex}`,
                    valueInputOption: 'RAW',
                    resource: { values: [[JSON.stringify(record)]] }
                });
            } else {
                // Insert
                 await gapi.client.sheets.spreadsheets.values.append({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: 'Records!A:B',
                    valueInputOption: 'RAW',
                    resource: { values: [[record.__backendId, JSON.stringify(record)]] },
                });
            }
            syncedCount++;
          } catch (e) {
              console.error("Sync failed for", record.__backendId, e);
              remainingRecords.push(record);
          }
      }

      saveOfflineData(remainingRecords);
      return syncedCount;
  },

  getPendingCount: (): number => {
      return getOfflineData().length;
  },

  // --- Users Logic (Sheet: 'Users') ---
  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];

    if (!accessToken) return defaults;

    try {
        const response = await gapi.client.sheets.spreadsheets.values.get({
            spreadsheetId: GOOGLE_SHEET_ID,
            range: 'Users!A:B',
        });
        const rows = response.result.values;
        if (!rows || rows.length === 0) return defaults;

        const users: User[] = [];
        const startIdx = rows[0][0] === 'ID' ? 1 : 0;

        for (let i = startIdx; i < rows.length; i++) {
            try {
                if (rows[i][1]) {
                    users.push(JSON.parse(rows[i][1]));
                }
            } catch(e) {}
        }

        return users.length > 0 ? users : defaults;
    } catch (e) {
        console.warn("Failed to get users from sheet", e);
        return defaults;
    }
  },

  saveUser: async (user: User) => {
      if (!accessToken) return;
      try {
           const response = await gapi.client.sheets.spreadsheets.values.get({
                spreadsheetId: GOOGLE_SHEET_ID,
                range: 'Users!A:A',
            });
            const rows = response.result.values || [];
            let rowIndex = rows.findIndex((r: any[]) => r[0] === user.id) + 1;

            if (rowIndex > 0) {
                 await gapi.client.sheets.spreadsheets.values.update({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: `Users!B${rowIndex}`,
                    valueInputOption: 'RAW',
                    resource: { values: [[JSON.stringify(user)]] }
                });
            } else {
                 await gapi.client.sheets.spreadsheets.values.append({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: 'Users!A:B',
                    valueInputOption: 'RAW',
                    resource: { values: [[user.id, JSON.stringify(user)]] },
                });
            }
      } catch (e) {
          console.error("Save user failed", e);
      }
  },

  deleteUser: async (userId: string) => {
      // Implement clear row logic if needed
      if (!accessToken) return;
      try {
           const response = await gapi.client.sheets.spreadsheets.values.get({
                spreadsheetId: GOOGLE_SHEET_ID,
                range: 'Users!A:A',
            });
            const rows = response.result.values || [];
            let rowIndex = rows.findIndex((r: any[]) => r[0] === userId) + 1;

            if (rowIndex > 0) {
                 await gapi.client.sheets.spreadsheets.values.clear({
                    spreadsheetId: GOOGLE_SHEET_ID,
                    range: `Users!A${rowIndex}:B${rowIndex}`,
                });
            }
      } catch (e) {
          console.error("Delete user failed", e);
      }
  }
};

import React, { useState, useEffect } from 'react';
import { Button, Card, Input } from '../components/UI';
import { StorageService } from '../services/storage';
import { SYSTEM_VERSION, GOOGLE_SHEET_ID } from '../constants';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
}

export const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Google Auth State
  const [isGoogleReady, setIsGoogleReady] = useState(false);
  const [showConfig, setShowConfig] = useState(false);
  const [apiKey, setApiKey] = useState('');
  const [clientId, setClientId] = useState('');
  const [isGoogleLoggedIn, setIsGoogleLoggedIn] = useState(false);

  useEffect(() => {
    // Load config from localstorage
    setApiKey(localStorage.getItem('GOOGLE_API_KEY') || '');
    setClientId(localStorage.getItem('GOOGLE_CLIENT_ID') || '');

    // Attempt init
    StorageService.initGoogle().then(success => {
        setIsGoogleReady(success);
        if (StorageService.isLoggedIn()) setIsGoogleLoggedIn(true);
    });
  }, []);

  const handleSaveConfig = () => {
      localStorage.setItem('GOOGLE_API_KEY', apiKey);
      localStorage.setItem('GOOGLE_CLIENT_ID', clientId);
      window.location.reload();
  };

  const handleGoogleLogin = async () => {
      try {
          await StorageService.loginToGoogle();
          setIsGoogleLoggedIn(true);
          setError('');
      } catch (e: any) {
          console.error(e);
          setError('Google Login Failed: ' + (e.message || JSON.stringify(e)));
      }
  };

  const handleLogin = async () => {
    setError('');
    setLoading(true);

    try {
        const users = await StorageService.getUsers();
        const user = users.find(u => u.id === username);

        if (user) {
          if (user.role === 'driver' && password === '123') {
            onLogin(user);
            return;
          } 
          if (user.role === 'tenko' && password === '123') {
            onLogin(user);
            return;
          }
        }

        setError('รหัสพนักงานหรือรหัสผ่านไม่ถูกต้อง');
    } catch (e) {
        setError('ไม่สามารถเชื่อมต่อฐานข้อมูลได้');
    } finally {
        setLoading(false);
    }
  };

  if (showConfig) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-slate-100 p-4">
              <Card className="w-full max-w-md">
                  <h2 className="text-xl font-bold mb-4">ตั้งค่า Google API</h2>
                  <div className="space-y-4">
                      <div className="p-3 bg-blue-50 text-xs text-blue-800 rounded">
                          <p>Sheet ID: {GOOGLE_SHEET_ID}</p>
                          <p className="mt-1">ต้องเปิดใช้งาน Google Sheets API ใน Google Cloud Console และสร้าง OAuth 2.0 Client ID</p>
                      </div>
                      <Input label="API Key" value={apiKey} onChange={e => setApiKey(e.target.value)} />
                      <Input label="Client ID" value={clientId} onChange={e => setClientId(e.target.value)} />
                      <div className="flex gap-2">
                          <Button onClick={handleSaveConfig} className="w-full">บันทึก & รีโหลด</Button>
                          <Button variant="secondary" onClick={() => setShowConfig(false)} className="w-full">ยกเลิก</Button>
                      </div>
                  </div>
              </Card>
          </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-50 to-indigo-100 p-4">
      <Card className="w-full max-w-md shadow-xl border-t-4 border-blue-600">
        <div className="text-center mb-8">
          <div className="w-20 h-20 bg-blue-600 rounded-full mx-auto mb-4 flex items-center justify-center shadow-lg shadow-blue-200">
            <i className="fas fa-truck-fast text-white text-3xl"></i>
          </div>
          <h1 className="text-3xl font-bold text-slate-800 mb-1">Tenko TTT by ACT</h1>
          <p className="text-slate-500">ระบบตรวจสอบความพร้อม (Google Sheets)</p>
        </div>

        <div className="space-y-5">
          {/* Google Login Section */}
          <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 text-center">
               {!isGoogleReady ? (
                   <div className="text-red-500 text-sm mb-2">
                       <i className="fas fa-exclamation-triangle"></i> ไม่พบการตั้งค่า API
                   </div>
               ) : isGoogleLoggedIn ? (
                   <div className="text-green-600 font-bold text-sm mb-2">
                       <i className="fas fa-check-circle"></i> เชื่อมต่อ Google Sheets แล้ว
                   </div>
               ) : (
                   <div className="text-slate-500 text-sm mb-2">กรุณาเชื่อมต่อ Google เพื่อซิงค์ข้อมูล</div>
               )}

               {!isGoogleLoggedIn && (
                   <Button 
                        onClick={isGoogleReady ? handleGoogleLogin : () => setShowConfig(true)} 
                        variant="secondary" 
                        className="w-full bg-white hover:bg-slate-50 text-slate-700 border-slate-300"
                        disabled={loading}
                    >
                        <i className="fab fa-google text-red-500"></i> {isGoogleReady ? 'Sign in with Google' : 'ตั้งค่า API Key'}
                   </Button>
               )}
               {isGoogleReady && !isGoogleLoggedIn && (
                   <button onClick={() => setShowConfig(true)} className="text-xs text-slate-400 mt-2 underline">แก้ไขการตั้งค่า</button>
               )}
          </div>

          <div className="border-t border-slate-200 my-4"></div>

          <Input 
            label="รหัสพนักงาน" 
            placeholder="กรอกรหัสพนักงาน" 
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            className="text-lg"
          />

          <div className="relative">
            <Input 
              label="รหัสผ่าน" 
              type={showPassword ? "text" : "password"} 
              placeholder="กรอกรหัสผ่าน"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="pr-10 text-lg"
              onKeyDown={(e) => e.key === 'Enter' && handleLogin()}
            />
            <button 
              className="absolute right-3 top-[38px] text-slate-400 hover:text-blue-600 transition-colors"
              onClick={() => setShowPassword(!showPassword)}
            >
              <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
            </button>
          </div>

          {error && (
            <div className="p-3 bg-red-50 text-red-600 text-sm rounded-lg flex items-center gap-2 animate-pulse">
              <i className="fas fa-exclamation-circle"></i>
              {error}
            </div>
          )}

          <Button onClick={handleLogin} isLoading={loading} className="w-full py-3 text-lg shadow-lg">
            <i className="fas fa-sign-in-alt"></i> เข้าสู่ระบบ
          </Button>

          <div className="text-center mt-6">
             <p className="text-xs text-slate-400 font-mono">{SYSTEM_VERSION}</p>
          </div>
        </div>
      </Card>
    </div>
  );
};

