ได้ครับ การใช้ **Google Apps Script (GAS)** เป็นวิธีที่ดีมาก เพราะช่วยลดความซับซ้อนฝั่งหน้าบ้าน (ไม่ต้องตั้งค่า API Key/OAuth บนเว็บ) และปลอดภัยกว่า โดยเราจะสร้าง "Web API" ขึ้นมาเองจาก Google Sheet ครับ

นี่คือขั้นตอนที่คุณต้องทำ และโค้ดที่ผมปรับปรุงให้ครับ

### ขั้นตอนที่ 1: ติดตั้ง Google Apps Script (สำคัญมาก)
1. เปิด Google Sheet ของคุณ (`15Xvv9HlOAv0ylJAuIjuZVZ1_BCcB3Lh46hKexKEz2sM`)
2. ไปที่เมนู **Extensions (ส่วนขยาย)** > **Apps Script**
3. ลบโค้ดเก่าทิ้งทั้งหมด แล้ววางโค้ดนี้ลงไป:

```javascript
function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var params = e.parameter;
    var postData = e.postData ? JSON.parse(e.postData.contents) : {};
    var action = params.action || postData.action;

    // Auto-create sheets if missing
    ensureSheet(ss, 'Records');
    ensureSheet(ss, 'Users');

    if (action === 'getAll') {
      var sheet = ss.getSheetByName('Records');
      var data = sheet.getDataRange().getValues();
      var result = [];
      // Skip header if empty or first row
      for (var i = 0; i < data.length; i++) {
        if (data[i][0] && data[i][1]) {
           try {
             var rec = JSON.parse(data[i][1]);
             rec.__backendId = data[i][0]; // Ensure ID matches row
             result.push(rec);
           } catch(err) {}
        }
      }
      return responseJSON(result);
    }

    if (action === 'getUsers') {
      var sheet = ss.getSheetByName('Users');
      var data = sheet.getDataRange().getValues();
      var result = [];
      for (var i = 0; i < data.length; i++) {
        if (data[i][1]) {
           try { result.push(JSON.parse(data[i][1])); } catch(err) {}
        }
      }
      return responseJSON(result);
    }

    if (action === 'create' || action === 'update') {
      var sheet = ss.getSheetByName('Records');
      var record = postData.data;
      var id = record.__backendId;
      var json = JSON.stringify(record);

      // Check existing
      var textFinder = sheet.createTextFinder(id).matchEntireCell(true);
      var found = textFinder.findNext();

      if (found) {
         var row = found.getRow();
         sheet.getRange(row, 2).setValue(json); // Update JSON in Col B
      } else {
         sheet.appendRow([id, json]);
      }
      return responseJSON({ status: 'success' });
    }

    if (action === 'delete') {
      var sheet = ss.getSheetByName('Records');
      var id = postData.id;
      var textFinder = sheet.createTextFinder(id).matchEntireCell(true);
      var found = textFinder.findNext();
      if (found) {
        sheet.deleteRow(found.getRow());
      }
      return responseJSON({ status: 'success' });
    }

    if (action === 'saveUser') {
      var sheet = ss.getSheetByName('Users');
      var user = postData.data;
      var id = user.id;
      var json = JSON.stringify(user);

      // Simple lookup by ID in Col A
      var data = sheet.getDataRange().getValues();
      var rowIndex = -1;
      for(var i=0; i<data.length; i++) {
        if(data[i][0] == id) { rowIndex = i+1; break; }
      }

      if (rowIndex > 0) {
        sheet.getRange(rowIndex, 2).setValue(json);
      } else {
        sheet.appendRow([id, json]);
      }
      return responseJSON({ status: 'success' });
    }

    if (action === 'deleteUser') {
      var sheet = ss.getSheetByName('Users');
      var id = postData.id;
      // Simple lookup
      var data = sheet.getDataRange().getValues();
      for(var i=0; i<data.length; i++) {
        if(data[i][0] == id) {
           sheet.deleteRow(i+1);
           break;
        }
      }
      return responseJSON({ status: 'success' });
    }

    return responseJSON({ error: 'Unknown action' });

  } catch (e) {
    return responseJSON({ error: e.toString() });
  } finally {
    lock.releaseLock();
  }
}

function ensureSheet(ss, name) {
