const callScript = async (action: string, payload: any = {}) => {
    const url = getScriptUrl();
    if (!url) throw new Error("No Script URL configured");

    // Google Apps Script Web App requests must be POST with text/plain to avoid CORS preflight issues,
    // or we rely on 'no-cors' but then we can't read response in some browsers easily.
    // However, modern fetch with 'follow' redirect usually works if the script returns JSON.
    // Best practice for GAS API: POST with JSON string body.

    try {
