                    </Card>
                )}

                {/* Main Menu Grid - Responsive Layout */}
                <div className="flex-1 grid grid-rows-3 md:grid-rows-1 md:grid-cols-3 gap-3 md:gap-6 min-h-0">
                    <Card 
                        onClick={() => {
                            if (checkinStatus.allowed) setView('checkin');
