                                </span>
                            </div>
                            {record.route_detail && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-map-marker-alt text-orange-400"></i> {record.route_detail}</div>}
