import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { StorageService } from '../../services/storage';
import { TenkoDashboard } from './TenkoDashboard';
import { ApprovalView } from './ApprovalView';
import { StaffManagement } from './StaffManagement';
import { TenkoHistory } from './TenkoHistory';
import { TenkoAnalytics } from './TenkoAnalytics';
import { TenkoReportPrint } from './TenkoReportPrint';
import { SYSTEM_VERSION } from '../../constants';

interface Props {
  user: User;
  onLogout: () => void;
}

type View = 'dashboard' | 'queue-checkin' | 'queue-checkout' | 'completed' | 'analytics' | 'manage' | 'report';

export const TenkoApp: React.FC<Props> = ({ user, onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [selectedRecordId, setSelectedRecordId] = useState<string | null>(null);

  const loadData = async () => {
      try {
          const data = await StorageService.getAll();
          setRecords(data);
      } catch (e) {
          console.error(e);
      }
  };

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, []);

  const handleUpdate = () => {
    loadData().then(() => {
        setSelectedRecordId(null);
    });
  };

  const handleDeleteRecord = async (id: string) => {
      if(confirm('คุณต้องการลบรายการนี้ทิ้งทันทีหรือไม่? (Driver ต้องส่งใหม่)')) {
          await StorageService.delete(id);
          handleUpdate();
      }
  };

  // Nav Item component reusable for both Sidebar (Desktop) and BottomNav (Mobile)
  const NavItem = ({ view, icon, label, mobile = false }: { view: View; icon: string; label: string; mobile?: boolean }) => {
      const isActive = currentView === view;
      const count = records.filter(r => view === 'queue-checkin' ? r.checkin_status === 'pending' : r.checkout_status === 'pending').length;

      if (mobile) {
          return (
            <button 
                onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
                className={`flex flex-col items-center justify-center p-2 flex-1 relative ${isActive ? 'text-blue-200' : 'text-slate-400'}`}
            >
                <i className={`fas ${icon} text-lg mb-0.5`}></i>
                <span className="text-[9px] leading-tight">{label.split(' ')[0]}</span>
                {view.includes('queue') && count > 0 && (
                    <span className="absolute top-1 right-2 w-4 h-4 bg-red-500 text-white text-[9px] flex items-center justify-center rounded-full font-bold border border-blue-900">
                        {count}
                    </span>
                )}
            </button>
          );
      }

      return (
        <div 
          onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
          className={`px-4 py-3 cursor-pointer flex items-center gap-3 transition-colors ${isActive ? 'bg-white/20 border-r-4 border-white' : 'hover:bg-white/10 border-r-4 border-transparent'}`}
        >
          <i className={`fas ${icon} w-6 text-center`}></i>
          <span className="font-medium">{label}</span>
          {view.includes('queue') && count > 0 && (
            <span className="ml-auto bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
                {count}
            </span>
          )}
        </div>
      );
  };

  const renderContent = () => {
    if (selectedRecordId) {
       const record = records.find(r => r.__backendId === selectedRecordId);
       if (!record) return <div>Record not found</div>;
       return (
         <ApprovalView 
            record={record} 
            user={user}
            type={currentView === 'queue-checkin' ? 'checkin' : currentView === 'queue-checkout' ? 'checkout' : 'view'}
            onBack={() => setSelectedRecordId(null)}
            onSuccess={handleUpdate}
         />
       );
    }

    switch (currentView) {
        case 'manage': return <StaffManagement />;
        case 'analytics': return <TenkoAnalytics records={records} />;
        case 'report': return <TenkoReportPrint records={records} />;
        case 'completed': return <TenkoHistory records={records} onSelectRecord={setSelectedRecordId} onDelete={handleUpdate} />;
        case 'queue-checkin': return <TenkoDashboard view="queue-checkin" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        case 'queue-checkout': return <TenkoDashboard view="queue-checkout" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        default: return <TenkoDashboard view="dashboard" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-full bg-slate-50 overflow-hidden">
      {/* Sidebar - Hidden on Mobile */}
      <aside className="hidden md:flex w-64 bg-gradient-to-b from-blue-900 to-blue-700 text-white flex-col shadow-xl z-20 print:hidden h-full">
        <div className="p-6 border-b border-blue-500/30">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                    <i className="fas fa-user-shield"></i>
                </div>
                <div>
                    <h3 className="font-bold leading-tight">{user.name}</h3>
                    <p className="text-xs text-blue-200">เจ้าหน้าที่ Tenko</p>
                </div>
            </div>
        </div>
        <nav className="flex-1 py-4 space-y-1 text-sm overflow-y-auto">
            <NavItem view="dashboard" icon="fa-home" label="หน้าหลัก" />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="คิว (ก่อนเริ่มงาน)" />
            <NavItem view="queue-checkout" icon="fa-flag-checkered" label="คิว (หลังเลิกงาน)" />
            <NavItem view="completed" icon="fa-check-double" label="รายการเสร็จสิ้น" />
            <NavItem view="analytics" icon="fa-chart-line" label="แดชบอร์ด/ปฏิทิน" />
            <NavItem view="report" icon="fa-print" label="พิมพ์รายงาน" />
            <NavItem view="manage" icon="fa-users-cog" label="ข้อมูลพนักงาน" />
        </nav>
        <div className="p-4 border-t border-blue-500/30">
            <button onClick={onLogout} className="w-full py-2 bg-blue-900/50 hover:bg-blue-800 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm">
                <i className="fas fa-sign-out-alt"></i> ออกจากระบบ
            </button>
            <div className="mt-4 text-center text-xs text-blue-300/60 font-mono">
                {SYSTEM_VERSION}
            </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8 print:p-0 print:overflow-visible pb-20 md:pb-8 w-full">
        {/* Mobile Header */}
        <div className="md:hidden flex justify-between items-center mb-4 bg-white p-3 rounded-lg shadow-sm border border-slate-100">
             <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white">
                    <i className="fas fa-user-shield text-xs"></i>
                </div>
                <span className="font-bold text-sm text-slate-700">{user.name}</span>
             </div>
             <button onClick={onLogout} className="text-slate-400 hover:text-red-500">
                 <i className="fas fa-sign-out-alt"></i>
             </button>
        </div>
        {renderContent()}
      </main>

      {/* Bottom Navigation - Hidden on Desktop */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-slate-900 text-slate-400 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] z-30 flex justify-around items-center border-t border-slate-800 safe-area-pb">
            <NavItem view="dashboard" icon="fa-home" label="Home" mobile />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="In" mobile />
            <NavItem view="queue-checkout" icon="fa-flag-checkered" label="Out" mobile />
            <NavItem view="completed" icon="fa-check-double" label="Done" mobile />
            <div className="w-[1px] h-6 bg-slate-700 mx-1"></div>
            <NavItem view="analytics" icon="fa-chart-line" label="Stats" mobile />
            <NavItem view="manage" icon="fa-cog" label="Admin" mobile />
      </nav>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, OptionButton, Input } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  user: User;
  onBack: () => void;
  onSubmitSuccess: () => void;
}

export const CheckinForm: React.FC<Props> = ({ user, onBack, onSubmitSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    tired: 'ไม่มี',
    sick: 'ไม่มี',
    drowsy: 'ไม่มี',
    injury: 'ไม่มี',
    medication: 'ไม่ทาน',
    body_condition: 'ปกติ',
    sleep_quality: 'หลับสนิท',
    extra_sleep: 'ไม่นอนเพิ่ม',
    worry_detail: 'ไม่มี',
    rest_location: 'บ้าน',
    vision_problem: 'ไม่มี',
    glasses: 'ไม่มี',
    hearing_problem: 'ไม่มี',
    hearing_aid: 'ไม่มี'
  });
  const [submitting, setSubmitting] = useState(false);
  const [lastCheckout, setLastCheckout] = useState<string | null>(null);

  useEffect(() => {
    // Find last checkout time (Async)
    const loadLastCheckout = async () => {
        const records = await StorageService.getAll();
        const myRecords = records
            .filter(r => r.driver_id === user.id && r.checkout_timestamp)
            .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());

        if (myRecords.length > 0) {
            setLastCheckout(new Date(myRecords[0].checkout_timestamp!).toLocaleString('th-TH'));
        }
    };
    loadLastCheckout();
  }, [user.id]);

  const updateForm = (key: keyof TenkoRecord, value: any) => {
    setForm(prev => ({ ...prev, [key]: value }));
  };

  const calculateHours = (start?: string, end?: string) => {
    if (!start || !end) return 0;
    const s = new Date(`2000-01-01T${start}`);
    let e = new Date(`2000-01-01T${end}`);
    if (e < s) e.setDate(e.getDate() + 1);
    return (e.getTime() - s.getTime()) / (1000 * 60 * 60);
  };

  const handleSleepChange = (field: 'sleep' | 'extra_sleep', type: 'start' | 'end', val: string) => {
    if (field === 'sleep') {
        const start = type === 'start' ? val : form.sleep_start;
        const end = type === 'end' ? val : form.sleep_end;
        updateForm(type === 'start' ? 'sleep_start' : 'sleep_end', val);
        if (start && end) updateForm('sleep_hours', calculateHours(start, end));
    } else {
        const start = type === 'start' ? val : form.extra_sleep_start;
        const end = type === 'end' ? val : form.extra_sleep_end;
        updateForm(type === 'start' ? 'extra_sleep_start' : 'extra_sleep_end', val);
        if (start && end) updateForm('extra_sleep_hours', calculateHours(start, end));
    }
  };

  const handleSubmit = async () => {
    if (!form.sleep_hours) {
      alert('กรุณากรอกเวลาการนอนหลับ');
      return;
    }

    setSubmitting(true);
    try {
        await StorageService.create({
            driver_id: user.id,
            driver_name: user.name,
            date: new Date().toISOString().split('T')[0],
            checkin_real_timestamp: new Date().toISOString(),
            checkin_status: 'pending',
            checkout_status: null,
            ...form
        });
        onSubmitSuccess();
    } catch (e) {
        alert('เกิดข้อผิดพลาดในการบันทึกข้อมูล');
        setSubmitting(false);
    }
  };

  const renderSection = (title: string, icon: string, children: React.ReactNode) => (
    <Card className="mb-4">
        <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2 text-lg border-b pb-2">
            <i className={`fas ${icon} text-blue-500`}></i> {title}
        </h3>
        {children}
    </Card>
  );

  const renderQuestion = (
    label: string, 
    field: keyof TenkoRecord, 
    detailField?: keyof TenkoRecord, 
    triggerValue: string = 'มี',
    choices: string[] = ['มี', 'ไม่มี']
  ) => (
    <div className="mb-4 last:mb-0">
      <label className="block text-slate-700 font-medium mb-2">{label}</label>
      <div className="flex gap-2 mb-2 flex-wrap">
        {choices.map(opt => (
          <OptionButton 
            key={opt}
            selected={form[field] === opt} 
            onClick={() => updateForm(field, opt)}
          >
            {opt}
          </OptionButton>
        ))}
      </div>
      {form[field] === triggerValue && detailField && (
        <Input 
          placeholder="ระบุรายละเอียด" 
          value={(form[detailField] as string) || ''}
          onChange={e => updateForm(detailField, e.target.value)}
        />
      )}
    </div>
  );

  return (
    <div className="h-full bg-slate-50 overflow-y-auto">
      <div className="bg-white sticky top-0 z-20 px-4 md:px-6 py-4 shadow-sm flex justify-between items-center">
        <div>
            <h2 className="text-xl font-bold text-slate-800">เท็งโกะก่อนเริ่มงาน</h2>
        </div>
        <Button variant="secondary" onClick={onBack} size="sm">ย้อนกลับ</Button>
      </div>

      <div className="max-w-4xl mx-auto p-4 md:p-6 pb-24">
        <Card className="mb-4 bg-slate-100 border-slate-200">
            <h3 className="font-semibold text-slate-700 mb-1 flex items-center gap-2">
                <i className="fas fa-clock text-slate-500"></i> เวลาเลิกงานล่าสุด
            </h3>
            <p className="text-2xl font-bold text-slate-800">{lastCheckout || 'ไม่มีประวัติ'}</p>
        </Card>

        {renderSection('อาการทั่วไป', 'fa-heartbeat', (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-x-8">
                {renderQuestion('1. มีอาการเหนื่อยล้า?', 'tired', 'tired_detail')}
                <div>
                    {renderQuestion('2. มีอาการเจ็บป่วย?', 'sick', 'sick_detail', 'มี')}
                    {form.sick === 'มี' && (
                        <div className="pl-4 border-l-2 border-slate-200 mt-2 space-y-3">
                            {renderQuestion('ไปพบแพทย์หรือไม่?', 'seen_doctor', 'seen_doctor_detail', 'มี')}
                        </div>
                    )}
                </div>
                {renderQuestion('3. มีอาการง่วงนอน?', 'drowsy', 'drowsy_detail')}
                {renderQuestion('4. มีอาการบาดเจ็บ?', 'injury', 'injury_detail')}
                {renderQuestion('5. ทานยาที่ส่งผลต่อการขับขี่?', 'medication', 'medication_name', 'ทาน', ['ทาน', 'ไม่ทาน'])}
                {renderQuestion('6. สภาพร่างกาย?', 'body_condition', 'body_condition_detail', 'ไม่ปกติ', ['ปกติ', 'ไม่ปกติ'])}
            </div>
        ))}

        {renderSection('การนอนหลับ', 'fa-bed', (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-x-8">
                <div>
                    <h4 className="font-bold text-slate-700 mb-2">7. การนอนปกติ</h4>
                    <div className="grid grid-cols-2 gap-4 mb-4">
                        <Input type="time" label="เริ่มนอน" value={form.sleep_start || ''} onChange={e => handleSleepChange('sleep', 'start', e.target.value)} />
                        <Input type="time" label="ตื่น" value={form.sleep_end || ''} onChange={e => handleSleepChange('sleep', 'end', e.target.value)} />
                    </div>
                    <div className={`p-3 rounded-lg text-center font-bold text-lg mb-4 border-2 ${
                        (form.sleep_hours || 0) < 6 ? 'bg-red-50 border-red-200 text-red-700' : 'bg-green-50 border-green-200 text-green-700'
                    }`}>
                        รวม {form.sleep_hours?.toFixed(1) || 0} ชั่วโมง
                    </div>
                    {renderQuestion('คุณภาพการนอน', 'sleep_quality', 'sleep_quality_detail', 'ไม่สนิท', ['หลับสนิท', 'ไม่สนิท'])}
                </div>

                <div>
                    <hr className="md:hidden my-4"/>
                    <h4 className="font-bold text-slate-700 mb-2">8. การนอนเพิ่ม</h4>
                    {renderQuestion('มีการนอนเพิ่มหรือไม่?', 'extra_sleep', undefined, 'นอนเพิ่ม', ['นอนเพิ่ม', 'ไม่นอนเพิ่ม'])}

                    {form.extra_sleep === 'นอนเพิ่ม' && (
                        <div className="bg-blue-50 p-4 rounded-lg mt-2">
                            <p className="text-sm text-blue-800 mb-2 font-bold"><i className="fas fa-info-circle"></i> การนอนเพิ่มควรมากกว่า 4.5 ชั่วโมง</p>
                            <div className="grid grid-cols-2 gap-4 mb-4">
                                <Input type="time" label="เริ่มนอนเพิ่ม" value={form.extra_sleep_start || ''} onChange={e => handleSleepChange('extra_sleep', 'start', e.target.value)} />
                                <Input type="time" label="ตื่นมาเพิ่ม" value={form.extra_sleep_end || ''} onChange={e => handleSleepChange('extra_sleep', 'end', e.target.value)} />
                            </div>
                            <div className={`p-3 rounded-lg text-center font-bold text-lg mb-4 border-2 ${
                                (form.extra_sleep_hours || 0) < 4.5 ? 'bg-red-50 border-red-200 text-red-700' : 'bg-green-50 border-green-200 text-green-700'
                            }`}>
                                รวม {form.extra_sleep_hours?.toFixed(1) || 0} ชั่วโมง
                            </div>
                            {renderQuestion('คุณภาพการนอนเพิ่ม', 'extra_sleep_quality', 'extra_sleep_quality_detail', 'ไม่สนิท', ['หลับสนิท', 'ไม่สนิท'])}
                        </div>
                    )}
                </div>
            </div>
        ))}

        {renderSection('สภาพแวดล้อมและประสาทสัมผัส', 'fa-eye', (
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-x-8">
                {renderQuestion('เรื่องกังวลใจ?', 'worry_detail', 'worry_text')}
                {renderQuestion('สถานที่พักผ่อน?', 'rest_location', 'rest_location_detail', 'นอกบ้าน', ['บ้าน', 'นอกบ้าน'])}

                {renderQuestion('ปัญหาสายตา?', 'vision_problem', 'vision_detail')}
                {renderQuestion('สวมแว่นตา?', 'glasses', 'glasses_detail')}

                {renderQuestion('ปัญหาการได้ยิน?', 'hearing_problem', 'hearing_detail')}
                {renderQuestion('เครื่องช่วยฟัง?', 'hearing_aid', 'hearing_aid_detail')}
             </div>
        ))}

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t flex justify-center z-20">
            <Button onClick={handleSubmit} isLoading={submitting} className="w-full max-w-md py-3 text-lg">
                <i className="fas fa-paper-plane"></i> ส่งข้อมูลให้ Tenko
            </Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../../services/storage';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Input, OptionButton, Badge } from '../../components/UI';

export const StaffManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<Partial<User>>({ role: 'driver' });
  const [loading, setLoading] = useState(false);

  // Layout State
  const [activeTab, setActiveTab] = useState<'users' | 'cleanup'>('users');

  // --- Cleanup Tool State ---
  const [cleanupSearch, setCleanupSearch] = useState('');
  const [cleanupRecords, setCleanupRecords] = useState<TenkoRecord[]>([]);
  const [searching, setSearching] = useState(false);

  const loadUsers = async () => {
      const data = await StorageService.getUsers();
      setUsers(data);
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleSave = async () => {
    if (!editingUser.id || !editingUser.name) return alert('กรุณากรอกข้อมูลให้ครบ');
    setLoading(true);
    await StorageService.saveUser(editingUser as User);
    await loadUsers();
    setLoading(false);
    setIsModalOpen(false);
    setEditingUser({ role: 'driver' });
  };

  const handleDeleteUser = async (id: string) => {
    if (confirm('ต้องการลบผู้ใช้นี้?')) {
        await StorageService.deleteUser(id);
        loadUsers();
    }
  };

  const openEdit = (user: User) => {
      setEditingUser(user);
      setIsModalOpen(true);
  };

  const openAdd = () => {
      setEditingUser({ role: 'driver', id: '', name: '' });
      setIsModalOpen(true);
  };

  // --- Cleanup Functions ---
  const handleSearchRecords = async () => {
      if (!cleanupSearch) return;
      setSearching(true);
      try {
          const allRecords = await StorageService.getAll();
          const matches = allRecords
            .filter(r => r.driver_id.includes(cleanupSearch) || r.driver_name.includes(cleanupSearch))
            .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

          setCleanupRecords(matches);
      } catch (e) {
          alert('เกิดข้อผิดพลาดในการดึงข้อมูล');
      } finally {
          setSearching(false);
      }
