                                autoFocus
                                value={form.temperature || ''} 
                                onChange={e => updateForm('temperature', parseFloat(e.target.value))}
                                className={isTempBad(form.temperature) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="3. ความดันตัวบน (Sys)" 
                                type="number" 
                                placeholder="120"
                                value={form.blood_pressure_high || ''} 
                                onChange={e => updateForm('blood_pressure_high', parseFloat(e.target.value))} 
                                className={isBPHighBad(form.blood_pressure_high) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                        <div className="space-y-4">
                            <Input 
                                label="2. แอลกอฮอล์ (mg%)" 
                                type="number" 
                                placeholder="0"
                                value={form.alcohol_checkin} 
                                onChange={e => updateForm('alcohol_checkin', parseFloat(e.target.value))}
                                className={isAlcoholBad(form.alcohol_checkin) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="4. ความดันตัวล่าง (Dia)" 
                                type="number" 
                                placeholder="80"
                                value={form.blood_pressure_low || ''} 
                                onChange={e => updateForm('blood_pressure_low', parseFloat(e.target.value))} 
                                className={isBPLowBad(form.blood_pressure_low) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                    </div>
                    {isAlcoholBad(form.alcohol_checkin) && (
                         <Input className="mt-3" placeholder="ระบุเหตุผลค่าแอลกอฮอล์" value={form.alcohol_checkin_reason || ''} onChange={e => updateForm('alcohol_checkin_reason', e.target.value)} />
                    )}
                </div>

                <div className="p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold block mb-2 text-sm text-slate-700">การใช้โทรศัพท์</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.phone_usage_compliant === 'ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ตรงตามที่แจ้ง')}>ตรงตามที่แจ้ง</OptionButton>
                        <OptionButton selected={form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ไม่ตรงตามที่แจ้ง')}>ไม่ตรงตามที่แจ้ง</OptionButton>
                    </div>
                    {form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง' && (
                        <div className="space-y-2 mt-2">
                             <Input placeholder="ระบุสาเหตุ" value={form.phone_usage_reason || ''} onChange={e => updateForm('phone_usage_reason', e.target.value)} />
                        </div>
                    )}
                </div>

                <div className="flex items-center justify-between p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold text-slate-700">อนุญาตให้ปฏิบัติงาน?</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.can_work === 'ได้'} onClick={() => updateForm('can_work', 'ได้')}>ได้</OptionButton>
                        <OptionButton selected={form.can_work === 'ไม่ได้'} onClick={() => updateForm('can_work', 'ไม่ได้')}>ไม่ได้</OptionButton>
                    </div>
                </div>
                {form.can_work === 'ไม่ได้' && (
                        <Input placeholder="ระบุสาเหตุที่ไม่อนุญาต" value={form.cannot_work_reason || ''} onChange={e => updateForm('cannot_work_reason', e.target.value)} />
                )}
            </div>
        )}

        {(type === 'checkout' || type === 'view') && (
            <div className="space-y-4 mt-6 border-t pt-4">
                <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                    <h4 className="font-bold text-purple-800 mb-3">ตรวจสอบหลังเลิกงาน</h4>
                    <div className="grid grid-cols-2 gap-4">
                         <Input 
                            label="แอลกอฮอล์ (ต้อง 0)" 
                            type="number" 
                            autoFocus
                            value={form.alcohol_checkout} 
                            onChange={e => updateForm('alcohol_checkout', parseFloat(e.target.value))}
                            className={isAlcoholBad(form.alcohol_checkout) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                         />
                         {isAlcoholBad(form.alcohol_checkout) && (
                             <Input label="เหตุผล" placeholder="ระบุเหตุผล" value={form.alcohol_checkout_reason || ''} onChange={e => updateForm('alcohol_checkout_reason', e.target.value)} />
                         )}
                    </div>

                     <div className="mt-4">
                        <label className="block text-sm font-semibold mb-2">ข้อละเมิดการขับขี่?</label>
                        <div className="flex gap-2">
                            <OptionButton selected={form.driving_violation === 'ไม่มี'} onClick={() => updateForm('driving_violation', 'ไม่มี')}>ไม่มี</OptionButton>
                            <OptionButton selected={form.driving_violation === 'มี'} onClick={() => updateForm('driving_violation', 'มี')}>มี</OptionButton>
                        </div>
                        {form.driving_violation === 'มี' && <Input className="mt-2" placeholder="ระบุรายละเอียด" value={form.violation_detail || ''} onChange={e => updateForm('violation_detail', e.target.value)} />}
                    </div>
                </div>
            </div>
        )}

        <div className="bg-yellow-50 p-3 rounded border border-yellow-200 mt-4">
            <label className="block text-sm font-bold mb-1 text-yellow-800">
                <i className="fas fa-clock"></i> เวลาที่บันทึก
            </label>
            <input 
                type="datetime-local" 
                className="w-full p-2 border rounded bg-white text-sm"
                value={formatDateForInput(type === 'checkout' ? form.checkout_timestamp : form.checkin_timestamp)}
                onChange={e => handleDateChange(e.target.value, type === 'checkout' ? 'checkout_timestamp' : 'checkin_timestamp')}
            />
        </div>

        <div className="mt-6 flex flex-col gap-3">
            <Button onClick={handleApprove} isLoading={submitting} className="w-full bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 py-3 text-lg">
                <i className="fas fa-save"></i> บันทึกข้อมูล (Save)
            </Button>

            <Button onClick={handleDelete} isLoading={submitting} variant="danger" className="w-full bg-white text-red-600 border-2 border-red-200 hover:bg-red-50 hover:border-red-500">
                <i className="fas fa-trash-alt"></i> ลบข้อมูล (เพื่อให้ส่งใหม่)
            </Button>
        </div>
    </Card>
  );

  return (
    <div className="space-y-4 max-w-6xl mx-auto pb-10 flex flex-col">
      <div className="flex justify-between items-center shrink-0">
        <h2 className="text-2xl font-bold text-slate-800">
          {type === 'checkin' ? 'คิวตรวจสอบ (ก่อนงาน)' : type === 'checkout' ? 'คิวตรวจสอบ (หลังงาน)' : 'แก้ไขข้อมูล'}
        </h2>
        <Button variant="secondary" onClick={onBack}>ย้อนกลับ</Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {renderDriverDataSection()}
        {renderTenkoInputSection()}
      </div>
    </div>
  );
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
  onDelete?: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord, onDelete }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  const activeDrivers = records.filter(r => r.checkin_status === 'approved' && !r.checkout_status);
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  // Helper function to get Monday of a week
  const getMonday = (dateStr: string) => {
    const d = new Date(dateStr);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff)).toISOString().split('T')[0];
  };

  // Shared Logic for calculating Fix Start Status
  const calculateFixStartForRecord = (record: TenkoRecord) => {
    // Only care about approved records for the same driver
    const driverRecords = records
        .filter(r => r.driver_id === record.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
        .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    if (driverRecords.length === 0) return { status: 'New', time: '--:--' };

    // Group records of the same week as the target record
    const targetMonday = getMonday(record.checkin_timestamp || record.checkin_real_timestamp || record.date);
    const currentWeekRecords = driverRecords.filter(r => getMonday(r.checkin_timestamp!) === targetMonday);

    // If this is the very first record of the week (none approved yet), or it's not approved yet, 
    // we need to find the "Reference" (Monday or first work day of that week)
    const mondayRecord = currentWeekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
    const referenceRecord = mondayRecord || currentWeekRecords[0];

    if (!referenceRecord) return { status: 'New', time: '--:--' };

    const refDate = new Date(referenceRecord.checkin_timestamp!);
    const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    // Check target record time vs reference
    const checkTimeStr = record.checkin_timestamp || record.checkin_real_timestamp;
    if (!checkTimeStr) return { status: 'OK', time: displayTime };

    const checkDate = new Date(checkTimeStr);
    const checkMinutes = checkDate.getHours() * 60 + checkDate.getMinutes();

    const isNG = Math.abs(checkMinutes - refTotalMinutes) > 120;
    return { status: isNG ? 'NG' : 'OK', time: displayTime };
  };

  const exportExcel = () => {
    const data = records.map(r => {
        const formatDetail = (status?: string, detail?: string) => {
            if (!status) return '-';
            return detail ? `${status} (${detail})` : status;
        };

        const sleepInfo = r.sleep_hours 
            ? `${r.sleep_hours} ชม. (${r.sleep_start || '-'} - ${r.sleep_end || '-'}) ${r.sleep_quality || ''}`
            : '-';

        const extraSleepInfo = r.extra_sleep === 'นอนเพิ่ม'
            ? `${r.extra_sleep_hours} ชม. (${r.extra_sleep_start || '-'} - ${r.extra_sleep_end || '-'}) ${r.extra_sleep_quality || ''}`
            : 'ไม่นอนเพิ่ม';

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,
            "ความเหนื่อยล้า": formatDetail(r.tired, r.tired_detail),
            "การเจ็บป่วย": r.sick === 'มี' ? `มี (${r.sick_detail || '-'}) หาหมอ: ${r.seen_doctor || '-'}` : 'ไม่มี',
            "ความง่วง": formatDetail(r.drowsy, r.drowsy_detail),
            "การบาดเจ็บ": formatDetail(r.injury, r.injury_detail),
            "การใช้ยา": r.medication === 'ทาน' ? `ทาน (${r.medication_name || '-'})` : 'ไม่ทาน',
            "สภาพร่างกาย(ก่อน)": formatDetail(r.body_condition, r.body_condition_detail),
            "การนอนหลับ": sleepInfo,
            "การนอนเพิ่ม": extraSleepInfo,
            "เรื่องกังวลใจ": formatDetail(r.worry_detail, r.worry_text),
            "สถานที่พักผ่อน": formatDetail(r.rest_location, r.rest_location_detail),
            "ปัญหาสายตา": `${r.vision_problem || '-'} (แว่น: ${r.glasses || '-'})`,
            "การได้ยิน": `${r.hearing_problem || '-'} (เครื่องช่วย: ${r.hearing_aid || '-'})`,
            "เวลาเข้างาน (อนุมัติ)": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เข้างาน)": r.checkin_tenko_name || '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "เหตุผลแอลกอฮอล์(เข้า)": r.alcohol_checkin_reason || '-',
            "การใช้โทรศัพท์": formatDetail(r.phone_usage_compliant, r.phone_usage_reason),
            "ผลประเมิน": formatDetail(r.can_work, r.cannot_work_reason),
            "การส่งมอบรถ": formatDetail(r.vehicle_handover, r.vehicle_detail),
            "สภาพร่างกาย(หลัง)": formatDetail(r.body_condition_checkout, r.body_detail_checkout),
            "จุดเสี่ยง": formatDetail(r.route_risk, r.route_detail),
            "เวลาเลิกงาน (อนุมัติ)": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เลิกงาน)": r.checkout_tenko_name || '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "เหตุผลแอลกอฮอล์(ออก)": r.alcohol_checkout_reason || '-',
            "ข้อละเมิดการขับขี่": formatDetail(r.driving_violation, r.violation_detail)
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);
    const wscols = [{wch: 12}, {wch: 20}, {wch: 10}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 25}, {wch: 25}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 20}, {wch: 10}, {wch: 10}, {wch: 10}, {wch: 15}, {wch: 20}, {wch: 20}, {wch: 20}, {wch: 15}, {wch: 20}, {wch: 10}, {wch: 15}, {wch: 20}];
    ws['!cols'] = wscols;
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `Tenko_Full_Report_${today}.xlsx`);
  };

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });
    } catch (e) {
        return '-';
    }
  };

  const getSafeDateTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleString('th-TH', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
    } catch (e) {
        return '-';
    }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    const { status, time } = calculateFixStartForRecord(record);
    if (status === 'NG') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-600 border border-red-200 whitespace-nowrap">Fix Start: NG (Ref: {time})</span>;
    if (status === 'OK') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-600 border border-emerald-200 whitespace-nowrap">Fix Start: OK (Ref: {time})</span>;
    return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 border border-slate-200 whitespace-nowrap">First Workday</span>;
  };

  const calculateFixStartNGMonth = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    let ngCount = 0;

    // Filter approved records for current month
    const monthApproved = records.filter(r => {
         if (!r.checkin_timestamp || r.checkin_status !== 'approved') return false;
         const d = new Date(r.checkin_timestamp);
         return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    // Check each record against its week's reference
    monthApproved.forEach(r => {
        const { status } = calculateFixStartForRecord(r);
        if (status === 'NG') ngCount++;
    });

    return ngCount;
  };

  const fixStartNGCount = calculateFixStartNGMonth();

  const renderStats = () => (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1 text-sm">รอตรวจก่อนงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-blue-500 to-cyan-600 text-white border-none">
            <h3 className="text-blue-100 mb-1 text-sm">กำลังปฏิบัติงาน</h3>
            <div className="text-3xl font-bold">{activeDrivers.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1 text-sm">รอตรวจหลังงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1 text-sm">เสร็จสิ้นแล้ว</h3>
            <div className="text-3xl font-bold">{completed.length}</div>
        </Card>
        <Card className={`${fixStartNGCount > 0 ? 'bg-red-600' : 'bg-blue-900'} text-white border-none`}>
            <h3 className="text-white/80 mb-1 text-sm">Fix Start (เดือนนี้)</h3>
            <div className="text-3xl font-bold flex items-baseline gap-2">
                {fixStartNGCount} <span className="text-sm font-normal">NG</span>
            </div>
            {fixStartNGCount === 0 && <div className="text-[10px] text-green-300 mt-1"><i className="fas fa-check-circle"></i> ปกติทุกท่าน</div>}
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
            <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group relative" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors flex items-center flex-wrap gap-1">
                                        {record.driver_name}
                                        {type === 'checkin' && getFixStartBadge(record)}
                                    </h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                <div className="flex items-center gap-2">
                                    {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                    {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                                    {onDelete && (type !== 'history') && (
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDelete(record.__backendId); }}
                                            className="w-8 h-8 rounded-full bg-red-50 text-red-500 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
                                            title="ลบรายการนี้"
                                        >
                                            <i className="fas fa-trash-alt text-xs"></i>
                                        </button>
                                    )}
                                </div>
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
            <Card className="flex flex-col h-full bg-white border-t-4 border-amber-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-700 text-lg">
                        <i className="fas fa-clock"></i> รอตรวจก่อนงาน
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors group relative">
                            <div>
                                <p className="font-semibold text-slate-700 flex items-center gap-1">
                                    {r.driver_name}
                                    {getFixStartBadge(r)}
                                </p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right flex items-center gap-3">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                                {onDelete && (
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); onDelete(r.__backendId); }}
                                        className="w-6 h-6 rounded-full bg-slate-100 text-slate-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
                                    >
                                        <i className="fas fa-trash-alt text-[10px]"></i>
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full bg-white border-t-4 border-blue-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-blue-700 text-lg">
                        <i className="fas fa-truck-moving"></i> กำลังปฏิบัติงาน (ยังไม่ส่งเลิก)
                    </h3>
                    <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full">{activeDrivers.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {activeDrivers.map(r => (
                        <div key={r.__backendId} className="flex justify-between p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-500">เริ่มงานเมื่อ: {getSafeDateTime(r.checkin_timestamp)}</p>
                            </div>
                            <div className="text-right">
                                <Badge type="approved">On Duty</Badge>
                            </div>
                        </div>
                    ))}
                    {activeDrivers.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-road text-4xl mb-2"></i>
                            <p>ไม่มีรถวิ่งงาน</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full bg-white border-t-4 border-purple-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-700 text-lg">
                        <i className="fas fa-flag-checkered"></i> รอตรวจหลังงาน
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                    {pendingCheckout.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors group relative">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right flex items-center gap-3">
                                <p className="text-sm font-bold text-slate-600">{getSafeDateTime(r.checkout_timestamp || r.checkout_real_timestamp)}</p>
                                {onDelete && (
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); onDelete(r.__backendId); }}
                                        className="w-6 h-6 rounded-full bg-slate-100 text-slate-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
                                    >
                                        <i className="fas fa-trash-alt text-[10px]"></i>
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}
                     {pendingCheckout.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>
        </div>
      </div>
    );
  }

  if (view === 'queue-checkin') return renderList('คิวตรวจสอบ (ก่อนเริ่มงาน)', pendingCheckin, 'checkin');
  if (view === 'queue-checkout') return renderList('คิวตรวจสอบ (หลังเลิกงาน)', pendingCheckout, 'checkout');
  if (view === 'completed') return renderList('ประวัติรายการที่เสร็จสิ้น', completed, 'history');

  return null;
};

import React from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
  onDelete?: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord, onDelete }) => {
  const pendingCheckin = records.filter(r => r.checkin_status === 'pending');
  const activeDrivers = records.filter(r => r.checkin_status === 'approved' && !r.checkout_status);
  const pendingCheckout = records.filter(r => r.checkout_status === 'pending');
  const completed = records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  const today = new Date().toISOString().split('T')[0];

  // Helper function to get Monday of a week
  const getMonday = (dateStr: string) => {
    const d = new Date(dateStr);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(d.setDate(diff));
    return monday.toISOString().split('T')[0];
  };

  // Improved Logic for calculating Fix Start Status consistent with DriverApp
  const calculateFixStartForRecord = (targetRecord: TenkoRecord) => {
    // 1. Get all approved records for this specific driver
    const driverApprovedRecords = records
        .filter(r => r.driver_id === targetRecord.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
        .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    // Find Monday of the week the target record belongs to
    const targetDateStr = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp || targetRecord.date;
    const targetMonday = getMonday(targetDateStr);

    // 2. Filter records of that specific week
    const weekRecords = driverApprovedRecords.filter(r => getMonday(r.checkin_timestamp!) === targetMonday);

    // 3. Find Reference Record (Monday record or the first work day of that week)
    const mondayRecord = weekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
    const referenceRecord = mondayRecord || weekRecords[0];

    // If no approved reference exists yet for this week, we check if the target is the first record
    if (!referenceRecord) {
        return { status: 'New', time: '--:--' };
    }

    const refDate = new Date(referenceRecord.checkin_timestamp!);
    const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    // 4. Compare target record time with reference
    const checkTimeStr = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp;
    if (!checkTimeStr) return { status: 'OK', time: displayTime };

    const checkDate = new Date(checkTimeStr);
    const checkMinutes = checkDate.getHours() * 60 + checkDate.getMinutes();

    // Difference more than 120 minutes is NG
    const isNG = Math.abs(checkMinutes - refTotalMinutes) > 120;
    return { status: isNG ? 'NG' : 'OK', time: displayTime };
  };

  const exportExcel = () => {
    const data = records.map(r => {
        const formatDetail = (status?: string, detail?: string) => {
            if (!status) return '-';
            return detail ? `${status} (${detail})` : status;
        };

        const sleepInfo = r.sleep_hours 
            ? `${r.sleep_hours} ชม. (${r.sleep_start || '-'} - ${r.sleep_end || '-'}) ${r.sleep_quality || ''}`
            : '-';

        const extraSleepInfo = r.extra_sleep === 'นอนเพิ่ม'
            ? `${r.extra_sleep_hours} ชม. (${r.extra_sleep_start || '-'} - ${r.extra_sleep_end || '-'}) ${r.extra_sleep_quality || ''}`
            : 'ไม่นอนเพิ่ม';

        const { status: fsStatus, time: fsTime } = calculateFixStartForRecord(r);

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,
            "Fix Start Status": `${fsStatus} (Ref: ${fsTime})`,
            "ความเหนื่อยล้า": formatDetail(r.tired, r.tired_detail),
            "การเจ็บป่วย": r.sick === 'มี' ? `มี (${r.sick_detail || '-'}) หาหมอ: ${r.seen_doctor || '-'}` : 'ไม่มี',
            "ความง่วง": formatDetail(r.drowsy, r.drowsy_detail),
            "การบาดเจ็บ": formatDetail(r.injury, r.injury_detail),
            "การใช้ยา": r.medication === 'ทาน' ? `ทาน (${r.medication_name || '-'})` : 'ไม่ทาน',
            "สภาพร่างกาย(ก่อน)": formatDetail(r.body_condition, r.body_condition_detail),
            "การนอนหลับ": sleepInfo,
            "การนอนเพิ่ม": extraSleepInfo,
            "เรื่องกังวลใจ": formatDetail(r.worry_detail, r.worry_text),
            "สถานที่พักผ่อน": formatDetail(r.rest_location, r.rest_location_detail),
            "ปัญหาสายตา": `${r.vision_problem || '-'} (แว่น: ${r.glasses || '-'})`,
            "การได้ยิน": `${r.hearing_problem || '-'} (เครื่องช่วย: ${r.hearing_aid || '-'})`,
            "เวลาเข้างาน (อนุมัติ)": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เข้างาน)": r.checkin_tenko_name || '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "เหตุผลแอลกอฮอล์(เข้า)": r.alcohol_checkin_reason || '-',
            "การใช้โทรศัพท์": formatDetail(r.phone_usage_compliant, r.phone_usage_reason),
            "ผลประเมิน": formatDetail(r.can_work, r.cannot_work_reason),
            "การส่งมอบรถ": formatDetail(r.vehicle_handover, r.vehicle_detail),
            "สภาพร่างกาย(หลัง)": formatDetail(r.body_condition_checkout, r.body_detail_checkout),
            "จุดเสี่ยง": formatDetail(r.route_risk, r.route_detail),
            "เวลาเลิกงาน (อนุมัติ)": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เลิกงาน)": r.checkout_tenko_name || '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "เหตุผลแอลกอฮอล์(ออก)": r.alcohol_checkout_reason || '-',
            "ข้อละเมิดการขับขี่": formatDetail(r.driving_violation, r.violation_detail)
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);
    const wscols = [{wch: 12}, {wch: 20}, {wch: 10}, {wch: 25}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 25}, {wch: 25}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 15}, {wch: 20}, {wch: 10}, {wch: 10}, {wch: 10}, {wch: 15}, {wch: 20}, {wch: 20}, {wch: 20}, {wch: 15}, {wch: 20}, {wch: 10}, {wch: 15}, {wch: 20}];
    ws['!cols'] = wscols;
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Tenko Data");
    XLSX.writeFile(wb, `Tenko_Full_Report_${today}.xlsx`);
  };

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });
    } catch (e) {
        return '-';
    }
  };

  const getSafeDateTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
        const d = new Date(dateStr);
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleString('th-TH', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
    } catch (e) {
        return '-';
    }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    const { status, time } = calculateFixStartForRecord(record);
    if (status === 'NG') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-red-100 text-red-600 border border-red-200 whitespace-nowrap"><i className="fas fa-exclamation-triangle"></i> NG (Ref: {time})</span>;
    if (status === 'OK') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-600 border border-emerald-200 whitespace-nowrap">OK (Ref: {time})</span>;
    return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 border border-slate-200 whitespace-nowrap">New Week</span>;
  };

  const calculateFixStartNGMonth = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    let ngCount = 0;

    // Filter approved records for current month
    const monthApproved = records.filter(r => {
         if (!r.checkin_timestamp || r.checkin_status !== 'approved') return false;
         const d = new Date(r.checkin_timestamp);
         return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    // Check each record against its week's reference
    monthApproved.forEach(r => {
        const { status } = calculateFixStartForRecord(r);
        if (status === 'NG') ngCount++;
    });

    return ngCount;
  };

  const fixStartNGCount = calculateFixStartNGMonth();

  const renderStats = () => (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 mb-8">
        <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none">
            <h3 className="text-amber-100 mb-1 text-sm">รอตรวจก่อนงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckin.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-blue-500 to-cyan-600 text-white border-none">
            <h3 className="text-blue-100 mb-1 text-sm">กำลังปฏิบัติงาน</h3>
            <div className="text-3xl font-bold">{activeDrivers.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none">
            <h3 className="text-purple-100 mb-1 text-sm">รอตรวจหลังงาน</h3>
            <div className="text-3xl font-bold">{pendingCheckout.length}</div>
        </Card>
        <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none">
            <h3 className="text-emerald-100 mb-1 text-sm">เสร็จสิ้นแล้ว</h3>
            <div className="text-3xl font-bold">{completed.length}</div>
        </Card>
        <Card className={`${fixStartNGCount > 0 ? 'bg-red-600' : 'bg-blue-900'} text-white border-none`}>
            <h3 className="text-white/80 mb-1 text-sm">Fix Start (เดือนนี้)</h3>
            <div className="text-3xl font-bold flex items-baseline gap-2">
                {fixStartNGCount} <span className="text-sm font-normal">NG</span>
            </div>
            {fixStartNGCount === 0 && <div className="text-[10px] text-green-300 mt-1"><i className="fas fa-check-circle"></i> ปกติทุกท่าน</div>}
        </Card>
        <Card className="bg-white border-l-4 border-blue-500">
            <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
            <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
        </Card>
    </div>
  );

  const renderList = (title: string, items: TenkoRecord[], type: 'checkin' | 'checkout' | 'history') => (
    <div className="space-y-4">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
            {type === 'history' && (
                <Button onClick={exportExcel} variant="secondary" size="sm">
                    <i className="fas fa-file-excel"></i> Export Excel
                </Button>
            )}
        </div>

        {items.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
                <i className="fas fa-inbox text-4xl text-slate-300 mb-3"></i>
                <p className="text-slate-500">ไม่มีรายการ</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {items.map(record => {
                    const timestamp = type === 'checkout' 
                        ? (record.checkout_timestamp || record.checkout_real_timestamp) 
                        : (record.checkin_timestamp || record.checkin_real_timestamp);

                    return (
                        <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer group relative" onClick={() => onSelectRecord(record.__backendId)}>
                            <div className="flex justify-between items-start mb-3">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-blue-600 transition-colors flex items-center flex-wrap gap-1">
                                        {record.driver_name}
                                        {type === 'checkin' && getFixStartBadge(record)}
                                    </h4>
                                    <p className="text-xs text-slate-500">ID: {record.driver_id}</p>
                                </div>
                                <div className="flex items-center gap-2">
                                    {type !== 'history' && <Badge type="pending">รออนุมัติ</Badge>}
                                    {type === 'history' && <Badge type="approved">เสร็จสิ้น</Badge>}
                                    {onDelete && (type !== 'history') && (
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); onDelete(record.__backendId); }}
                                            className="w-8 h-8 rounded-full bg-red-50 text-red-500 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
                                            title="ลบรายการนี้"
                                        >
                                            <i className="fas fa-trash-alt text-xs"></i>
                                        </button>
                                    )}
                                </div>
                            </div>
                            <div className="text-sm text-slate-600 space-y-1">
                                <p><i className="fas fa-calendar-day w-5 text-center text-slate-400"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                                <p><i className="fas fa-clock w-5 text-center text-slate-400"></i> {getSafeTime(timestamp)}</p>
                            </div>
                        </Card>
                    );
                })}
            </div>
        )}
    </div>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10">
        <h1 className="text-2xl font-bold mb-6">ภาพรวมระบบ Tenko</h1>
        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
            <Card className="flex flex-col h-full bg-white border-t-4 border-amber-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-amber-700 text-lg">
                        <i className="fas fa-clock"></i> รอตรวจก่อนงาน
                    </h3>
                    <span className="bg-amber-100 text-amber-800 text-xs px-2 py-1 rounded-full">{pendingCheckin.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2 custom-scrollbar">
                    {pendingCheckin.map(r => (
                        <div key={r.__backendId} onClick={() => onSelectRecord(r.__backendId)} className="flex justify-between p-3 hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-colors group relative">
                            <div>
                                <p className="font-semibold text-slate-700 flex items-center gap-1">
                                    {r.driver_name}
                                    {getFixStartBadge(r)}
                                </p>
                                <p className="text-xs text-slate-400">ID: {r.driver_id}</p>
                            </div>
                            <div className="text-right flex items-center gap-3">
                                <p className="text-sm font-bold text-slate-600">{getSafeTime(r.checkin_timestamp || r.checkin_real_timestamp)}</p>
                                {onDelete && (
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); onDelete(r.__backendId); }}
                                        className="w-6 h-6 rounded-full bg-slate-100 text-slate-400 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
                                    >
                                        <i className="fas fa-trash-alt text-[10px]"></i>
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}
                    {pendingCheckin.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-check-circle text-4xl mb-2"></i>
                            <p>ไม่มีรายการ</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full bg-white border-t-4 border-blue-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-blue-700 text-lg">
                        <i className="fas fa-truck-moving"></i> กำลังปฏิบัติงาน (ยังไม่ส่งเลิก)
                    </h3>
                    <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full">{activeDrivers.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2 custom-scrollbar">
                    {activeDrivers.map(r => (
                        <div key={r.__backendId} className="flex justify-between p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <div>
                                <p className="font-semibold text-slate-700">{r.driver_name}</p>
                                <p className="text-xs text-slate-500">เริ่มงานเมื่อ: {getSafeDateTime(r.checkin_timestamp)}</p>
                            </div>
                            <div className="text-right">
                                <Badge type="approved">On Duty</Badge>
                            </div>
                        </div>
                    ))}
                    {activeDrivers.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <i className="fas fa-road text-4xl mb-2"></i>
                            <p>ไม่มีรถวิ่งงาน</p>
                        </div>
                    )}
                </div>
            </Card>

            <Card className="flex flex-col h-full bg-white border-t-4 border-purple-500">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-purple-700 text-lg">
                        <i className="fas fa-flag-checkered"></i> รอตรวจหลังงาน
                    </h3>
                    <span className="bg-purple-100 text-purple-800 text-xs px-2 py-1 rounded-full">{pendingCheckout.length}</span>
                </div>
                <div className="flex-1 overflow-y-auto pr-2 space-y-2 custom-scrollbar">
