        </div>
        <nav className="flex-1 py-4 space-y-1 text-sm overflow-y-auto">
            <NavItem view="dashboard" icon="fa-home" label="หน้าหลัก" />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="คิว (ก่อนเริ่มงาน)" />
