import { TenkoRecord, User } from '../types';
import { DRIVERS, TENKO_USERS, DEFAULT_SCRIPT_URL } from '../constants';

const OFFLINE_KEY = 'tenko_offline_records';
const SCRIPT_URL_KEY = 'TENKO_SCRIPT_URL';

let lastConnectionStatus: 'online' | 'offline' | 'error' = 'online';

const getScriptUrl = () => {
    if (DEFAULT_SCRIPT_URL) return DEFAULT_SCRIPT_URL;
    return localStorage.getItem(SCRIPT_URL_KEY) || '';
};

const getOfflineData = (): TenkoRecord[] => {
    try {
        return JSON.parse(localStorage.getItem(OFFLINE_KEY) || '[]');
    } catch {
        return [];
    }
};

const saveOfflineData = (records: TenkoRecord[]) => {
    localStorage.setItem(OFFLINE_KEY, JSON.stringify(records));
};

const callScript = async (action: string, payload: any = {}) => {
    const url = getScriptUrl();
    if (!url) throw new Error("No Script URL configured");

    try {
        const response = await fetch(url, {
            method: 'POST',
            body: JSON.stringify({ action, ...payload })
        });

        const json = await response.json();
        lastConnectionStatus = 'online';
        return json;
    } catch (e) {
        lastConnectionStatus = 'offline';
        throw e;
    }
};

export const StorageService = {
  getConnectionStatus: () => lastConnectionStatus,

  hasScriptUrl: () => !!getScriptUrl(),

  clearLocalCache: () => {
      localStorage.removeItem(OFFLINE_KEY);
  },

  getAll: async (): Promise<TenkoRecord[]> => {
    let dbRecords: TenkoRecord[] = [];

    if (getScriptUrl()) {
        try {
            dbRecords = await callScript('getAll');
            if (!Array.isArray(dbRecords)) dbRecords = [];
        } catch (e) {
            console.warn("Failed to fetch from script", e);
        }
    }

    const offlineRecords = getOfflineData();
    const recordMap = new Map<string, TenkoRecord>();

    // Server data is the source of truth
    dbRecords.forEach(r => recordMap.set(r.__backendId, r));

    // Local data might have newer updates or pending creates
    offlineRecords.forEach(r => recordMap.set(r.__backendId, r));

    // Deduplicate logical duplicates
    const uniqueMap = new Map<string, TenkoRecord>();
    Array.from(recordMap.values()).forEach(r => {
        const key = `${r.driver_id}_${r.date}`;
        if (!uniqueMap.has(key)) {
            uniqueMap.set(key, r);
        } else {
            const existing = uniqueMap.get(key)!;
            let scoreExisting = (existing.checkin_status === 'approved' ? 2 : 0) + (existing.checkout_status === 'approved' ? 2 : 0);
            let scoreNew = (r.checkin_status === 'approved' ? 2 : 0) + (r.checkout_status === 'approved' ? 2 : 0);

            if (scoreNew > scoreExisting) {
                uniqueMap.set(key, r);
            } else if (scoreNew === scoreExisting) {
                const timeExisting = new Date(existing.checkin_real_timestamp || existing.date).getTime();
                const timeNew = new Date(r.checkin_real_timestamp || r.date).getTime();
                if (timeNew > timeExisting) uniqueMap.set(key, r);
            }
        }
    });

    return Array.from(uniqueMap.values()).sort((a, b) => 
        new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    const offline = getOfflineData();
    const today = record.date || new Date().toISOString().split('T')[0];
    const id = crypto.randomUUID();
    const fullRecord = { 
        ...record, 
        __backendId: id,
        driver_id: record.driver_id || '',
        date: today
    } as TenkoRecord;

    offline.push(fullRecord);
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('create', { data: fullRecord }).catch(e => console.warn(e));
    }

    return { isOk: true, data: fullRecord };
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    const offline = getOfflineData();
    const index = offline.findIndex(r => r.__backendId === record.__backendId);
    if (index >= 0) {
        offline[index] = record;
    } else {
        offline.push(record);
    }
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('update', { data: record }).catch(e => console.warn(e));
    }

    return { isOk: true };
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    // 1. ลบจาก Local Storage ทันทีเพื่อไม่ให้กลับมาตอน Merge
    const offline = getOfflineData().filter(r => r.__backendId !== recordId);
    saveOfflineData(offline);

    // 2. ส่งคำสั่งลบไปยัง Server (Google Sheet)
    if (getScriptUrl()) {
        try {
            await callScript('delete', { id: recordId });
            console.log("Deleted from server:", recordId);
        } catch (e) {
            console.error("Server delete failed, but local is cleared:", e);
        }
    }

    return { isOk: true };
  },

  syncPendingData: async (): Promise<number> => {
      if (!getScriptUrl()) return 0;
      const offlineRecords = getOfflineData();
      if (offlineRecords.length === 0) return 0;

      let syncedCount = 0;
      for (const record of offlineRecords) {
          try {
             await callScript('update', { data: record });
             syncedCount++;
          } catch (e) {
              console.error("Sync failed for", record.__backendId, e);
          }
      }
      return syncedCount;
  },

  getPendingCount: (): number => lastConnectionStatus === 'offline' ? 1 : 0,

  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];
    if (!getScriptUrl()) return defaults;
    try {
        const users = await callScript('getUsers');
        return Array.isArray(users) && users.length > 0 ? users : defaults;
    } catch (e) {
        return defaults;
    }
  },

  saveUser: async (user: User) => {
      if (getScriptUrl()) await callScript('saveUser', { data: user }).catch(e => console.error(e));
  },

  deleteUser: async (userId: string) => {
      if (getScriptUrl()) await callScript('deleteUser', { id: userId }).catch(e => console.error(e));
  },

  initializeDefaultUsers: async () => {
      const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
      ];
      let successCount = 0;
      for (const user of defaults) {
          try {
              await callScript('saveUser', { data: user });
              successCount++;
          } catch (e) {}
      }
      return successCount;
  }
};

import { TenkoRecord, User } from '../types';
import { DRIVERS, TENKO_USERS, DEFAULT_SCRIPT_URL } from '../constants';

const OFFLINE_KEY = 'tenko_offline_records';
const SCRIPT_URL_KEY = 'TENKO_SCRIPT_URL';

let lastConnectionStatus: 'online' | 'offline' | 'error' = 'online';

const getScriptUrl = () => {
    if (DEFAULT_SCRIPT_URL) return DEFAULT_SCRIPT_URL;
    return localStorage.getItem(SCRIPT_URL_KEY) || '';
};

const getOfflineData = (): TenkoRecord[] => {
    try {
        const data = localStorage.getItem(OFFLINE_KEY);
        return data ? JSON.parse(data) : [];
    } catch {
        return [];
    }
};

const saveOfflineData = (records: TenkoRecord[]) => {
    localStorage.setItem(OFFLINE_KEY, JSON.stringify(records));
};

const callScript = async (action: string, payload: any = {}) => {
    const url = getScriptUrl();
    if (!url) throw new Error("No Script URL configured");

    try {
        const response = await fetch(url, {
            method: 'POST',
            body: JSON.stringify({ action, ...payload })
        });

        const text = await response.text();
        let json;
        try {
            json = JSON.parse(text);
        } catch (e) {
            console.error("Failed to parse server response:", text);
            throw new Error("Invalid server response format");
        }

        lastConnectionStatus = 'online';
        return json;
    } catch (e) {
        lastConnectionStatus = 'offline';
        throw e;
    }
};

export const StorageService = {
  getConnectionStatus: () => lastConnectionStatus,

  hasScriptUrl: () => !!getScriptUrl(),

  clearLocalCache: () => {
      localStorage.removeItem(OFFLINE_KEY);
  },

  getAll: async (): Promise<TenkoRecord[]> => {
    let dbRecords: TenkoRecord[] = [];
    const localRecords = getOfflineData();

    if (getScriptUrl()) {
        try {
            const serverData = await callScript('getAll');
            if (Array.isArray(serverData)) {
                dbRecords = serverData;

                // --- RECONCILIATION LOGIC ---
                // If we successfully reached the server, we should clean up the local cache.
                // A local record should be removed if it's NOT on the server AND it's NOT a "newly created" pending record.
                const serverIds = new Set(dbRecords.map(r => r.__backendId));

                const reconciledLocal = localRecords.filter(lr => {
                    const existsOnServer = serverIds.has(lr.__backendId);
                    // A record is "Brand New" if it's pending and hasn't been approved by a Tenko yet.
                    // Once a record has 'checkin_tenko_id', it must exist on the server.
                    const isNewPending = lr.checkin_status === 'pending' && !lr.checkin_tenko_id;

                    return existsOnServer || isNewPending;
                });

                saveOfflineData(reconciledLocal);
            }
        } catch (e) {
            console.warn("Failed to fetch from script, using local only", e);
        }
    }

    const currentLocal = getOfflineData();
    const recordMap = new Map<string, TenkoRecord>();

    // Server records are base
    dbRecords.forEach(r => recordMap.set(r.__backendId, r));

    // Local records override or add
    currentLocal.forEach(r => recordMap.set(r.__backendId, r));

    // Deduplicate logical duplicates (Driver + Date)
    // We keep the one with most progress or the latest timestamp
    const uniqueMap = new Map<string, TenkoRecord>();
    Array.from(recordMap.values()).forEach(r => {
        const key = `${String(r.driver_id).trim()}_${r.date}`;
        if (!uniqueMap.has(key)) {
            uniqueMap.set(key, r);
        } else {
            const existing = uniqueMap.get(key)!;
            let scoreExisting = (existing.checkin_status === 'approved' ? 2 : 0) + (existing.checkout_status === 'approved' ? 2 : 0);
            let scoreNew = (r.checkin_status === 'approved' ? 2 : 0) + (r.checkout_status === 'approved' ? 2 : 0);

            if (scoreNew > scoreExisting) {
                uniqueMap.set(key, r);
            } else if (scoreNew === scoreExisting) {
                const timeExisting = new Date(existing.checkin_real_timestamp || existing.date).getTime();
                const timeNew = new Date(r.checkin_real_timestamp || r.date).getTime();
                if (timeNew > timeExisting) uniqueMap.set(key, r);
            }
        }
    });

    return Array.from(uniqueMap.values()).sort((a, b) => 
        new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    const offline = getOfflineData();
    const today = record.date || new Date().toISOString().split('T')[0];
    const id = crypto.randomUUID();
    const fullRecord = { 
        ...record, 
        __backendId: id,
        driver_id: String(record.driver_id || '').trim(),
        date: today
    } as TenkoRecord;

    offline.push(fullRecord);
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('create', { data: fullRecord }).catch(e => console.warn("Background create sync failed", e));
    }

    return { isOk: true, data: fullRecord };
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    const offline = getOfflineData();
    const index = offline.findIndex(r => r.__backendId === record.__backendId);
    if (index >= 0) {
        offline[index] = record;
    } else {
        offline.push(record);
    }
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('update', { data: record }).catch(e => console.warn("Background update sync failed", e));
    }

    return { isOk: true };
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    // 1. Immediately remove from local storage
    const offline = getOfflineData().filter(r => r.__backendId !== recordId);
    saveOfflineData(offline);

    // 2. Send delete command to server
    if (getScriptUrl()) {
        try {
            await callScript('delete', { id: recordId });
        } catch (e) {
            console.error("Server-side delete failed, but local is cleared", e);
        }
    }

    return { isOk: true };
  },

  syncPendingData: async (): Promise<number> => {
      if (!getScriptUrl()) return 0;
      const offlineRecords = getOfflineData();
      // Only sync records that are truly pending (never approved) or have updates
      const pendingSync = offlineRecords.filter(r => r.checkin_status === 'pending' || r.checkout_status === 'pending');

      if (pendingSync.length === 0) return 0;

      let syncedCount = 0;
      for (const record of pendingSync) {
          try {
             await callScript('update', { data: record });
             syncedCount++;
          } catch (e) {
              console.error("Sync failed for", record.__backendId, e);
          }
      }
      return syncedCount;
  },

  getPendingCount: (): number => {
      const offline = getOfflineData();
      return offline.filter(r => r.checkin_status === 'pending' || r.checkout_status === 'pending').length;
  },

  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];
    if (!getScriptUrl()) return defaults;
    try {
        const users = await callScript('getUsers');
        return Array.isArray(users) && users.length > 0 ? users : defaults;
    } catch (e) {
        return defaults;
    }
  },

  saveUser: async (user: User) => {
      if (getScriptUrl()) await callScript('saveUser', { data: user }).catch(e => console.error(e));
  },

  deleteUser: async (userId: string) => {
      if (getScriptUrl()) await callScript('deleteUser', { id: userId }).catch(e => console.error(e));
  },

  initializeDefaultUsers: async () => {
      const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
      ];
      let successCount = 0;
      for (const user of defaults) {
          try {
              await callScript('saveUser', { data: user });
              successCount++;
          } catch (e) {}
      }
      return successCount;
  }
};

import React, { useState, useEffect } from 'react';
import { StorageService } from '../../services/storage';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Input, OptionButton, Badge } from '../../components/UI';

export const StaffManagement: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<Partial<User>>({ role: 'driver' });
  const [loading, setLoading] = useState(false);

  // Layout State for Tab switching
  const [activeTab, setActiveTab] = useState<'users' | 'cleanup'>('users');

  // --- Cleanup Tool State ---
  const [cleanupSearch, setCleanupSearch] = useState('');
  const [cleanupRecords, setCleanupRecords] = useState<TenkoRecord[]>([]);
  const [searching, setSearching] = useState(false);

  const loadUsers = async () => {
      const data = await StorageService.getUsers();
      setUsers(data);
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleSave = async () => {
    if (!editingUser.id || !editingUser.name) return alert('กรุณากรอกข้อมูลให้ครบ');
    setLoading(true);
    await StorageService.saveUser(editingUser as User);
    await loadUsers();
    setLoading(false);
    setIsModalOpen(false);
    setEditingUser({ role: 'driver' });
  };

  const handleDeleteUser = async (id: string) => {
    if (confirm('ต้องการลบผู้ใช้นี้?')) {
        await StorageService.deleteUser(id);
        loadUsers();
    }
  };

  const openEdit = (user: User) => {
      setEditingUser(user);
      setIsModalOpen(true);
  };

  const openAdd = () => {
      setEditingUser({ role: 'driver', id: '', name: '' });
      setIsModalOpen(true);
  };

  // --- Cleanup Functions ---
  const handleSearchRecords = async () => {
      const query = cleanupSearch.trim();
      if (!query) return;

      setSearching(true);
      try {
          // Force a fresh fetch from the storage/server
          const allRecords = await StorageService.getAll();

          const matches = allRecords
            .filter(r => {
                const rId = String(r.driver_id).toLowerCase().trim();
                const rName = r.driver_name.toLowerCase();
                const sQuery = query.toLowerCase();
                return rId === sQuery || rName.includes(sQuery);
            })
            .sort((a,b) => {
                // Priority to pending records
                if (a.checkin_status === 'pending' && b.checkin_status !== 'pending') return -1;
                if (a.checkin_status !== 'pending' && b.checkin_status === 'pending') return 1;
                return new Date(b.date).getTime() - new Date(a.date).getTime();
            });

          setCleanupRecords(matches);
          if (matches.length === 0) {
              alert('ไม่พบข้อมูลของพนักงานท่านนี้');
          }
      } catch (e) {
          alert('เกิดข้อผิดพลาดในการดึงข้อมูล');
      } finally {
          setSearching(false);
      }
  };

  const handleForceDeleteRecord = async (recordId: string) => {
      if (confirm('ยืนยันลบรายการนี้ถาวร?\n(พนักงานจะสามารถส่งข้อมูลใหม่ได้ทันที และข้อมูลเดิมจะหายไปจากทั้งเครื่องนี้และ Google Sheet)')) {
          setSearching(true);
          try {
              const result = await StorageService.delete(recordId);
              if (result.isOk) {
                  // Update UI immediately by filtering out the deleted record
                  setCleanupRecords(prev => prev.filter(r => r.__backendId !== recordId));
                  alert('ลบข้อมูลเรียบร้อยแล้ว');
              }
          } catch (e) {
              alert('ล้มเหลวในการลบข้อมูล: ' + e);
          } finally {
              setSearching(false);
          }
      }
  };

  const handleClearLocalCache = () => {
      if (confirm('คำเตือน: การ "ล้างแคชเครื่องนี้" จะลบข้อมูลที่พักไว้ในเครื่องนี้ทั้งหมด\n\nใช้สำหรับแก้ปัญหาข้อมูลค้าง/ซ้ำ ที่เกิดจากการใช้งานขณะเน็ตหลุด\n\nคุณแน่ใจหรือไม่?')) {
          StorageService.clearLocalCache();
          alert('ล้างแคชเรียบร้อย กรุณารีเฟรชหน้าเว็บ');
          window.location.reload();
      }
