                                                        <Badge type={r.checkout_status === 'approved' ? 'approved' : r.checkout_status === 'pending' ? 'pending' : 'neutral'}>
                                                            Check-out: {r.checkout_status === 'pending' ? 'รออนุมัติ' : r.checkout_status || '-'}
                                                        </Badge>
