import { TenkoRecord, User } from '../types';
import { DRIVERS, TENKO_USERS, DEFAULT_SCRIPT_URL } from '../constants';

const OFFLINE_KEY = 'tenko_offline_records';
const SCRIPT_URL_KEY = 'TENKO_SCRIPT_URL';

let lastConnectionStatus: 'online' | 'offline' | 'error' = 'online';

// Utility to get YYYY-MM-DD in local time
const getLocalISODate = () => {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

const getScriptUrl = () => {
    if (DEFAULT_SCRIPT_URL) return DEFAULT_SCRIPT_URL;
    return localStorage.getItem(SCRIPT_URL_KEY) || '';
};

const getOfflineData = (): TenkoRecord[] => {
    try {
        const data = localStorage.getItem(OFFLINE_KEY);
        return data ? JSON.parse(data) : [];
    } catch {
        return [];
    }
};

const saveOfflineData = (records: TenkoRecord[]) => {
    localStorage.setItem(OFFLINE_KEY, JSON.stringify(records));
};

const callScript = async (action: string, payload: any = {}) => {
    const url = getScriptUrl();
    if (!url) throw new Error("No Script URL configured");

    try {
        const response = await fetch(url, {
            method: 'POST',
            body: JSON.stringify({ action, ...payload })
        });

        const text = await response.text();
        let json;
        try {
            json = JSON.parse(text);
        } catch (e) {
            console.error("Failed to parse server response:", text);
            throw new Error("Invalid server response format");
        }

        lastConnectionStatus = 'online';
        return json;
    } catch (e) {
        lastConnectionStatus = 'offline';
        throw e;
    }
};

export const StorageService = {
  getConnectionStatus: () => lastConnectionStatus,

  hasScriptUrl: () => !!getScriptUrl(),

  clearLocalCache: () => {
      localStorage.removeItem(OFFLINE_KEY);
  },

  getAll: async (): Promise<TenkoRecord[]> => {
    let dbRecords: TenkoRecord[] = [];
    const localRecords = getOfflineData();

    if (getScriptUrl()) {
        try {
            const serverData = await callScript('getAll');
            if (Array.isArray(serverData)) {
                dbRecords = serverData;
                const serverIds = new Set(dbRecords.map(r => r.__backendId));
                const reconciledLocal = localRecords.filter(lr => {
                    const existsOnServer = serverIds.has(lr.__backendId);
                    const isNewPending = lr.checkin_status === 'pending' && !lr.checkin_tenko_id;
                    return existsOnServer || isNewPending;
                });
                saveOfflineData(reconciledLocal);
            }
        } catch (e) {
            console.warn("Failed to fetch from script", e);
        }
    }

    const currentLocal = getOfflineData();
    const recordMap = new Map<string, TenkoRecord>();
    dbRecords.forEach(r => recordMap.set(r.__backendId, r));
    currentLocal.forEach(r => recordMap.set(r.__backendId, r));

    const uniqueMap = new Map<string, TenkoRecord>();
    Array.from(recordMap.values()).forEach(r => {
        const key = `${String(r.driver_id).trim()}_${r.date}`;
        if (!uniqueMap.has(key)) {
            uniqueMap.set(key, r);
        } else {
            const existing = uniqueMap.get(key)!;
            let scoreExisting = (existing.checkin_status === 'approved' ? 2 : 0) + (existing.checkout_status === 'approved' ? 2 : 0);
            let scoreNew = (r.checkin_status === 'approved' ? 2 : 0) + (r.checkout_status === 'approved' ? 2 : 0);

            if (scoreNew > scoreExisting) {
                uniqueMap.set(key, r);
            } else if (scoreNew === scoreExisting) {
                const timeExisting = new Date(existing.checkin_real_timestamp || existing.date).getTime();
                const timeNew = new Date(r.checkin_real_timestamp || r.date).getTime();
                if (timeNew > timeExisting) uniqueMap.set(key, r);
            }
        }
    });

    return Array.from(uniqueMap.values()).sort((a, b) => 
        new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    const offline = getOfflineData();
    // Use local date instead of UTC ISO string
    const today = record.date || getLocalISODate();
    const id = crypto.randomUUID();
    const fullRecord = { 
        ...record, 
        __backendId: id,
        driver_id: String(record.driver_id || '').trim(),
        date: today
    } as TenkoRecord;

    offline.push(fullRecord);
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('create', { data: fullRecord }).catch(e => console.warn(e));
    }

    return { isOk: true, data: fullRecord };
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    const offline = getOfflineData();
    const index = offline.findIndex(r => r.__backendId === record.__backendId);
    if (index >= 0) {
        offline[index] = record;
    } else {
        offline.push(record);
    }
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('update', { data: record }).catch(e => console.warn(e));
    }

    return { isOk: true };
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    const offline = getOfflineData().filter(r => r.__backendId !== recordId);
    saveOfflineData(offline);
    if (getScriptUrl()) {
        try {
            await callScript('delete', { id: recordId });
        } catch (e) {
            console.error(e);
        }
    }
    return { isOk: true };
  },

  syncPendingData: async (): Promise<number> => {
      if (!getScriptUrl()) return 0;
      const offlineRecords = getOfflineData();
      const pendingSync = offlineRecords.filter(r => r.checkin_status === 'pending' || r.checkout_status === 'pending');
      if (pendingSync.length === 0) return 0;
      let syncedCount = 0;
      for (const record of pendingSync) {
          try {
             await callScript('update', { data: record });
             syncedCount++;
          } catch (e) {
              console.error(e);
          }
      }
      return syncedCount;
  },

  getPendingCount: (): number => {
      const offline = getOfflineData();
      return offline.filter(r => r.checkin_status === 'pending' || r.checkout_status === 'pending').length;
  },

  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];
    if (!getScriptUrl()) return defaults;
    try {
        const users = await callScript('getUsers');
        return Array.isArray(users) && users.length > 0 ? users : defaults;
    } catch (e) {
        return defaults;
    }
  },

  saveUser: async (user: User) => {
      if (getScriptUrl()) await callScript('saveUser', { data: user }).catch(e => console.error(e));
  },

  deleteUser: async (userId: string) => {
      if (getScriptUrl()) await callScript('deleteUser', { id: userId }).catch(e => console.error(e));
  },

  initializeDefaultUsers: async () => {
      const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
      ];
      let successCount = 0;
      for (const user of defaults) {
          try {
              await callScript('saveUser', { data: user });
              successCount++;
          } catch (e) {}
      }
      return successCount;
  }
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import { CheckinForm } from './CheckinForm';
import { CheckoutForm } from './CheckoutForm';
import { DriverHistory } from './DriverHistory';
import { SYSTEM_VERSION } from '../../constants';

interface DriverAppProps {
  user: User;
  onLogout: () => void;
}

export const DriverApp: React.FC<DriverAppProps> = ({ user, onLogout }) => {
  const [view, setView] = useState<'home' | 'checkin' | 'checkout' | 'history'>('home');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [pendingCount, setPendingCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'online' | 'offline' | 'error'>('online');

  const fetchData = async () => {
      try {
          await StorageService.syncPendingData();
          const data = await StorageService.getAll();
          setRecords(data);
          setPendingCount(StorageService.getPendingCount());
          setConnectionStatus(StorageService.getConnectionStatus());
      } catch(e) {
          console.error(e);
          setConnectionStatus('offline');
      } finally {
          setIsLoading(false);
      }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 15000);
    return () => clearInterval(interval);
  }, []);

  // Utility to get YYYY-MM-DD in local time
  const getTodayStr = () => {
      const now = new Date();
      return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const today = getTodayStr();

  // LOGIC IMPROVEMENT: 
  // Instead of strictly today's date, let's look for the most recent record.
  // If the record from "today" (local) exists, use it.
  // Otherwise, if there is a record within the last 12 hours that is NOT checked out, use it (for midnight shifts).
  const myRecords = records
    .filter(r => r.driver_id === user.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const activeRecord = myRecords[0]; // The very latest record

  // Check if activeRecord belongs to "today" or is still "open"
  const isCurrentSession = activeRecord && (
      activeRecord.date === today || 
      (!activeRecord.checkout_status && (new Date().getTime() - new Date(activeRecord.checkin_real_timestamp || activeRecord.date).getTime()) < 24 * 60 * 60 * 1000)
  );

  const currentRecord = isCurrentSession ? activeRecord : null;

  const getLatestCheckoutTime = () => {
    const closedRecords = myRecords
      .filter(r => r.checkout_timestamp)
      .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());
    return closedRecords.length > 0 ? new Date(closedRecords[0].checkout_timestamp!) : null;
  };

  const checkFixStartTime = () => {
    const approvedRecords = myRecords
        .filter(r => r.checkin_timestamp && r.checkin_status === 'approved')
        .sort((a, b) => new Date(b.checkin_timestamp!).getTime() - new Date(a.checkin_timestamp!).getTime());

    if (approvedRecords.length === 0) return { status: 'OK', time: '--:--' };

    const getMonday = (dateStr: string) => {
        const d = new Date(dateStr);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? -6 : 1);
        const monday = new Date(d.setDate(diff));
        return `${monday.getFullYear()}-${String(monday.getMonth()+1).padStart(2,'0')}-${String(monday.getDate()).padStart(2,'0')}`;
    };

    const weeks: Record<string, TenkoRecord[]> = {};
    approvedRecords.forEach(record => {
        const mondayStr = getMonday(record.checkin_timestamp!);
        if (!weeks[mondayStr]) weeks[mondayStr] = [];
        weeks[mondayStr].push(record);
    });

    const latestMonday = Object.keys(weeks).sort().reverse()[0];
    const currentWeekRecords = weeks[latestMonday];

    const mondayRecord = currentWeekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
    const referenceRecord = mondayRecord || currentWeekRecords[currentWeekRecords.length - 1];

    const refDate = new Date(referenceRecord.checkin_timestamp!);
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });
    const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();

    let status = 'OK';
    for (let record of currentWeekRecords) {
        const checkDate = new Date(record.checkin_timestamp!);
        const checkTime = checkDate.getHours() * 60 + checkDate.getMinutes();
        if (Math.abs(checkTime - refTotalMinutes) > 120) {
            status = 'NG';
            break;
        }
    }

    return { status, time: displayTime };
  };

  const canStartCheckin = () => {
     const latestCheckout = getLatestCheckoutTime();
     if (!latestCheckout) return { allowed: true };
     const diffHours = (new Date().getTime() - latestCheckout.getTime()) / (1000 * 60 * 60);
     if (diffHours < 8) {
         return { 
             allowed: false, 
             message: `ต้องพักผ่อนให้ครบ 8 ชม. (อีก ${(8 - diffHours).toFixed(1)} ชม.)` 
         };
     }

     if (currentRecord) {
         if (currentRecord.checkin_status === 'approved' && currentRecord.checkout_status === 'approved') {
             return { allowed: true, message: "เริ่มรอบใหม่ได้" };
         }
         return { allowed: false, message: "คุณมีรายการที่ยังทำไม่จบในวันนี้" };
     }
     return { allowed: true };
  };

  const checkinStatus = canStartCheckin();
  const fixData = checkFixStartTime();

  const handleDataUpdate = () => {
      setIsLoading(true);
      fetchData().then(() => {
          setView('home');
          setIsLoading(false);
      });
  };

  const renderConnectionBadge = () => {
      if (connectionStatus === 'error') return <div className="flex items-center gap-2 bg-red-500 text-white px-3 py-1 rounded-full text-xs font-bold shadow-sm"><i className="fas fa-database"></i> DB Error</div>;
      if (connectionStatus === 'offline' || pendingCount > 0) return <div className="flex items-center gap-2 bg-amber-400 text-black px-3 py-1 rounded-full text-xs font-bold animate-pulse shadow-sm"><i className="fas fa-wifi-slash"></i> Offline ({pendingCount})</div>;
      return <div className="flex items-center gap-2 bg-emerald-500/20 text-emerald-100 border border-emerald-400/30 px-3 py-1 rounded-full text-xs font-bold"><i className="fas fa-wifi"></i> Online</div>;
  };

  if (view === 'checkin') return <CheckinForm user={user} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'checkout') return <CheckoutForm user={user} record={currentRecord!} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
