import { TenkoRecord, User } from '../types';
import { DRIVERS, TENKO_USERS, DEFAULT_SCRIPT_URL } from '../constants';

const OFFLINE_KEY = 'tenko_offline_records';
const SCRIPT_URL_KEY = 'TENKO_SCRIPT_URL';

let lastConnectionStatus: 'online' | 'offline' | 'error' = 'online';

// Utility to get YYYY-MM-DD in local time
const getLocalISODate = () => {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

const getScriptUrl = () => {
    if (DEFAULT_SCRIPT_URL) return DEFAULT_SCRIPT_URL;
    return localStorage.getItem(SCRIPT_URL_KEY) || '';
};

const getOfflineData = (): TenkoRecord[] => {
    try {
        const data = localStorage.getItem(OFFLINE_KEY);
        return data ? JSON.parse(data) : [];
    } catch {
        return [];
    }
};

const saveOfflineData = (records: TenkoRecord[]) => {
    localStorage.setItem(OFFLINE_KEY, JSON.stringify(records));
};

const callScript = async (action: string, payload: any = {}) => {
    const url = getScriptUrl();
    if (!url) throw new Error("No Script URL configured");

    try {
        const response = await fetch(url, {
            method: 'POST',
            body: JSON.stringify({ action, ...payload })
        });

        const text = await response.text();
        let json;
        try {
            json = JSON.parse(text);
        } catch (e) {
            console.error("Failed to parse server response:", text);
            throw new Error("Invalid server response format");
        }

        lastConnectionStatus = 'online';
        return json;
    } catch (e) {
        lastConnectionStatus = 'offline';
        throw e;
    }
};

export const StorageService = {
  getConnectionStatus: () => lastConnectionStatus,

  hasScriptUrl: () => !!getScriptUrl(),

  clearLocalCache: () => {
      localStorage.removeItem(OFFLINE_KEY);
  },

  getAll: async (): Promise<TenkoRecord[]> => {
    let dbRecords: TenkoRecord[] = [];
    const localRecords = getOfflineData();

    if (getScriptUrl()) {
        try {
            const serverData = await callScript('getAll');
            if (Array.isArray(serverData)) {
                dbRecords = serverData;
                const serverIds = new Set(dbRecords.map(r => r.__backendId));
                const reconciledLocal = localRecords.filter(lr => {
                    const existsOnServer = serverIds.has(lr.__backendId);
                    const isNewPending = lr.checkin_status === 'pending' && !lr.checkin_tenko_id;
                    return existsOnServer || isNewPending;
                });
                saveOfflineData(reconciledLocal);
            }
        } catch (e) {
            console.warn("Failed to fetch from script", e);
        }
    }

    const currentLocal = getOfflineData();
    const recordMap = new Map<string, TenkoRecord>();
    dbRecords.forEach(r => recordMap.set(r.__backendId, r));
    currentLocal.forEach(r => recordMap.set(r.__backendId, r));

    const uniqueMap = new Map<string, TenkoRecord>();
    Array.from(recordMap.values()).forEach(r => {
        const driverId = String(r.driver_id).trim();
        const key = `${driverId}_${r.date}`;

        if (!uniqueMap.has(key)) {
            uniqueMap.set(key, r);
        } else {
            const existing = uniqueMap.get(key)!;

            // PRIORITY LOGIC: 
            // 1. Give priority to records that are NOT fully closed (Check-out is still pending or empty)
            // 2. If both are the same status, pick the one with the latest timestamp

            const getScore = (rec: TenkoRecord) => {
                let score = 0;
                // If check-in is pending, high priority (needs action)
                if (rec.checkin_status === 'pending') score += 100;
                // If check-in is approved but check-out is pending, even higher priority (in-queue for exit)
                if (rec.checkin_status === 'approved' && rec.checkout_status === 'pending') score += 200;
                // If approved but not checked out yet, high priority (currently working)
                if (rec.checkin_status === 'approved' && !rec.checkout_status) score += 50;
                return score;
            };

            const existingScore = getScore(existing);
            const newScore = getScore(r);

            if (newScore > existingScore) {
                uniqueMap.set(key, r);
            } else if (newScore === existingScore) {
                // If scores are equal, pick the one with the most recent actual interaction
                const timeExisting = new Date(existing.checkout_real_timestamp || existing.checkin_real_timestamp || existing.date).getTime();
                const timeNew = new Date(r.checkout_real_timestamp || r.checkin_real_timestamp || r.date).getTime();
                if (timeNew > timeExisting) {
                    uniqueMap.set(key, r);
                }
            }
        }
    });

    return Array.from(uniqueMap.values()).sort((a, b) => 
        new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  },

  create: async (record: Partial<TenkoRecord>): Promise<{ isOk: boolean, data?: TenkoRecord }> => {
    const offline = getOfflineData();
    const today = record.date || getLocalISODate();
    const id = crypto.randomUUID();
    const fullRecord = { 
        ...record, 
        __backendId: id,
        driver_id: String(record.driver_id || '').trim(),
        date: today
    } as TenkoRecord;

    offline.push(fullRecord);
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('create', { data: fullRecord }).catch(e => console.warn(e));
    }

    return { isOk: true, data: fullRecord };
  },

  update: async (record: TenkoRecord): Promise<{ isOk: boolean }> => {
    const offline = getOfflineData();
    const index = offline.findIndex(r => r.__backendId === record.__backendId);
    if (index >= 0) {
        offline[index] = record;
    } else {
        offline.push(record);
    }
    saveOfflineData(offline);

    if (getScriptUrl()) {
        await callScript('update', { data: record }).catch(e => console.warn(e));
    }

    return { isOk: true };
  },

  delete: async (recordId: string): Promise<{ isOk: boolean }> => {
    const offline = getOfflineData().filter(r => r.__backendId !== recordId);
    saveOfflineData(offline);
    if (getScriptUrl()) {
        try {
            await callScript('delete', { id: recordId });
        } catch (e) {
            console.error(e);
        }
    }
    return { isOk: true };
  },

  syncPendingData: async (): Promise<number> => {
      if (!getScriptUrl()) return 0;
      const offlineRecords = getOfflineData();
      const pendingSync = offlineRecords.filter(r => r.checkin_status === 'pending' || r.checkout_status === 'pending');
      if (pendingSync.length === 0) return 0;
      let syncedCount = 0;
      for (const record of pendingSync) {
          try {
             await callScript('update', { data: record });
             syncedCount++;
          } catch (e) {
              console.error(e);
          }
      }
      return syncedCount;
  },

  getPendingCount: (): number => {
      const offline = getOfflineData();
      return offline.filter(r => r.checkin_status === 'pending' || r.checkout_status === 'pending').length;
  },

  getUsers: async (): Promise<User[]> => {
    const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
    ];
    if (!getScriptUrl()) return defaults;
    try {
        const users = await callScript('getUsers');
        return Array.isArray(users) && users.length > 0 ? users : defaults;
    } catch (e) {
        return defaults;
    }
  },

  saveUser: async (user: User) => {
      if (getScriptUrl()) await callScript('saveUser', { data: user }).catch(e => console.error(e));
  },

  deleteUser: async (userId: string) => {
      if (getScriptUrl()) await callScript('deleteUser', { id: userId }).catch(e => console.error(e));
  },

  initializeDefaultUsers: async () => {
      const defaults = [
          ...DRIVERS.map(d => ({ ...d, role: 'driver' as const })),
          ...TENKO_USERS.map(u => ({ ...u, role: 'tenko' as const }))
      ];
      let successCount = 0;
      for (const user of defaults) {
          try {
              await callScript('saveUser', { data: user });
              successCount++;
          } catch (e) {}
      }
      return successCount;
  }
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { StorageService } from '../../services/storage';
import { TenkoDashboard } from './TenkoDashboard';
import { ApprovalView } from './ApprovalView';
import { StaffManagement } from './StaffManagement';
import { TenkoHistory } from './TenkoHistory';
import { TenkoAnalytics } from './TenkoAnalytics';
import { TenkoReportPrint } from './TenkoReportPrint';
import { SYSTEM_VERSION } from '../../constants';

interface Props {
  user: User;
  onLogout: () => void;
}

type View = 'dashboard' | 'queue-checkin' | 'queue-checkout' | 'completed' | 'analytics' | 'manage' | 'report';

export const TenkoApp: React.FC<Props> = ({ user, onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [selectedRecordId, setSelectedRecordId] = useState<string | null>(null);

  const loadData = async () => {
      try {
          const data = await StorageService.getAll();
          setRecords(data);
      } catch (e) {
          console.error(e);
      }
  };

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, []);

  const handleUpdate = () => {
    loadData().then(() => {
        setSelectedRecordId(null);
    });
  };

  const handleDeleteRecord = async (id: string) => {
      if(confirm('คุณต้องการลบรายการนี้ทิ้งทันทีหรือไม่? (Driver ต้องส่งใหม่)')) {
          await StorageService.delete(id);
          handleUpdate();
      }
  };

  // Nav Item component
  const NavItem = ({ view, icon, label, mobile = false }: { view: View; icon: string; label: string; mobile?: boolean }) => {
      const isActive = currentView === view;
      const count = records.filter(r => view === 'queue-checkin' ? r.checkin_status === 'pending' : r.checkout_status === 'pending').length;

      if (mobile) {
          return (
            <button 
                onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
                className={`flex flex-col items-center justify-center p-2 flex-1 relative ${isActive ? 'text-blue-200' : 'text-slate-400'}`}
            >
                <i className={`fas ${icon} text-lg mb-0.5`}></i>
                <span className="text-[9px] leading-tight">{label.split(' ')[0]}</span>
                {(view === 'queue-checkin' || view === 'queue-checkout') && count > 0 && (
                    <span className="absolute top-1 right-2 w-4 h-4 bg-red-500 text-white text-[9px] flex items-center justify-center rounded-full font-bold border border-blue-900">
                        {count}
                    </span>
                )}
            </button>
          );
      }

      return (
        <div 
          onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
          className={`px-4 py-3 cursor-pointer flex items-center gap-3 transition-colors ${isActive ? 'bg-white/20 border-r-4 border-white' : 'hover:bg-white/10 border-r-4 border-transparent'}`}
        >
          <i className={`fas ${icon} w-6 text-center`}></i>
          <span className="font-medium">{label}</span>
          {(view === 'queue-checkin' || view === 'queue-checkout') && count > 0 && (
            <span className="ml-auto bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
                {count}
            </span>
          )}
        </div>
      );
  };

  const renderContent = () => {
    // CRITICAL: Handle selection first
    if (selectedRecordId) {
       const record = records.find(r => r.__backendId === selectedRecordId);
       if (!record) return <div>Record not found</div>;

       let approvalType: 'checkin' | 'checkout' | 'view' = 'view';
       if (record.checkin_status === 'pending') {
           approvalType = 'checkin';
       } else if (record.checkout_status === 'pending') {
           approvalType = 'checkout';
       } else if (record.checkin_status === 'approved' && !record.checkout_status) {
           // ADDED: Allow Tenko to force checkout for working drivers
           approvalType = 'checkout';
       }

       return (
         <ApprovalView 
            record={record} 
            user={user}
            type={approvalType}
            onBack={() => setSelectedRecordId(null)}
            onSuccess={handleUpdate}
         />
       );
    }

    switch (currentView) {
        case 'manage': return <StaffManagement />;
        case 'analytics': return <TenkoAnalytics records={records} />;
        case 'report': return <TenkoReportPrint records={records} />;
        case 'completed': return <TenkoHistory records={records} onSelectRecord={setSelectedRecordId} onDelete={handleUpdate} />;
        case 'queue-checkin': return <TenkoDashboard view="queue-checkin" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        case 'queue-checkout': return <TenkoDashboard view="queue-checkout" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        default: return <TenkoDashboard view="dashboard" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-full bg-slate-50 overflow-hidden">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-64 bg-gradient-to-b from-blue-900 to-blue-700 text-white flex-col shadow-xl z-20 print:hidden h-full">
        <div className="p-6 border-b border-blue-500/30">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                    <i className="fas fa-user-shield"></i>
                </div>
                <div>
                    <h3 className="font-bold leading-tight">{user.name}</h3>
                    <p className="text-xs text-blue-200">เจ้าหน้าที่ Tenko</p>
                </div>
            </div>
        </div>
        <nav className="flex-1 py-4 space-y-1 text-sm overflow-y-auto">
            <NavItem view="dashboard" icon="fa-home" label="หน้าหลัก" />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="คิว (ก่อนเริ่มงาน)" />
            <NavItem view="queue-checkout" icon="fa-flag-checkered" label="คิว (หลังเลิกงาน)" />
            <NavItem view="completed" icon="fa-check-double" label="รายการเสร็จสิ้น" />
            <NavItem view="analytics" icon="fa-chart-line" label="แดชบอร์ด/ปฏิทิน" />
            <NavItem view="report" icon="fa-print" label="พิมพ์รายงาน" />
            <NavItem view="manage" icon="fa-users-cog" label="ข้อมูลพนักงาน" />
        </nav>
        <div className="p-4 border-t border-blue-500/30">
            <button onClick={onLogout} className="w-full py-2 bg-blue-900/50 hover:bg-blue-800 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm">
                <i className="fas fa-sign-out-alt"></i> ออกจากระบบ
            </button>
            <div className="mt-4 text-center text-xs text-blue-300/60 font-mono">
                {SYSTEM_VERSION}
            </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8 print:p-0 print:overflow-visible pb-20 md:pb-8 w-full">
        {/* Mobile Header */}
        <div className="md:hidden flex justify-between items-center mb-4 bg-white p-3 rounded-lg shadow-sm border border-slate-100">
             <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white">
                    <i className="fas fa-user-shield text-xs"></i>
                </div>
                <span className="font-bold text-sm text-slate-700">{user.name}</span>
             </div>
             <button onClick={onLogout} className="text-slate-400 hover:text-red-500">
                 <i className="fas fa-sign-out-alt"></i>
             </button>
        </div>
        {renderContent()}
      </main>

      {/* Bottom Navigation - Mobile */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-slate-900 text-slate-400 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] z-30 flex justify-around items-center border-t border-slate-800 safe-area-pb">
            <NavItem view="dashboard" icon="fa-home" label="Home" mobile />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="In" mobile />
            <NavItem view="queue-checkout" icon="fa-flag-checkered" label="Out" mobile />
            <NavItem view="completed" icon="fa-check-double" label="Done" mobile />
            <div className="w-[1px] h-6 bg-slate-700 mx-1"></div>
            <NavItem view="analytics" icon="fa-chart-line" label="Stats" mobile />
            <NavItem view="manage" icon="fa-cog" label="Admin" mobile />
      </nav>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { TenkoRecord, User } from '../../types';
import { Button, Card, Input, OptionButton, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  record: TenkoRecord;
  user: User;
  type: 'checkin' | 'checkout' | 'view';
  onBack: () => void;
  onSuccess: () => void;
}

export const ApprovalView: React.FC<Props> = ({ record, user, type, onBack, onSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    temperature: record.temperature,
    blood_pressure_high: record.blood_pressure_high,
    blood_pressure_low: record.blood_pressure_low,
    alcohol_checkin: record.alcohol_checkin ?? 0,
    alcohol_checkout: record.alcohol_checkout ?? 0,
    phone_usage_compliant: record.phone_usage_compliant || 'ตรงตามที่แจ้ง',
    can_work: record.can_work || 'ได้',
    driving_violation: record.driving_violation || 'ไม่มี',

    // Driver fields (for when Tenko fills them)
    vehicle_handover: record.vehicle_handover || 'ปกติ',
    vehicle_detail: record.vehicle_detail || '',
    body_condition_checkout: record.body_condition_checkout || 'ปกติ',
    body_detail_checkout: record.body_detail_checkout || '',
    route_risk: record.route_risk || 'ปกติ',
    route_detail: record.route_detail || '',

    checkin_timestamp: record.checkin_timestamp || new Date().toISOString(),
    checkout_timestamp: record.checkout_timestamp || new Date().toISOString()
  });

  const [fixStartStatus, setFixStartStatus] = useState<string>('N/A');
  const [lastCheckout, setLastCheckout] = useState<string>('-');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const loadHistory = async () => {
        const allRecords = await StorageService.getAll();

        const previousRecords = allRecords
            .filter(r => r.driver_id === record.driver_id && r.checkout_timestamp && r.__backendId !== record.__backendId)
            .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());
        if (previousRecords.length > 0) {
            setLastCheckout(new Date(previousRecords[0].checkout_timestamp!).toLocaleString('th-TH'));
        }

        const driverRecords = allRecords
            .filter(r => r.driver_id === record.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
            .sort((a, b) => new Date(b.checkin_timestamp!).getTime() - new Date(a.checkin_timestamp!).getTime());

        if (driverRecords.length === 0) {
            setFixStartStatus('OK (First Record)');
            return;
        }

        const getMonday = (dateStr: string) => {
            const d = new Date(dateStr);
            const day = d.getDay();
            const diff = d.getDate() - day + (day === 0 ? -6 : 1);
            return new Date(d.setDate(diff)).toISOString().split('T')[0];
        };

        const currentRecordMonday = getMonday(form.checkin_timestamp!);
        const currentWeekRecords = driverRecords.filter(r => getMonday(r.checkin_timestamp!) === currentRecordMonday);

        const mondayRecord = currentWeekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
        const referenceRecord = mondayRecord || (currentWeekRecords.length > 0 ? currentWeekRecords[currentWeekRecords.length - 1] : null);

        if (!referenceRecord) {
            setFixStartStatus('OK');
            return;
        }

        const refDate = new Date(referenceRecord.checkin_timestamp!);
        const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
        const displayTime = refDate.toLocaleTimeString('th-TH', { 
            hour: '2-digit', 
            minute: '2-digit',
            hour12: false
        });

        const currentCheckTime = new Date(form.checkin_timestamp!);
        const currentMinutes = currentCheckTime.getHours() * 60 + currentCheckTime.getMinutes();
        const diff = Math.abs(currentMinutes - refTotalMinutes);

        if (diff > 120) {
            setFixStartStatus(`NG (Ref: ${displayTime})`);
        } else {
            setFixStartStatus(`OK (Ref: ${displayTime})`);
        }
    };
    loadHistory();
  }, [record.driver_id, form.checkin_timestamp, record.__backendId]);


  const updateForm = (k: keyof TenkoRecord, v: any) => setForm(p => ({ ...p, [k]: v }));

  const isTempBad = (t?: number) => t && t > 37.5;
  const isBPHighBad = (bp?: number) => bp && (bp < 90 || bp > 160);
  const isBPLowBad = (bp?: number) => bp && (bp < 60 || bp > 100);
  const isAlcoholBad = (a?: number) => a !== undefined && a !== 0;

  const handleApprove = async () => {
    if (isAlcoholBad(form.alcohol_checkin) && !form.alcohol_checkin_reason) return alert('กรุณาระบุเหตุผลค่าแอลกอฮอล์');
    if (form.can_work === 'ไม่ได้' && !form.cannot_work_reason) return alert('กรุณาระบุสาเหตุที่วิ่งงานไม่ได้');

    setSubmitting(true);
    const updateData: Partial<TenkoRecord> = { ...form };

    if (type === 'checkin') {
      updateData.checkin_status = 'approved';
      updateData.checkin_tenko_id = user.id;
      updateData.checkin_tenko_name = user.name;
    } else if (type === 'checkout') {
      updateData.checkout_status = 'approved';
      updateData.checkout_tenko_id = user.id;
      updateData.checkout_tenko_name = user.name;
      // Also ensure driver timestamp is set if forced
      if (!record.checkout_real_timestamp) {
          updateData.checkout_real_timestamp = new Date().toISOString();
      }
    }

    try {
        await StorageService.update({ ...record, ...updateData });
        onSuccess();
    } catch(e) {
        alert('เกิดข้อผิดพลาด');
    } finally {
        setSubmitting(false);
    }
  };

  const handleDelete = async () => {
      if(confirm('คุณต้องการลบรายการนี้ใช่หรือไม่?\n\nการลบจะทำให้ข้อมูลหายไป และพนักงานขับรถสามารถส่งรายการเข้ามาใหม่ได้')) {
          setSubmitting(true);
          try {
              await StorageService.delete(record.__backendId);
              onSuccess();
          } catch (e) {
              alert('ล้มเหลวในการลบข้อมูล');
          } finally {
              setSubmitting(false);
          }
      }
  }

  const formatDateForInput = (isoString?: string) => {
      if (!isoString) return '';
      const date = new Date(isoString);
      if (isNaN(date.getTime())) return '';
      const tzOffset = date.getTimezoneOffset() * 60000; 
      const localDate = new Date(date.getTime() - tzOffset);
      return localDate.toISOString().slice(0, 16);
  };

  const handleDateChange = (val: string, field: 'checkin_timestamp' | 'checkout_timestamp') => {
      if (!val) return;
      const date = new Date(val);
      if (!isNaN(date.getTime())) {
          updateForm(field, date.toISOString());
      }
  };

  const renderDriverDataSection = () => (
    <Card className="h-fit">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex justify-between">
            <span><i className="fas fa-user-circle"></i> ข้อมูลพนักงาน</span>
            <span className="text-sm font-normal text-slate-500">{record.driver_name} ({record.driver_id})</span>
        </h3>

        <div className="space-y-4 text-sm pr-2">
            <div className="bg-slate-50 p-3 rounded border space-y-2">
                <p><strong>เลิกงานล่าสุด:</strong> {lastCheckout}</p>
                <p><strong>Fix Start Time:</strong> <Badge type={fixStartStatus.includes('OK') ? 'approved' : 'danger'}>{fixStartStatus}</Badge></p>

                <div className="border-t border-slate-200 pt-2 mt-2">
                    <p className="flex justify-between items-center">
                        <span className="font-bold text-blue-700">เข้างาน:</span>
                        <span>{record.checkin_timestamp ? new Date(record.checkin_timestamp).toLocaleString('th-TH', { dateStyle: 'short', timeStyle: 'short' }) : '-'}</span>
                    </p>
                    {(type === 'checkout' || type === 'view') && (
                        <p className="flex justify-between items-center mt-1">
                            <span className="font-bold text-purple-700">เลิกงาน:</span>
                            <span>{record.checkout_timestamp ? new Date(record.checkout_timestamp).toLocaleString('th-TH', { dateStyle: 'short', timeStyle: 'short' }) : '-'}</span>
                        </p>
                    )}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-2">
                <p><strong>เหนื่อยล้า:</strong> {record.tired} {record.tired_detail && `(${record.tired_detail})`}</p>
                <p><strong>เจ็บป่วย:</strong> {record.sick} {record.sick === 'มี' && `(หาหมอ: ${record.seen_doctor})`}</p>
                <p><strong>ง่วงนอน:</strong> {record.drowsy}</p>
                <p><strong>บาดเจ็บ:</strong> {record.injury}</p>
                <p><strong>ยา:</strong> {record.medication} {record.medication_name}</p>
                <p><strong>สายตา/การได้ยิน:</strong> {record.vision_problem}/{record.hearing_problem}</p>
            </div>

            <div className="p-3 bg-blue-50 rounded border border-blue-100">
                <h4 className="font-bold mb-1">การนอน</h4>
                <p>ปกติ: {record.sleep_start} - {record.sleep_end} ({record.sleep_hours} ชม.) - <span className={record.sleep_hours! < 6 ? 'text-red-600 font-bold' : 'text-green-600'}>{record.sleep_quality}</span></p>
                {record.extra_sleep === 'นอนเพิ่ม' && (
                    <p>เพิ่ม: {record.extra_sleep_start} - {record.extra_sleep_end} ({record.extra_sleep_hours} ชม.) - <span className={record.extra_sleep_hours! < 4.5 ? 'text-red-600 font-bold' : 'text-green-600'}>{record.extra_sleep_quality}</span></p>
                )}
            </div>

            {(type === 'checkout' || type === 'view') && (
                <div className="p-3 bg-purple-50 rounded border border-purple-100 mt-2">
                    <h4 className="font-bold text-purple-800 mb-2 border-b border-purple-200 pb-1 flex items-center gap-2">
                        <i className="fas fa-clipboard-list"></i> รายงานหลังเลิกงาน
                    </h4>

                    {/* UI for Tenko to fill missing Driver fields */}
                    {!record.checkout_real_timestamp && type === 'checkout' ? (
                        <div className="space-y-4 bg-white p-3 rounded-lg border border-purple-200">
                            <p className="text-xs text-amber-600 font-bold mb-2"><i className="fas fa-info-circle"></i> พนักงานไม่ได้ส่งข้อมูลมา เจ้าหน้าที่สามารถกรอกแทนได้</p>

                            <div>
                                <label className="block text-xs font-bold mb-1">1. การส่งมอบรถสินค้า</label>
                                <div className="flex gap-2 mb-2">
                                    <OptionButton selected={form.vehicle_handover === 'ปกติ'} onClick={() => updateForm('vehicle_handover', 'ปกติ')}>ปกติ</OptionButton>
                                    <OptionButton selected={form.vehicle_handover === 'ไม่ปกติ'} onClick={() => updateForm('vehicle_handover', 'ไม่ปกติ')}>ไม่ปกติ</OptionButton>
                                </div>
                                {form.vehicle_handover === 'ไม่ปกติ' && <Input placeholder="ระบุรายละเอียด" value={form.vehicle_detail} onChange={e => updateForm('vehicle_detail', e.target.value)} />}
                            </div>

                            <div>
                                <label className="block text-xs font-bold mb-1">2. สภาพร่างกายหลังงาน</label>
                                <div className="flex gap-2 mb-2">
                                    <OptionButton selected={form.body_condition_checkout === 'ปกติ'} onClick={() => updateForm('body_condition_checkout', 'ปกติ')}>ปกติ</OptionButton>
                                    <OptionButton selected={form.body_condition_checkout === 'ไม่ปกติ'} onClick={() => updateForm('body_condition_checkout', 'ไม่ปกติ')}>ไม่ปกติ</OptionButton>
                                </div>
                                {form.body_condition_checkout === 'ไม่ปกติ' && <Input placeholder="ระบุรายละเอียด" value={form.body_detail_checkout} onChange={e => updateForm('body_detail_checkout', e.target.value)} />}
                            </div>

                            <div>
                                <label className="block text-xs font-bold mb-1">3. จุดเสี่ยงในเส้นทาง</label>
                                <div className="flex gap-2 mb-2">
                                    <OptionButton selected={form.route_risk === 'ปกติ'} onClick={() => updateForm('route_risk', 'ปกติ')}>ปกติ</OptionButton>
                                    <OptionButton selected={form.route_risk === 'พบจุดเสี่ยง'} onClick={() => updateForm('route_risk', 'พบจุดเสี่ยง')}>พบจุดเสี่ยง</OptionButton>
                                </div>
                                {form.route_risk === 'พบจุดเสี่ยง' && <Input placeholder="ระบุรายละเอียด" value={form.route_detail} onChange={e => updateForm('route_detail', e.target.value)} />}
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            <div className="flex flex-col">
                                <div className="flex justify-between">
                                    <span className="font-semibold text-slate-700">การส่งมอบรถ:</span>
                                    <span className={record.vehicle_handover === 'ปกติ' ? 'text-green-600 font-bold' : 'text-red-600 font-bold'}>
                                        {record.vehicle_handover || '-'}
                                    </span>
                                </div>
                                {record.vehicle_detail && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-exclamation-circle text-red-400"></i> {record.vehicle_detail}</div>}
                            </div>

                            <div className="flex flex-col">
                                <div className="flex justify-between">
                                    <span className="font-semibold text-slate-700">สภาพร่างกาย:</span>
                                    <span className={record.body_condition_checkout === 'ปกติ' ? 'text-green-600 font-bold' : 'text-red-600 font-bold'}>
                                        {record.body_condition_checkout || '-'}
                                    </span>
                                </div>
                                {record.body_detail_checkout && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-exclamation-circle text-red-400"></i> {record.body_detail_checkout}</div>}
                            </div>

                            <div className="flex flex-col">
                                <div className="flex justify-between">
                                    <span className="font-semibold text-slate-700">จุดเสี่ยง:</span>
                                    <span className={record.route_risk === 'ปกติ' ? 'text-green-600 font-bold' : 'text-orange-600 font-bold'}>
                                        {record.route_risk || '-'}
                                    </span>
                                </div>
                                {record.route_detail && <div className="text-slate-600 text-xs mt-1 bg-white p-2 rounded border border-purple-100"><i className="fas fa-map-marker-alt text-orange-400"></i> {record.route_detail}</div>}
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
    </Card>
  );

  const renderTenkoInputSection = () => (
    <Card className="h-fit border-l-4 border-blue-500">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex items-center gap-2">
            <i className="fas fa-user-shield"></i> ส่วนบันทึกของ Tenko
        </h3>

        {(type === 'checkin' || type === 'view') && (
            <div className="space-y-4">
                <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                    <h4 className="font-bold text-blue-800 mb-3"><i className="fas fa-stethoscope"></i> ข้อมูลสัญญาณชีพ (กรอกต่อเนื่อง)</h4>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-4">
                            <Input 
                                label="1. อุณหภูมิ (°C)" 
                                type="number" step="0.1"
                                placeholder="36.5"
                                autoFocus
                                value={form.temperature || ''} 
                                onChange={e => updateForm('temperature', parseFloat(e.target.value))}
                                className={isTempBad(form.temperature) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="3. ความดันตัวบน (Sys)" 
                                type="number" 
                                placeholder="120"
                                value={form.blood_pressure_high || ''} 
                                onChange={e => updateForm('blood_pressure_high', parseFloat(e.target.value))} 
                                className={isBPHighBad(form.blood_pressure_high) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                        <div className="space-y-4">
                            <Input 
                                label="2. แอลกอฮอล์ (mg%)" 
                                type="number" 
                                placeholder="0"
                                value={form.alcohol_checkin} 
                                onChange={e => updateForm('alcohol_checkin', parseFloat(e.target.value))}
                                className={isAlcoholBad(form.alcohol_checkin) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                            />
                            <Input 
                                label="4. ความดันตัวล่าง (Dia)" 
                                type="number" 
                                placeholder="80"
                                value={form.blood_pressure_low || ''} 
                                onChange={e => updateForm('blood_pressure_low', parseFloat(e.target.value))} 
                                className={isBPLowBad(form.blood_pressure_low) ? 'border-red-500 bg-red-50' : ''} 
                            />
                        </div>
                    </div>
                    {isAlcoholBad(form.alcohol_checkin) && (
                         <Input className="mt-3" placeholder="ระบุเหตุผลค่าแอลกอฮอล์" value={form.alcohol_checkin_reason || ''} onChange={e => updateForm('alcohol_checkin_reason', e.target.value)} />
                    )}
                </div>

                <div className="p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold block mb-2 text-sm text-slate-700">การใช้โทรศัพท์</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.phone_usage_compliant === 'ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ตรงตามที่แจ้ง')}>ตรงตามที่แจ้ง</OptionButton>
                        <OptionButton selected={form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง'} onClick={() => updateForm('phone_usage_compliant', 'ไม่ตรงตามที่แจ้ง')}>ไม่ตรงตามที่แจ้ง</OptionButton>
                    </div>
                    {form.phone_usage_compliant === 'ไม่ตรงตามที่แจ้ง' && (
                        <div className="space-y-2 mt-2">
                             <Input placeholder="ระบุสาเหตุ" value={form.phone_usage_reason || ''} onChange={e => updateForm('phone_usage_reason', e.target.value)} />
                        </div>
                    )}
                </div>

                <div className="flex items-center justify-between p-3 border rounded-lg bg-slate-50">
                    <label className="font-bold text-slate-700">อนุญาตให้ปฏิบัติงาน?</label>
                    <div className="flex gap-2">
                        <OptionButton selected={form.can_work === 'ได้'} onClick={() => updateForm('can_work', 'ได้')}>ได้</OptionButton>
                        <OptionButton selected={form.can_work === 'ไม่ได้'} onClick={() => updateForm('can_work', 'ไม่ได้')}>ไม่ได้</OptionButton>
                    </div>
                </div>
                {form.can_work === 'ไม่ได้' && (
                        <Input placeholder="ระบุสาเหตุที่ไม่อนุญาต" value={form.cannot_work_reason || ''} onChange={e => updateForm('cannot_work_reason', e.target.value)} />
                )}
            </div>
        )}

        {(type === 'checkout' || type === 'view') && (
            <div className="space-y-4 mt-6 border-t pt-4">
                <div className="bg-purple-50 p-4 rounded-xl border border-purple-100">
                    <h4 className="font-bold text-purple-800 mb-3">ตรวจสอบหลังเลิกงาน</h4>
                    <div className="grid grid-cols-2 gap-4">
                         <Input 
                            label="แอลกอฮอล์ (ต้อง 0)" 
                            type="number" 
                            autoFocus
                            value={form.alcohol_checkout} 
                            onChange={e => updateForm('alcohol_checkout', parseFloat(e.target.value))}
                            className={isAlcoholBad(form.alcohol_checkout) ? 'border-red-500 bg-red-50 text-red-700' : ''} 
                         />
                         {isAlcoholBad(form.alcohol_checkout) && (
                             <Input label="เหตุผล" placeholder="ระบุเหตุผล" value={form.alcohol_checkout_reason || ''} onChange={e => updateForm('alcohol_checkout_reason', e.target.value)} />
                         )}
                    </div>

                     <div className="mt-4">
                        <label className="block text-sm font-semibold mb-2">ข้อละเมิดการขับขี่?</label>
                        <div className="flex gap-2">
                            <OptionButton selected={form.driving_violation === 'ไม่มี'} onClick={() => updateForm('driving_violation', 'ไม่มี')}>ไม่มี</OptionButton>
                            <OptionButton selected={form.driving_violation === 'มี'} onClick={() => updateForm('driving_violation', 'มี')}>มี</OptionButton>
                        </div>
                        {form.driving_violation === 'มี' && <Input className="mt-2" placeholder="ระบุรายละเอียด" value={form.violation_detail || ''} onChange={e => updateForm('violation_detail', e.target.value)} />}
                    </div>
                </div>
            </div>
        )}

        <div className="bg-yellow-50 p-3 rounded border border-yellow-200 mt-4">
            <label className="block text-sm font-bold mb-1 text-yellow-800">
                <i className="fas fa-clock"></i> เวลาที่บันทึก
            </label>
            <input 
                type="datetime-local" 
                className="w-full p-2 border rounded bg-white text-sm"
                value={formatDateForInput(type === 'checkout' ? form.checkout_timestamp : form.checkin_timestamp)}
                onChange={e => handleDateChange(e.target.value, type === 'checkout' ? 'checkout_timestamp' : 'checkin_timestamp')}
            />
        </div>

        <div className="mt-6 flex flex-col gap-3">
            <Button onClick={handleApprove} isLoading={submitting} className="w-full bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 py-3 text-lg">
                <i className="fas fa-save"></i> บันทึกข้อมูล (Save)
            </Button>

            <Button onClick={handleDelete} isLoading={submitting} variant="danger" className="w-full bg-white text-red-600 border-2 border-red-200 hover:bg-red-50 hover:border-red-500">
                <i className="fas fa-trash-alt"></i> ลบข้อมูล (เพื่อให้ส่งใหม่)
            </Button>
        </div>
    </Card>
  );

  return (
    <div className="space-y-4 max-w-6xl mx-auto pb-10 flex flex-col">
      <div className="flex justify-between items-center shrink-0">
        <h2 className="text-2xl font-bold text-slate-800">
          {type === 'checkin' ? 'คิวตรวจสอบ (ก่อนงาน)' : type === 'checkout' ? 'คิวตรวจสอบ (หลังงาน)' : 'แก้ไขข้อมูล'}
        </h2>
        <Button variant="secondary" onClick={onBack}>ย้อนกลับ</Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {renderDriverDataSection()}
        {renderTenkoInputSection()}
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
  onDelete: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord, onDelete }) => {
  const [filterMode, setFilterMode] = useState<'all' | 'ng'>('all');
  const today = new Date().toISOString().split('T')[0];

  const getMonday = (dateStr: string) => {
    const d = new Date(dateStr);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff)).toISOString().split('T')[0];
  };

  const calculateResult = (targetTime: string, refMinutes: number) => {
      const d = new Date(targetTime);
      const m = d.getHours() * 60 + d.getMinutes();
      return Math.abs(m - refMinutes) > 120 ? 'NG' : 'OK';
  };

  const getFixStartInfo = (targetRecord: TenkoRecord) => {
    const driverApproved = records
      .filter(r => r.driver_id === targetRecord.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
      .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const targetDate = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp || targetRecord.date;
    const targetMonday = getMonday(targetDate);

    const weekRecords = driverApproved.filter(r => getMonday(r.checkin_timestamp!) === targetMonday);
    const mondayRecord = weekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
    const referenceRecord = mondayRecord || weekRecords[0];

    if (!referenceRecord) return { status: 'New', time: '--:--' };

    const refDate = new Date(referenceRecord.checkin_timestamp!);
    const refMinutes = refDate.getHours() * 60 + refDate.getMinutes();
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    const checkTimeStr = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp;
    if (!checkTimeStr) return { status: 'OK', time: displayTime };

    const result = calculateResult(checkTimeStr, refMinutes);
    return { status: result, time: displayTime };
  };

  // Pre-calculate lists with filtering support
  const { pendingCheckin, activeDrivers, pendingCheckout, completed } = useMemo(() => {
    let filtered = records;
    if (filterMode === 'ng') {
        filtered = records.filter(r => getFixStartInfo(r).status === 'NG');
    }

    return {
        pendingCheckin: filtered.filter(r => r.checkin_status === 'pending'),
        activeDrivers: filtered.filter(r => r.checkin_status === 'approved' && !r.checkout_status),
        pendingCheckout: filtered.filter(r => r.checkout_status === 'pending'),
        completed: records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved')
    };
  }, [records, filterMode]);

  const stats = useMemo(() => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();

    const monthApproved = records.filter(r => {
      if (!r.checkin_timestamp || r.checkin_status !== 'approved') return false;
      const d = new Date(r.checkin_timestamp);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const ngDrivers = new Set();
    let totalNGCount = 0;

    monthApproved.forEach(r => {
      const info = getFixStartInfo(r);
      if (info.status === 'NG') {
        totalNGCount++;
        ngDrivers.add(r.driver_id);
      }
    });

    return { totalNGCount, uniqueNGDrivers: ngDrivers.size };
  }, [records]);

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
      const d = new Date(dateStr);
      return isNaN(d.getTime()) ? '-' : d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });
    } catch { return '-'; }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    const info = getFixStartInfo(record);
    if (info.status === 'New') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-slate-100 text-slate-500 border border-slate-200">First Entry</span>;

    return (
      <span className={`ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold border whitespace-nowrap ${
        info.status === 'NG' ? 'bg-red-100 text-red-600 border-red-200' : 'bg-emerald-100 text-emerald-600 border-emerald-200'
      }`}>
        {info.status} (Ref: {info.time})
      </span>
    );
  };

  const renderStats = () => (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 mb-8">
      <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none shadow-amber-200">
        <h3 className="text-amber-100 mb-1 text-sm">รอตรวจก่อนงาน</h3>
        <div className="text-3xl font-bold">{pendingCheckin.length}</div>
      </Card>
      <Card className="bg-gradient-to-br from-blue-500 to-cyan-600 text-white border-none shadow-blue-200">
        <h3 className="text-blue-100 mb-1 text-sm">กำลังปฏิบัติงาน</h3>
        <div className="text-3xl font-bold">{activeDrivers.length}</div>
      </Card>
      <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none shadow-purple-200">
        <h3 className="text-purple-100 mb-1 text-sm">รอตรวจหลังงาน</h3>
        <div className="text-3xl font-bold">{pendingCheckout.length}</div>
      </Card>
      <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none shadow-emerald-200">
        <h3 className="text-emerald-100 mb-1 text-sm">เสร็จสิ้นแล้ว</h3>
        <div className="text-3xl font-bold">{completed.length}</div>
      </Card>
      <Card className={`${stats.totalNGCount > 0 ? 'bg-red-600 shadow-red-200' : 'bg-blue-900 shadow-blue-900/20'} text-white border-none`}>
        <h3 className="text-white/80 mb-1 text-sm">NG Fix Start</h3>
        <div className="text-3xl font-bold">{stats.totalNGCount} <span className="text-xs font-normal opacity-70">ครั้ง</span></div>
        <p className="text-[10px] mt-1 text-white/60">พนักงาน {stats.uniqueNGDrivers} ท่าน (เดือนนี้)</p>
      </Card>
      <Card className="bg-white border-l-4 border-blue-500">
        <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
        <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
      </Card>
    </div>
  );

  const renderQueueList = (title: string, icon: string, items: TenkoRecord[], color: string) => (
    <Card className={`flex flex-col h-full bg-white border-t-4 border-${color}-500 shadow-lg`}>
      <div className="flex justify-between items-center mb-4">
        <h3 className={`font-bold text-${color}-700 text-lg flex items-center gap-2`}>
          <i className={`fas ${icon}`}></i> {title}
        </h3>
        <span className={`bg-${color}-100 text-${color}-800 text-xs px-2.5 py-1 rounded-full font-bold`}>{items.length}</span>
      </div>
      <div className="flex-1 overflow-y-auto pr-2 space-y-2 custom-scrollbar">
        {items.map(r => (
          <div key={r.__backendId} className="group relative flex items-center gap-2">
            <div 
                onClick={() => onSelectRecord(r.__backendId)} 
                className="flex-1 flex justify-between p-3 bg-white hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-all hover:border-blue-200"
            >
                <div>
                  <p className="font-semibold text-slate-700 flex items-center flex-wrap gap-1">
                    {r.driver_name}
                    {getFixStartBadge(r)}
                  </p>
                  <p className="text-[10px] text-slate-400">ID: {r.driver_id} • {new Date(r.date).toLocaleDateString('th-TH')}</p>
                </div>
                <div className="text-right flex items-center gap-3">
                  <p className="text-sm font-bold text-slate-600">{getSafeTime(title.includes('หลังเลิกงาน') ? r.checkout_real_timestamp : r.checkin_real_timestamp)}</p>
                  <i className="fas fa-chevron-right text-slate-300 group-hover:text-blue-500 transition-colors"></i>
                </div>
            </div>
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(r.__backendId); }}
                className="opacity-0 group-hover:opacity-100 transition-opacity w-10 h-10 flex items-center justify-center text-red-400 hover:text-red-600 hover:bg-red-50 rounded-full"
                title="ลบรายการ"
            >
                <i className="fas fa-trash-alt"></i>
            </button>
          </div>
        ))}
        {items.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-300 py-10">
            <i className={`fas ${filterMode === 'ng' ? 'fa-shield-heart' : 'fa-check-circle'} text-4xl mb-2`}></i>
            <p className="text-sm">{filterMode === 'ng' ? 'ไม่พบรายการที่ติด NG' : 'ไม่มีรายการค้าง'}</p>
          </div>
        )}
      </div>
    </Card>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10 animate-fade-in">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
            <h1 className="text-2xl font-bold flex items-center gap-3 text-slate-800">
                <i className="fas fa-tachometer-alt text-blue-600"></i> แผงควบคุมเจ้าหน้าที่
            </h1>

            {/* Filter Menu */}
            <div className="flex bg-slate-200 p-1 rounded-lg shadow-inner w-full sm:w-auto">
                <button 
                    onClick={() => setFilterMode('all')}
                    className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                    พนักงานทั้งหมด
                </button>
                <button 
                    onClick={() => setFilterMode('ng')}
                    className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${filterMode === 'ng' ? 'bg-red-500 text-white shadow-sm' : 'text-slate-500'}`}
                >
                    <i className="fas fa-exclamation-triangle"></i>
                    เฉพาะคนติด NG
                </button>
            </div>
        </div>

        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
          {renderQueueList('รอตรวจก่อนเริ่มงาน', 'fa-clock', pendingCheckin, 'amber')}
          {renderQueueList('พนักงานกำลังปฏิบัติงาน', 'fa-truck-moving', activeDrivers, 'blue')}
          {renderQueueList('รอตรวจหลังเลิกงาน', 'fa-flag-checkered', pendingCheckout, 'purple')}
        </div>
        <style>{`
          .custom-scrollbar::-webkit-scrollbar { width: 5px; }
          .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
          .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
          .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
          .animate-fade-in { animation: fadeIn 0.4s ease-out; }
          @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        `}</style>
      </div>
    );
  }

  if (view === 'queue-checkin') return <div className="animate-fade-in h-[600px]">{renderQueueList('รอตรวจก่อนเริ่มงาน', 'fa-clock', pendingCheckin, 'amber')}</div>;
  if (view === 'queue-checkout') return <div className="animate-fade-in h-[600px]">{renderQueueList('รอตรวจหลังเลิกงาน', 'fa-flag-checkered', pendingCheckout, 'purple')}</div>;

  return null;
};

import React, { useState, useMemo, useEffect } from 'react';
import { TenkoRecord, User } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import * as XLSX from 'xlsx';

interface Props {
  records: TenkoRecord[];
}

export const TenkoAnalytics: React.FC<Props> = ({ records }) => {
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(today);
  const [selectedDriverId, setSelectedDriverId] = useState<string>(''); // Filter state
  const [drivers, setDrivers] = useState<User[]>([]);
  const [showNGModal, setShowNGModal] = useState(false);

  useEffect(() => {
    StorageService.getUsers().then(users => {
        setDrivers(users.filter(u => u.role === 'driver'));
    });
  }, []);

  // --- NG Logic Helpers ---
  const getMonday = (dateStr: string) => {
    const d = new Date(dateStr);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff)).toISOString().split('T')[0];
  };

  const calculateResult = (targetTime: string, refMinutes: number) => {
      const d = new Date(targetTime);
      const m = d.getHours() * 60 + d.getMinutes();
      return Math.abs(m - refMinutes) > 120 ? 'NG' : 'OK';
  };

  const getFixStartInfo = (targetRecord: TenkoRecord) => {
    const driverApproved = records
      .filter(r => r.driver_id === targetRecord.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
      .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const targetDate = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp || targetRecord.date;
    const targetMonday = getMonday(targetDate);

    const weekRecords = driverApproved.filter(r => getMonday(r.checkin_timestamp!) === targetMonday);
    const mondayRecord = weekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
    const referenceRecord = mondayRecord || weekRecords[0];

    if (!referenceRecord) return { status: 'New', time: '--:--' };

    const refDate = new Date(referenceRecord.checkin_timestamp!);
    const refMinutes = refDate.getHours() * 60 + refDate.getMinutes();
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    const checkTimeStr = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp;
    if (!checkTimeStr) return { status: 'OK', time: displayTime };

    const result = calculateResult(checkTimeStr, refMinutes);
    return { status: result, time: displayTime, refTime: displayTime };
  };

  // --- Filtering Logic ---
  const filteredRecords = useMemo(() => {
    let res = records;
    if (selectedDriverId) {
        res = res.filter(r => r.driver_id === selectedDriverId);
    }
    return res;
  }, [records, selectedDriverId]);

  const monthRecords = useMemo(() => {
    return filteredRecords.filter(r => {
        const parts = r.date.split('-');
        if (parts.length !== 3) return false;
        const rYear = parseInt(parts[0]);
        const rMonth = parseInt(parts[1]) - 1;
        return rMonth === currentMonth.getMonth() && rYear === currentMonth.getFullYear();
    });
  }, [filteredRecords, currentMonth]);

  const ngRecords = useMemo(() => {
      return monthRecords.filter(r => getFixStartInfo(r).status === 'NG');
  }, [monthRecords, records]);

  // --- Graph Data ---
  const graphData = useMemo(() => {
    const sorted = [...monthRecords]
        .filter(r => r.blood_pressure_high && r.blood_pressure_low)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    return sorted.slice(-5);
  }, [monthRecords]);


  // --- Export Logic ---
  const exportExcel = () => {
    const data = monthRecords.map(r => {
        const formatDetail = (status?: string, detail?: string) => {
            if (!status) return '-';
            return detail ? `${status} (${detail})` : status;
        };

        const sleepInfo = r.sleep_hours 
            ? `${r.sleep_hours} ชม. (${r.sleep_start || '-'} - ${r.sleep_end || '-'}) ${r.sleep_quality || ''}`
            : '-';

        const extraSleepInfo = r.extra_sleep === 'นอนเพิ่ม'
            ? `${r.extra_sleep_hours} ชม. (${r.extra_sleep_start || '-'} - ${r.extra_sleep_end || '-'}) ${r.extra_sleep_quality || ''}`
            : 'ไม่นอนเพิ่ม';

        return {
            "วันที่": r.date,
            "ชื่อพนักงาน": r.driver_name,
            "รหัสพนักงาน": r.driver_id,
            "ความเหนื่อยล้า": formatDetail(r.tired, r.tired_detail),
            "การเจ็บป่วย": r.sick === 'มี' ? `มี (${r.sick_detail || '-'}) หาหมอ: ${r.seen_doctor || '-'}` : 'ไม่มี',
            "ความง่วง": formatDetail(r.drowsy, r.drowsy_detail),
            "การบาดเจ็บ": formatDetail(r.injury, r.injury_detail),
            "การใช้ยา": r.medication === 'ทาน' ? `ทาน (${r.medication_name || '-'})` : 'ไม่ทาน',
            "สภาพร่างกาย(ก่อน)": formatDetail(r.body_condition, r.body_condition_detail),
            "การนอนหลับ": sleepInfo,
            "การนอนเพิ่ม": extraSleepInfo,
            "เรื่องกังวลใจ": formatDetail(r.worry_detail, r.worry_text),
            "สถานที่พักผ่อน": formatDetail(r.rest_location, r.rest_location_detail),
            "ปัญหาสายตา": `${r.vision_problem || '-'} (แว่น: ${r.glasses || '-'})`,
            "การได้ยิน": `${r.hearing_problem || '-'} (เครื่องช่วย: ${r.hearing_aid || '-'})`,
            "เวลาเข้างาน (อนุมัติ)": r.checkin_timestamp ? new Date(r.checkin_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เข้างาน)": r.checkin_tenko_name || '-',
            "อุณหภูมิ": r.temperature || '-',
            "ความดัน": `${r.blood_pressure_high || '-'}/${r.blood_pressure_low || '-'}`,
            "แอลกอฮอล์ (เข้า)": r.alcohol_checkin || 0,
            "เหตุผลแอลกอฮอล์(เข้า)": r.alcohol_checkin_reason || '-',
            "การใช้โทรศัพท์": formatDetail(r.phone_usage_compliant, r.phone_usage_reason),
            "ผลประเมิน": formatDetail(r.can_work, r.cannot_work_reason),
            "การส่งมอบรถ": formatDetail(r.vehicle_handover, r.vehicle_detail),
            "สภาพร่างกาย(หลัง)": formatDetail(r.body_condition_checkout, r.body_detail_checkout),
            "จุดเสี่ยง": formatDetail(r.route_risk, r.route_detail),
            "เวลาเลิกงาน (อนุมัติ)": r.checkout_timestamp ? new Date(r.checkout_timestamp).toLocaleTimeString('th-TH') : '-',
            "ผู้ตรวจ (เลิกงาน)": r.checkout_tenko_name || '-',
            "แอลกอฮอล์ (ออก)": r.alcohol_checkout || 0,
            "เหตุผลแอลกอฮอล์(ออก)": r.alcohol_checkout_reason || '-',
            "ข้อละเมิดการขับขี่": formatDetail(r.driving_violation, r.violation_detail)
        };
    });

    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "TenkoReport");
    XLSX.writeFile(wb, `Tenko_Full_Export_${selectedDriverId || 'ALL'}_${currentMonth.toISOString().slice(0,7)}.xlsx`);
  };

  // --- Calendar Helpers ---
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  const getDayCount = (day: number) => {
    const y = currentMonth.getFullYear();
    const m = String(currentMonth.getMonth() + 1).padStart(2, '0');
    const d = String(day).padStart(2, '0');
    const target = `${y}-${m}-${d}`;
    return filteredRecords.filter(r => r.date === target).length;
  };

  // --- SVG Graph Render ---
  const renderBPGraph = () => {
    if (graphData.length < 2) return <div className="h-64 flex items-center justify-center text-slate-400 bg-slate-50 rounded-lg border border-dashed">ข้อมูลไม่เพียงพอสำหรับกราฟ (ต้องมีอย่างน้อย 2 วัน)</div>;

    const svgHeight = 300;
    const svgWidth = 800;
    const paddingX = 80;
    const paddingY = 40;
    const maxVal = 180;
    const minVal = 50;
    const range = maxVal - minVal;
    const drawingHeight = svgHeight - (paddingY * 2);
    const drawingWidth = svgWidth - (paddingX * 2);

    const getX = (i: number) => paddingX + (i / (graphData.length - 1)) * drawingWidth;
    const getY = (val: number) => (svgHeight - paddingY) - ((val - minVal) / range) * drawingHeight;

    const pointsHigh = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_high || 0)}`).join(' ');
    const pointsLow = graphData.map((d, i) => `${getX(i)},${getY(d.blood_pressure_low || 0)}`).join(' ');

    return (
        <div className="relative h-[320px] w-full p-2">
            <svg viewBox={`0 0 ${svgWidth} ${svgHeight}`} className="w-full h-full overflow-visible drop-shadow-sm">
                {[60, 90, 120, 150].map((val) => (
                    <g key={val}>
                        <line x1={paddingX - 10} y1={getY(val)} x2={svgWidth - paddingX + 10} y2={getY(val)} stroke="#e2e8f0" strokeWidth="1" />
                        <text x={paddingX - 20} y={getY(val) + 4} fontSize="12" fill="#94a3b8" textAnchor="end">{val}</text>
                    </g>
                ))}
                <polyline points={pointsHigh} fill="none" stroke="#ef4444" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
