import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import { CheckinForm } from './CheckinForm';
import { CheckoutForm } from './CheckoutForm';
import { DriverHistory } from './DriverHistory';
import { SYSTEM_VERSION } from '../../constants';

interface DriverAppProps {
  user: User;
  onLogout: () => void;
}

export const DriverApp: React.FC<DriverAppProps> = ({ user, onLogout }) => {
  const [view, setView] = useState<'home' | 'checkin' | 'checkout' | 'history'>('home');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [pendingCount, setPendingCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'online' | 'offline' | 'error'>('online');

  const fetchData = async () => {
      try {
          await StorageService.syncPendingData();
          const data = await StorageService.getAll();
          setRecords(data);
          setPendingCount(StorageService.getPendingCount());
          setConnectionStatus(StorageService.getConnectionStatus());
      } catch(e) {
          console.error(e);
          setConnectionStatus('offline');
      } finally {
          setIsLoading(false);
      }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 15000);
    return () => clearInterval(interval);
  }, []);

  const getTodayStr = () => {
      const now = new Date();
      return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const today = getTodayStr();
  const myRecords = records
    .filter(r => r.driver_id === user.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const activeRecord = myRecords[0]; 
  const isCurrentSession = activeRecord && (
      activeRecord.date === today || 
      (!activeRecord.checkout_status && (new Date().getTime() - new Date(activeRecord.checkin_real_timestamp || activeRecord.date).getTime()) < 24 * 60 * 60 * 1000)
  );

  const currentRecord = isCurrentSession ? activeRecord : null;

  const checkFixStartTime = () => {
    // Look for all records of the week (including pending/current) to find the baseline
    const getMonday = (dateStr: string) => {
        const d = new Date(dateStr);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? -6 : 1);
        const monday = new Date(d.setDate(diff));
        return `${monday.getFullYear()}-${String(monday.getMonth()+1).padStart(2,'0')}-${String(monday.getDate()).padStart(2,'0')}`;
    };

    const thisWeekMonday = getMonday(today);
    const thisWeekRecords = myRecords.filter(r => getMonday(r.date) === thisWeekMonday);

    // Reference is the earliest approved record, OR if none, the earliest record of the week
    const approvedThisWeek = thisWeekRecords
        .filter(r => r.checkin_status === 'approved')
        .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const referenceRecord = approvedThisWeek.length > 0 
        ? approvedThisWeek[0] 
        : (thisWeekRecords.length > 0 ? thisWeekRecords[thisWeekRecords.length - 1] : null);

    if (!referenceRecord) return { status: 'New', time: '--:--' };

    const refTimeSource = referenceRecord.checkin_timestamp || referenceRecord.checkin_real_timestamp;
    const refDate = new Date(refTimeSource!);
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    // If we only have 1 record this week, it's the "Baseline" (Reference)
    if (thisWeekRecords.length === 1 && (!currentRecord || currentRecord.checkin_status !== 'approved')) {
        return { status: 'Ref', time: displayTime };
    }

    // Comparison logic
    if (currentRecord && currentRecord.checkin_timestamp) {
        const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
        const checkDate = new Date(currentRecord.checkin_timestamp);
        const checkTime = checkDate.getHours() * 60 + checkDate.getMinutes();
        if (Math.abs(checkTime - refTotalMinutes) > 120) return { status: 'NG', time: displayTime };
    }

    return { status: 'OK', time: displayTime };
  };

  const canStartCheckin = () => {
     if (currentRecord) {
         if (currentRecord.checkin_status === 'approved' && currentRecord.checkout_status === 'approved') return { allowed: true };
         return { allowed: false, message: "คุณมีรายการที่ยังทำไม่จบ" };
     }
     return { allowed: true };
  };

  const checkinStatus = canStartCheckin();
  const fixData = checkFixStartTime();

  const handleDataUpdate = () => {
      setIsLoading(true);
      fetchData().then(() => {
          setView('home');
          setIsLoading(false);
      });
  };

  if (view === 'checkin') return <CheckinForm user={user} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'checkout') return <CheckoutForm user={user} record={currentRecord!} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'history') return <DriverHistory user={user} records={records} onBack={() => setView('home')} fixStartTime={fixData.status} displayTime={fixData.time} />;

  return (
    <div className="h-full bg-slate-50 flex flex-col overflow-hidden animate-fade-in">
      <header className="bg-gradient-to-r from-blue-700 to-blue-500 text-white p-4 md:p-6 shadow-lg shrink-0 z-10">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-xl md:text-2xl font-bold flex items-center gap-2">
              <i className="fas fa-user-circle"></i> {user.name}
            </h1>
            <div className="flex items-center gap-3 text-sm opacity-80 mt-1">
                <span>รหัส: {user.id}</span>
                <Badge type={fixData.status === 'OK' || fixData.status === 'Ref' ? 'approved' : 'danger'}>
                    Fix Start: {fixData.status === 'Ref' ? 'Baseline' : fixData.status}
                </Badge>
            </div>
          </div>
          <div className="flex flex-col items-end gap-2">
              <Button variant="secondary" size="sm" onClick={onLogout} className="border-white text-white hover:bg-white/20 px-3 h-8">
                  <i className="fas fa-sign-out-alt"></i> ออก
              </Button>
              <div className="text-[10px] font-bold opacity-60">{connectionStatus === 'online' ? '● Online' : '○ Offline'}</div>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 md:p-6 w-full flex-1 overflow-y-auto">
        <div className="space-y-4 md:space-y-6">
            {currentRecord && currentRecord.checkin_status === 'pending' && (
                <Card className="bg-amber-50 border-amber-500 py-4 px-6 border-l-4 shadow-sm animate-pulse">
                    <div className="flex items-center gap-4 text-amber-800">
                        <i className="fas fa-hourglass-half text-2xl"></i>
                        <div>
                            <h3 className="font-bold">ส่งข้อมูลแล้ว รอเจ้าหน้าที่ตรวจสอบ</h3>
                            <p className="text-sm opacity-90">กรุณาแจ้งชื่อพนักงานให้เจ้าหน้าที่ Tenko ทราบ</p>
                        </div>
                    </div>
                </Card>
            )}

            {currentRecord && currentRecord.checkin_status === 'approved' && !currentRecord.checkout_status && (
                <Card className="bg-emerald-50 border-emerald-600 py-5 px-6 border-l-4 shadow-md">
                    <div className="flex items-center gap-4 text-emerald-900">
                        <div className="bg-emerald-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl shadow-lg">
                            <i className="fas fa-check-circle"></i>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <h3 className="font-black text-lg">ตรวจผ่านแล้ว - เริ่มงานได้</h3>
                                <Badge type="approved">ACTIVE</Badge>
                            </div>
                            <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-1 text-xs font-bold text-emerald-800/70">
                                <p><i className="fas fa-clock mr-1.5"></i> ตรวจเมื่อ: {new Date(currentRecord.checkin_timestamp!).toLocaleTimeString('th-TH', {hour:'2-digit', minute:'2-digit'})} น.</p>
                                <p><i className="fas fa-user-shield mr-1.5"></i> ผู้ตรวจ: {currentRecord.checkin_tenko_name || '-'}</p>
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <Card onClick={() => checkinStatus.allowed ? setView('checkin') : alert(checkinStatus.message)} className={`flex flex-col items-center justify-center p-6 hover:border-blue-400 transition-all ${!checkinStatus.allowed ? 'opacity-50 grayscale' : 'border-blue-100'}`}>
                    <div className="w-14 h-14 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-3 text-2xl"><i className="fas fa-clipboard-check"></i></div>
                    <h3 className="font-bold text-slate-800">ก่อนเริ่มงาน</h3>
                    {!checkinStatus.allowed && <p className="text-red-500 text-[10px] mt-1 font-bold">{checkinStatus.message}</p>}
                </Card>

                <Card onClick={() => (currentRecord?.checkin_status === 'approved' && !currentRecord.checkout_status) ? setView('checkout') : alert('ยังไม่สามารถเลิกงานได้')} className={`flex flex-col items-center justify-center p-6 hover:border-emerald-400 transition-all ${(!currentRecord || currentRecord.checkin_status !== 'approved' || currentRecord.checkout_status) ? 'opacity-50 grayscale' : 'border-emerald-100'}`}>
                    <div className="w-14 h-14 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-3 text-2xl"><i className="fas fa-flag-checkered"></i></div>
                    <h3 className="font-bold text-slate-800">หลังเลิกงาน</h3>
                </Card>

                <Card onClick={() => setView('history')} className="flex flex-col items-center justify-center p-6 hover:border-purple-400 border-purple-50 transition-all">
                    <div className="w-14 h-14 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mb-3 text-2xl"><i className="fas fa-history"></i></div>
                    <h3 className="font-bold text-slate-800">รายงานของฉัน</h3>
                </Card>
            </div>

            <div className="mt-8 text-center bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                <p className="text-sm text-slate-500 mb-1">เวลาอ้างอิง Fix Start Time สัปดาห์นี้</p>
                <p className="text-3xl font-black text-blue-600 tracking-tight">{fixData.time}</p>
                <div className="flex justify-center gap-2 mt-2">
                    {fixData.status === 'Ref' ? (
                        <span className="text-[11px] bg-blue-100 text-blue-700 px-3 py-1 rounded-full font-bold">
                            <i className="fas fa-star mr-1"></i> เป็นวันแรก (ใช้เป็นเวลาอ้างอิง)
                        </span>
                    ) : (
                        <Badge type={fixData.status === 'OK' ? 'approved' : 'danger'}>สถานะ: {fixData.status}</Badge>
                    )}
                </div>
            </div>
        </div>
      </main>
      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

import React from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, Badge } from '../../components/UI';

interface Props {
  user: User;
  records: TenkoRecord[];
  onBack: () => void;
  fixStartTime: string;
  displayTime: string;
}

export const DriverHistory: React.FC<Props> = ({ user, records, onBack, fixStartTime, displayTime }) => {
  const myRecords = records
    .filter(r => r.driver_id === user.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const currentMonth = new Date();
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  const getDayStatus = (day: number) => {
    const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const record = myRecords.find(r => r.date === dateStr);

    if (!record) return 'none';
    if (record.checkin_status === 'approved' && record.checkout_status === 'approved') return 'complete';
    if (record.checkin_status === 'approved') return 'working';
    return 'pending';
  };

  const getStatusBadge = (r: TenkoRecord) => {
      if (r.checkin_status === 'approved' && r.checkout_status === 'approved') return <Badge type="approved">เสร็จสมบูรณ์</Badge>;
      if (r.checkin_status === 'approved') return <Badge type="pending">กำลังปฏิบัติงาน</Badge>;
      return <Badge type="danger">รอตรวจสอบ</Badge>;
  };

  return (
    <div className="h-full bg-slate-50 overflow-y-auto pb-10">
      <div className="bg-purple-600 text-white px-6 py-6 shadow-md">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
            <div>
                <h2 className="text-2xl font-bold">รายงานของฉัน</h2>
                <p className="opacity-80">ประวัติการปฏิบัติงานและการตรวจสอบ</p>
            </div>
            <Button onClick={onBack} variant="secondary" className="border-white text-white hover:bg-white/20">ย้อนกลับ</Button>
        </div>
      </div>

      <div className="max-w-4xl mx-auto p-6 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
             <Card className="bg-white border-l-4 border-blue-500">
                 <p className="text-sm text-slate-500">เดือนนี้</p>
                 <p className="text-3xl font-bold text-blue-600">{myRecords.filter(r => new Date(r.date).getMonth() === currentMonth.getMonth()).length}</p>
                 <p className="text-xs text-slate-400">รายการ</p>
             </Card>
             <Card className="bg-white border-l-4 border-purple-500">
                 <p className="text-sm text-slate-500">ทั้งหมด</p>
                 <p className="text-3xl font-bold text-purple-600">{myRecords.length}</p>
                 <p className="text-xs text-slate-400">รายการ</p>
             </Card>
             <Card className={`bg-white border-l-4 ${fixStartTime === 'NG' ? 'border-red-500' : 'border-emerald-500'}`}>
                 <p className="text-sm text-slate-500">Fix Start Time สัปดาห์นี้</p>
                 <p className={`text-3xl font-bold ${fixStartTime === 'NG' ? 'text-red-600' : 'text-emerald-600'}`}>
                    {fixStartTime === 'Ref' ? 'Baseline' : `"${fixStartTime}"`}
                 </p>
                 <div className="flex justify-between items-center mt-1">
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Ref Time: {displayTime}</p>
                 </div>
             </Card>
        </div>

        <Card>
            <h3 className="font-bold mb-4 text-slate-700">ปฏิทิน {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</h3>
            <div className="grid grid-cols-7 gap-1">
                {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                {Array.from({length: daysInMonth}).map((_, i) => {
                    const status = getDayStatus(i+1);
                    return (
                        <div key={i} className={`
                            h-10 flex items-center justify-center rounded-lg text-sm font-medium border
                            ${status === 'complete' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' : 
                              status === 'working' ? 'bg-blue-100 text-blue-700 border-blue-200' :
                              status === 'pending' ? 'bg-amber-50 text-amber-600 border-amber-200' : 
                              'bg-slate-50 text-slate-300 border-slate-100'}
                        `}>
                            {i+1}
                        </div>
                    );
                })}
            </div>
        </Card>

        <div className="space-y-4">
            <h3 className="font-bold text-slate-700">รายการล่าสุด (10 รายการ)</h3>
            {myRecords.slice(0, 10).map(record => (
                <Card key={record.__backendId} className="hover:bg-slate-50 transition-colors border border-slate-100">
                    <div className="flex justify-between items-start mb-3 border-b pb-2">
                        <div>
                            <p className="font-bold text-slate-800">
                                {new Date(record.date).toLocaleDateString('th-TH', { dateStyle: 'long' })}
                            </p>
                            <p className="text-[10px] text-slate-400">Record ID: {record.__backendId.substring(0, 8)}</p>
                        </div>
                        {getStatusBadge(record)}
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
                        <div className="p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <p className="font-bold text-blue-800 text-xs mb-1 uppercase tracking-wider">ก่อนเริ่มงาน (Check-in)</p>
                            <div className="space-y-1">
                                <p className="flex justify-between"><span>เวลาอนุมัติ:</span> <span className="font-bold">{record.checkin_timestamp ? new Date(record.checkin_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'} น.</span></p>
                                <p className="flex justify-between"><span>ผู้ตรวจ:</span> <span className="text-slate-600">{record.checkin_tenko_name || '-'}</span></p>
                            </div>
                        </div>
                        <div className={`p-3 rounded-lg border ${record.checkout_status === 'approved' ? 'bg-emerald-50/50 border-emerald-100' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                            <p className="font-bold text-emerald-800 text-xs mb-1 uppercase tracking-wider">หลังเลิกงาน (Check-out)</p>
                            <div className="space-y-1">
                                <p className="flex justify-between items-center">
                                    <span>วัน/เวลาเลิกงาน:</span> 
                                    <span className="font-bold text-right">
                                        {record.checkout_timestamp 
                                            ? new Date(record.checkout_timestamp).toLocaleString('th-TH', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' }) 
                                            : '-'}
                                    </span>
                                </p>
                                <p className="flex justify-between"><span>ผู้ตรวจ:</span> <span className="text-slate-600">{record.checkout_tenko_name || '-'}</span></p>
                            </div>
                        </div>
                    </div>
                </Card>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button } from '../../components/UI';
import * as XLSX from 'xlsx';

interface Props {
  view: string;
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
  onDelete: (id: string) => void;
}

export const TenkoDashboard: React.FC<Props> = ({ view, records, onSelectRecord, onDelete }) => {
  const [filterMode, setFilterMode] = useState<'all' | 'ng'>('all');
  const [showNGModal, setShowNGModal] = useState(false);
  const today = new Date().toISOString().split('T')[0];

  const getMonday = (dateStr: string) => {
    const d = new Date(dateStr);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff)).toISOString().split('T')[0];
  };

  const calculateResult = (targetTime: string, refMinutes: number) => {
      const d = new Date(targetTime);
      const m = d.getHours() * 60 + d.getMinutes();
      return Math.abs(m - refMinutes) > 120 ? 'NG' : 'OK';
  };

  const getFixStartInfo = (targetRecord: TenkoRecord) => {
    const driverApproved = records
      .filter(r => r.driver_id === targetRecord.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
      .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const targetDate = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp || targetRecord.date;
    const targetMonday = getMonday(targetDate);

    const weekRecords = driverApproved.filter(r => getMonday(r.checkin_timestamp!) === targetMonday);
    const mondayRecord = weekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
    const referenceRecord = mondayRecord || (weekRecords.length > 0 ? weekRecords[0] : null);

    if (!referenceRecord) return { status: 'Baseline', time: '--:--' };

    const refDate = new Date(referenceRecord.checkin_timestamp!);
    const refMinutes = refDate.getHours() * 60 + refDate.getMinutes();
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    // If target is the reference record itself
    if (targetRecord.__backendId === referenceRecord.__backendId) {
        return { status: 'Baseline', time: displayTime };
    }

    const checkTimeStr = targetRecord.checkin_timestamp || targetRecord.checkin_real_timestamp;
    if (!checkTimeStr) return { status: 'OK', time: displayTime };

    const result = calculateResult(checkTimeStr, refMinutes);
    return { status: result, time: displayTime };
  };

  const { pendingCheckin, activeDrivers, pendingCheckout, completed, ngRecordsToday } = useMemo(() => {
    const baseRecords = records;
    const todayRecords = records.filter(r => r.date === today);
    const ngToday = todayRecords.filter(r => getFixStartInfo(r).status === 'NG');

    let filtered = baseRecords;
    if (filterMode === 'ng') {
        filtered = baseRecords.filter(r => getFixStartInfo(r).status === 'NG');
    }

    return {
        pendingCheckin: filtered.filter(r => r.checkin_status === 'pending'),
        activeDrivers: filtered.filter(r => r.checkin_status === 'approved' && !r.checkout_status),
        pendingCheckout: filtered.filter(r => r.checkout_status === 'pending'),
        completed: baseRecords.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved'),
        ngRecordsToday: ngToday
    };
  }, [records, filterMode, today]);

  const stats = useMemo(() => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();

    const monthApproved = records.filter(r => {
      if (!r.checkin_timestamp || r.checkin_status !== 'approved') return false;
      const d = new Date(r.checkin_timestamp);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const ngDrivers = new Set();
    let totalNGCount = 0;

    monthApproved.forEach(r => {
      const info = getFixStartInfo(r);
      if (info.status === 'NG') {
        totalNGCount++;
        ngDrivers.add(r.driver_id);
      }
    });

    return { totalNGCount, uniqueNGDrivers: ngDrivers.size };
  }, [records]);

  const getSafeTime = (dateStr?: string | null) => {
    if (!dateStr) return '-';
    try {
      const d = new Date(dateStr);
      return isNaN(d.getTime()) ? '-' : d.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });
    } catch { return '-'; }
  };

  const getFixStartBadge = (record: TenkoRecord) => {
    const info = getFixStartInfo(record);
    if (info.status === 'Baseline') return <span className="ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold bg-blue-50 text-blue-500 border border-blue-200">Baseline</span>;

    return (
      <span className={`ml-2 px-1.5 py-0.5 rounded text-[10px] font-bold border whitespace-nowrap ${
        info.status === 'NG' ? 'bg-red-100 text-red-600 border-red-200' : 'bg-emerald-100 text-emerald-600 border-emerald-200'
      }`}>
        {info.status} (Ref: {info.time})
      </span>
    );
  };

  const renderStats = () => (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-6 mb-8">
      <Card className="bg-gradient-to-br from-amber-500 to-orange-600 text-white border-none shadow-amber-200">
        <h3 className="text-amber-100 mb-1 text-sm">รอตรวจก่อนงาน</h3>
        <div className="text-3xl font-bold">{pendingCheckin.length}</div>
      </Card>
      <Card className="bg-gradient-to-br from-blue-500 to-cyan-600 text-white border-none shadow-blue-200">
        <h3 className="text-blue-100 mb-1 text-sm">กำลังปฏิบัติงาน</h3>
        <div className="text-3xl font-bold">{activeDrivers.length}</div>
      </Card>
      <Card className="bg-gradient-to-br from-purple-500 to-indigo-600 text-white border-none shadow-purple-200">
        <h3 className="text-purple-100 mb-1 text-sm">รอตรวจหลังงาน</h3>
        <div className="text-3xl font-bold">{pendingCheckout.length}</div>
      </Card>
      <Card className="bg-gradient-to-br from-emerald-500 to-teal-600 text-white border-none shadow-emerald-200">
        <h3 className="text-emerald-100 mb-1 text-sm">เสร็จสิ้นแล้ว</h3>
        <div className="text-3xl font-bold">{completed.length}</div>
      </Card>
      <Card 
        className={`${stats.totalNGCount > 0 ? 'bg-red-600 shadow-red-200' : 'bg-blue-900 shadow-blue-900/20'} text-white border-none cursor-pointer hover:scale-105 transition-transform`}
        onClick={() => setShowNGModal(true)}
      >
        <div className="flex justify-between items-start">
            <h3 className="text-white/80 mb-1 text-sm">NG Fix Start</h3>
            <i className="fas fa-list-ul text-xs opacity-50"></i>
        </div>
        <div className="text-3xl font-bold">{stats.totalNGCount} <span className="text-xs font-normal opacity-70">ครั้ง</span></div>
        <p className="text-[10px] mt-1 text-white/60">พนักงาน {stats.uniqueNGDrivers} ท่าน (เดือนนี้)</p>
      </Card>
      <Card className="bg-white border-l-4 border-blue-500">
        <h3 className="text-slate-500 mb-1 text-sm">รายการวันนี้</h3>
        <div className="text-3xl font-bold text-slate-800">{records.filter(r => r.date === today).length}</div>
      </Card>
    </div>
  );

  const renderQueueList = (title: string, icon: string, items: TenkoRecord[], color: string) => (
    <Card className={`flex flex-col h-full bg-white border-t-4 border-${color}-500 shadow-lg`}>
      <div className="flex justify-between items-center mb-4">
        <h3 className={`font-bold text-${color}-700 text-lg flex items-center gap-2`}>
          <i className={`fas ${icon}`}></i> {title}
        </h3>
        <span className={`bg-${color}-100 text-${color}-800 text-xs px-2.5 py-1 rounded-full font-bold`}>{items.length}</span>
      </div>
      <div className="flex-1 overflow-y-auto pr-2 space-y-2 custom-scrollbar">
        {items.map(r => (
          <div key={r.__backendId} className="group relative flex items-center gap-2">
            <div 
                onClick={() => onSelectRecord(r.__backendId)} 
                className="flex-1 flex justify-between p-3 bg-white hover:bg-slate-50 rounded-lg cursor-pointer border border-slate-100 transition-all hover:border-blue-200"
            >
                <div>
                  <p className="font-semibold text-slate-700 flex items-center flex-wrap gap-1">
                    {r.driver_name}
                    {getFixStartBadge(r)}
                  </p>
                  <p className="text-[10px] text-slate-400">ID: {r.driver_id} • {new Date(r.date).toLocaleDateString('th-TH')}</p>
                </div>
                <div className="text-right flex items-center gap-3">
                  <p className="text-sm font-bold text-slate-600">{getSafeTime(title.includes('หลังเลิกงาน') ? r.checkout_real_timestamp : r.checkin_real_timestamp)}</p>
                  <i className="fas fa-chevron-right text-slate-300 group-hover:text-blue-500 transition-colors"></i>
                </div>
            </div>
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(r.__backendId); }}
                className="opacity-0 group-hover:opacity-100 transition-opacity w-10 h-10 flex items-center justify-center text-red-400 hover:text-red-600 hover:bg-red-50 rounded-full"
                title="ลบรายการ"
            >
                <i className="fas fa-trash-alt"></i>
            </button>
          </div>
        ))}
        {items.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-slate-300 py-10">
            <i className={`fas ${filterMode === 'ng' ? 'fa-shield-heart' : 'fa-check-circle'} text-4xl mb-2`}></i>
            <p className="text-sm">{filterMode === 'ng' ? 'ไม่พบรายการที่ติด NG' : 'ไม่มีรายการค้าง'}</p>
          </div>
        )}
      </div>
    </Card>
  );

  if (view === 'dashboard') {
    return (
      <div className="pb-10 animate-fade-in">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
            <h1 className="text-2xl font-bold flex items-center gap-3 text-slate-800">
                <i className="fas fa-tachometer-alt text-blue-600"></i> แผงควบคุมเจ้าหน้าที่
            </h1>

            <div className="flex bg-slate-200 p-1 rounded-lg shadow-inner w-full sm:w-auto">
                <button 
                    onClick={() => setFilterMode('all')}
                    className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                    พนักงานทั้งหมด
                </button>
                <button 
                    onClick={() => setFilterMode('ng')}
                    className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${filterMode === 'ng' ? 'bg-red-500 text-white shadow-sm' : 'text-slate-500'}`}
                >
                    <i className="fas fa-exclamation-triangle"></i>
                    เฉพาะคนติด NG
                </button>
            </div>
        </div>

        {renderStats()}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[500px]">
          {renderQueueList('รอตรวจก่อนเริ่มงาน', 'fa-clock', pendingCheckin, 'amber')}
          {renderQueueList('พนักงานกำลังปฏิบัติงาน', 'fa-truck-moving', activeDrivers, 'blue')}
          {renderQueueList('รอตรวจหลังเลิกงาน', 'fa-flag-checkered', pendingCheckout, 'purple')}
        </div>

        {/* NG Modal for Dashboard */}
        {showNGModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
                <Card className="w-full max-w-4xl max-h-[80vh] flex flex-col shadow-2xl overflow-hidden animate-scale-up">
                    <div className="flex justify-between items-center mb-4 border-b pb-4">
                        <h3 className="text-xl font-bold text-red-700 flex items-center gap-2">
                            <i className="fas fa-exclamation-triangle"></i> รายชื่อพนักงานที่ติดสถานะ NG (เดือนนี้)
                        </h3>
                        <button onClick={() => setShowNGModal(false)} className="text-slate-400 hover:text-slate-600 text-2xl">&times;</button>
                    </div>

                    <div className="overflow-y-auto flex-1 pr-2 custom-scrollbar">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-red-50 text-red-800 font-bold border-b border-red-100 sticky top-0">
                                <tr>
                                    <th className="p-3">วันที่</th>
                                    <th className="p-3">ชื่อพนักงาน</th>
                                    <th className="p-3">เวลาเริ่มงาน</th>
                                    <th className="p-3">เวลาอ้างอิง (Ref)</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {records
                                    .filter(r => {
                                        const d = new Date(r.date);
                                        return d.getMonth() === new Date().getMonth() && getFixStartInfo(r).status === 'NG';
                                    })
                                    .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime())
                                    .map(r => {
                                        const info = getFixStartInfo(r);
                                        return (
                                            <tr key={r.__backendId} className="hover:bg-red-50/30 cursor-pointer" onClick={() => { onSelectRecord(r.__backendId); setShowNGModal(false); }}>
                                                <td className="p-3 font-medium">{new Date(r.date).toLocaleDateString('th-TH')}</td>
                                                <td className="p-3 font-bold">{r.driver_name} ({r.driver_id})</td>
                                                <td className="p-3 text-red-600 font-bold">{getSafeTime(r.checkin_timestamp)}</td>
                                                <td className="p-3 text-slate-500">{info.time}</td>
                                            </tr>
                                        );
                                    })
                                }
                            </tbody>
                        </table>
                    </div>
                    <div className="mt-4 pt-4 border-t flex justify-end">
                        <Button onClick={() => setShowNGModal(false)} variant="secondary">ปิดหน้าต่าง</Button>
                    </div>
                </Card>
            </div>
        )}

        <style>{`
          .custom-scrollbar::-webkit-scrollbar { width: 5px; }
          .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
          .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
          .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
          .animate-fade-in { animation: fadeIn 0.4s ease-out; }
          .animate-scale-up { animation: scaleUp 0.2s ease-out; }
          @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
          @keyframes scaleUp { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        `}</style>
      </div>
    );
  }

  if (view === 'queue-checkin') return <div className="animate-fade-in h-[600px]">{renderQueueList('รอตรวจก่อนเริ่มงาน', 'fa-clock', pendingCheckin, 'amber')}</div>;
  if (view === 'queue-checkout') return <div className="animate-fade-in h-[600px]">{renderQueueList('รอตรวจหลังเลิกงาน', 'fa-flag-checkered', pendingCheckout, 'purple')}</div>;

  return null;
};

import React, { useState, useEffect } from 'react';
import { TenkoRecord, User } from '../../types';
import { Button, Card, Input, OptionButton, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  record: TenkoRecord;
  user: User;
  type: 'checkin' | 'checkout' | 'view';
  onBack: () => void;
  onSuccess: () => void;
}

const InfoRow = ({ label, value, detail, alert }: { label: string, value?: string, detail?: string, alert?: boolean }) => (
    <div className={`flex flex-col mb-2 pb-2 border-b border-slate-50 last:border-0 ${alert ? 'bg-red-50 p-1.5 rounded' : ''}`}>
        <div className="flex justify-between text-sm items-start gap-2">
            <span className="font-semibold text-slate-600 shrink-0">{label}:</span>
            <span className={`font-bold text-right break-words ${alert ? 'text-red-600' : 'text-slate-800'}`}>{value || '-'}</span>
        </div>
        {detail && <div className="text-xs bg-white/50 p-1.5 rounded mt-1 border border-slate-100 text-slate-600 italic"><i className="fas fa-info-circle text-slate-400"></i> {detail}</div>}
    </div>
);

export const ApprovalView: React.FC<Props> = ({ record, user, type, onBack, onSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    temperature: record.temperature,
    blood_pressure_high: record.blood_pressure_high,
    blood_pressure_low: record.blood_pressure_low,
    alcohol_checkin: record.alcohol_checkin ?? 0,
    alcohol_checkout: record.alcohol_checkout ?? 0,
    phone_usage_compliant: record.phone_usage_compliant || 'ตรงตามที่แจ้ง',
    can_work: record.can_work || 'ได้',
    driving_violation: record.driving_violation || 'ไม่มี',

    // Driver fields (for when Tenko fills them)
    vehicle_handover: record.vehicle_handover || 'ปกติ',
    vehicle_detail: record.vehicle_detail || '',
    body_condition_checkout: record.body_condition_checkout || 'ปกติ',
    body_detail_checkout: record.body_detail_checkout || '',
    route_risk: record.route_risk || 'ปกติ',
    route_detail: record.route_detail || '',

    checkin_timestamp: record.checkin_timestamp || new Date().toISOString(),
    checkout_timestamp: record.checkout_timestamp || new Date().toISOString()
  });

  const [fixStartStatus, setFixStartStatus] = useState<string>('N/A');
  const [lastCheckout, setLastCheckout] = useState<string>('-');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const loadHistory = async () => {
        const allRecords = await StorageService.getAll();

        const previousRecords = allRecords
            .filter(r => r.driver_id === record.driver_id && r.checkout_timestamp && r.__backendId !== record.__backendId)
            .sort((a, b) => new Date(b.checkout_timestamp!).getTime() - new Date(a.checkout_timestamp!).getTime());
        if (previousRecords.length > 0) {
            setLastCheckout(new Date(previousRecords[0].checkout_timestamp!).toLocaleString('th-TH'));
        }

        const driverRecords = allRecords
            .filter(r => r.driver_id === record.driver_id && r.checkin_timestamp && r.checkin_status === 'approved')
            .sort((a, b) => new Date(b.checkin_timestamp!).getTime() - new Date(a.checkin_timestamp!).getTime());

        if (driverRecords.length === 0) {
            setFixStartStatus('OK (First Record)');
            return;
        }

        const getMonday = (dateStr: string) => {
            const d = new Date(dateStr);
            const day = d.getDay();
            const diff = d.getDate() - day + (day === 0 ? -6 : 1);
            return new Date(d.setDate(diff)).toISOString().split('T')[0];
        };

        const currentRecordMonday = getMonday(form.checkin_timestamp!);
        const currentWeekRecords = driverRecords.filter(r => getMonday(r.checkin_timestamp!) === currentRecordMonday);

        const mondayRecord = currentWeekRecords.find(r => new Date(r.checkin_timestamp!).getDay() === 1);
        const referenceRecord = mondayRecord || (currentWeekRecords.length > 0 ? currentWeekRecords[currentWeekRecords.length - 1] : null);

        if (!referenceRecord) {
            setFixStartStatus('OK');
            return;
        }

        const refDate = new Date(referenceRecord.checkin_timestamp!);
        const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
        const displayTime = refDate.toLocaleTimeString('th-TH', { 
            hour: '2-digit', 
            minute: '2-digit',
            hour12: false
        });

        const currentCheckTime = new Date(form.checkin_timestamp!);
        const currentMinutes = currentCheckTime.getHours() * 60 + currentCheckTime.getMinutes();
        const diff = Math.abs(currentMinutes - refTotalMinutes);

        if (diff > 120) {
            setFixStartStatus(`NG (Ref: ${displayTime})`);
        } else {
            setFixStartStatus(`OK (Ref: ${displayTime})`);
        }
    };
    loadHistory();
  }, [record.driver_id, form.checkin_timestamp, record.__backendId]);


  const updateForm = (k: keyof TenkoRecord, v: any) => setForm(p => ({ ...p, [k]: v }));

  const isTempBad = (t?: number) => t && t > 37.5;
  const isBPHighBad = (bp?: number) => bp && (bp < 90 || bp > 160);
  const isBPLowBad = (bp?: number) => bp && (bp < 60 || bp > 100);
  const isAlcoholBad = (a?: number) => a !== undefined && a !== 0;

  const handleApprove = async () => {
    if (isAlcoholBad(form.alcohol_checkin) && !form.alcohol_checkin_reason) return alert('กรุณาระบุเหตุผลค่าแอลกอฮอล์');
    if (form.can_work === 'ไม่ได้' && !form.cannot_work_reason) return alert('กรุณาระบุสาเหตุที่วิ่งงานไม่ได้');

    setSubmitting(true);
    const updateData: Partial<TenkoRecord> = { ...form };

    if (type === 'checkin') {
      updateData.checkin_status = 'approved';
      updateData.checkin_tenko_id = user.id;
      updateData.checkin_tenko_name = user.name;
    } else if (type === 'checkout') {
      updateData.checkout_status = 'approved';
      updateData.checkout_tenko_id = user.id;
      updateData.checkout_tenko_name = user.name;
      // Also ensure driver timestamp is set if forced
      if (!record.checkout_real_timestamp) {
          updateData.checkout_real_timestamp = new Date().toISOString();
      }
    }

    try {
        await StorageService.update({ ...record, ...updateData });
        onSuccess();
    } catch(e) {
        alert('เกิดข้อผิดพลาด');
    } finally {
        setSubmitting(false);
    }
  };

  const handleDelete = async () => {
      if(confirm('คุณต้องการลบรายการนี้ใช่หรือไม่?\n\nการลบจะทำให้ข้อมูลหายไป และพนักงานขับรถสามารถส่งรายการเข้ามาใหม่ได้')) {
          setSubmitting(true);
          try {
              await StorageService.delete(record.__backendId);
              onSuccess();
          } catch (e) {
              alert('ล้มเหลวในการลบข้อมูล');
          } finally {
              setSubmitting(false);
          }
      }
  }

  const formatDateForInput = (isoString?: string) => {
      if (!isoString) return '';
      const date = new Date(isoString);
      if (isNaN(date.getTime())) return '';
      const tzOffset = date.getTimezoneOffset() * 60000; 
      const localDate = new Date(date.getTime() - tzOffset);
      return localDate.toISOString().slice(0, 16);
  };

  const handleDateChange = (val: string, field: 'checkin_timestamp' | 'checkout_timestamp') => {
      if (!val) return;
      const date = new Date(val);
      if (!isNaN(date.getTime())) {
          updateForm(field, date.toISOString());
      }
  };

  const renderDriverDataSection = () => (
    <Card className="h-fit overflow-y-auto max-h-[85vh]">
        <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex justify-between items-center sticky top-0 bg-white z-10">
            <span className="flex items-center gap-2"><i className="fas fa-user-circle text-blue-600"></i> ข้อมูลพนักงาน</span>
            <div className="text-right">
                <div className="text-sm font-bold">{record.driver_name}</div>
                <div className="text-xs text-slate-400">ID: {record.driver_id}</div>
            </div>
        </h3>

        <div className="space-y-4 text-sm pr-1">
            {/* Context Info */}
            <div className="bg-slate-100 p-3 rounded-lg border border-slate-200 space-y-2">
                <div className="flex justify-between items-center">
                    <span className="text-slate-600 font-medium">เวลาเลิกงานล่าสุด:</span>
