import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { StorageService } from '../../services/storage';
import { TenkoDashboard } from './TenkoDashboard';
import { ApprovalView } from './ApprovalView';
import { StaffManagement } from './StaffManagement';
import { TenkoHistory } from './TenkoHistory';
import { TenkoAnalytics } from './TenkoAnalytics';
import { TenkoReportPrint } from './TenkoReportPrint';
import { SYSTEM_VERSION } from '../../constants';

interface Props {
  user: User;
  onLogout: () => void;
}

type View = 'dashboard' | 'queue-checkin' | 'queue-checkout' | 'completed' | 'analytics' | 'manage' | 'report';

export const TenkoApp: React.FC<Props> = ({ user, onLogout }) => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [selectedRecordId, setSelectedRecordId] = useState<string | null>(null);

  const loadData = async () => {
      try {
          const data = await StorageService.getAll();
          setRecords(data);
      } catch (e) {
          console.error(e);
      }
  };

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, []);

  const handleUpdate = () => {
    loadData().then(() => {
        setSelectedRecordId(null);
    });
  };

  const handleDeleteRecord = async (id: string) => {
      if(confirm('คุณต้องการลบรายการนี้ทิ้งทันทีหรือไม่? (Driver ต้องส่งใหม่)')) {
          const res = await StorageService.delete(id);
          if (res.isOk) {
            handleUpdate();
          } else {
            alert('ไม่สามารถลบข้อมูลที่ Server ได้ กรุณาลองใหม่');
          }
      }
  };

  // Nav Item component
  const NavItem = ({ view, icon, label, mobile = false }: { view: View; icon: string; label: string; mobile?: boolean }) => {
      const isActive = currentView === view;
      const count = records.filter(r => view === 'queue-checkin' ? r.checkin_status === 'pending' : r.checkout_status === 'pending').length;

      if (mobile) {
          return (
            <button 
                onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
                className={`flex flex-col items-center justify-center p-2 flex-1 relative ${isActive ? 'text-blue-200' : 'text-slate-400'}`}
            >
                <i className={`fas ${icon} text-lg mb-0.5`}></i>
                <span className="text-[9px] leading-tight">{label.split(' ')[0]}</span>
                {(view === 'queue-checkin' || view === 'queue-checkout') && count > 0 && (
                    <span className="absolute top-1 right-2 w-4 h-4 bg-red-500 text-white text-[9px] flex items-center justify-center rounded-full font-bold border border-blue-900">
                        {count}
                    </span>
                )}
            </button>
          );
      }

      return (
        <div 
          onClick={() => { setCurrentView(view); setSelectedRecordId(null); }}
          className={`px-4 py-3 cursor-pointer flex items-center gap-3 transition-colors ${isActive ? 'bg-white/20 border-r-4 border-white' : 'hover:bg-white/10 border-r-4 border-transparent'}`}
        >
          <i className={`fas ${icon} w-6 text-center`}></i>
          <span className="font-medium">{label}</span>
          {(view === 'queue-checkin' || view === 'queue-checkout') && count > 0 && (
            <span className="ml-auto bg-red-500 text-white text-xs font-bold px-2 py-0.5 rounded-full">
                {count}
            </span>
          )}
        </div>
      );
  };

  const renderContent = () => {
    // CRITICAL: Handle selection first
    if (selectedRecordId) {
       const record = records.find(r => r.__backendId === selectedRecordId);
       if (!record) return <div>Record not found</div>;

       let approvalType: 'checkin' | 'checkout' | 'view' = 'view';
       if (record.checkin_status === 'pending') {
           approvalType = 'checkin';
       } else if (record.checkout_status === 'pending') {
           approvalType = 'checkout';
       } else if (record.checkin_status === 'approved' && !record.checkout_status) {
           // ADDED: Allow Tenko to force checkout for working drivers
           approvalType = 'checkout';
       }

       return (
         <ApprovalView 
            record={record} 
            user={user}
            type={approvalType}
            onBack={() => setSelectedRecordId(null)}
            onSuccess={handleUpdate}
         />
       );
    }

    switch (currentView) {
        case 'manage': return <StaffManagement />;
        case 'analytics': return <TenkoAnalytics records={records} onSelectRecord={setSelectedRecordId} />;
        case 'report': return <TenkoReportPrint records={records} />;
        case 'completed': return <TenkoHistory records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        case 'queue-checkin': return <TenkoDashboard view="queue-checkin" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        case 'queue-checkout': return <TenkoDashboard view="queue-checkout" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
        default: return <TenkoDashboard view="dashboard" records={records} onSelectRecord={setSelectedRecordId} onDelete={handleDeleteRecord} />;
    }
  };

  return (
    <div className="flex flex-col md:flex-row h-full bg-slate-50 overflow-hidden">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-64 bg-gradient-to-b from-blue-900 to-blue-700 text-white flex-col shadow-xl z-20 print:hidden h-full">
        <div className="p-6 border-b border-blue-500/30">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                    <i className="fas fa-user-shield"></i>
                </div>
                <div>
                    <h3 className="font-bold leading-tight">{user.name}</h3>
                    <p className="text-xs text-blue-200">เจ้าหน้าที่ Tenko</p>
                </div>
            </div>
        </div>
        <nav className="flex-1 py-4 space-y-1 text-sm overflow-y-auto">
            <NavItem view="dashboard" icon="fa-home" label="หน้าหลัก" />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="คิว (ก่อนเริ่มงาน)" />
            <NavItem view="queue-checkout" icon="fa-flag-checkered" label="คิว (หลังเลิกงาน)" />
            <NavItem view="completed" icon="fa-check-double" label="รายการเสร็จสิ้น" />
            <NavItem view="analytics" icon="fa-chart-line" label="แดชบอร์ด/ปฏิทิน" />
            <NavItem view="report" icon="fa-print" label="พิมพ์รายงาน" />
            <NavItem view="manage" icon="fa-users-cog" label="ข้อมูลพนักงาน" />
        </nav>
        <div className="p-4 border-t border-blue-500/30">
            <button onClick={onLogout} className="w-full py-2 bg-blue-900/50 hover:bg-blue-800 rounded-lg transition-colors flex items-center justify-center gap-2 text-sm">
                <i className="fas fa-sign-out-alt"></i> ออกจากระบบ
            </button>
            <div className="mt-4 text-center text-xs text-blue-300/60 font-mono">
                {SYSTEM_VERSION}
            </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 md:p-8 print:p-0 print:overflow-visible pb-20 md:pb-8 w-full">
        {/* Mobile Header */}
        <div className="md:hidden flex justify-between items-center mb-4 bg-white p-3 rounded-lg shadow-sm border border-slate-100">
             <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white">
                    <i className="fas fa-user-shield text-xs"></i>
                </div>
                <span className="font-bold text-sm text-slate-700">{user.name}</span>
             </div>
             <button onClick={onLogout} className="text-slate-400 hover:text-red-500">
                 <i className="fas fa-sign-out-alt"></i>
             </button>
        </div>
        {renderContent()}
      </main>

      {/* Bottom Navigation - Mobile */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-slate-900 text-slate-400 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] z-30 flex justify-around items-center border-t border-slate-800 safe-area-pb">
            <NavItem view="dashboard" icon="fa-home" label="Home" mobile />
            <NavItem view="queue-checkin" icon="fa-clipboard-check" label="In" mobile />
            <NavItem view="queue-checkout" icon="fa-flag-checkered" label="Out" mobile />
            <NavItem view="completed" icon="fa-check-double" label="Done" mobile />
            <div className="w-[1px] h-6 bg-slate-700 mx-1"></div>
            <NavItem view="analytics" icon="fa-chart-line" label="Stats" mobile />
            <NavItem view="manage" icon="fa-cog" label="Admin" mobile />
      </nav>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button, Input } from '../../components/UI';

interface Props {
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
  onDelete: (id: string) => void;
}

export const TenkoHistory: React.FC<Props> = ({ records, onSelectRecord, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(''); // YYYY-MM format

  // Only completed records
  const completed = useMemo(() => {
    return records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  }, [records]);

  const filtered = useMemo(() => {
      return completed.filter(r => {
          const matchName = r.driver_name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           r.driver_id.toLowerCase().includes(searchTerm.toLowerCase());
          const matchMonth = selectedMonth ? r.date.startsWith(selectedMonth) : true;
          return matchName && matchMonth;
      }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [completed, searchTerm, selectedMonth]);

  return (
    <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                <i className="fas fa-check-double text-emerald-600"></i> รายการเสร็จสิ้น ({filtered.length})
            </h2>
            <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
                <div className="relative w-full sm:w-64">
                    <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
                    <input 
                        className="w-full pl-9 pr-4 py-2 rounded-lg border-2 border-slate-200 focus:outline-none focus:border-blue-500 text-sm"
                        placeholder="ค้นหาชื่อหรือรหัสพนักงาน..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>
                <input 
                    type="month"
                    className="p-2 rounded-lg border-2 border-slate-200 focus:outline-none focus:border-blue-500 text-sm"
                    value={selectedMonth}
                    onChange={e => setSelectedMonth(e.target.value)}
                />
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filtered.map(record => (
                <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer border border-slate-200 relative group" onClick={() => onSelectRecord(record.__backendId)}>
                    <div className="flex justify-between items-start mb-2">
                        <h4 className="font-bold text-slate-800 text-lg">{record.driver_name}</h4>
                        <Badge type="approved">Completed</Badge>
                    </div>
                    <div className="text-sm space-y-2 text-slate-600">
                        <p className="flex items-center gap-2"><i className="fas fa-calendar w-4"></i> {new Date(record.date).toLocaleDateString('th-TH')}</p>
                        <div className="grid grid-cols-2 gap-2 text-xs bg-slate-50 p-2 rounded">
                            <div>
                                <p className="font-bold text-blue-600">เข้างาน</p>
                                <p>{new Date(record.checkin_timestamp!).toLocaleString('th-TH', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' })}</p>
                                <p className="truncate">โดย: {record.checkin_tenko_name}</p>
                            </div>
                            <div>
                                <p className="font-bold text-orange-600">เลิกงาน</p>
                                <p>{new Date(record.checkout_timestamp!).toLocaleString('th-TH', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' })}</p>
                                <p className="truncate">โดย: {record.checkout_tenko_name}</p>
                            </div>
                        </div>
                    </div>

                    <button 
                        onClick={(e) => { e.stopPropagation(); onDelete(record.__backendId); }}
                        className="opacity-0 group-hover:opacity-100 absolute top-3 right-3 w-8 h-8 flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
                        title="ลบรายการ"
                    >
                        <i className="fas fa-trash-alt"></i>
                    </button>
                </Card>
            ))}
        </div>

        {filtered.length === 0 && (
            <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                <i className="fas fa-search text-5xl mb-4 opacity-20"></i>
                <p>ไม่พบรายการที่ตรงตามเงื่อนไข</p>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import { CheckinForm } from './CheckinForm';
import { CheckoutForm } from './CheckoutForm';
import { DriverHistory } from './DriverHistory';
import { SYSTEM_VERSION } from '../../constants';

interface DriverAppProps {
  user: User;
  onLogout: () => void;
}

export const DriverApp: React.FC<DriverAppProps> = ({ user, onLogout }) => {
  const [view, setView] = useState<'home' | 'checkin' | 'checkout' | 'history'>('home');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [pendingCount, setPendingCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'online' | 'offline' | 'error'>('online');

  const fetchData = async () => {
      try {
          await StorageService.syncPendingData();
          const data = await StorageService.getAll();
          setRecords(data);
          setPendingCount(StorageService.getPendingCount());
          setConnectionStatus(StorageService.getConnectionStatus());
      } catch(e) {
          console.error(e);
          setConnectionStatus('offline');
      } finally {
          setIsLoading(false);
      }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 15000);
    return () => clearInterval(interval);
  }, []);

  const getTodayStr = () => {
      const now = new Date();
      return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const today = getTodayStr();
  const myRecords = records
    .filter(r => r.driver_id === user.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const activeRecord = myRecords[0]; 
  const isCurrentSession = activeRecord && (
      activeRecord.date === today || 
      (!activeRecord.checkout_status && (new Date().getTime() - new Date(activeRecord.checkin_real_timestamp || activeRecord.date).getTime()) < 24 * 60 * 60 * 1000)
  );

  const currentRecord = isCurrentSession ? activeRecord : null;

  const calculateNextStart = (checkoutTime?: string) => {
    if (!checkoutTime) return '-';
    const date = new Date(checkoutTime);
    // Add 8 hours for safety rest
    const nextDate = new Date(date.getTime() + 8 * 60 * 60 * 1000);
    return nextDate.toLocaleString('th-TH', { 
        day: '2-digit', 
        month: '2-digit', 
        year: '2-digit', 
        hour: '2-digit', 
        minute: '2-digit' 
    }) + ' น.';
  };

  const checkFixStartTime = () => {
    const getMonday = (dateStr: string) => {
        const d = new Date(dateStr);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? -6 : 1);
        const monday = new Date(d.setDate(diff));
        return `${monday.getFullYear()}-${String(monday.getMonth()+1).padStart(2,'0')}-${String(monday.getDate()).padStart(2,'0')}`;
    };

    const thisWeekMonday = getMonday(today);
    const thisWeekRecords = myRecords.filter(r => getMonday(r.date) === thisWeekMonday);

    const approvedThisWeek = thisWeekRecords
        .filter(r => r.checkin_status === 'approved')
        .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const referenceRecord = approvedThisWeek.length > 0 
        ? approvedThisWeek[0] 
        : (thisWeekRecords.length > 0 ? thisWeekRecords[thisWeekRecords.length - 1] : null);

    if (!referenceRecord) return { status: 'New', time: '--:--' };

    const refTimeSource = referenceRecord.checkin_timestamp || referenceRecord.checkin_real_timestamp;
    const refDate = new Date(refTimeSource!);
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    if (thisWeekRecords.length === 1 && (!currentRecord || currentRecord.checkin_status !== 'approved')) {
        return { status: 'Ref', time: displayTime };
    }

    if (currentRecord && currentRecord.checkin_timestamp) {
        const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
        const checkDate = new Date(currentRecord.checkin_timestamp);
        const checkTime = checkDate.getHours() * 60 + checkDate.getMinutes();
        if (Math.abs(checkTime - refTotalMinutes) > 120) return { status: 'NG', time: displayTime };
    }

    return { status: 'OK', time: displayTime };
  };

  const canStartCheckin = () => {
     if (currentRecord) {
         if (currentRecord.checkin_status === 'approved' && currentRecord.checkout_status === 'approved') return { allowed: true };
         return { allowed: false, message: "คุณมีรายการที่ยังทำไม่จบ" };
     }
     return { allowed: true };
  };

  const checkinStatus = canStartCheckin();
  const fixData = checkFixStartTime();

  const handleDataUpdate = () => {
      setIsLoading(true);
      fetchData().then(() => {
          setView('home');
          setIsLoading(false);
      });
  };

  if (view === 'checkin') return <CheckinForm user={user} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'checkout') return <CheckoutForm user={user} record={currentRecord!} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'history') return <DriverHistory user={user} records={records} onBack={() => setView('home')} fixStartTime={fixData.status} displayTime={fixData.time} />;

  return (
    <div className="h-full bg-slate-50 flex flex-col overflow-hidden animate-fade-in">
      <header className="bg-gradient-to-r from-blue-700 to-blue-500 text-white p-4 md:p-6 shadow-lg shrink-0 z-10">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-xl md:text-2xl font-bold flex items-center gap-2">
              <i className="fas fa-user-circle"></i> {user.name}
            </h1>
            <div className="flex items-center gap-3 text-sm opacity-80 mt-1">
                <span>รหัส: {user.id}</span>
                <Badge type={fixData.status === 'OK' || fixData.status === 'Ref' ? 'approved' : 'danger'}>
                    Fix Start: {fixData.status === 'Ref' ? 'Baseline' : fixData.status}
                </Badge>
            </div>
          </div>
          <div className="flex flex-col items-end gap-2">
              <Button variant="secondary" size="sm" onClick={onLogout} className="border-white text-white hover:bg-white/20 px-3 h-8">
                  <i className="fas fa-sign-out-alt"></i> ออก
              </Button>
              <div className="text-[10px] font-bold opacity-60">{connectionStatus === 'online' ? '● Online' : '○ Offline'}</div>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 md:p-6 w-full flex-1 overflow-y-auto">
        <div className="space-y-4 md:space-y-6">
            {currentRecord && currentRecord.checkin_status === 'pending' && (
                <Card className="bg-amber-50 border-amber-500 py-4 px-6 border-l-4 shadow-sm animate-pulse">
                    <div className="flex items-center gap-4 text-amber-800">
                        <i className="fas fa-hourglass-half text-2xl"></i>
                        <div>
                            <h3 className="font-bold">ส่งข้อมูลแล้ว รอเจ้าหน้าที่ตรวจสอบ</h3>
                            <p className="text-sm opacity-90">กรุณาแจ้งชื่อพนักงานให้เจ้าหน้าที่ Tenko ทราบ</p>
                        </div>
                    </div>
                </Card>
            )}

            {currentRecord && currentRecord.checkin_status === 'approved' && !currentRecord.checkout_status && (
                <Card className="bg-emerald-50 border-emerald-600 py-5 px-6 border-l-4 shadow-md">
                    <div className="flex items-center gap-4 text-emerald-900">
                        <div className="bg-emerald-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl shadow-lg">
                            <i className="fas fa-check-circle"></i>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <h3 className="font-black text-lg">ตรวจผ่านแล้ว - เริ่มงานได้</h3>
                                <Badge type="approved">ACTIVE</Badge>
                            </div>
                            <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-1 text-xs font-bold text-emerald-800/70">
                                <p><i className="fas fa-clock mr-1.5"></i> ตรวจเมื่อ: {new Date(currentRecord.checkin_timestamp!).toLocaleTimeString('th-TH', {hour:'2-digit', minute:'2-digit'})} น.</p>
                                <p><i className="fas fa-user-shield mr-1.5"></i> ผู้ตรวจ: {currentRecord.checkin_tenko_name || '-'}</p>
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            {currentRecord && currentRecord.checkout_status === 'approved' && (
                <Card className="bg-indigo-50 border-indigo-600 py-5 px-6 border-l-4 shadow-md border-r border-t border-b animate-slide-up">
                    <div className="flex items-center gap-4 text-indigo-900">
                        <div className="bg-indigo-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl shadow-lg shrink-0">
                            <i className="fas fa-bed"></i>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <h3 className="font-black text-lg">บันทึกเลิกงานเรียบร้อย</h3>
                                <Badge type="neutral">FINISHED</Badge>
                            </div>
                            <p className="text-sm font-bold text-indigo-800 mt-1">พักผ่อนมากกว่า 8 ชม. เพื่อความปลอดภัย</p>
                            <div className="mt-3 inline-flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-indigo-200 text-xs font-bold text-indigo-700 shadow-sm">
                                <i className="fas fa-clock text-indigo-500"></i> เริ่มงานครั้งถัดไปได้เวลา: {calculateNextStart(currentRecord.checkout_timestamp)}
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <Card onClick={() => checkinStatus.allowed ? setView('checkin') : alert(checkinStatus.message)} className={`flex flex-col items-center justify-center p-6 hover:border-blue-400 transition-all ${!checkinStatus.allowed ? 'opacity-50 grayscale' : 'border-blue-100'}`}>
                    <div className="w-14 h-14 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-3 text-2xl"><i className="fas fa-clipboard-check"></i></div>
                    <h3 className="font-bold text-slate-800">ก่อนเริ่มงาน</h3>
                    {!checkinStatus.allowed && <p className="text-red-500 text-[10px] mt-1 font-bold">{checkinStatus.message}</p>}
                </Card>

                <Card onClick={() => (currentRecord?.checkin_status === 'approved' && !currentRecord.checkout_status) ? setView('checkout') : alert('ยังไม่สามารถเลิกงานได้')} className={`flex flex-col items-center justify-center p-6 hover:border-emerald-400 transition-all ${(!currentRecord || currentRecord.checkin_status !== 'approved' || currentRecord.checkout_status) ? 'opacity-50 grayscale' : 'border-emerald-100'}`}>
                    <div className="w-14 h-14 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mb-3 text-2xl"><i className="fas fa-flag-checkered"></i></div>
                    <h3 className="font-bold text-slate-800">หลังเลิกงาน</h3>
                </Card>

                <Card onClick={() => setView('history')} className="flex flex-col items-center justify-center p-6 hover:border-purple-400 border-purple-50 transition-all">
                    <div className="w-14 h-14 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mb-3 text-2xl"><i className="fas fa-history"></i></div>
                    <h3 className="font-bold text-slate-800">รายงานของฉัน</h3>
                </Card>
            </div>

            <div className="mt-8 text-center bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                <p className="text-sm text-slate-500 mb-1">เวลาอ้างอิง Fix Start Time สัปดาห์นี้</p>
                <p className="text-3xl font-black text-blue-600 tracking-tight">{fixData.time}</p>
                <div className="flex justify-center gap-2 mt-2">
                    {fixData.status === 'Ref' ? (
                        <span className="text-[11px] bg-blue-100 text-blue-700 px-3 py-1 rounded-full font-bold">
                            <i className="fas fa-star mr-1"></i> เป็นวันแรก (ใช้เป็นเวลาอ้างอิง)
                        </span>
                    ) : (
                        <Badge type={fixData.status === 'OK' ? 'approved' : 'danger'}>สถานะ: {fixData.status}</Badge>
                    )}
                </div>
            </div>
        </div>
      </main>
      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        .animate-slide-up { animation: slideUp 0.5s cubic-bezier(0.16, 1, 0.3, 1); }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </div>
  );
};

import React from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, Badge } from '../../components/UI';

interface Props {
  user: User;
  records: TenkoRecord[];
  onBack: () => void;
  fixStartTime: string;
  displayTime: string;
}

export const DriverHistory: React.FC<Props> = ({ user, records, onBack, fixStartTime, displayTime }) => {
  const myRecords = records
    .filter(r => r.driver_id === user.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const currentMonth = new Date();
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  // ป้องกันปัญหา Timezone โดยการสร้าง Date จาก string YYYY-MM-DD โดยตรง
  const parseSafeDate = (dateStr: string) => {
    const [y, m, d] = dateStr.split('-').map(Number);
    return new Date(y, m - 1, d);
  };

  const getDayStatus = (day: number) => {
    const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    const record = myRecords.find(r => r.date === dateStr);

    if (!record) return 'none';
    if (record.checkin_status === 'approved' && record.checkout_status === 'approved') return 'complete';
    if (record.checkin_status === 'approved') return 'working';
    return 'pending';
  };

  const getStatusBadge = (r: TenkoRecord) => {
      if (r.checkin_status === 'approved' && r.checkout_status === 'approved') return <Badge type="approved">เสร็จสมบูรณ์</Badge>;
      if (r.checkin_status === 'approved') return <Badge type="pending">กำลังปฏิบัติงาน</Badge>;
      return <Badge type="danger">รอตรวจสอบ</Badge>;
  };

  return (
    <div className="h-full bg-slate-50 overflow-y-auto pb-10">
      <div className="bg-purple-600 text-white px-6 py-6 shadow-md">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
            <div>
                <h2 className="text-2xl font-bold">รายงานของฉัน</h2>
                <p className="opacity-80">ประวัติการปฏิบัติงานและการตรวจสอบ</p>
            </div>
            <Button onClick={onBack} variant="secondary" className="border-white text-white hover:bg-white/20">ย้อนกลับ</Button>
        </div>
      </div>

      <div className="max-w-4xl mx-auto p-6 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
             <Card className="bg-white border-l-4 border-blue-500">
                 <p className="text-sm text-slate-500">เดือนนี้</p>
                 <p className="text-3xl font-bold text-blue-600">{myRecords.filter(r => parseSafeDate(r.date).getMonth() === currentMonth.getMonth()).length}</p>
                 <p className="text-xs text-slate-400">รายการ</p>
             </Card>
             <Card className="bg-white border-l-4 border-purple-500">
                 <p className="text-sm text-slate-500">ทั้งหมด</p>
                 <p className="text-3xl font-bold text-purple-600">{myRecords.length}</p>
                 <p className="text-xs text-slate-400">รายการ</p>
             </Card>
             <Card className={`bg-white border-l-4 ${fixStartTime === 'NG' ? 'border-red-500' : 'border-emerald-500'}`}>
                 <p className="text-sm text-slate-500">Fix Start Time สัปดาห์นี้</p>
                 <p className={`text-3xl font-bold ${fixStartTime === 'NG' ? 'text-red-600' : 'text-emerald-600'}`}>
                    {fixStartTime === 'Ref' ? 'Baseline' : `"${fixStartTime}"`}
                 </p>
                 <div className="flex justify-between items-center mt-1">
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Ref Time: {displayTime}</p>
                 </div>
             </Card>
        </div>

        <Card>
            <h3 className="font-bold mb-4 text-slate-700">ปฏิทิน {currentMonth.toLocaleString('th-TH', { month: 'long', year: 'numeric' })}</h3>
            <div className="grid grid-cols-7 gap-1">
                {['อา','จ','อ','พ','พฤ','ศ','ส'].map(d => <div key={d} className="text-center text-xs font-bold text-slate-400 py-2">{d}</div>)}
                {Array.from({length: firstDay}).map((_, i) => <div key={`empty-${i}`} />)}
                {Array.from({length: daysInMonth}).map((_, i) => {
                    const status = getDayStatus(i+1);
                    return (
                        <div key={i} className={`
                            h-10 flex items-center justify-center rounded-lg text-sm font-medium border
                            ${status === 'complete' ? 'bg-emerald-100 text-emerald-700 border-emerald-200' : 
                              status === 'working' ? 'bg-blue-100 text-blue-700 border-blue-200' :
                              status === 'pending' ? 'bg-amber-50 text-amber-600 border-amber-200' : 
                              'bg-slate-50 text-slate-300 border-slate-100'}
                        `}>
                            {i+1}
                        </div>
                    );
                })}
            </div>
        </Card>

        <div className="space-y-4">
            <h3 className="font-bold text-slate-700">รายการล่าสุด (10 รายการ)</h3>
            {myRecords.slice(0, 10).map(record => (
                <Card key={record.__backendId} className="hover:bg-slate-50 transition-colors border border-slate-100">
                    <div className="flex justify-between items-start mb-3 border-b pb-2">
                        <div>
                            <p className="font-bold text-slate-800">
                                {parseSafeDate(record.date).toLocaleDateString('th-TH', { dateStyle: 'long' })}
                            </p>
                            <p className="text-[10px] text-slate-400">Record ID: {record.__backendId.substring(0, 8)}</p>
                        </div>
                        {getStatusBadge(record)}
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
                        <div className="p-3 bg-blue-50/50 rounded-lg border border-blue-100">
                            <p className="font-bold text-blue-800 text-xs mb-1 uppercase tracking-wider">ก่อนเริ่มงาน (Check-in)</p>
                            <div className="space-y-1">
                                <p className="flex justify-between"><span>เวลาอนุมัติ:</span> <span className="font-bold">{record.checkin_timestamp ? new Date(record.checkin_timestamp).toLocaleTimeString('th-TH', {hour: '2-digit', minute:'2-digit'}) : '-'} น.</span></p>
                                <p className="flex justify-between"><span>ผู้ตรวจ:</span> <span className="text-slate-600">{record.checkin_tenko_name || '-'}</span></p>
                            </div>
                        </div>
                        <div className={`p-3 rounded-lg border ${record.checkout_status === 'approved' ? 'bg-emerald-50/50 border-emerald-100' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                            <p className="font-bold text-emerald-800 text-xs mb-1 uppercase tracking-wider">หลังเลิกงาน (Check-out)</p>
                            <div className="space-y-1">
                                <p className="flex justify-between items-center">
                                    <span>วัน/เวลาเลิกงาน:</span> 
                                    <span className="font-bold text-right">
                                        {record.checkout_timestamp 
                                            ? new Date(record.checkout_timestamp).toLocaleString('th-TH', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' }) 
                                            : '-'}
                                    </span>
                                </p>
                                <p className="flex justify-between"><span>ผู้ตรวจ:</span> <span className="text-slate-600">{record.checkout_tenko_name || '-'}</span></p>
                            </div>
                        </div>
                    </div>
                </Card>
            ))}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { TenkoRecord } from '../../types';
import { Card, Badge, Button, Input } from '../../components/UI';

interface Props {
  records: TenkoRecord[];
  onSelectRecord: (id: string) => void;
  onDelete: (id: string) => void;
}

export const TenkoHistory: React.FC<Props> = ({ records, onSelectRecord, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState(''); // YYYY-MM format

  // Only completed records
  const completed = useMemo(() => {
    return records.filter(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');
  }, [records]);

  // ป้องกันปัญหา Timezone โดยการสร้าง Date จาก string YYYY-MM-DD โดยตรง
  const parseSafeDate = (dateStr: string) => {
    const [y, m, d] = dateStr.split('-').map(Number);
    return new Date(y, m - 1, d);
  };

  const filtered = useMemo(() => {
      return completed.filter(r => {
          const matchName = r.driver_name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           r.driver_id.toLowerCase().includes(searchTerm.toLowerCase());
          const matchMonth = selectedMonth ? r.date.startsWith(selectedMonth) : true;
          return matchName && matchMonth;
      }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [completed, searchTerm, selectedMonth]);

  return (
    <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
                <i className="fas fa-check-double text-emerald-600"></i> รายการเสร็จสิ้น ({filtered.length})
            </h2>
            <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
                <div className="relative w-full sm:w-64">
                    <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>
                    <input 
                        className="w-full pl-9 pr-4 py-2 rounded-lg border-2 border-slate-200 focus:outline-none focus:border-blue-500 text-sm"
                        placeholder="ค้นหาชื่อหรือรหัสพนักงาน..."
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>
                <input 
                    type="month"
                    className="p-2 rounded-lg border-2 border-slate-200 focus:outline-none focus:border-blue-500 text-sm"
                    value={selectedMonth}
                    onChange={e => setSelectedMonth(e.target.value)}
                />
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filtered.map(record => (
                <Card key={record.__backendId} className="hover:shadow-md transition-all cursor-pointer border border-slate-200 relative group" onClick={() => onSelectRecord(record.__backendId)}>
                    <div className="flex justify-between items-start mb-2">
                        <h4 className="font-bold text-slate-800 text-lg">{record.driver_name}</h4>
                        <Badge type="approved">Completed</Badge>
                    </div>
                    <div className="text-sm space-y-2 text-slate-600">
                        <p className="flex items-center gap-2">
                          <i className="fas fa-calendar w-4"></i> 
                          {parseSafeDate(record.date).toLocaleDateString('th-TH', { dateStyle: 'long' })}
                        </p>
                        <div className="grid grid-cols-2 gap-2 text-xs bg-slate-50 p-2 rounded">
                            <div>
                                <p className="font-bold text-blue-600">เข้างาน</p>
                                <p>{new Date(record.checkin_timestamp!).toLocaleString('th-TH', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' })}</p>
                                <p className="truncate">โดย: {record.checkin_tenko_name}</p>
                            </div>
                            <div>
                                <p className="font-bold text-orange-600">เลิกงาน</p>
                                <p>{new Date(record.checkout_timestamp!).toLocaleString('th-TH', { day: '2-digit', month: '2-digit', year: '2-digit', hour: '2-digit', minute: '2-digit' })}</p>
                                <p className="truncate">โดย: {record.checkout_tenko_name}</p>
                            </div>
                        </div>
                    </div>

                    <button 
                        onClick={(e) => { e.stopPropagation(); onDelete(record.__backendId); }}
                        className="opacity-0 group-hover:opacity-100 absolute top-3 right-3 w-8 h-8 flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"
                        title="ลบรายการ"
                    >
                        <i className="fas fa-trash-alt"></i>
                    </button>
                </Card>
            ))}
        </div>

        {filtered.length === 0 && (
            <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                <i className="fas fa-search text-5xl mb-4 opacity-20"></i>
                <p>ไม่พบรายการที่ตรงตามเงื่อนไข</p>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Card, Button, Badge } from '../../components/UI';
import { StorageService } from '../../services/storage';
import { CheckinForm } from './CheckinForm';
import { CheckoutForm } from './CheckoutForm';
import { DriverHistory } from './DriverHistory';
import { SYSTEM_VERSION } from '../../constants';

interface DriverAppProps {
  user: User;
  onLogout: () => void;
}

export const DriverApp: React.FC<DriverAppProps> = ({ user, onLogout }) => {
  const [view, setView] = useState<'home' | 'checkin' | 'checkout' | 'history'>('home');
  const [records, setRecords] = useState<TenkoRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [pendingCount, setPendingCount] = useState(0);
  const [connectionStatus, setConnectionStatus] = useState<'online' | 'offline' | 'error'>('online');
  const [now, setNow] = useState(new Date());

  const fetchData = async () => {
      try {
          await StorageService.syncPendingData();
          const data = await StorageService.getAll();
          setRecords(data);
          setPendingCount(StorageService.getPendingCount());
          setConnectionStatus(StorageService.getConnectionStatus());
      } catch(e) {
          console.error(e);
          setConnectionStatus('offline');
      } finally {
          setIsLoading(false);
      }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 15000);
    const clockInterval = setInterval(() => setNow(new Date()), 60000); // Update every minute for the rest timer
    return () => {
        clearInterval(interval);
        clearInterval(clockInterval);
    };
  }, []);

  const getTodayStr = () => {
      const d = new Date();
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  const today = getTodayStr();
  const myRecords = records
    .filter(r => r.driver_id === user.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  const activeRecord = myRecords[0]; 

  // Check if we have a current session in progress
  const isCurrentSession = activeRecord && (
      activeRecord.date === today || 
      (!activeRecord.checkout_status && (now.getTime() - new Date(activeRecord.checkin_real_timestamp || activeRecord.date).getTime()) < 24 * 60 * 60 * 1000)
  );

  const currentRecord = isCurrentSession ? activeRecord : null;

  // Find the last completed record to calculate rest time
  const lastFinishedRecord = myRecords.find(r => r.checkin_status === 'approved' && r.checkout_status === 'approved');

  const getRestInfo = () => {
      if (!lastFinishedRecord || !lastFinishedRecord.checkout_timestamp) return null;
      const checkoutTime = new Date(lastFinishedRecord.checkout_timestamp);
      const restUntil = new Date(checkoutTime.getTime() + 8 * 60 * 60 * 1000);
      const isResting = now < restUntil;

      return {
          checkoutTime,
          restUntil,
          isResting,
          restUntilStr: restUntil.toLocaleString('th-TH', { 
              day: '2-digit', month: '2-digit', year: '2-digit', 
              hour: '2-digit', minute: '2-digit' 
          }) + ' น.'
      };
  };

  const restInfo = getRestInfo();

  const checkFixStartTime = () => {
    const getMonday = (dateStr: string) => {
        const d = new Date(dateStr);
        const day = d.getDay();
        const diff = d.getDate() - day + (day === 0 ? -6 : 1);
        const monday = new Date(d.setDate(diff));
        return `${monday.getFullYear()}-${String(monday.getMonth()+1).padStart(2,'0')}-${String(monday.getDate()).padStart(2,'0')}`;
    };

    const thisWeekMonday = getMonday(today);
    const thisWeekRecords = myRecords.filter(r => getMonday(r.date) === thisWeekMonday);

    const approvedThisWeek = thisWeekRecords
        .filter(r => r.checkin_status === 'approved')
        .sort((a, b) => new Date(a.checkin_timestamp!).getTime() - new Date(b.checkin_timestamp!).getTime());

    const referenceRecord = approvedThisWeek.length > 0 
        ? approvedThisWeek[0] 
        : (thisWeekRecords.length > 0 ? thisWeekRecords[thisWeekRecords.length - 1] : null);

    if (!referenceRecord) return { status: 'New', time: '--:--' };

    const refTimeSource = referenceRecord.checkin_timestamp || referenceRecord.checkin_real_timestamp;
    const refDate = new Date(refTimeSource!);
    const displayTime = refDate.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', hour12: false });

    if (thisWeekRecords.length === 1 && (!currentRecord || currentRecord.checkin_status !== 'approved')) {
        return { status: 'Ref', time: displayTime };
    }

    if (currentRecord && currentRecord.checkin_timestamp) {
        const refTotalMinutes = refDate.getHours() * 60 + refDate.getMinutes();
        const checkDate = new Date(currentRecord.checkin_timestamp);
        const checkTime = checkDate.getHours() * 60 + checkDate.getMinutes();
        if (Math.abs(checkTime - refTotalMinutes) > 120) return { status: 'NG', time: displayTime };
    }

    return { status: 'OK', time: displayTime };
  };

  const canStartCheckin = () => {
     if (currentRecord) {
         if (currentRecord.checkin_status === 'approved' && currentRecord.checkout_status === 'approved') {
             // If resting, allow but warn
             if (restInfo?.isResting) {
                 return { allowed: true, warning: `คุณยังพักผ่อนไม่ครบ 8 ชม. (ครบเวลา ${restInfo.restUntilStr}) ต้องการเข้างานเลยใช่หรือไม่?` };
             }
             return { allowed: true };
         }
         return { allowed: false, message: "คุณมีรายการที่ยังทำไม่จบ" };
     }
     return { allowed: true };
  };

  const checkinStatus = canStartCheckin();
  const fixData = checkFixStartTime();

  const handleDataUpdate = () => {
      setIsLoading(true);
      fetchData().then(() => {
          setView('home');
          setIsLoading(false);
      });
  };

  const handleCheckinClick = () => {
      const status = canStartCheckin();
      if (!status.allowed) {
          alert(status.message);
          return;
      }
      if (status.warning) {
          if (!confirm(status.warning)) return;
      }
      setView('checkin');
  };

  if (view === 'checkin') return <CheckinForm user={user} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'checkout') return <CheckoutForm user={user} record={currentRecord!} onBack={() => setView('home')} onSubmitSuccess={handleDataUpdate} />;
  if (view === 'history') return <DriverHistory user={user} records={records} onBack={() => setView('home')} fixStartTime={fixData.status} displayTime={fixData.time} />;

  return (
    <div className="h-full bg-slate-50 flex flex-col overflow-hidden animate-fade-in">
      <header className="bg-gradient-to-r from-blue-700 to-blue-500 text-white p-4 md:p-6 shadow-lg shrink-0 z-10">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-xl md:text-2xl font-bold flex items-center gap-2">
              <i className="fas fa-user-circle"></i> {user.name}
            </h1>
            <div className="flex items-center gap-3 text-sm opacity-80 mt-1">
                <span>รหัส: {user.id}</span>
                <Badge type={fixData.status === 'OK' || fixData.status === 'Ref' ? 'approved' : 'danger'}>
                    Fix Start: {fixData.status === 'Ref' ? 'Baseline' : fixData.status}
                </Badge>
            </div>
          </div>
          <div className="flex flex-col items-end gap-2">
              <Button variant="secondary" size="sm" onClick={onLogout} className="border-white text-white hover:bg-white/20 px-3 h-8">
                  <i className="fas fa-sign-out-alt"></i> ออก
              </Button>
              <div className="text-[10px] font-bold opacity-60">{connectionStatus === 'online' ? '● Online' : '○ Offline'}</div>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 md:p-6 w-full flex-1 overflow-y-auto">
        <div className="space-y-4 md:space-y-6">
            {/* Status: Pending Approval */}
            {currentRecord && currentRecord.checkin_status === 'pending' && (
                <Card className="bg-amber-50 border-amber-500 py-4 px-6 border-l-4 shadow-sm animate-pulse">
                    <div className="flex items-center gap-4 text-amber-800">
                        <i className="fas fa-hourglass-half text-2xl"></i>
                        <div>
                            <h3 className="font-bold">ส่งข้อมูลแล้ว รอเจ้าหน้าที่ตรวจสอบ</h3>
                            <p className="text-sm opacity-90">กรุณาแจ้งชื่อพนักงานให้เจ้าหน้าที่ Tenko ทราบ</p>
                        </div>
                    </div>
                </Card>
            )}

            {/* Status: Active Working */}
            {currentRecord && currentRecord.checkin_status === 'approved' && !currentRecord.checkout_status && (
                <Card className="bg-emerald-50 border-emerald-600 py-5 px-6 border-l-4 shadow-md">
                    <div className="flex items-center gap-4 text-emerald-900">
                        <div className="bg-emerald-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl shadow-lg">
                            <i className="fas fa-check-circle"></i>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <h3 className="font-black text-lg">ตรวจผ่านแล้ว - เริ่มงานได้</h3>
                                <Badge type="approved">ACTIVE</Badge>
                            </div>
                            <div className="mt-2 grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-1 text-xs font-bold text-emerald-800/70">
                                <p><i className="fas fa-clock mr-1.5"></i> ตรวจเมื่อ: {new Date(currentRecord.checkin_timestamp!).toLocaleTimeString('th-TH', {hour:'2-digit', minute:'2-digit'})} น.</p>
                                <p><i className="fas fa-user-shield mr-1.5"></i> ผู้ตรวจ: {currentRecord.checkin_tenko_name || '-'}</p>
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            {/* Status: Resting (Persistent Alert) */}
            {restInfo?.isResting && (!currentRecord || currentRecord.checkout_status === 'approved') && (
                <Card className="bg-indigo-50 border-indigo-600 py-5 px-6 border-l-4 shadow-md border-r border-t border-b animate-slide-up">
                    <div className="flex items-center gap-4 text-indigo-900">
                        <div className="bg-indigo-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl shadow-lg shrink-0">
                            <i className="fas fa-bed"></i>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-start">
                                <h3 className="font-black text-lg">พักผ่อนมากกว่า 8 ชม. เพื่อความปลอดภัย</h3>
                                <Badge type="neutral">RESTING</Badge>
                            </div>
                            <p className="text-sm font-bold text-indigo-800 mt-1">กรุณาพักผ่อนให้เพียงพอก่อนเริ่มงานครั้งถัดไป</p>
                            <div className="mt-3 inline-flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-indigo-200 text-xs font-bold text-indigo-700 shadow-sm">
                                <i className="fas fa-clock text-indigo-500"></i> เริ่มงานครั้งถัดไปได้เวลา: {restInfo.restUntilStr}
                            </div>
                        </div>
                    </div>
                </Card>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <Card 
                    onClick={handleCheckinClick} 
                    className={`flex flex-col items-center justify-center p-6 transition-all group relative ${
                        !checkinStatus.allowed ? 'opacity-50 grayscale bg-slate-100' : 
                        restInfo?.isResting ? 'border-amber-400 bg-amber-50/30' : 'border-blue-100 hover:border-blue-400'
                    }`}
                >
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center mb-3 text-2xl transition-transform group-hover:scale-110 ${
                        !checkinStatus.allowed ? 'bg-slate-200 text-slate-400' : 
                        restInfo?.isResting ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'
                    }`}>
                        <i className="fas fa-clipboard-check"></i>
                    </div>
                    <h3 className="font-bold text-slate-800">ก่อนเริ่มงาน</h3>
                    {!checkinStatus.allowed ? (
                        <p className="text-red-500 text-[10px] mt-1 font-bold">{checkinStatus.message}</p>
                    ) : restInfo?.isResting ? (
                        <p className="text-amber-600 text-[10px] mt-1 font-bold text-center">ยังพักไม่ครบ 8 ชม.</p>
                    ) : (
                        <p className="text-slate-400 text-[10px] mt-1 font-bold">พร้อมตรวจสอบ</p>
                    )}
                </Card>

                <Card 
                    onClick={() => (currentRecord?.checkin_status === 'approved' && !currentRecord.checkout_status) ? setView('checkout') : alert('ยังไม่สามารถเลิกงานได้')} 
                    className={`flex flex-col items-center justify-center p-6 transition-all group ${(!currentRecord || currentRecord.checkin_status !== 'approved' || currentRecord.checkout_status) ? 'opacity-50 grayscale' : 'border-emerald-100 hover:border-emerald-400'}`}
                >
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center mb-3 text-2xl transition-transform group-hover:scale-110 ${(!currentRecord || currentRecord.checkin_status !== 'approved' || currentRecord.checkout_status) ? 'bg-slate-200 text-slate-400' : 'bg-emerald-100 text-emerald-600'}`}>
                        <i className="fas fa-flag-checkered"></i>
                    </div>
                    <h3 className="font-bold text-slate-800">หลังเลิกงาน</h3>
                    {currentRecord?.checkin_status === 'approved' && !currentRecord.checkout_status && (
                        <p className="text-emerald-600 text-[10px] mt-1 font-bold">กำลังปฏิบัติงาน</p>
                    )}
                </Card>

                <Card onClick={() => setView('history')} className="flex flex-col items-center justify-center p-6 hover:border-purple-400 border-purple-50 transition-all group">
                    <div className="w-14 h-14 bg-purple-100 text-purple-600 rounded-full flex items-center justify-center mb-3 text-2xl transition-transform group-hover:scale-110">
                        <i className="fas fa-history"></i>
                    </div>
                    <h3 className="font-bold text-slate-800">รายงานของฉัน</h3>
                    <p className="text-slate-400 text-[10px] mt-1 font-bold">ดูประวัติย้อนหลัง</p>
                </Card>
            </div>

            <div className="mt-8 text-center bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                <p className="text-sm text-slate-500 mb-1">เวลาอ้างอิง Fix Start Time สัปดาห์นี้</p>
                <p className="text-3xl font-black text-blue-600 tracking-tight">{fixData.time}</p>
                <div className="flex justify-center gap-2 mt-2">
                    {fixData.status === 'Ref' ? (
                        <span className="text-[11px] bg-blue-100 text-blue-700 px-3 py-1 rounded-full font-bold">
                            <i className="fas fa-star mr-1"></i> เป็นวันแรก (ใช้เป็นเวลาอ้างอิง)
                        </span>
                    ) : (
                        <Badge type={fixData.status === 'OK' ? 'approved' : 'danger'}>สถานะ: {fixData.status}</Badge>
                    )}
                </div>
            </div>
        </div>
      </main>
      <style>{`
        .animate-fade-in { animation: fadeIn 0.4s ease-out; }
        .animate-slide-up { animation: slideUp 0.5s cubic-bezier(0.16, 1, 0.3, 1); }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes slideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User, TenkoRecord } from '../../types';
import { Button, Card, OptionButton, Input } from '../../components/UI';
import { StorageService } from '../../services/storage';

interface Props {
  user: User;
  onBack: () => void;
  onSubmitSuccess: () => void;
}

export const CheckinForm: React.FC<Props> = ({ user, onBack, onSubmitSuccess }) => {
  const [form, setForm] = useState<Partial<TenkoRecord>>({
    tired: 'ไม่มี',
    sick: 'ไม่มี',
    drowsy: 'ไม่มี',
    injury: 'ไม่มี',
    medication: 'ไม่ทาน',
    body_condition: 'ปกติ',
    sleep_quality: 'หลับสนิท',
    extra_sleep: 'ไม่นอนเพิ่ม',
    worry_detail: 'ไม่มี',
    rest_location: 'บ้าน',
